const neptuneLLBoundsMin = R.laplaceLagrangeBounds.neptune[0];
const neptuneLLBoundsMax = R.laplaceLagrangeBounds.neptune[1];

// Laplace-Lagrange inclination eigenmode phase angles (degrees)
// Source: Farside Table 10.1 (Brouwer & van Woerkom refinement)
// https://farside.ph.utexas.edu/teaching/celestial/Celestial/node91.html
// f₅ = 0 (invariable plane, no evolution) is excluded — 7 active modes remain
const EIGENMODE_PHASES = [
  // Per-planet phase angles (ICRF perihelion)
  { value: 99.52,    label: '99.52° (Me)', group: 'model' },
  { value: 79.82,    label: '79.82° (Ve)', group: 'model' },
  { value: 21.77,    label: '21.77° (Ea)', group: 'model' },
  { value: 96.95,    label: '96.95° (Ma)', group: 'model' },
  { value: 291.18,   label: '291.18° (Ju)', group: 'model' },
  { value: 120.38,   label: '120.38° (Sa)', group: 'model' },
  { value: 21.33,    label: '21.33° (Ur)', group: 'model' },
  { value: 354.04,   label: '354.04° (Ne)', group: 'model' },
  // Laplace-Lagrange eigenmode phase angles (Farside Table 10.1), from
  // R.eigenmodePhasesLaplaceLagrange — labels render the same values as text.
  { value: R.eigenmodePhasesLaplaceLagrange.gamma8, label: `γ₈ = ${R.eigenmodePhasesLaplaceLagrange.gamma8}°` },
  { value: R.eigenmodePhasesLaplaceLagrange.gamma1, label: `γ₁ = ${R.eigenmodePhasesLaplaceLagrange.gamma1}°` },
  { value: R.eigenmodePhasesLaplaceLagrange.gamma3, label: `γ₃ = ${R.eigenmodePhasesLaplaceLagrange.gamma3}°` },
  { value: R.eigenmodePhasesLaplaceLagrange.gamma4, label: `γ₄ = ${R.eigenmodePhasesLaplaceLagrange.gamma4}°` },
  { value: R.eigenmodePhasesLaplaceLagrange.gamma6, label: `γ₆ = ${R.eigenmodePhasesLaplaceLagrange.gamma6}°` },
  { value: R.eigenmodePhasesLaplaceLagrange.gamma7, label: `γ₇ = ${R.eigenmodePhasesLaplaceLagrange.gamma7}°` },
  { value: R.eigenmodePhasesLaplaceLagrange.gamma2, label: `γ₂ = ${R.eigenmodePhasesLaplaceLagrange.gamma2}°` },
  { value: 'custom', label: 'Custom...' }
];

// --- C5b. JPL ecliptic inclination trend rates (°/century) ---
// Source: JPL Approximate Positions — https://ssd.jpl.nasa.gov/planets/approx_pos.html
// Target rates for model verification.
// Compared against the model's own computed trend (trendError, directionMatch)
// — never an input to it, hence REFERENCE_DATA.
const mercuryEclipticInclinationTrendJPL = R.jplEclipticInclinationTrends.mercury;  // degrees/century (DECREASING)
const venusEclipticInclinationTrendJPL = R.jplEclipticInclinationTrends.venus;      // degrees/century (DECREASING)
const marsEclipticInclinationTrendJPL = R.jplEclipticInclinationTrends.mars;        // degrees/century (DECREASING)
const jupiterEclipticInclinationTrendJPL = R.jplEclipticInclinationTrends.jupiter;  // degrees/century (DECREASING)
const saturnEclipticInclinationTrendJPL = R.jplEclipticInclinationTrends.saturn;    // degrees/century (INCREASING)
const uranusEclipticInclinationTrendJPL = R.jplEclipticInclinationTrends.uranus;    // degrees/century (DECREASING)
const neptuneEclipticInclinationTrendJPL = R.jplEclipticInclinationTrends.neptune;  // degrees/century (INCREASING)
const plutoEclipticInclinationTrendJPL = R.jplEclipticInclinationTrends.pluto;      // degrees/century (estimated)

// ─── C6. Astronomical reference object (ASTRO_REFERENCE) ─────────────────
// J2000 epoch values, year/day lengths, perihelion reference, Meeus
// coefficients, perihelion precession rates, and measurement offsets.
// ─────────────────────────────────────────────────────────────────────────
const ASTRO_REFERENCE = {
  // --- 8a. Earth J2000 reference values ---
  // Source: IAU 2006 precession model (Capitaine et al. 2003)
  //
  // §12e landed: the JSON is on IAU 2006 now, so these migrate at last —
  // the arcsec form is derived (deg × 3600) rather than a second literal.
  obliquityJ2000_arcsec: K.earthOrbital.obliquityJ2000_deg * 3600,   // ε₀ at J2000.0
  obliquityJ2000_deg: K.earthOrbital.obliquityJ2000_deg,             // = 23.439279°
  obliquityRate_arcsecPerCentury: K.earthOrbital.obliquityRate_arcsecPerCentury,
  obliquityRate_degPerCentury: K.earthOrbital.obliquityRate_arcsecPerCentury / 3600,  // = -0.013010°/century
  // Source: Astronomical Almanac, 1°34'43.3" at J2000.0, rate -18"/cy
  earthInclinationJ2000_deg: K.earthOrbital.earthInclinationJ2000_deg,
  earthInclinationRate_arcsecPerCentury: K.earthOrbital.earthInclinationRate_arcsecPerCentury,
  // Source: JPL Horizons / Astronomical Almanac
  eccentricityJ2000: K.earthOrbital.earthEccentricityJ2000,   // Earth eccentricity at J2000.0
  eccentricityDotJ2000: K.earthOrbital.earthEccentricityDotJ2000,  // Earth eccentricity rate at J2000 (per Julian cy) — secular-theory coefficient corroborated by modern ephemeris fits, the lunar node channel (doc 66 §1; v4 note: the old "s_Ω ≈ 1 measures ė" reading was superseded by the frame attribution — physical s_Ω = 0.867, effective 1.018), and the ancient timing record; not a raw observation. REFERENCE/Taylor-check anchor only: the shipped lunar channel does NOT consume it — the fully-derived H/3 fluctuation line PREDICTS −4.273e-5 (+1.7%; see _FW_ECC and docs/66 §1, incl. the falsified H/16-phase alternative −8.389e-6)
  eccentricityDotDotJ2000: K.earthOrbital.earthEccentricityDotDotJ2000,  // Earth eccentricity curvature at J2000 (per Julian cy²; 2× Meeus Eq. 25.4 T² coefficient). REFERENCE/Taylor-check anchor only — the derived H/3 line predicts −3.7e-8 (same sign; the documented divergence behind the drift meter's BCE M′/F rows)
  // Was the truncated literal 102.947 against the JSON's 102.94719 — 0.684"
  // apart. Not cosmetic: this feeds earthInvPlaneInclinationMean, the deep-time
  // inclination oscillation and the Meeus mean anomaly, and tools/lib computes
  // the same th0 = (periLong - inclinationCycleAnchor) from the FULL value. The
  // two engines therefore disagreed by 3.3e-6 in cos(th0). Importing adopts the
  // precise figure the JSON and the Node engine have always used.
  perihelionLongitudeJ2000_deg: K.earthOrbital.earthPerihelionLongitudeJ2000,  // Longitude of perihelion at J2000.0
  sunMeanLongitudeJ2000_deg: K.earthOrbital.sunMeanLongitudeJ2000_deg,  // Sun mean longitude at J2000.0 (D5 aberration anchor)
  elpW1T2Decomposition_arcsecPerCy2: {               // v4 K_PL budget primary sources (Chapront et al. 2002 + Lieske 1976) — consumed by the split Lp carriers
    // Three of the JSON block's six terms are used here; the tides* pair and
    // the IAU2006 variant are analysis-only (tools/explore/v4-kpl-budget.js).
    planetary: K.moonMeeus.elpW1T2Decomposition_arcsecPerCy2.planetary,
    earthFigureJ2: K.moonMeeus.elpW1T2Decomposition_arcsecPerCy2.earthFigureJ2,
    generalPrecessionPA_T2_Lieske1976: K.moonMeeus.elpW1T2Decomposition_arcsecPerCy2.generalPrecessionPA_T2_Lieske1976,
  },
  perihelionPassageJ2000_JD: K.earthOrbital.perihelionPassageJ2000_JD,  // Earth perihelion 2000 Jan 3 13:00 UTC (USNO)
  // Source: USNO / timeanddate.com
  juneSolstice2000_JD: K.earthOrbital.juneSolstice2000_JD,  // June 21, 2000 01:48 UTC

  // --- 8b. Model epoch offsets (June 21, 2000 00:00 UTC, JD 2451716.5) ---
  // Adjusted from J2000.0 for the 171.5 day offset (0.004696 centuries)
  modelEpochOffsetDays: startmodelJD - j2000JD,
  modelEpochOffsetCenturies: (startmodelJD - j2000JD) / julianCenturyDays,
  // Obliquity at model epoch: obliquityJ2000 + rate × offset ≈ 23.439218°
  get obliquityModelEpoch_arcsec() {
    return this.obliquityJ2000_arcsec + this.obliquityRate_arcsecPerCentury * this.modelEpochOffsetCenturies;
  },
  get obliquityModelEpoch_deg() {
    return this.obliquityModelEpoch_arcsec / 3600;   // ≈ 23.439218°
  },
  // Earth inclination at model epoch (change over 171.5 days is negligible)
  get earthInclinationModelEpoch_deg() {
    const changeArcsec = this.earthInclinationRate_arcsecPerCentury * this.modelEpochOffsetCenturies;
    return this.earthInclinationJ2000_deg + changeArcsec / 3600;  // ≈ 1.57869°
  },

  // --- 8c. Year & day lengths (J2000.0) ---
  // Source: Meeus & Savoie (1992) "The history of the tropical year"
  // Local names carry a `J2000` suffix the JSON keys do not — the suffix marks
  // these as the fixed J2000 anchors, distinct from the epoch-dependent values
  // recomputeEpochAnchors produces.
  tropicalYearVEJ2000: K.yearLengthRef.tropicalYearVE,        // Vernal Equinox to Vernal Equinox
  tropicalYearSSJ2000: K.yearLengthRef.tropicalYearSS,        // Summer Solstice to Summer Solstice
  tropicalYearAEJ2000: K.yearLengthRef.tropicalYearAE,        // Autumnal Equinox to Autumnal Equinox
  tropicalYearWSJ2000: K.yearLengthRef.tropicalYearWS,        // Winter Solstice to Winter Solstice
  tropicalYearMeanJ2000: meansolaryearlengthinDays,           // Mean tropical year at J2000.0 — derived from the sidereal year and p_A (plan 09; the alias name stays for its readers)
  tropicalYearRateSecPerCentury: K.yearLengthRef.tropicalYearRateSecPerCentury,  // Secular change in tropical year length
  // Source: JPL Horizons (the J2000 anomalistic year is _anomalisticYearJ2000Days(), the law of date at 2000)
  siderealYearJ2000: K.yearLengthRef.siderealYear,            // Fixed star reference (one complete orbit)
  // Source: IERS Conventions / IAU definitions.
  // THREE distinct day lengths exist in this model — SI 86400 (definition),
  // LOD_mean (the kinematic day, ω₀ at J2000) and LOD_real (physical). This is the SI one.
  solarDayJ2000: K.yearLengthRef.solarDay,                    // Mean solar day (SI definition)
  siderealDayJ2000: K.yearLengthRef.siderealDay,              // ~23h 56m 4.0905s
  stellarDayJ2000: K.yearLengthRef.stellarDay,                // ~23h 56m 4.0989s (slightly longer due to precession)

  // --- 8d. Lunar mean longitude coefficients (Meeus Ch. 47) ---
  // Used for lunar perturbation corrections (EoC, evection, variation, annual equation)
  moonMeanAnomalyJ2000_deg: K.moonMeeus.moonMeanAnomalyJ2000_deg,      // Moon's mean anomaly at J2000.0 (degrees)
  moonMeanAnomalyRate_degPerDay: K.moonMeeus.moonMeanAnomalyRate_degPerDay,  // Moon's mean anomaly rate (degrees/day)
  moonMeanElongationJ2000_deg: K.moonMeeus.moonMeanElongationJ2000_deg,      // Mean elongation Moon-Sun at J2000.0 (degrees)
  moonMeanElongationRate_degPerDay: K.moonMeeus.moonMeanElongationRate_degPerDay,  // Mean elongation rate (degrees/day)
  sunMeanAnomalyJ2000_deg: K.moonMeeus.sunMeanAnomalyJ2000_deg,        // Sun's mean anomaly at J2000.0 (degrees)
  sunMeanAnomalyRate_degPerDay: K.moonMeeus.sunMeanAnomalyRate_degPerDay,    // Sun's mean anomaly rate (degrees/day)
  moonArgLatJ2000_deg: K.moonMeeus.moonArgLatJ2000_deg,                // Moon's argument of latitude F at J2000.0 (degrees)
  moonArgLatRate_degPerCentury: K.moonMeeus.moonArgLatRate_degPerCentury,    // F rate (degrees/Julian century)
  moonMeanElongationJ2000Full_deg: K.moonMeeus.moonMeanElongationJ2000Full_deg,  // D at J2000.0 (full precision for latitude)
  moonMeanElongationRate_degPerCentury: K.moonMeeus.moonMeanElongationRate_degPerCentury,  // D rate (degrees/Julian century)

  // --- 8e. Perihelion precession rates (1900–2100 trend) ---
  // Source: JPL SPICE/WebGeoCalc. Fluctuate over time; not valid for long-term predictions.
  perihelionPrecessionRates: R.perihelionPrecessionRatesJPL,

  // --- 8f. Measurement offset corrections (derived from model geometry) ---
  // These offsets arise from measuring from Earth's precessing position rather
  // than from fixed reference points.

};

// The J2000 precession period is _certifiedAxialPrecessionJ2000Years(); the
// tropical year is DERIVED from the sidereal year and p_A, so sid/(sid − trop)
// = T_p counted in tropical years (25,772.13 — the same period as 25,771.58
// Julian years) closes by construction.

// ─── E. DERIVED CONSTANTS ───────────────────────────────────────────────
// Computed from foundational constants. Time units, EoC parameters,
// Moon cycles, speeds, and orbital distances.
// ─────────────────────────────────────────────────────────────────────────

// --- 9a. Time units & year lengths ---
let   meanearthRotationsinDays = meansolaryearlengthinDays+1;  // Phase 6: mutable (Tier 2)
// The phase origin is J2000 (plan 07 R10): balancedYear is 2000 by construction
// in all four runtimes; the variable name stays as the code's phase-origin.
let   balancedYear = 2000;   // Phase 6: mutable in name only — the dormant epoch updater re-sets it to 2000
const balancedJD = startmodelJD-(meansolaryearlengthinDays*(startmodelYear-balancedYear));
const perihelionalignmentJD = Math.round(startmodelJD - (meansolaryearlengthinDays * (startmodelYear - perihelionalignmentYear)));   // plan 11 step 5: on the epoch itself (the rounded day-0 moved one day with the correction's deletion)
// Perihelion-calendar walk-start hint (shared by dayToPerihelionCalendarDate
// and dateToPerihelionJulianDay — see the docstring there). Declared HERE
// because module-init code calls the converters long before their own
// declarations run (the C1 hover-TDZ class).
let _periCalHintYear = 0, _periCalHintDays = 0;
const yearsFromBalancedToJ2000 = (startmodelJD - balancedJD) / meansolaryearlengthinDays;
// Sidereal year in days at J2000 — the IAU input (365.256363004); the same
// value as meansiderealyearlengthinDays_kinematic below.
let   meansiderealyearlengthinDays = ASTRO_REFERENCE.siderealYearJ2000;  // Phase 1: mutable for deep-time mode
// Sidereal year in seconds at J2000 — the IAU input × the SI day.
let   meansiderealyearlengthinSeconds = ASTRO_REFERENCE.siderealYearJ2000 * SECONDS_PER_DAY; // (Phase 1: mutable for deep-time mode)
// The sidereal year in days at J2000 — the IAU input. A J2000 CONSTANT, not an
// epoch global: "kinematic" is not a code path but f(2000) (year/day plan §2c).
// At any other epoch the same quantity is `meansiderealyearlengthinDays`, which
// recomputeEpochAnchors fills from Layer 0. The identifier keeps its name for
// its readers.
const meansiderealyearlengthinDays_kinematic = ASTRO_REFERENCE.siderealYearJ2000;
// The J2000 day length ω₀ is the SI day (an input, 86,400 s). Twins: tools/lib
// constants.js meanLengthOfDay, model.js.
let   meanlengthofday = K.yearLengthRef.solarDay;  // Phase 1: mutable for deep-time mode

// The J2000 sidereal-year constant under its formula-site name (the one reader
// is the chart fallback's T_sid·(1 − 1/P)). A baseline that moves with scene
// state is the transparency violation (f(Y) must depend on Y alone — plan §5c).
const SIDEREAL_YEAR_DAYS_KINEMATIC_J2000 = meansiderealyearlengthinDays_kinematic;

// Module-load values of the seven epoch globals — what resetEpochToJ2000
// restores (R16). These are the FITTED kinematic constants the shipped
// coefficients were calibrated against; recomputeEpochAnchors(0) returns the
// deep-time chain's values instead, 118 ms away on the sidereal year (that gap
// is R1's fit basis and closes with the Phase C/D refit, not here). Snapshot
// taken here, after the last of the seven is initialised.
const _EPOCH_SEEDS_J2000 = Object.freeze({
  meanlengthofday, meansiderealyearlengthinSeconds,
  meansiderealyearlengthinDays, meansolaryearlengthinDays,
});

let   meanSiderealday = (meansolaryearlengthinDays/(meansolaryearlengthinDays+1))*meanlengthofday;  // Phase 6: mutable (Tier 2)
let   meanStellarday = NaN;  // Phase 6: mutable (Tier 2) — set by recomputeDerivedAnchorsForEpoch on the certified precession period (the Direct laws are not initialised at this line; no consumer reads it before that call)
// --- Coin rotation offsets (derived from day/year lengths and precession cycles) ---
// Perihelion coin rotation: the solar-day scan derives it from the displayed
// perihelion-of-date period, predictions.perihelionPrecession.
// Axial coin rotation: 1 extra sidereal day per precession period T_p. Set by
// recomputeDerivedAnchorsForEpoch — the Direct laws are not initialised at this
// line; no consumer reads it before.
let   axialCoinRotationMs = NaN;  // Phase 6: mutable (Tier 2)
let   axialCoinRotationYearlySeconds = NaN;  // Phase 6: mutable (Tier 2)

// ═══════════════════════════════════════════════════════════════════════════
// CANONICAL MEAN/REAL YEAR & DAY VARIABLES
//
// Three-dimensional disambiguation:
//   1. Value type:  MEAN (structural)  vs  REAL (measured, year-specific)
//   2. Time unit:   SEC (SI seconds)  vs  86400DAYS (SI-days)  vs  MEANLODDAYS  vs  REALLODDAYS
//   3. Time domain: year-invariant (MEAN)  vs  year-dependent (REAL, functions)
//
// Convention:
//   • MEAN_*_SEC = the J2000 constant in SI seconds (the IAU input × 86400).
//   • MEAN_*_86400DAYS = MEAN_*_SEC / 86400 (SI-day count, IAU convention).
//   • MEAN_*_MEANLODDAYS = MEAN_*_SEC / MEAN_LOD_SEC — ≡ the 86400DAYS form since
//     plan 09 (MEAN_LOD_SEC is the SI day); kept for its readers.
//   • real*86400Days(year), real*RealLodDays(year) = derived by division.
//   • realLodSec(year) = MEAN_LOD_SEC + tidal + GIA + ΔT residual (Bond+Hallstat).
//
// At J2000:
//   • MEAN_LOD_SEC              = 86,400 s (IAU sec / IAU days — plan 09, ONE J2000 day)
//   • MEAN_TROPICAL_YEAR_SEC    = 31,556,925.19 (= the IAU tropical mean × 86400)
//   • MEAN_SIDEREAL_YEAR_SEC    = 31,558,149.7635 (IAU × 86400, physical orbital period)
//   • MEAN_SIDEREAL_YEAR_86400DAYS = 365.256363 (IAU)
// ═══════════════════════════════════════════════════════════════════════════

const MEAN_TROPICAL_YEAR_SEC = meansolaryearlengthinDays * SECONDS_PER_DAY;                             // = 31,556,925.19 s (the IAU tropical mean × 86400)
const MEAN_SIDEREAL_YEAR_SEC = ASTRO_REFERENCE.siderealYearJ2000 * SECONDS_PER_DAY;                    // = 31,558,149.7635 s (IAU physical)
const MEAN_LOD_SEC = MEAN_SIDEREAL_YEAR_SEC / meansiderealyearlengthinDays_kinematic;         // = 86,400 s (IAU sec / IAU days, plan 09)

const MEAN_TROPICAL_YEAR_86400DAYS = MEAN_TROPICAL_YEAR_SEC / SECONDS_PER_DAY;                          // = the IAU tropical mean
const MEAN_TROPICAL_YEAR_MEANLODDAYS = MEAN_TROPICAL_YEAR_SEC / MEAN_LOD_SEC;                 // ≡ MEAN_TROPICAL_YEAR_86400DAYS (plan 09)
const MEAN_SIDEREAL_YEAR_86400DAYS = MEAN_SIDEREAL_YEAR_SEC / SECONDS_PER_DAY;                          // ≈ 365.256363 (IAU)
const MEAN_SIDEREAL_YEAR_MEANLODDAYS = MEAN_SIDEREAL_YEAR_SEC / MEAN_LOD_SEC;                 // ≡ MEAN_SIDEREAL_YEAR_86400DAYS (plan 09)

const MEAN_PRECESSION = MEAN_SIDEREAL_YEAR_SEC / (MEAN_SIDEREAL_YEAR_SEC - MEAN_TROPICAL_YEAR_SEC); // the J2000 axial precession period, years

// --- 9b. Equation of center (EoC) derived parameters ---
// Equation of center eccentricity — derived, not a free parameter.
// The off-center orbit geometry provides apparent speed variation with amplitude e_geom (first order).
// The explicit EoC adds 2·eoc. Total must equal Keplerian 2·e_real → eoc = e_real - e_geom/2.
// Unification: the static (J2000) value is e(J2000) − base'/2 — the same split
// the wheel applies dynamically (dynEcc − base'/2). Mirrors tools/lib/constants.js.
// Unification: the Sun node's EoC eccentricity is HALF the one law's e(t) (the
// geometric offset −e(t)·û(ϖ), animated every frame in moveModel, supplies the
// other half); this const is its J2000 value — moveModel overrides it per frame.
const eocEccentricity = K.earthOrbital.earthEccentricityJ2000 / 2;

// --- 9c. Speeds & distances ---
const speedofSuninKM = (currentAUDistance*2*Math.PI)/(meansiderealyearlengthinSeconds/60/60);

// Deep-time mode helpers. When DEEP_TIME_MODE_ENABLED is OFF (production parity),
// cardinal-scan approxJDs and the sidereal-day-LOD factor revert to pre-Phase-9
// epoch-local values. DEEP_TIME_MODE_ENABLED itself is declared later (line ~5530);
// these helper bodies resolve the flag at call time, so the forward reference is fine.
function _phase9YearToJDDays() {
  return DEEP_TIME_MODE_ENABLED ? SI_TROPICAL_YEAR_DAYS : meansolaryearlengthinDays;
}
function _phase9SiderealDayLODFactor() {
  return DEEP_TIME_MODE_ENABLED ? meanlengthofday : SECONDS_PER_DAY;
}

// --- 9d. Simulation time steps (fractions of a tropical year) ---
// sDay initial value uses the pre-Phase-9 epoch-local form. At J2000 the two
// formulas (`86400/(meansol×LOD)` vs `1/meansol`) are numerically equivalent
// to ~1e-14 because LOD ≈ 86400. After deep-time setEpoch, `recomputeTimeUnitsForEpoch`
// switches to the SI-anchored form when DEEP_TIME_MODE_ENABLED is true.
let   sDay = 1 / meansolaryearlengthinDays;
let   sYear = sDay*365;                           // Phase 6.7: mutable
let   sMonth = sDay*30;                           // Phase 6.7: mutable
let   sWeek = sDay*7;                             // Phase 6.7: mutable
let   sHour = sDay/24;                            // Phase 6.7: mutable
let   sMinute = sHour/60;                         // Phase 6.7: mutable
let   sSecond = sMinute/60;                       // Phase 6.7: mutable

// Phase 6.7 J2000 snapshots — used by speed-comparison logic at lines 7975-7997
// where dropdown options were captured at tweakpane construction (J2000 values).
// Each speed-button comparison checks `speedFact === SYEAR_J2000 * N` to stay
// consistent with the dropdown's frozen numeric values. The dropdown labels
// like "1 year/sec" semantically mean "1 modern tropical year" — the J2000
// snapshot preserves that intent at any epoch.
const SDAY_J2000    = sDay;
const SYEAR_J2000   = sYear;
const SMONTH_J2000  = sMonth;
const SWEEK_J2000   = sWeek;
const SHOUR_J2000   = sHour;
const SMINUTE_J2000 = sMinute;
const SSECOND_J2000 = sSecond;

const lightYear = speedOfLight*meanlengthofday*meansolaryearlengthinDays;
const sunOrbitPeriod = (lightYear*milkywayDistance*Math.PI*2)/(sunSpeed/60/60*meanlengthofday*meansolaryearlengthinDays);
const milkywayOrbitPeriod = (lightYear*greatattractorDistance*Math.PI*2)/(milkywaySpeed/60/60*meanlengthofday*meansolaryearlengthinDays);

// --- 9e. Moon derived cycles ---
// The Moon's J2000 periods on the IAU inputs (astro-reference moonReference):
// the sidereal month and the EQUINOX-OF-DATE apsidal and nodal precession
// periods (the legacy-'ICRF' input names); the star-referenced periods remove
// the equinox's own precession, 1/T_E = 1/T_I ∓ 1/T_p (perigee advances, node
// regresses), T_p the J2000 precession anchor in days (docs/66 §1 keeps the
// derivation record). ONE home since plan 13
// B3: @essrt/physics earth/mass-chain computeMoonPeriodsJ2000 — the anomalistic
// and nodal months are KINEMATIC consequences of sidereal + precession
// (1/T_ano = 1/T_M − 1/T_apsidalE, 1/T_nod = 1/T_M + 1/T_nodalE), the synodic
// month the beat with the sidereal year, the tropical month the sidereal month
// seen from the precessing equinox. The J2000 values below seed the mutable
// of-date globals (Phase 2 / 6.5: recomputeMoonAndAuForEpoch and the epoch
// orchestrators reassign them).
const AXIAL_PRECESSION_J2000_DAYS = (1296000 / K.earthOrbital.generalPrecessionJ2000_arcsecPerYr) * DAYS_PER_JULIAN_YEAR;
let   moonSiderealMonth = moonSiderealMonthInput;  // Phase 2: mutable
let   moonApsidalPrecessionindaysICRF = moonApsidalPrecessionDaysInputICRF;  // Phase 6.5: mutable (equinox of date)
let   moonNodalPrecessionindaysICRF = moonNodalPrecessionDaysInputICRF;  // Phase 6.5: mutable (equinox of date)
const _MOON_PERIODS_J2000 = computeMoonPeriodsJ2000({
  moonSiderealMonthDays: moonSiderealMonth,
  moonApsidalPrecessionDaysInput: moonApsidalPrecessionindaysICRF,
  moonNodalPrecessionDaysInput: moonNodalPrecessionindaysICRF,
  axialPrecessionJ2000Days: AXIAL_PRECESSION_J2000_DAYS,
  meanSiderealYearDays: meansiderealyearlengthinDays_kinematic,
  meanSolarYearDays: meansolaryearlengthinDays,
});
let   moonApsidalPrecessionindaysEarth = _MOON_PERIODS_J2000.moonApsidalPrecessionDaysEarth;  // Phase 2: mutable (star-referenced)
let   moonNodalPrecessionindaysEarth = _MOON_PERIODS_J2000.moonNodalPrecessionDaysEarth;  // Phase 2: mutable (star-referenced)
let   moonAnomalisticMonth = _MOON_PERIODS_J2000.moonAnomalisticMonthDays;  // Phase 2: mutable
let   moonNodalMonth = _MOON_PERIODS_J2000.moonNodalMonthDays;  // Phase 2: mutable
let   moonSynodicMonth = _MOON_PERIODS_J2000.moonSynodicMonthDays;  // Phase 2: mutable
let   moonTropicalMonth = _MOON_PERIODS_J2000.moonTropicalMonthDays;  // Phase 2: mutable
let   moonFullMoonCycleEarth = _MOON_PERIODS_J2000.moonFullMoonCycleEarthDays;  // Phase 6.5: mutable
let   moonFullMoonCycleICRF = _MOON_PERIODS_J2000.moonFullMoonCycleICRFDays;  // Phase 6.5: mutable — the precessing-frame partner (the OBSERVED supermoon cycle is the Earth-named 411.784 d)
let   moonApsidalMeetsNodalindays = _MOON_PERIODS_J2000.moonApsidalMeetsNodalDays;  // Phase 6.5: mutable
let   moonLunarLevelingCycleindays = _MOON_PERIODS_J2000.moonLunarLevelingCycleDays;  // Phase 6.5: mutable
let   moonDraconicYearICRF = _MOON_PERIODS_J2000.moonDraconicYearICRFDays;  // Phase 6.5: mutable — the mixed-frame partner (346.607 d; NOT the observable)
let   moonDraconicYearEarth = _MOON_PERIODS_J2000.moonDraconicYearEarthDays;  // Phase 6.5: mutable — THE OBSERVED ECLIPSE YEAR (346.620 d; removing one equinox turn compensates the mixed-frame intermediate above: ≡ tropical⊕of-date ≡ sidereal⊕star-referenced)
let   moonSpeed = (moonDistance*Math.PI*2)/(meansolaryearlengthinDays*(1/(meansolaryearlengthinDays/moonSiderealMonth)))/24;  // Phase 6.5: mutable

// ─── E2. Mass calculations ──────────────────────────────────────────────
// GM and mass for Sun, Earth, Moon, and all planets. Derived from
// Kepler's 3rd Law, DE440 mass ratios, and Moon orbital mechanics.
// ─────────────────────────────────────────────────────────────────────────

// --- E2a. Sun, Earth, Moon masses (Kepler's 3rd Law) ---
//
// Convention: For every planet we define TWO variants of the mass constants:
//   MASS_RATIO_SUN_<P>_SYSTEM, GM_<P>_SYSTEM, M_<P>_SYSTEM  (planet + moons)
//   MASS_RATIO_SUN_<P>_ALONE,  GM_<P>_ALONE,  M_<P>_ALONE   (planet only)
//
// SYSTEM is correct for orbital dynamics (Hill sphere, sphere of influence,
// N-body perturbations, balance/AMD calculations) — a distant body sees the
// planet+moons as one point mass.
//
// ALONE is correct for intrinsic body properties (surface gravity, escape
// velocity, density, Schwarzschild radius) — moons are too far from the
// planet's surface to contribute.
//
// For Mercury/Venus (no moons) SYSTEM = ALONE trivially.
// For Pluto (Charon = 10.85% of system) the two differ by 12% — the only
// case where the distinction is visible in the simulation panel.
//
// Order of computation: Earth/Moon → Sun. Kepler's 3rd law on Earth's orbit
// gives G(M_Sun + M_Earth), so GM_EARTH_ALONE must be known first to back
// it out of the Sun's GM derivation. See doc 24 for the universal
// mass-from-moon formula and per-planet verification.

// Gravitational constant (km³/(kg·s²))
// G_CONSTANT (6.6743e-20 km³/(kg·s²)) lives in section C3 "Deep-time physics anchors" near the top.

// Earth-Moon mass ratio (DE440 SPICE kernel: GM_E/GM_M = 81.30056816).
const MASS_RATIO_EARTH_MOON = K.physicalConstants.MASS_RATIO_EARTH_MOON;

// The J2000 mass chain — ONE home since plan 13 B3: @essrt/physics
// earth/mass-chain computeMassChainJ2000 (the package model and the Node
// constants module read the same function). Solar Δa correction for the
// Moon's apparent semi-major axis (doc 24): Δa = a_M × M_M/(M_E + M_M) × m
// ≈ 349 km; Kepler on the corrected Moon orbit → G(M_E + M_M); the DE440
// split → GM_E, GM_M; Kepler on Earth's orbit → G(M_☉ + M_E); minus GM_E →
// GM_☉ (the JPL/IAU convention; without the M+m correction GM_Sun is biased
// high by ~398,605 km³/s², 3 ppm — with it, JPL DE440 to ~0.07 ppm; the
// Sun-side analog is a "Kepler-effective AU" of AU − 149.77 km, doc 24).
const _MASS_CHAIN_J2000 = computeMassChainJ2000({
  moonDistanceKm: moonDistance, moonSiderealMonthDays: moonSiderealMonth,
  meanSiderealYearDays: meansiderealyearlengthinDays, meanLengthOfDaySeconds: meanlengthofday,
  massRatioEarthMoon: MASS_RATIO_EARTH_MOON, currentAUDistanceKm: AU_J2000_KM,
  gravitationalConstantKm3KgS2: G_CONSTANT,
});
let   moonOrbitalShift = _MASS_CHAIN_J2000.moonOrbitalShiftKm;  // Phase 2: mutable
let   moonDistanceCorrected = _MASS_CHAIN_J2000.moonDistanceCorrectedKm;  // Phase 2: mutable

// Earth-Moon SYSTEM gravitational parameter from Kepler on the Moon's orbit
const GM_EARTH_MOON_SYSTEM = _MASS_CHAIN_J2000.gmEarthMoonSystemKm3S2;
const GM_EARTH_SYSTEM = GM_EARTH_MOON_SYSTEM;  // alias for naming consistency
// Result: ~403,505 km³/s² (DE440 BODY3: 403,503.24, residual ~3.7 ppm)

// Earth ALONE (split from system via Earth/Moon mass ratio)
const GM_EARTH_ALONE = _MASS_CHAIN_J2000.gmEarthAloneKm3S2;
const M_EARTH_ALONE  = GM_EARTH_ALONE / G_CONSTANT;
// Result: ~398,602 km³/s² (DE440 BODY399: 398,600.44, residual ~3.7 ppm)

// Moon ALONE (split from system)
const GM_MOON_ALONE = _MASS_CHAIN_J2000.gmMoonAloneKm3S2;
const M_MOON_ALONE  = GM_MOON_ALONE / G_CONSTANT;
// Result: ~4,902.82 km³/s² (DE440 BODY301: 4902.800, residual ~3.7 ppm)

// Earth-Moon SYSTEM mass
const M_EARTH_SYSTEM = M_EARTH_ALONE + M_MOON_ALONE;

// Gravitational parameter of the Sun, M_Sun only (JPL/IAU convention) — the
// mass chain's Kepler on Earth's orbit minus GM_EARTH_ALONE (one home, above).
const GM_SUN_PLUS_EARTH = _MASS_CHAIN_J2000.gmSunPlusEarthKm3S2;
const GM_SUN = _MASS_CHAIN_J2000.gmSunKm3S2;
// Result: ~1.32712 × 10¹¹ km³/s² (JPL DE440: 132,712,440,042; residual 0.07 ppm)

// Sun's mass derived from gravitational parameter (kg)
const M_SUN = _MASS_CHAIN_J2000.sunMassKg;

// Mass ratios Sun/Earth — both variants
const MASS_RATIO_SUN_EARTH_ALONE  = M_SUN / M_EARTH_ALONE;    // ~332,945 (planet alone)
const MASS_RATIO_SUN_EARTH_SYSTEM = M_SUN / M_EARTH_SYSTEM;   // ~328,899 (Earth+Moon)

// --- E2b. Planetary mass ratios — DE440 SPICE kernel gm_de440.tpc ---
//
// For each planet: SYSTEM (BODY-i, planet + moons) and ALONE (BODY-iJ9,
// planet only). For orbital dynamics use _SYSTEM. For intrinsic body
// properties (surface gravity, escape velocity, density) use _ALONE.

// Mercury (no moons, SYSTEM = ALONE)
const MASS_RATIO_SUN_MERCURY_SYSTEM = K.physicalConstants.massRatioDE440.mercury;
const MASS_RATIO_SUN_MERCURY_ALONE  = MASS_RATIO_SUN_MERCURY_SYSTEM;
const GM_MERCURY_SYSTEM = GM_SUN / MASS_RATIO_SUN_MERCURY_SYSTEM;
const GM_MERCURY_ALONE  = GM_MERCURY_SYSTEM;
const M_MERCURY_SYSTEM  = GM_MERCURY_SYSTEM / G_CONSTANT;
const M_MERCURY_ALONE   = M_MERCURY_SYSTEM;

// Venus (no moons, SYSTEM = ALONE)
const MASS_RATIO_SUN_VENUS_SYSTEM = K.physicalConstants.massRatioDE440.venus;
const MASS_RATIO_SUN_VENUS_ALONE  = MASS_RATIO_SUN_VENUS_SYSTEM;
const GM_VENUS_SYSTEM = GM_SUN / MASS_RATIO_SUN_VENUS_SYSTEM;
const GM_VENUS_ALONE  = GM_VENUS_SYSTEM;
const M_VENUS_SYSTEM  = GM_VENUS_SYSTEM / G_CONSTANT;
const M_VENUS_ALONE   = M_VENUS_SYSTEM;

// Mars (Phobos/Deimos negligible, <1 ppm)
const MASS_RATIO_SUN_MARS_SYSTEM = K.physicalConstants.massRatioDE440.mars;
const MASS_RATIO_SUN_MARS_ALONE  = K.physicalConstants.massRatioDE440Alone.mars;
const GM_MARS_SYSTEM = GM_SUN / MASS_RATIO_SUN_MARS_SYSTEM;
const GM_MARS_ALONE  = GM_SUN / MASS_RATIO_SUN_MARS_ALONE;
const M_MARS_SYSTEM  = GM_MARS_SYSTEM / G_CONSTANT;
const M_MARS_ALONE   = GM_MARS_ALONE / G_CONSTANT;

// Jupiter (Galileans + small moons = 207 ppm of system)
const MASS_RATIO_SUN_JUPITER_SYSTEM = K.physicalConstants.massRatioDE440.jupiter;
const MASS_RATIO_SUN_JUPITER_ALONE  = K.physicalConstants.massRatioDE440Alone.jupiter;
const GM_JUPITER_SYSTEM = GM_SUN / MASS_RATIO_SUN_JUPITER_SYSTEM;
const GM_JUPITER_ALONE  = GM_SUN / MASS_RATIO_SUN_JUPITER_ALONE;
const M_JUPITER_SYSTEM  = GM_JUPITER_SYSTEM / G_CONSTANT;
const M_JUPITER_ALONE   = GM_JUPITER_ALONE / G_CONSTANT;

// Saturn (Titan + others = 247 ppm of system)
const MASS_RATIO_SUN_SATURN_SYSTEM = K.physicalConstants.massRatioDE440.saturn;
const MASS_RATIO_SUN_SATURN_ALONE  = K.physicalConstants.massRatioDE440Alone.saturn;
const GM_SATURN_SYSTEM = GM_SUN / MASS_RATIO_SUN_SATURN_SYSTEM;
const GM_SATURN_ALONE  = GM_SUN / MASS_RATIO_SUN_SATURN_ALONE;
const M_SATURN_SYSTEM  = GM_SATURN_SYSTEM / G_CONSTANT;
const M_SATURN_ALONE   = GM_SATURN_ALONE / G_CONSTANT;

// Uranus (major moons = 105 ppm of system)
const MASS_RATIO_SUN_URANUS_SYSTEM = K.physicalConstants.massRatioDE440.uranus;
const MASS_RATIO_SUN_URANUS_ALONE  = K.physicalConstants.massRatioDE440Alone.uranus;
const GM_URANUS_SYSTEM = GM_SUN / MASS_RATIO_SUN_URANUS_SYSTEM;
const GM_URANUS_ALONE  = GM_SUN / MASS_RATIO_SUN_URANUS_ALONE;
const M_URANUS_SYSTEM  = GM_URANUS_SYSTEM / G_CONSTANT;
const M_URANUS_ALONE   = GM_URANUS_ALONE / G_CONSTANT;

// Neptune (Triton + others = 210 ppm of system)
const MASS_RATIO_SUN_NEPTUNE_SYSTEM = K.physicalConstants.massRatioDE440.neptune;
const MASS_RATIO_SUN_NEPTUNE_ALONE  = K.physicalConstants.massRatioDE440Alone.neptune;
const GM_NEPTUNE_SYSTEM = GM_SUN / MASS_RATIO_SUN_NEPTUNE_SYSTEM;
const GM_NEPTUNE_ALONE  = GM_SUN / MASS_RATIO_SUN_NEPTUNE_ALONE;
const M_NEPTUNE_SYSTEM  = GM_NEPTUNE_SYSTEM / G_CONSTANT;
const M_NEPTUNE_ALONE   = GM_NEPTUNE_ALONE / G_CONSTANT;

// Pluto (Charon binary — ALONE differs from SYSTEM by 10.85%, visible in panel)
const MASS_RATIO_SUN_PLUTO_SYSTEM = K.physicalConstants.massRatioDE440.pluto;
const MASS_RATIO_SUN_PLUTO_ALONE  = K.physicalConstants.massRatioDE440Alone.pluto;
const GM_PLUTO_SYSTEM = GM_SUN / MASS_RATIO_SUN_PLUTO_SYSTEM;
const GM_PLUTO_ALONE  = GM_SUN / MASS_RATIO_SUN_PLUTO_ALONE;
const M_PLUTO_SYSTEM  = GM_PLUTO_SYSTEM / G_CONSTANT;
const M_PLUTO_ALONE   = GM_PLUTO_ALONE / G_CONSTANT;

// Ceres: Mass from Dawn spacecraft (2015-2018)
const GM_CERES = K.physicalConstants.smallBodyMasses.ceresGmKm3PerS2;  // km³/s² (Dawn radiometric tracking)
const M_CERES = GM_CERES / G_CONSTANT;               // ~9.38 × 10²⁰ kg

// Halley's Comet: Mass estimated from size (~11×8×8 km) and density (~0.6 g/cm³)
// No spacecraft has orbited it, so mass is approximate
const M_HALLEYS = K.physicalConstants.smallBodyMasses.halleysMassKg;   // ~2.2 × 10¹⁴ kg (estimated)
const GM_HALLEYS = M_HALLEYS * G_CONSTANT;           // ~1.47 × 10⁻⁵ km³/s²

// 433 Eros: Mass precisely measured by NEAR Shoemaker spacecraft (2000-2001)
const M_EROS = K.physicalConstants.smallBodyMasses.erosMassKg;         // 6.687 × 10¹⁵ kg (measured)
const GM_EROS = M_EROS * G_CONSTANT;                 // ~4.46 × 10⁻⁴ km³/s²

// ─── E2c. (a planet's inclination of date has one home, the N-body chain,
// _chainElementsOfDate; the SYSTEM/ALONE mass convention is doc 24's) ──────────

// ─── E2d. Wobble periods, obliquity cycles, and K-derived eccentricity ──
// Moved here (before scene geometry) so orbitalEccentricityBase is available
// for perihelion distance calculations at line ~2088.

// The eccentricity cycle period is the chain's OWN g-mode beat — the dominant
// mode × largest companion of the planet's eccentricity vector
// (keplerian-chain computeSecularShape, the panel's "Eccentricity Cycle
// (g-mode beat)" row; ONE home, both scene twins). A constant: the g-modes
// scale only with the solar mass (Driver 2), so the epoch recompute leaves
// these alone.
function calcWobblePeriod(planetKey) {
  return computeSecularShape(CHAIN_ARTIFACT, planetKey).beatYears;
}
const mercuryWobblePeriod  = calcWobblePeriod('mercury');
const venusWobblePeriod    = calcWobblePeriod('venus');
const marsWobblePeriod     = calcWobblePeriod('mars');
const jupiterWobblePeriod  = calcWobblePeriod('jupiter');
const saturnWobblePeriod   = calcWobblePeriod('saturn');
const uranusWobblePeriod   = calcWobblePeriod('uranus');
const neptuneWobblePeriod  = calcWobblePeriod('neptune');

// The K eccentricity law's obliquity input (Plan 06 Phase 7 commit 2): the
// spin channel's DERIVED J2000 obliquity — the IAU pole against the chain's
// J2000 plane (spin-channel computeObliquityJ2000Deg, no mode table, no
// integration) — in the acute form the law reads (sin|ε|; Venus 2.6°,
// Uranus 82.2°). The planets' obliquity OF DATE is computePlanetObliquity
// (the channel).
function calcObliquityMean(planetKey) {
  const A = CHAIN_ARTIFACT.j2000AnchorElements[planetKey];
  const eps = computeObliquityJ2000Deg({
    spin: K.planetSpinPhysical[planetKey],
    anchorInclEclipticDeg: A.inclEclipticDeg,
    anchorAscNodeEclipticDeg: A.ascNodeEclipticDeg,
    obliquityJ2000Deg: K.earthOrbital.obliquityJ2000_deg,
  });
  return Math.min(eps, 180 - eps);
}
const mercuryObliquityMean = calcObliquityMean('mercury');
const venusObliquityMean   = calcObliquityMean('venus');
const marsObliquityMean    = calcObliquityMean('mars');
const jupiterObliquityMean = calcObliquityMean('jupiter');
const saturnObliquityMean  = calcObliquityMean('saturn');
const uranusObliquityMean  = calcObliquityMean('uranus');
const neptuneObliquityMean = calcObliquityMean('neptune');

// A planet's eccentricity of date has ONE home, the chain:
// `_chainElementsOfDate(key, jd).e`.

// ─── E3. Orbital formulas ───────────────────────────────────────────────
// Pure helper functions for orbital mechanics. No model-specific state.
// Used by the About panel and orbital element displays.
// ─────────────────────────────────────────────────────────────────────────
const OrbitalFormulas = {
  // --- 11a. Kepler's equation & orbital elements ---

  // Solve Kepler's equation for Eccentric Anomaly using Newton-Raphson
  // M = E - e·sin(E)  →  solve for E given M and e
  // Input: M in degrees, e (eccentricity)
  // Output: E in degrees
  eccentricAnomaly: (M_deg, e) => {
    const M = M_deg * Math.PI / 180;
    let E = M; // Initial guess
    for (let i = 0; i < 30; i++) {
      const dE = (E - e * Math.sin(E) - M) / (1 - e * Math.cos(E));
      E -= dE;
      if (Math.abs(dE) < 1e-10) break;
    }
    return E * 180 / Math.PI;
  },

  // Mean motion in degrees per day
  // n = 360° / P
  meanMotion: (P_days) => 360 / P_days,

  // Semi-minor axis (AU)
  // b = a × √(1 - e²)
  semiMinorAxis: (a, e) => a * Math.sqrt(1 - e * e),

  // Perihelion distance (AU)
  // q = a × (1 - e)
  perihelionDist: (a, e) => a * (1 - e),

  // Aphelion distance (AU)
  // Q = a × (1 + e)
  aphelionDist: (a, e) => a * (1 + e),

  // Semi-latus rectum (AU)
  // p = a × (1 - e²)
  semiLatusRectum: (a, e) => a * (1 - e * e),

  // Focal distance (AU)
  // c = a × e
  focalDistance: (a, e) => a * e,

  // Heliocentric distance from true anomaly (AU)
  // r = a × (1 - e²) / (1 + e × cos(ν))
  heliocentricDist: (a, e, nu_deg) => {
    const nu = nu_deg * Math.PI / 180;
    return a * (1 - e * e) / (1 + e * Math.cos(nu));
  },

  // Flight path angle (degrees)
  // tan(γ) = e × sin(ν) / (1 + e × cos(ν))
  flightPathAngle: (e, nu_deg) => {
    const nu = nu_deg * Math.PI / 180;
    return Math.atan2(e * Math.sin(nu), 1 + e * Math.cos(nu)) * 180 / Math.PI;
  },

  // Mean longitude (degrees)
  // L = M + ϖ (mod 360°)
  meanLongitude: (M_deg, lonPerihelion_deg) => ((M_deg + lonPerihelion_deg) % 360 + 360) % 360,

  // True longitude (degrees)
  // λ = ν + ϖ (mod 360°)
  trueLongitude: (nu_deg, lonPerihelion_deg) => ((nu_deg + lonPerihelion_deg) % 360 + 360) % 360,

  // Argument of latitude (degrees)
  // u = ω + ν
  argumentOfLatitude: (omega_deg, nu_deg) => ((omega_deg + nu_deg) % 360 + 360) % 360,

  // Time since perihelion (days)
  // t = P × M / 360°
  timeSincePerihelion: (P_days, M_deg) => P_days * M_deg / 360,

  // Time to next perihelion (days)
  // t_next = P × (360° - M) / 360°
  timeToNextPerihelion: (P_days, M_deg) => P_days * (360 - M_deg) / 360,

  // Orbital velocity using vis-viva equation (km/s)
  // v = √(GM × (2/r - 1/a))
  // Input: r in km, a in km, GM in km³/s² (defaults to GM_SUN)
  orbitalVelocity: (r_km, a_km, GM = GM_SUN) => {
    return Math.sqrt(GM * (2 / r_km - 1 / a_km));
  },

  // Perihelion velocity (km/s)
  // v_p = √(GM × (1 + e) / (a × (1 - e)))
  perihelionVelocity: (a_km, e, GM = GM_SUN) => {
    return Math.sqrt(GM * (1 + e) / (a_km * (1 - e)));
  },

  // Aphelion velocity (km/s)
  // v_a = √(GM × (1 - e) / (a × (1 + e)))
  aphelionVelocity: (a_km, e, GM = GM_SUN) => {
    return Math.sqrt(GM * (1 - e) / (a_km * (1 + e)));
  },

  // Specific orbital energy (km²/s²)
  // ε = -GM / (2a)
  specificEnergy: (a_km, GM = GM_SUN) => {
    return -GM / (2 * a_km);
  },

  // Specific angular momentum (km²/s)
  // h = √(GM × a × (1 - e²))
  specificAngularMomentum: (a_km, e, GM = GM_SUN) => {
    return Math.sqrt(GM * a_km * (1 - e * e));
  },

  // Radial velocity (km/s)
  // v_r = √(GM/p) × e × sin(ν)
  // where p = a(1-e²) is the semi-latus rectum
  radialVelocity: (a_km, e, nu_deg, GM = GM_SUN) => {
    const nu = nu_deg * Math.PI / 180;
    const p = a_km * (1 - e * e);
    return Math.sqrt(GM / p) * e * Math.sin(nu);
  },

  // Transverse velocity (km/s)
  // v_t = √(GM/p) × (1 + e × cos(ν))
  // where p = a(1-e²) is the semi-latus rectum
  transverseVelocity: (a_km, e, nu_deg, GM = GM_SUN) => {
    const nu = nu_deg * Math.PI / 180;
    const p = a_km * (1 - e * e);
    return Math.sqrt(GM / p) * (1 + e * Math.cos(nu));
  },

  // Escape velocity at distance r from primary (km/s)
  // v_esc = √(2GM/r)
  escapeVelocity: (r_km, GM = GM_SUN) => Math.sqrt(2 * GM / r_km),

  // Circular orbit velocity at distance r (km/s)
  // v_circ = √(GM/r)
  circularVelocity: (r_km, GM = GM_SUN) => Math.sqrt(GM / r_km),

  // Velocity ratio (current velocity / circular velocity)
  // Shows orbital dynamics: >1 near perihelion, <1 near aphelion, =√2 at escape
  velocityRatio: (v_km_s, r_km, GM = GM_SUN) => v_km_s / Math.sqrt(GM / r_km),

  // Heliocentric latitude (degrees)
  // sin(β) = sin(i) × sin(u) where u = ω + ν
  heliocentricLatitude: (inclination_deg, omega_deg, nu_deg) => {
    const i = inclination_deg * Math.PI / 180;
    const u = (omega_deg + nu_deg) * Math.PI / 180;
    return Math.asin(Math.sin(i) * Math.sin(u)) * 180 / Math.PI;
  },

  // True anomaly rate (degrees/day)
  // dν/dt = n × (1 + e×cos(ν))² / (1 - e²)^(3/2)
  // Fastest at perihelion, slowest at aphelion
  trueAnomalyRate: (n_deg_day, e, nu_deg) => {
    const nu = nu_deg * Math.PI / 180;
    const factor = Math.pow(1 + e * Math.cos(nu), 2) / Math.pow(1 - e * e, 1.5);
    return n_deg_day * factor;
  },

  // Eccentric anomaly rate (degrees/day)
  // dE/dt = n / (1 - e×cos(E))
  eccentricAnomalyRate: (n_deg_day, e, E_deg) => {
    const E = E_deg * Math.PI / 180;
    return n_deg_day / (1 - e * Math.cos(E));
  },

  // Area sweep rate (km²/s) - Kepler's 2nd Law
  // dA/dt = h/2 (constant throughout orbit)
  areaSweepRate: (a_km, e, GM = GM_SUN) => OrbitalFormulas.specificAngularMomentum(a_km, e, GM) / 2,

  // Synodic period between any two planets (days)
  // P_syn = |P₁ × P₂ / (P₁ - P₂)|
  synodicPeriod: (P1_days, P2_days) => {
    if (P1_days === P2_days) return Infinity;
    return Math.abs(P1_days * P2_days / (P1_days - P2_days));
  },

  // Phase angle between two planets (degrees, 0-180)
  // Angular separation as seen from Sun
  phaseAngle: (lambda1_deg, lambda2_deg) => {
    let diff = Math.abs(lambda1_deg - lambda2_deg);
    if (diff > 180) diff = 360 - diff;
    return diff;
  },

  // Radius of curvature (km)
  // ρ = p × (1 + e² + 2e×cos(ν))^(3/2) / (1 + e×cos(ν))²
  radiusOfCurvature: (a_km, e, nu_deg) => {
    const p = a_km * (1 - e * e);
    const nu = nu_deg * Math.PI / 180;
    const cosNu = Math.cos(nu);
    const numerator = Math.pow(1 + e*e + 2*e*cosNu, 1.5);
    const denominator = Math.pow(1 + e*cosNu, 2);
    return p * numerator / denominator;
  },

  // Velocity ratio at perihelion vs aphelion
  // v_p/v_a = (1 + e) / (1 - e)
  velocityRatioPeriApo: (e) => (1 + e) / (1 - e),

  // Distance ratio aphelion vs perihelion
  // Q/q = (1 + e) / (1 - e)
  distanceRatioApoPerip: (e) => (1 + e) / (1 - e),

  // Kepler's 3rd Law: Orbital period from semi-major axis
  // P = 2π√(a³/GM) - returns days
  //
  // Default GM is GM_SUN_PLUS_EARTH — the SYSTEM gravitational parameter that
  // anchors the model's AU via 4π²·meanAU³ = (GM_Sun + GM_Earth_alone)·sidYearSec².
  // Using the system mass for every planet makes Kepler verification exact.
  //
  // Algebraic identity (see doc 24): this simple form is identically equal to
  // the elaborate two-body Kepler formula
  //   T = 2π · √( (a − Δa)³ / (GM_Sun + GM_Earth − GM_body) )
  // when Δa = a · (1 − ((μ_S + μ_E − μ_b)/(μ_S + μ_E))^(1/3)).
  // The (a−Δa)³ numerator and (GM_sys − GM_body) denominator cancel by
  // construction. No Δa is computed here; the simple form captures the same
  // physics in one line.
  //
  // By default a year-frame compensation factor (solar/sidereal) is applied
  // to reconcile the model's dual year-frame chain:
  //   - GM_SUN_PLUS_EARTH is derived using the sidereal year (4π²·meanAU³/sidYearSec²)
  //   - Planet orbit distances are derived using the solar year
  // Without this factor, every planet's T_kepler would be sid/solar ≈ 1.0000388
  // times its actual input period — the residual T/(T-T_solar) ≈ T_p (Earth's
  // precession period) would appear uniformly. The compensation hides this
  // dual-frame artifact so verification reads as expected.
  //
  // Every planet (including Earth) uses the compensation so all verifications
  // sit in the same solar-year frame. Set applyYearCompensation = false only
  // when the bare sidereal year is wanted explicitly.
  keplerPeriod: (a_km, GM = GM_SUN_PLUS_EARTH, applyYearCompensation = true) => {
    const P_seconds = 2 * Math.PI * Math.sqrt(Math.pow(a_km, 3) / GM);
    const compensation = applyYearCompensation
      ? (meansolaryearlengthinDays / meansiderealyearlengthinDays)
      : 1;
    return (P_seconds / meanlengthofday) * compensation;
  },

  // Hill Sphere Radius (km)
  // r_Hill = a × (m / 3M)^(1/3)
  // Region where body's gravity dominates over the primary's gravity
  // Satellites must orbit within this radius to remain bound
  hillSphereRadius: (a_km, m_body, M_primary) => {
    return a_km * Math.pow(m_body / (3 * M_primary), 1/3);
  },

  // Sphere of Influence - Laplace definition (km)
  // r_SOI = a × (m / M)^(2/5)
  // Region where body's gravitational influence exceeds perturbation from primary
  // Used in patched conic approximation for spacecraft trajectories
  sphereOfInfluence: (a_km, m_body, M_primary) => {
    return a_km * Math.pow(m_body / M_primary, 2/5);
  },

  // Lagrange L1/L2 Distance from smaller body (km) - approximate
  // Same formula as Hill sphere: r_L1 ≈ r_L2 ≈ a × (m / 3M)^(1/3)
  // L1 is between the bodies, L2 is on the far side (unstable equilibrium points)
  lagrangeL1L2Distance: (a_km, m_body, M_primary) => {
    return a_km * Math.pow(m_body / (3 * M_primary), 1/3);
  },

  // Earth-Moon Barycenter distance from Earth center (km)
  // d_bary = moonDistance / (1 + mass_ratio)
  // Result: ~4,670 km (inside Earth, which has radius ~6,371 km)
  barycenterDistance: (moonDist_km, massRatio) => {
    return moonDist_km / (1 + massRatio);
  },

  // Schwarzschild Radius (km) - theoretical
  // r_s = 2GM / c²
  // The radius at which escape velocity equals speed of light
  // If all mass were compressed within this radius, it would form a black hole
  schwarzschildRadius: (GM) => {
    return 2 * GM / (speedOfLight * speedOfLight);
  },

  // Tidal Force Ratio (dimensionless)
  // Compares tidal force from body1 vs body2 at given distances
  // F_ratio = (M1 / M2) × (r2 / r1)³
  // For Sun/Moon on Earth: ~0.46 (Sun's tidal force is ~46% of Moon's)
  tidalForceRatio: (M1, M2, r1_km, r2_km) => {
    return (M1 / M2) * Math.pow(r2_km / r1_km, 3);
  },

  // Gravitational Potential at distance r (km²/s²)
  // Φ = -GM/r
  // Gravitational potential energy per unit mass at distance r
  gravitationalPotential: (GM, r_km) => {
    return -GM / r_km;
  },

  // Surface Gravity (m/s²)
  // g = GM / R²
  // Gravitational acceleration at the surface
  surfaceGravity: (GM_km3_s2, R_km) => {
    // GM in km³/s², R in km, result in m/s²
    return GM_km3_s2 / (R_km * R_km) * 1000;  // Convert km/s² to m/s²
  },

  // Surface Escape Velocity (km/s)
  // v_esc = √(2GM/R)
  // Minimum velocity needed to escape from the surface
  surfaceEscapeVelocity: (GM, R_km) => {
    return Math.sqrt(2 * GM / R_km);
  },

  // Mean Density (kg/m³)
  // ρ = M / V = 3M / (4πR³)
  // Average density of the body
  meanDensity: (M_kg, R_km) => {
    const R_m = R_km * 1000;
    const V = (4/3) * Math.PI * Math.pow(R_m, 3);
    return M_kg / V;
  },

  // Orbital Energy Ratio (dimensionless)
  // ratio = r/a - shows position relative to semi-major axis
  // < 1: closer than semi-major axis (moving toward aphelion)
  // = 1: at semi-major axis distance
  // > 1: farther than semi-major axis (moving toward perihelion)
  orbitalEnergyRatio: (r_km, a_km) => r_km / a_km,

  // Tidal Acceleration (m/s²)
  // a_tidal = 2 × GM × Δr / r³
  // Differential gravitational acceleration across an extended body
  tidalAcceleration: (GM, r_km, delta_r_km) => {
    return 2 * GM * delta_r_km / Math.pow(r_km, 3) * 1000;  // Convert to m/s²
  },

  // Semi-major Axis from Period (km)
  // a = (GM × P² / 4π²)^(1/3)
  // Inverse of Kepler's 3rd Law
  semiMajorAxisFromPeriod: (P_seconds, GM) => {
    return Math.pow(GM * P_seconds * P_seconds / (4 * Math.PI * Math.PI), 1/3);
  },

  // Mean Motion from GM (rad/s)
  // n = √(GM / a³)
  // Angular velocity in radians per second
  meanMotionFromGM: (GM, a_km) => Math.sqrt(GM / Math.pow(a_km, 3)),

  // --- 11b. Precession & Newtonian dynamics ---

  // Precession rate from precession period (arcsec/century)
  // Rate = 360° × 3600"/° × 100 years / Period_years = 129,600,000 / Period_years
  precessionRateFromPeriod: (period_years) => {
    if (!isFinite(period_years) || period_years === 0) return 0;
    return 129600000 / period_years;
  },

  // Precession period from rate (years for full 360° cycle)
  // Period = 129,600,000 / Rate_arcsec_per_century
  precessionPeriodFromRate: (arcsec_per_century) => {
    if (!isFinite(arcsec_per_century) || arcsec_per_century === 0) return Infinity;
    return 129600000 / arcsec_per_century;
  },

  // Convert precession against Ecliptic to precession against ICRF
  // From ω_ICRF = ω_ecl - ω_ref → T_ICRF = (T_ecl × T_ref) / (T_ref - T_ecl)
  // Reference is typically the axial precession period T_p (general precession)
  precessionEclipticToICRF: (ecliptic_years, reference_years) => {
    const diff = reference_years - ecliptic_years;
    if (diff === 0) return Infinity;
    return (ecliptic_years * reference_years) / diff;
  },

  // Convert precession against ICRF to precession against Ecliptic
  // Inverse transformation: ecliptic = (ICRF × reference) / (ICRF + reference)
  precessionICRFToEcliptic: (ICRF_years, reference_years) => {
    const sum = ICRF_years + reference_years;
    if (sum === 0) return Infinity;
    return (ICRF_years * reference_years) / sum;
  },

  // Ratio of Earth Fundamental Cycle to precession period
  // Shows resonance structure in Newtonian precession (e.g., Mars = 4, Earth = 3)
  holisticPrecessionRatio: (precession_period, holistic_year) => {
    if (precession_period === 0) return Infinity;
    return holistic_year / precession_period;
  },

  // Precession period from Earth Fundamental Cycle ratio
  // period in years
  precessionFromHolisticRatio: (holistic_year, ratio) => {
    if (ratio === 0) return Infinity;
    return holistic_year / ratio;
  },

  // Precession angular velocity (rad/year) from arcsec/century
  // Converts observational units to angular velocity
  precessionAngularVelocity: (arcsec_per_century) => {
    // 1 arcsec = π/(180×3600) rad, 1 century = 100 years
    return (arcsec_per_century / 100) * (Math.PI / 648000);
  },

  // Newtonian perturbation strength estimate (dimensionless)
  // Shows relative influence of perturbing planet on another
  // strength = (m_perturber/M_sun) × (a_inner/a_outer)²
  perturbationStrength: (a_planet_km, a_perturber_km, m_perturber, M_sun) => {
    const ratio = a_planet_km < a_perturber_km
      ? Math.pow(a_planet_km / a_perturber_km, 2)
      : Math.pow(a_perturber_km / a_planet_km, 2);
    return (m_perturber / M_sun) * ratio;
  },

  // Precession ratio between two planets
  // Useful for identifying resonance patterns
  precessionRatio: (rate1_arcsec, rate2_arcsec) => {
    if (rate2_arcsec === 0) return Infinity;
    return rate1_arcsec / rate2_arcsec;
  },

  // Decompose total precession into ecliptic and perturbation components
  // Returns object with total, ecliptic contribution, and planetary perturbations
  precessionDecomposition: (total_arcsec, ecliptic_contribution_arcsec) => {
    return {
      total: total_arcsec,
      ecliptic: ecliptic_contribution_arcsec,
      perturbations: total_arcsec - ecliptic_contribution_arcsec
    };
  },

  // Format a period's ratio to the frozen clock's anchor interval as a readable
  // fraction (e.g., "anchor interval / 4" for ratio=4). Plan 06 Phase 4d: the
  // interval is the correction bases' unit, named as such — not a cycle.
  holisticRatioDescription: (ratio) => {
    if (!isFinite(ratio) || ratio === 0) return 'N/A';
    const absRatio = Math.abs(ratio);
    const sign = ratio < 0 ? ' (retrograde)' : '';
    // Check if it's close to an integer
    if (Math.abs(absRatio - Math.round(absRatio)) < 0.01) {
      const n = Math.round(absRatio);
      if (n === 1) return `= anchor interval${sign}`;
      return `= anchor interval / ${n}${sign}`;
    }
    return `≈ anchor interval / ${absRatio.toFixed(2)}${sign}`;
  },

  // --- 11c. Precession breakdown (Lagrange-Laplace secular theory) ---

  // Laplace coefficient b_{3/2}^{(1)}(α) - for outer perturber on inner planet
  // Computed using numerical integration of the defining integral:
  //   b_s^j(α) = (1/π) × ∫₀^(2π) cos(jψ) / (1 - 2α cos(ψ) + α²)^s dψ
  // This is more accurate than series expansion for larger α values (e.g., Venus α=0.54)
  // Reference: Murray & Dermott (1999), Solar System Dynamics, Chapter 7
  laplaceCoefficient_3_2_1: (alpha) => {
    // Numerical integration with 1000 steps (accurate to <0.1%)
    const steps = 1000;
    const dPsi = (2 * Math.PI) / steps;
    let sum = 0;

    for (let i = 0; i < steps; i++) {
      const psi = i * dPsi;
      const cosPsi = Math.cos(psi);
      const denom = Math.pow(1 - 2 * alpha * cosPsi + alpha * alpha, 1.5);
      sum += cosPsi / denom;
    }

    return sum * dPsi / Math.PI;
  },

  // Laplace coefficient b_{3/2}^{(2)}(α) - for inner perturber on outer planet
  // Computed using numerical integration with j=2:
  //   b_s^j(α) = (1/π) × ∫₀^(2π) cos(jψ) / (1 - 2α cos(ψ) + α²)^s dψ
  // Used when calculating perturbation from an INNER planet
  laplaceCoefficient_3_2_2: (alpha) => {
    const steps = 1000;
    const dPsi = (2 * Math.PI) / steps;
    let sum = 0;

    for (let i = 0; i < steps; i++) {
      const psi = i * dPsi;
      const cosPsi = Math.cos(psi);
      const cos2Psi = Math.cos(2 * psi);
      const denom = Math.pow(1 - 2 * alpha * cosPsi + alpha * alpha, 1.5);
      sum += cos2Psi / denom;
    }

    return sum * dPsi / Math.PI;
  },

  // Eccentricity correction factor for precession (first-order)
  // For first-order secular theory, this is negligible (~2% for Mercury)
  // Full formula from disturbing function: f(e) ≈ 1 + (1/2)e² + O(e⁴)
  // Reference: PERIHELION_PRECESSION_CORRECTED.md
  eccentricityCorrectionFactor: (e_planet, e_perturber) => {
    // Simplified first-order correction - negligible for most planets
    // Setting to 1.0 matches the corrected document which doesn't use this
    return 1.0;
  },

  // Mutual inclination between two orbital planes (degrees)
  // cos(I_mutual) = cos(i₁)cos(i₂) + sin(i₁)sin(i₂)cos(ΔΩ)
  mutualInclination: (i1_deg, i2_deg, deltaOmega_deg) => {
    const i1 = i1_deg * Math.PI / 180;
    const i2 = i2_deg * Math.PI / 180;
    const dO = deltaOmega_deg * Math.PI / 180;
    const cosI = Math.cos(i1) * Math.cos(i2) + Math.sin(i1) * Math.sin(i2) * Math.cos(dO);
    return Math.acos(Math.max(-1, Math.min(1, cosI))) * 180 / Math.PI;
  },

  // Inclination correction factor for precession
  // g(I) = cos(I_mutual) - reduces in-plane perturbation
  inclinationCorrectionFactor: (i_mutual_deg) => {
    return Math.cos(i_mutual_deg * Math.PI / 180);
  },

  // Mean motion in rad/year from orbital period in days
  meanMotionRadPerYear: (period_days) => {
    const period_years = period_days / DAYS_PER_JULIAN_YEAR;
    return (2 * Math.PI) / period_years;
  },

  // Secular precession contribution from ONE perturber (arcsec/century)
  // Implements Lagrange-Laplace first-order secular perturbation theory.
  //     A_ii = Σ(j≠i) (n_i/4) × ε_ij × α_ij × ᾱ_ij × b₃/₂⁽¹⁾(α_ij)
  // Where:
  //   ε_ij = m_j / M_sun
  //   α_ij = min(a_i, a_j) / max(a_i, a_j) (always ≤ 1)
  //   ᾱ_ij = α_ij if j is outer of i (α × ᾱ = α²)
  //          1    if j is inner of i (α × ᾱ = α)
  //   b₃/₂⁽¹⁾(α) = Laplace coefficient — ALWAYS this one for the diagonal
  //                self-precession rate.  b₃/₂⁽²⁾ appears only in the
  //                off-diagonal A_ij terms (eigenvector mixing), which we
  //                don't use for the per-planet precession display.
  // All contributions are POSITIVE: the diagonal self-precession rate is
  // prograde for every perturber.  (An earlier version negated inner
  // perturbers; that was a confusion with the off-diagonal A_ij formula.)
  // Reference: Murray & Dermott (1999) §7.4, eq 7.138.
  secularPrecessionContribution: (
    n_rad_per_year,       // Mean motion of perturbed planet (rad/year)
    m_perturber,          // Mass of perturbing planet (kg)
    M_sun,                // Mass of Sun (kg)
    a_planet_km,          // Semi-major axis of perturbed planet (km)
    a_perturber_km,       // Semi-major axis of perturbing planet (km)
    e_planet,             // Eccentricity of perturbed planet
    e_perturber,          // Eccentricity of perturbing planet
    i_planet_deg,         // Ecliptic inclination of perturbed planet (degrees)
    i_perturber_deg,      // Ecliptic inclination of perturbing planet (degrees)
    deltaOmega_deg        // Difference in ascending node longitudes (degrees)
  ) => {
    const isOuter = a_perturber_km > a_planet_km;

    // α = a_inner / a_outer (always < 1)
    const alpha = isOuter
      ? a_planet_km / a_perturber_km
      : a_perturber_km / a_planet_km;

    // ᾱ = a_planet / a_perturber for outer, or 1 for inner perturber
    const alpha_bar = isOuter
      ? a_planet_km / a_perturber_km  // Same as α for outer perturber
      : 1;                             // 1 for inner perturber

    // Diagonal A_ii secular contributions always use b₃/₂⁽¹⁾(α) —
    // for both inner and outer perturbers.  The shape difference comes
    // from the α · ᾱ prefactor above, not from switching Laplace orders.
    const laplace = OrbitalFormulas.laplaceCoefficient_3_2_1(alpha);

    // Mass ratio ε = m_perturber / M_sun
    const massRatio = m_perturber / M_sun;

    // Base secular precession rate (rad/year).  Laplace-Lagrange first-order
    // secular theory, diagonal A_ii contribution:
    //
    //   For EXTERIOR perturber:  dω/dt = (n/4) × ε × α² × b₃/₂⁽¹⁾(α)
    //   For INTERIOR perturber:  dω/dt = (n/4) × ε × α  × b₃/₂⁽¹⁾(α)
    //
    // Both use the SAME Laplace coefficient b₃/₂⁽¹⁾; the α-vs-α² difference
    // is the α·ᾱ prefactor computed above.  Both contribute prograde (+),
    // no sign flip.
    //
    // Eccentricity and inclination corrections are negligible at first order
    // (~2–5 % for Mercury, within the method's ~4 % expected accuracy).
    const rate_rad_per_year = 0.25 * n_rad_per_year * massRatio * alpha * alpha_bar * laplace;

    // Convert rad/year to arcsec/century (1 rad = 206264.806 arcsec).
    const arcsec_per_century = rate_rad_per_year * 206264.806 * 100;

    return arcsec_per_century;
  }
};

