  '<div style="margin-top:3px;color:rgba(254,170,13,.35);font-size:8px;line-height:1;">&#9660;</div>';
const periLabelObj = new CSS2DObject(periLabelDiv);
periLabelObj.position.set(0, 0.08, 0);
