scene.add(sceneObjects.constellations);
// we can add other fixed objects over here later on. e.g.
//scene.add(sceneObjects.blackholes);

// --- Create Starfield ---
createStarfield();
// The star and constellation catalogs are J2000 RA/Dec: align their containers
// ONCE to the J2000 equatorial frame through the world frame — the frame the
// first _applyEngineEarthFrame places before the series artifact arrives (the
// Earth axis then precesses against this fixed sky, as it did under the
// scaffold). The axis's rest pose is 0 and the engine places it only at the
// first update, AFTER this alignment — so the alignment must build the frame
// itself (measured on the pre-fix build: pole tilt 23.44° and equinox offset
// 68.23° missing — the Sun read ~160° against the constellations at the
// June-solstice epoch where it belongs at RA 90°). Gate: perihelion-at-sun's
// star-field rows.
{
  const R0 = computeSceneWorldFrameJ2000();
  const F0 = computeEarthFrameOfDate(_CHAIN_J2000_REST_SAMPLE);
  const toW = (v) => new THREE.Vector3(R0[0][0] * v[0] + R0[0][1] * v[1] + R0[0][2] * v[2], R0[1][0] * v[0] + R0[1][1] * v[1] + R0[1][2] * v[2], R0[2][0] * v[0] + R0[2][1] * v[1] + R0[2][2] * v[2]);
  const s0 = toW(F0.s), g0 = toW(F0.g);
  _chainSetWorldRotation(earth.rotationAxis, new THREE.Vector3().crossVectors(s0, g0), s0, g0);
}
scene.updateMatrixWorld();
sceneObjects.stars.applyMatrix4(earth.rotationAxis.matrixWorld);
sceneObjects.stars.visible = true;

