// ═══════════════════════════════════════════════════════════════════════
// PLANET INSPECTOR (plan 06 R10) — the orbit of date from the N-body chain
// ═══════════════════════════════════════════════════════════════════════
// One view per planet, everything from the chain the scene renders:
// elements of date via _chainElementsOfDate at o.julianDay, heliocentric points
// via _chainHelioAU through the frame bridge _chainR, the rendered ecliptic of date
// (the sun-plane container's pole n̂ and equinox ĝ — R4). The visual (the
// former "Step 4", the part worth keeping): the actual chain orbit fanned
// from the Sun, green above / red below the ecliptic of date, its ascending
// and descending nodes and its highest and lowest points found ON that orbit,
// the perihelion point from the chain's ϖ with the Sun→perihelion line, the
// Sun→planet line, the true anomaly ν swept at the Sun and the chain's mean
// anomaly M beside it. The position report (vs the NASA/JPL test dates)
// stays, on demand.
const hierarchyInspector = {
  panel: null,
  currentPlanet: 'mercury',
  highlightActive: false,
  showAllResults: false,
  // Camera: while active the animation loop follows _cameraTarget (an
  // Object3D — the Sun mesh for the orbit view, the planet mesh for the
  // planet view) instead of o.lookAtObj.
  _cameraControlActive: false,
  _cameraTarget: null,
  _lastTargetPos: null,     // the target's last world position — the loop translates the camera by its displacement
  helpers: {
    showInclinationPlane: true,   // orbit fan, nodes, extremes, ecliptic ring
    showPerihelion: true,         // perihelion point + Sun→perihelion line
    showAnomalies: true,          // Sun→planet line, ν and M arcs
    showLocator: true,            // cyan ring around the rendered planet
  },
  group: null,          // THREE.Group in WORLD coordinates; all helper meshes
  parts: null,          // named handles into `group` (built per planet)
  _frame: null,         // the per-frame orbit frame (pooled vectors)
  _orbitSampleJD: null, // epoch of the last orbit resample
  _orbitSampleMs: 0,
  _els: null,           // cached readout DOM elements (per planet)
  _lastReadoutJD: null,
  _lastReadoutPlanet: null,
};

const _HI_ORBIT_SEGS = 256;   // orbit fan resolution (one period of the chain orbit)
const _HI_ARC_SEGS = 64;      // anomaly arcs
const _HI_TILT_DEG = 3;       // top-down camera tilt: keeps the screen-up direction defined (see focusInspectorCamera)
const _hiD2R = Math.PI / 180;
const _chainPeriSunMarkers = {};   // the chain planets' perihelion-at-Sun markers (built by the Show/Hide grid; see _chainPeriSunMarker)
const _moonMarkers = {};        // the Moon's perigee and line-of-nodes markers (built by the Show/Hide grid; see _moonMarker)
const _ssbMarkers = {};         // the Sun-barycenter marker (built by the Show/Hide grid; see _ssbMarker)
const _SSB_PATH_HALF_YEARS = 25, _SSB_PATH_STEP_YEARS = 0.25, _SSB_PATH_SAMPLES = 2 * _SSB_PATH_HALF_YEARS / _SSB_PATH_STEP_YEARS;
const _SSB_BODIES = [['mercury', 'M_MERCURY_SYSTEM'], ['venus', 'M_VENUS_SYSTEM'], ['earth', 'M_EARTH_SYSTEM'], ['mars', 'M_MARS_SYSTEM'],
  ['jupiter', 'M_JUPITER_SYSTEM'], ['saturn', 'M_SATURN_SYSTEM'], ['uranus', 'M_URANUS_SYSTEM'], ['neptune', 'M_NEPTUNE_SYSTEM']];
const _ssbPathMemo = new Map();   // quantized year → [x, y, z] world offset (scene units); cleared on a series change
let _ssbPathMemoSeries = null;
const _SSB_S = new THREE.Vector3(), _SSB_D = new THREE.Vector3();
const _hiWrap360 = wrap360;   // the one-home wraps (plan 13 B1)
const _hiWrap180 = wrap180;   // [−180, 180)
const _hiClamp1 = (x) => Math.min(1, Math.max(-1, x));
const _hiQuat = new THREE.Quaternion();
const _hiTmpA = new THREE.Vector3(), _hiTmpB = new THREE.Vector3(), _hiTmpC = new THREE.Vector3();
const _hiFollowDelta = new THREE.Vector3();   // the animation loop's camera-follow displacement

/** The pooled orbit frame (allocated once). */
function _hiFrame() {
  if (!hierarchyInspector._frame) {
    hierarchyInspector._frame = {
      S: new THREE.Vector3(), P: new THREE.Vector3(), r: new THREE.Vector3(),
      p: new THREE.Vector3(), q: new THREE.Vector3(), nOrb: new THREE.Vector3(),
      n: new THREE.Vector3(), g: new THREE.Vector3(), u2: new THREE.Vector3(),
      node: new THREE.Vector3(), tmp: new THREE.Vector3(),
      el: null, obj: null, jd: 0, aScene: 0, pDays: 0,
      trueAnomalyDeg: 0, meanAnomalyDeg: 0, eocDeg: 0, rAU: 0, rPeriAU: 0, rApoAU: 0,
      inclDateDeg: 0, nodeLonDateDeg: 0, argLatDeg: 0, heightAU: 0, maxHeightAU: 0,
    };
  }
  return hierarchyInspector._frame;
}

/** Rotate a J2000-ecliptic triple through the chain frame bridge R into world axes. */
function _hiRotJ2000(R, v, out) {
  return out.set(
    R[0][0] * v[0] + R[0][1] * v[1] + R[0][2] * v[2],
    R[1][0] * v[0] + R[1][1] * v[1] + R[1][2] * v[2],
    R[2][0] * v[0] + R[2][1] * v[1] + R[2][2] * v[2]);
}

/**
 * The orbit frame of date for a chain planet at the scene epoch: the chain
 * elements, the perihelion/in-plane/normal directions in WORLD axes (the same
 * element→position convention as kcComputeHeliocentricEclipticFromElements,
 * through the frame bridge R), the rendered ecliptic-of-date pole n̂ and
 * equinox ĝ, and the derived angles. Null while the frame bridge is not yet
 * derived (first frame) or for a no-chain body.
 */
function computeInspectorOrbitFrame(planetKey) {
  const target = PLANET_HIERARCHIES[planetKey];
  if (!target || !target.chain || !_chainR) return null;
  const f = _hiFrame();
  const obj = target.obj();
  if (!obj?.planetObj || !sun?.planetObj) return null;
  const jd = o.julianDay;
  const el = _chainElementsOfDate(planetKey, jd);
  const R = _chainR;
  const Om = el.ascNodeEclipticDeg * _hiD2R, inc = el.inclEclipticDeg * _hiD2R;
  const w = (el.lonPeriEclipticDeg - el.ascNodeEclipticDeg) * _hiD2R;
  const cw = Math.cos(w), sw = Math.sin(w), cO = Math.cos(Om), sO = Math.sin(Om), ci = Math.cos(inc), si = Math.sin(inc);
  // perihelion direction p̂, the in-plane direction 90° ahead q̂, the orbit normal n̂_orb (J2000 ecliptic)
  _hiRotJ2000(R, [cw * cO - sw * sO * ci, cw * sO + sw * cO * ci, sw * si], f.p).normalize();
  _hiRotJ2000(R, [-sw * cO - cw * sO * ci, -sw * sO + cw * cO * ci, cw * si], f.q).normalize();
  _hiRotJ2000(R, [si * sO, -si * cO, ci], f.nOrb).normalize();
  // the rendered ecliptic of date: the sun-plane container's world basis is [ĝ, n̂, ĝ×n̂] (R4)
  earthPerihelionPrecession1.containerObj.getWorldQuaternion(_hiQuat);
  f.n.set(0, 1, 0).applyQuaternion(_hiQuat).normalize();
  f.g.set(1, 0, 0).applyQuaternion(_hiQuat).normalize();
  f.u2.crossVectors(f.n, f.g).normalize();          // ecliptic longitude +90°
  sun.planetObj.getWorldPosition(f.S);
  obj.planetObj.getWorldPosition(f.P);              // the RENDERED planet (light-time retarded, as the eye sees it)
  f.el = el; f.obj = obj; f.jd = jd;
  f.aScene = 100 * el.aAU;
  f.pDays = DAYS_PER_JULIAN_YEAR * Math.pow(el.aAU, 1.5);         // Kepler III in the solar-mass unit (as _chainUpdateOrbitLine)
  f.r.subVectors(f.P, f.S);
  f.rAU = f.r.length() / 100;
  f.rPeriAU = el.aAU * (1 - el.e);
  f.rApoAU = el.aAU * (1 + el.e);
  // ν at the Sun: the angle from p̂ to the planet in the orbit plane (sign from n̂_orb via q̂)
  f.trueAnomalyDeg = _hiWrap360(Math.atan2(f.r.dot(f.q), f.r.dot(f.p)) / _hiD2R);
  f.meanAnomalyDeg = _hiWrap360(el.meanAnomalyDeg ?? (el.meanLonEclipticDeg - el.lonPeriEclipticDeg));
  f.eocDeg = _hiWrap180(f.trueAnomalyDeg - f.meanAnomalyDeg);
  // of-date geometry against the rendered ecliptic
  f.inclDateDeg = Math.acos(_hiClamp1(f.nOrb.dot(f.n))) / _hiD2R;
  f.node.crossVectors(f.n, f.nOrb);                 // the ascending node direction (n̂_ecl × n̂_orb)
  if (f.node.lengthSq() < 1e-18) f.node.copy(f.g);
  f.node.normalize();
  f.nodeLonDateDeg = _hiWrap360(Math.atan2(f.node.dot(f.u2), f.node.dot(f.g)) / _hiD2R);
  f.tmp.crossVectors(f.node, f.r);
  f.argLatDeg = _hiWrap360(Math.atan2(f.tmp.dot(f.nOrb), f.r.dot(f.node)) / _hiD2R);
  f.heightAU = f.r.dot(f.n) / 100;
  f.maxHeightAU = f.rAU * Math.sin(f.inclDateDeg * _hiD2R);
  return f;
}

// ─── the inspector's paper export ───────────────────────────────────────────
// The orbit picture per planet (owner: the hand-made 09_<planet>_orbit_picture
// figures, now printed from the scene): the Orbit view drawn flat — the frame
// computeInspectorOrbitFrame renders, projected onto the ecliptic of date
// (equinox to the right, longitude counter-clockwise), the orbit split by its
// side of the ecliptic, the line of nodes, the line of apsides, the rendered
// planet with its direction of motion, and a month ring at the model's own
// Sun longitude on the first of each month of the scene year. Nothing here is
// computed on a path of its own; the page is the standard export page.
const _HI_PAPER = { above: '#15803d', below: '#b91c1c', ecliptic: '#2563eb', asc: '#c026d3', desc: '#0891b2', peri: '#15803d', sun: '#d97706', planet: '#0e7490', ring: '#9ca3af', text: '#374151' };
const _HI_MONTHS = ['JANUARY', 'FEBRUARY', 'MARCH', 'APRIL', 'MAY', 'JUNE', 'JULY', 'AUGUST', 'SEPTEMBER', 'OCTOBER', 'NOVEMBER', 'DECEMBER'];
// (_HI_ECLIPTIC_CONSTELLATIONS — the thirteen IAU constellations the ecliptic
// crosses — is defined beside the scene's zodiac-constellations band, which
// is built at load from the same table.)
const _HI_CARDINALS = [['VE', 0, 'VERNAL EQUINOX'], ['SS', 90, 'SUMMER SOLSTICE'], ['AE', 180, 'AUTUMNAL EQUINOX'], ['WS', 270, 'WINTER SOLSTICE']];

/** The constellation (of the thirteen) that holds a J2000 ecliptic longitude. */
function _hiConstellationAt(lonJ2000) {
  const lon = _hiWrap360(lonJ2000);
  let best = null;   // the greatest entry longitude at or below lon; below Aries' 29° the band is still Pisces (it wraps through 0°)
  for (const [n, start] of _HI_ECLIPTIC_CONSTELLATIONS) if (lon >= start && (best === null || start > best[1])) best = [n, start];
  return best ? best[0] : _HI_ECLIPTIC_CONSTELLATIONS[0][0];
}

/** "YYYY-MM-DD HH:MM UT" for a JD (UT). */
function _hiDateTimeFromJD(jd) {
  const d = _hiCalendarFromJD(jd);
  const frac = jd + 0.5 - Math.floor(jd + 0.5);
  const mins = Math.round(frac * 1440), hh = Math.floor(mins / 60) % 24, mm = mins % 60;
  return `${d.year}-${String(d.month).padStart(2, '0')}-${String(d.day).padStart(2, '0')} ${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')} UT`;
}

/** The model's four cardinal instants of the scene year (the Earth-predictions panel's call: the crossing nearest the calendar year's midpoint). */
function _hiCardinalDates(year) {
  const out = {};
  try {
    const seed = dateToJulianDay(year, 7, 2) + 0.5, cpM = _tierModelB().cardinal;
    for (const [cp] of _HI_CARDINALS) out[cp] = _hiDateTimeFromJD(cpM.jdNearUT(seed, cp));
  } catch (e) { for (const [cp] of _HI_CARDINALS) out[cp] = '—'; }
  return out;
}

/** Calendar date of a JD (Meeus ch. 7, the reform applied) — the one-home converter (plan 13 B1). */
function _hiCalendarFromJD(jd) {
  const { year, month, day } = jdToCalendar(jd);
  return { year, month, day };
}

/** The Sun's ecliptic longitude of date on the first of each month of `year` (the model's own certified Sun; 30° steps if a date is out of the calendar helper's range). */
function _hiMonthSunLongitudes(year) {
  return _HI_MONTHS.map((_, i) => {
    try { return _hiWrap360(_tierModelB().eclipse.sunLonDegAtJD(dateToJulianDay(year, i + 1, 1))); }
    catch (e) { return _hiWrap360(360 * (i - 2) / 12); }
  });
}

function inspectorRenderPaperSVG(planetKey) {
  const target = PLANET_HIERARCHIES[planetKey];
  const f = target && target.chain ? computeInspectorOrbitFrame(planetKey) : null;
  if (!f) return '<svg xmlns="http://www.w3.org/2000/svg" width="600" height="100"><text x="20" y="50" font-family="Inter,system-ui,sans-serif" font-size="14" fill="#222">Planet Orbit Analysis: the orbit frame is not ready yet</text></svg>';
  const el = f.el, C = _HI_PAPER;
  const W = 800, PLOT = 736;   // the month ring (radius 310), the constellation band (to 358) and their names
  // the equinox of date in the chain's J2000 frame (R's columns are the J2000
  // axes in world coordinates): where the vernal point stands among the stars
  const Rj = _chainR, gJx = Rj[0][0] * f.g.x + Rj[1][0] * f.g.y + Rj[2][0] * f.g.z, gJy = Rj[0][1] * f.g.x + Rj[1][1] * f.g.y + Rj[2][1] * f.g.z;
  const eqLonJ2000 = _hiWrap360(Math.atan2(gJy, gJx) / _hiD2R);
  const eqConstellation = _hiConstellationAt(eqLonJ2000);
  // projection onto the ecliptic of date: x along ĝ (the equinox), y along û₂ (longitude +90°), h along n̂
  const proj = (v) => ({ x: v.dot(f.g), y: v.dot(f.u2), h: v.dot(f.n) });
  const tmp = new THREE.Vector3();
  const orbitPt = (nuDeg) => {
    const nu = nuDeg * _hiD2R;
    const r = el.aAU * (1 - el.e * el.e) / (1 + el.e * Math.cos(nu));
    tmp.set(0, 0, 0).addScaledVector(f.p, r * Math.cos(nu)).addScaledVector(f.q, r * Math.sin(nu));
    return proj(tmp);
  };
  // one period sampled from the ascending node: the first arc lies above the ecliptic of date
  const nuAsc = _hiWrap360(Math.atan2(f.node.dot(f.q), f.node.dot(f.p)) / _hiD2R);
  const N = _HI_ORBIT_SEGS;
  const pts = [];
  for (let i = 0; i <= N; i++) pts.push(orbitPt(nuAsc + 360 * i / N));
  let kDesc = pts.findIndex((p, i) => i > 2 && p.h <= 0);
  if (kDesc < 0) kDesc = N;
  const rMax = pts.reduce((m, p) => Math.max(m, Math.hypot(p.x, p.y)), 0);
  const R = 250, scale = R / rMax, ringR = R * 1.24;

  const dt = _hiCalendarFromJD(f.jd);
  const dateStr = `${dt.year}-${String(dt.month).padStart(2, '0')}-${String(dt.day).padStart(2, '0')}`;
  const legend = [
    { name: 'Orbit above the ecliptic of date', color: C.above, bold: true },
    { name: 'Orbit below the ecliptic of date', color: C.below, bold: true },
    { name: 'Ecliptic of date at a', color: C.ecliptic, dash: '6,4' },
    { name: 'Ascending node ↑', color: C.asc, marker: 'dot' },
    { name: 'Descending node ↓', color: C.desc, marker: 'dot' },
    { name: 'Perihelion P · aphelion A', color: C.peri, marker: 'diamond' },
    { name: 'Sun → planet: the rendered planet and its motion', color: C.sun },
    { name: 'Ω and ω: arcs at the Sun, from the equinox of date', color: '#6b7280' },
    { name: 'Month ring: the Sun’s longitude on the 1st', color: C.ring },
    { name: 'Cardinal points: the model’s dates (UT)', color: C.text },
    { name: 'IAU constellation boundaries (J2000), carried with the precession', color: C.ring },
  ];
  const head = chartExportHeader(`Planet Orbit Analysis — ${target.label}, orbit of date ${dateStr}`, legend, W);
  // the values block under the diagram: the three angles (and i) in both
  // frames, e and a, the equinox of date among the stars — the same numbers
  // the inspector's readout rows show
  const ROW = 16, VALUE_ROWS = 8, BLOCK = 10 + VALUE_ROWS * ROW + 6;
  const top = head.bottom + 8, H = top + PLOT + BLOCK + CHART_EXPORT_CREDIT_H;
  const cx = W / 2, cy = top + PLOT / 2;
  const X = (p) => (cx + p.x * scale).toFixed(1), Y = (p) => (cy - p.y * scale).toFixed(1);
  const path = (arr) => arr.map((p, i) => `${i ? 'L' : 'M'}${X(p)},${Y(p)}`).join(' ');
  let s = '';

  // the month ring — the Sun's longitude on the first of each month, read counter-clockwise
  s += `<circle cx="${cx}" cy="${cy}" r="${ringR.toFixed(1)}" fill="none" stroke="${C.ring}" stroke-width="1"/>`;
  _hiMonthSunLongitudes(dt.year).forEach((lon, i) => {
    const a = lon * _hiD2R, ca = Math.cos(a), sa = Math.sin(a);
    s += `<line x1="${(cx + (ringR - 5) * ca).toFixed(1)}" y1="${(cy - (ringR - 5) * sa).toFixed(1)}" x2="${(cx + (ringR + 5) * ca).toFixed(1)}" y2="${(cy - (ringR + 5) * sa).toFixed(1)}" stroke="${C.ring}" stroke-width="1"/>`;
    const lx = cx + (ringR + 18) * ca, ly = cy - (ringR + 18) * sa;
    const rot = sa < 0 ? 270 - lon : 90 - lon;   // along the ring, upright on the lower half too
    s += `<text x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="middle" dominant-baseline="middle" font-size="11" font-weight="600" fill="${C.text}" transform="rotate(${rot.toFixed(1)} ${lx.toFixed(1)} ${ly.toFixed(1)})">${_HI_MONTHS[i]}</text>`;
  });
  // the four cardinal points — fixed on the ring by construction (0°, 90°,
  // 180°, 270° of the ecliptic of date), each with the model's date of the
  // scene year, so the month ring's drift against the seasons reads itself
  const cpDates = _hiCardinalDates(dt.year);
  for (const [cp, deg, name] of _HI_CARDINALS) {
    const a = deg * _hiD2R, ca = Math.cos(a), sa = Math.sin(a);
    s += `<line x1="${(cx + (ringR - 10) * ca).toFixed(1)}" y1="${(cy - (ringR - 10) * sa).toFixed(1)}" x2="${(cx + (ringR + 10) * ca).toFixed(1)}" y2="${(cy - (ringR + 10) * sa).toFixed(1)}" stroke="${C.text}" stroke-width="1.6"/>`;
    const lr = ringR - 13, lx = cx + lr * ca, ly = cy - lr * sa;
    const rot = sa < -1e-9 ? 270 - deg : 90 - deg;
    s += `<text x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="middle" dominant-baseline="middle" font-size="9.5" font-weight="600" fill="${C.text}" transform="rotate(${rot.toFixed(1)} ${lx.toFixed(1)} ${ly.toFixed(1)})">${name} · ${cpDates[cp]}</text>`;
  }
  s += `<line x1="${cx}" y1="${cy}" x2="${(cx + R * 0.34).toFixed(1)}" y2="${cy}" stroke="#6b7280" stroke-width="0.8" stroke-dasharray="3,3"/>`;

  // the constellation band: the IAU boundaries at J2000 longitude λ sit at
  // λ − λ_eq in the ecliptic of date (the precession of the equinox)
  const bIn = ringR + 30, bOut = ringR + 48, bMid = ringR + 39;
  s += `<circle cx="${cx}" cy="${cy}" r="${bIn.toFixed(1)}" fill="none" stroke="${C.ring}" stroke-width="0.8"/>`;
  s += `<circle cx="${cx}" cy="${cy}" r="${bOut.toFixed(1)}" fill="none" stroke="${C.ring}" stroke-width="0.8"/>`;
  _HI_ECLIPTIC_CONSTELLATIONS.forEach(([name, start], i) => {
    const next = _HI_ECLIPTIC_CONSTELLATIONS[(i + 1) % _HI_ECLIPTIC_CONSTELLATIONS.length][1];
    const span = _hiWrap360(next - start), lon0 = _hiWrap360(start - eqLonJ2000), mid = _hiWrap360(lon0 + span / 2);
    const a0 = lon0 * _hiD2R;
    s += `<line x1="${(cx + bIn * Math.cos(a0)).toFixed(1)}" y1="${(cy - bIn * Math.sin(a0)).toFixed(1)}" x2="${(cx + bOut * Math.cos(a0)).toFixed(1)}" y2="${(cy - bOut * Math.sin(a0)).toFixed(1)}" stroke="${C.ring}" stroke-width="0.8"/>`;
    const am = mid * _hiD2R, lx = cx + bMid * Math.cos(am), ly = cy - bMid * Math.sin(am);
    const rot = Math.sin(am) < 0 ? 270 - mid : 90 - mid;
    const label = span < 12 ? name.slice(0, 3) : name;   // Scorpius' 6.5° holds its IAU abbreviation
    s += `<text x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="middle" dominant-baseline="middle" font-size="8.5" fill="#6b7280" transform="rotate(${rot.toFixed(1)} ${lx.toFixed(1)} ${ly.toFixed(1)})">${label}</text>`;
  });
  for (const deg of [45, 225]) {   // the sense of the year on the ring
    const a = deg * _hiD2R, tx = -Math.sin(a), ty = Math.cos(a);   // the counter-clockwise tangent
    const px = cx + ringR * Math.cos(a), py = cy - ringR * Math.sin(a);
    const tip = [px + 9 * tx, py - 9 * ty], l = [px - 6 * tx + 5 * Math.cos(a), py + 6 * ty - 5 * Math.sin(a)], r2 = [px - 6 * tx - 5 * Math.cos(a), py + 6 * ty + 5 * Math.sin(a)];
    s += `<polygon points="${tip[0].toFixed(1)},${tip[1].toFixed(1)} ${l[0].toFixed(1)},${l[1].toFixed(1)} ${r2[0].toFixed(1)},${r2[1].toFixed(1)}" fill="${C.ring}"/>`;
  }

  // the ecliptic of date at the semi-major axis, the two halves of the orbit
  s += `<circle cx="${cx}" cy="${cy}" r="${(el.aAU * scale).toFixed(1)}" fill="none" stroke="${C.ecliptic}" stroke-width="1" stroke-dasharray="6,4"/>`;
  const above = pts.slice(0, kDesc + 1), below = pts.slice(kDesc);
  s += `<path d="${path(above)} Z" fill="${C.above}" opacity="0.07"/>`;
  s += `<path d="${path(below)} Z" fill="${C.below}" opacity="0.07"/>`;
  s += `<path d="${path(above)}" fill="none" stroke="${C.above}" stroke-width="2.2"/>`;
  s += `<path d="${path(below)}" fill="none" stroke="${C.below}" stroke-width="2.2"/>`;

  // the line of nodes with the two nodes on the orbit
  const nodeDir = proj(f.node), L = rMax * 1.08;
  s += `<line x1="${(cx - nodeDir.x * L * scale).toFixed(1)}" y1="${(cy + nodeDir.y * L * scale).toFixed(1)}" x2="${(cx + nodeDir.x * L * scale).toFixed(1)}" y2="${(cy - nodeDir.y * L * scale).toFixed(1)}" stroke="#6b7280" stroke-width="1" stroke-dasharray="2,3"/>`;
  // labels sit on the INNER side of the orbit (a node near the ring collided
  // with the month names), with a white halo over the shading
  const labelAt = (p, text, color, outX, outY) => {
    const off = 15, dirX = -outX, dirY = -outY;
    const lx = cx + p.x * scale + dirX * off, ly = cy - p.y * scale - dirY * off;
    const anchor = dirX < -0.3 ? 'end' : dirX > 0.3 ? 'start' : 'middle';
    const attrs = `x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="${anchor}" dominant-baseline="middle" font-size="12" font-weight="600"`;
    return `<text ${attrs} fill="#fff" stroke="#fff" stroke-width="4" stroke-linejoin="round">${text}</text><text ${attrs} fill="${color}">${text}</text>`;
  };
  const asc = pts[0], desc = orbitPt(nuAsc + 180);
  s += `<circle cx="${X(asc)}" cy="${Y(asc)}" r="5.5" fill="${C.asc}" stroke="#fff" stroke-width="1.2"/>` + labelAt(asc, 'Ascending node ↑', C.asc, nodeDir.x, nodeDir.y);
  s += `<circle cx="${X(desc)}" cy="${Y(desc)}" r="5.5" fill="${C.desc}" stroke="#fff" stroke-width="1.2"/>` + labelAt(desc, 'Descending node ↓', C.desc, -nodeDir.x, -nodeDir.y);

  // the line of apsides with P and A
  const P = orbitPt(0), A = orbitPt(180), pDir = proj(f.p);
  s += `<line x1="${X(A)}" y1="${Y(A)}" x2="${X(P)}" y2="${Y(P)}" stroke="${C.peri}" stroke-width="1.2"/>`;
  for (const [pt, name, dx, dy] of [[P, 'P', pDir.x, pDir.y], [A, 'A', -pDir.x, -pDir.y]]) {
    s += `<rect x="${(+X(pt) - 4).toFixed(1)}" y="${(+Y(pt) - 4).toFixed(1)}" width="8" height="8" transform="rotate(45 ${X(pt)} ${Y(pt)})" fill="${C.peri}" stroke="#fff" stroke-width="1"/>` + labelAt(pt, name, C.peri, dx, dy);
  }

  // Ω and ω as arcs at the Sun: Ω from the equinox to the ascending node
  // along the ecliptic of date, ω from the node to P (the projection of the
  // in-plane angle; the block below carries the exact numbers)
  const arc = (r, fromDeg, spanDeg, color, label) => {
    const a0 = fromDeg * _hiD2R, a1 = (fromDeg + spanDeg) * _hiD2R, am = (fromDeg + spanDeg / 2) * _hiD2R;
    const x0 = cx + r * Math.cos(a0), y0 = cy - r * Math.sin(a0), x1 = cx + r * Math.cos(a1), y1 = cy - r * Math.sin(a1);
    const lx = cx + (r + 13) * Math.cos(am), ly = cy - (r + 13) * Math.sin(am);
    return `<path d="M${x0.toFixed(1)},${y0.toFixed(1)} A${r},${r} 0 ${spanDeg > 180 ? 1 : 0} 0 ${x1.toFixed(1)},${y1.toFixed(1)}" fill="none" stroke="${color}" stroke-width="1.3"/>` +
      `<text x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="middle" dominant-baseline="middle" font-size="13" font-style="italic" font-weight="600" fill="${color}">${label}</text>`;
  };
  const nodeDeg = _hiWrap360(Math.atan2(nodeDir.y, nodeDir.x) / _hiD2R), periDeg = _hiWrap360(Math.atan2(pDir.y, pDir.x) / _hiD2R);
  s += arc(R * 0.22, 0, nodeDeg, C.asc, 'Ω');
  s += arc(R * 0.30, nodeDeg, _hiWrap360(periDeg - nodeDeg), C.peri, 'ω');

  // the Sun, the rendered planet, its direction of motion
  s += `<circle cx="${cx}" cy="${cy}" r="7" fill="#f59e0b" stroke="#b45309" stroke-width="1"/>`;
  const pl = { x: f.r.dot(f.g) / 100, y: f.r.dot(f.u2) / 100 };
  s += `<line x1="${cx}" y1="${cy}" x2="${X(pl)}" y2="${Y(pl)}" stroke="${C.sun}" stroke-width="1.4"/>`;
  const nu = f.trueAnomalyDeg * _hiD2R;
  tmp.set(0, 0, 0).addScaledVector(f.p, -Math.sin(nu)).addScaledVector(f.q, el.e + Math.cos(nu));
  const v = proj(tmp), vn = Math.hypot(v.x, v.y) || 1, vx = v.x / vn, vy = v.y / vn;
  const ax0 = +X(pl) + vx * 13, ay0 = +Y(pl) - vy * 13, ax1 = ax0 + vx * 26, ay1 = ay0 - vy * 26;
  s += `<line x1="${ax0.toFixed(1)}" y1="${ay0.toFixed(1)}" x2="${ax1.toFixed(1)}" y2="${ay1.toFixed(1)}" stroke="${C.sun}" stroke-width="1.6"/>`;
  s += `<polygon points="${(ax1 + vx * 7).toFixed(1)},${(ay1 - vy * 7).toFixed(1)} ${(ax1 - vy * 4).toFixed(1)},${(ay1 - vx * 4).toFixed(1)} ${(ax1 + vy * 4).toFixed(1)},${(ay1 + vx * 4).toFixed(1)}" fill="${C.sun}"/>`;
  s += `<circle cx="${X(pl)}" cy="${Y(pl)}" r="10" fill="none" stroke="${C.planet}" stroke-width="1.5"/><circle cx="${X(pl)}" cy="${Y(pl)}" r="4.5" fill="${C.planet}"/>`;

  // the values block — the readout rows' numbers, both frames named
  const fx = (v, d, unit = '') => (Number.isFinite(v) ? v.toFixed(d) + unit : '—');
  const omJ = _hiWrap360(el.ascNodeEclipticDeg), lpJ = _hiWrap360(el.lonPeriEclipticDeg), wJ = _hiWrap360(lpJ - omJ);
  const omD = f.nodeLonDateDeg, wD = _hiWrap360(f.argLatDeg - f.trueAnomalyDeg), lpD = _hiWrap360(omD + wD);
  const rows = [
    ['', 'J2000 ecliptic', 'ecliptic of date'],
    ['Ascending node Ω', fx(omJ, 3, '°'), fx(omD, 3, '°')],
    ['Argument of perihelion ω = ϖ − Ω', fx(wJ, 3, '°'), fx(wD, 3, '°')],
    ['Longitude of perihelion ϖ = Ω + ω', fx(lpJ, 3, '°'), fx(lpD, 3, '°')],
    ['Inclination i', fx(el.inclEclipticDeg, 3, '°'), fx(f.inclDateDeg, 3, '°')],
    ['Eccentricity e', fx(el.e, 6), ''],
    ['Semi-major axis a', fx(el.aAU, 6, ' AU'), ''],
    [`Vernal equinox of date, among the stars: in ${eqConstellation}`, fx(eqLonJ2000, 3, '°'), ''],
  ];
  const bx = cx - 250, by = top + PLOT + 10;
  s += `<line x1="${bx}" y1="${by - 4}" x2="${cx + 250}" y2="${by - 4}" stroke="#e5e7eb" stroke-width="1"/>`;
  rows.forEach((r, i) => {
    const y = by + ROW * (i + 1) - 4, bold = i === 0 ? ' font-weight="600"' : '';
    s += `<text x="${bx}" y="${y}" font-size="11.5" fill="${C.text}"${bold}>${r[0]}</text>`;
    s += `<text x="${cx + 95}" y="${y}" text-anchor="end" font-size="11.5" fill="${C.text}"${bold}>${r[1]}</text>`;
    s += `<text x="${cx + 250}" y="${y}" text-anchor="end" font-size="11.5" fill="${C.text}"${bold}>${r[2]}</text>`;
  });

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" font-family="Inter, system-ui, sans-serif">
    <rect width="${W}" height="${H}" fill="white"/>
    ${head.svg}
    ${s}
    ${chartExportCredit(W, H)}
  </svg>`;
}

// ─── visual helpers (one THREE.Group in world coordinates) ─────────────────

function _hiLine(color, n, dashed) {
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(n * 3), 3));
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 3, gapSize: 2 })
    : new THREE.LineBasicMaterial({ color });
  const line = new THREE.Line(geom, mat);
  line.frustumCulled = false;
  return line;
}
function _hiSphere(color, radius) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(radius, 16, 16),
    new THREE.MeshBasicMaterial({ color, depthTest: false }));
  m.renderOrder = 998;
  return m;
}
function _hiArrow(color, length) {
  return new THREE.ArrowHelper(new THREE.Vector3(0, 1, 0), new THREE.Vector3(), length, color, length * 0.35, length * 0.2);
}
function _hiLabelSprite(text, sizeScene) {
  const canvas = document.createElement('canvas');
  canvas.width = 64; canvas.height = 64;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 44px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, 32, 32);
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(canvas), depthTest: false, transparent: true }));
  sprite.scale.set(sizeScene, sizeScene, 1);
  sprite.renderOrder = 1001;
  return sprite;
}
function _hiSetLine(line, i, v) {
  const a = line.geometry.attributes.position.array;
  a[i * 3] = v.x; a[i * 3 + 1] = v.y; a[i * 3 + 2] = v.z;
}
function _hiFlagLine(line) {
  line.geometry.attributes.position.needsUpdate = true;
  if (line.material.isLineDashedMaterial) line.computeLineDistances();
}

/** Build the helper group for the current planet (idempotent per planet). */
function createVisualHelpers() {
  clearVisualHelpers();
  const f = computeInspectorOrbitFrame(hierarchyInspector.currentPlanet);
  if (!f) return;
  const H = hierarchyInspector, h = H.helpers;
  const group = new THREE.Group();
  group.name = 'PlanetInspectorHelpers';
  const parts = { planet: H.currentPlanet };
  const a = f.aScene;
  const N = _HI_ORBIT_SEGS;

  if (h.showInclinationPlane) {
    // the orbit fan: centre (the Sun) + N+1 ring points; two meshes SHARE the
    // position attribute and split the triangles by the ring points' height
    const pos = new THREE.BufferAttribute(new Float32Array((N + 2) * 3), 3);
    const mkFan = (color) => {
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', pos);
      g.setIndex([]);
      const m = new THREE.Mesh(g, new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide, transparent: true, opacity: 0.3, depthWrite: false }));
      m.frustumCulled = false;
      return m;
    };
    parts.fanPos = pos;
    parts.fanAbove = mkFan(0x00ff00);
    parts.fanBelow = mkFan(0xff0000);
    parts.heights = new Float64Array(N + 1);
    parts.orbitLine = _hiLine(0xffffff, N + 1, false);
    parts.eclipticRing = _hiLine(0x4488ff, N + 1, true);
    parts.nodesLine = _hiLine(0xffff00, 2, true);
    parts.ascNode = _hiSphere(0xff00ff, a * 0.03);
    parts.descNode = _hiSphere(0x00ffff, a * 0.03);
    parts.ascArrow = _hiArrow(0xff00ff, a * 0.18);
    parts.descArrow = _hiArrow(0x00ffff, a * 0.18);
    parts.highPoint = _hiSphere(0x00ff00, a * 0.02);
    parts.lowPoint = _hiSphere(0xff0000, a * 0.02);
    parts.highArrow = _hiArrow(0x00ff00, a * 0.1);
    parts.lowArrow = _hiArrow(0xff0000, a * 0.1);
    group.add(parts.fanAbove, parts.fanBelow, parts.orbitLine, parts.eclipticRing, parts.nodesLine,
      parts.ascNode, parts.descNode, parts.ascArrow, parts.descArrow,
      parts.highPoint, parts.lowPoint, parts.highArrow, parts.lowArrow);
  }
  if (h.showPerihelion) {
    parts.periPoint = _hiSphere(0x00ff00, a * 0.025);
    parts.periPoint.renderOrder = 999;
    parts.periLabel = _hiLabelSprite('P', a * 0.09);
    parts.periLine = _hiLine(0x00ff00, 2, false);
    group.add(parts.periPoint, parts.periLabel, parts.periLine);
  }
  if (h.showAnomalies) {
    parts.sunPlanetLine = _hiLine(0xffbf00, 2, false);
    parts.trueArc = _hiLine(0xffbf00, _HI_ARC_SEGS + 1, false);
    parts.meanArc = _hiLine(0x00ffff, _HI_ARC_SEGS + 1, true);
    parts.trueArcR = a * 0.42 * (1 - f.el.e);
    parts.meanArcR = a * 0.30 * (1 - f.el.e);
    group.add(parts.sunPlanetLine, parts.trueArc, parts.meanArc);
  }
  if (h.showLocator) {
    const size = Math.max((f.obj.size || 1) * 3, 2);
    parts.locator = new THREE.Mesh(new THREE.TorusGeometry(size, size * 0.1, 8, 32),
      new THREE.MeshBasicMaterial({ color: 0x00ffff, transparent: true, opacity: 0.8, side: THREE.DoubleSide, depthTest: false }));
    parts.locator.renderOrder = 998;
    group.add(parts.locator);
  }
  scene.add(group);
  H.group = group;
  H.parts = parts;
  H._orbitSampleJD = null;
  updateInspectorVisuals(f, true);
}

/** Remove and dispose the helper group. */
function clearVisualHelpers() {
  const H = hierarchyInspector;
  if (!H.group) return;
  H.group.parent?.remove(H.group);
  H.group.traverse((child) => {
    child.geometry?.dispose?.();
    if (child.material) { child.material.map?.dispose?.(); child.material.dispose?.(); }
  });
  H.group = null;
  H.parts = null;
  H._orbitSampleJD = null;
}

/**
 * Per-frame geometry update. The ORBIT (fan, outline, nodes, extremes,
 * ecliptic ring) is resampled from the chain over one period when the epoch
 * has moved by more than 1/720 of the period and at most four times a second
 * (the _chainUpdateOrbitLine floor: 257 chain evaluations per resample); the
 * planet-dependent parts (lines, arcs, locator, perihelion) move every frame.
 */
function updateInspectorVisuals(f, force = false) {
  const H = hierarchyInspector, P = H.parts;
  if (!P || P.planet !== H.currentPlanet) return;
  const nowMs = performance.now();
  const N = _HI_ORBIT_SEGS;
  if (P.fanPos && (force || H._orbitSampleJD === null ||
      (Math.abs(f.jd - H._orbitSampleJD) > f.pDays / 720 && nowMs - H._orbitSampleMs >= 250))) {
    H._orbitSampleJD = f.jd; H._orbitSampleMs = nowMs;
    const R = _chainR, key = H.currentPlanet;
    const fp = P.fanPos.array, op = P.orbitLine.geometry.attributes.position.array, ep = P.eclipticRing.geometry.attributes.position.array;
    fp[0] = f.S.x; fp[1] = f.S.y; fp[2] = f.S.z;
    let iHi = 0, iLo = 0;
    const yC = _engineYearTT(f.jd);   // one ΔT bridge per resample, as the scene rings (_chainHelioAUAtEngineYear)
    for (let i = 0; i <= N; i++) {
      const hv = _chainHelioAUAtEngineYear(key, yC + (i / N - 0.5) * f.pDays / DAYS_PER_JULIAN_YEAR);
      _hiRotJ2000(R, hv, _hiTmpA).multiplyScalar(100).add(f.S);
      const k = (i + 1) * 3;
      fp[k] = _hiTmpA.x; fp[k + 1] = _hiTmpA.y; fp[k + 2] = _hiTmpA.z;
      op[i * 3] = _hiTmpA.x; op[i * 3 + 1] = _hiTmpA.y; op[i * 3 + 2] = _hiTmpA.z;
      const hgt = _hiTmpB.subVectors(_hiTmpA, f.S).dot(f.n);
      P.heights[i] = hgt;
      if (hgt > P.heights[iHi]) iHi = i;
      if (hgt < P.heights[iLo]) iLo = i;
      // the ecliptic-of-date reference ring at the semi-major axis
      const t = (i / N) * 2 * Math.PI;
      _hiTmpC.copy(f.S).addScaledVector(f.g, f.aScene * Math.cos(t)).addScaledVector(f.u2, f.aScene * Math.sin(t));
      ep[i * 3] = _hiTmpC.x; ep[i * 3 + 1] = _hiTmpC.y; ep[i * 3 + 2] = _hiTmpC.z;
    }
    P.fanPos.needsUpdate = true;
    _hiFlagLine(P.orbitLine);
    _hiFlagLine(P.eclipticRing);
    // fan triangles split by the ring segment's mean height
    const above = [], below = [];
    for (let i = 0; i < N; i++) {
      ((P.heights[i] + P.heights[i + 1]) / 2 > 0 ? above : below).push(0, i + 1, i + 2);
    }
    P.fanAbove.geometry.setIndex(above);
    P.fanBelow.geometry.setIndex(below);
    // nodes: the orbit's crossings of the ecliptic of date, interpolated on the sampled orbit
    const ringPt = (i, out) => out.set(fp[(i + 1) * 3], fp[(i + 1) * 3 + 1], fp[(i + 1) * 3 + 2]);
    let ascFound = false, descFound = false;
    for (let i = 0; i < N; i++) {
      const h0 = P.heights[i], h1 = P.heights[i + 1];
      if (h0 === h1 || (h0 < 0) === (h1 < 0)) continue;
      const t = h0 / (h0 - h1);
      ringPt(i, _hiTmpA); ringPt(i + 1, _hiTmpB);
      _hiTmpC.lerpVectors(_hiTmpA, _hiTmpB, t);
      if (h0 < 0 && !ascFound) { ascFound = true; P.ascNode.position.copy(_hiTmpC); P.ascArrow.position.copy(_hiTmpC); }
      else if (h0 >= 0 && !descFound) { descFound = true; P.descNode.position.copy(_hiTmpC); P.descArrow.position.copy(_hiTmpC); }
    }
    P.ascArrow.setDirection(f.n);
    P.descArrow.setDirection(_hiTmpA.copy(f.n).negate());
    _hiSetLine(P.nodesLine, 0, P.ascNode.position);
    _hiSetLine(P.nodesLine, 1, P.descNode.position);
    _hiFlagLine(P.nodesLine);
    ringPt(iHi, P.highPoint.position); ringPt(iLo, P.lowPoint.position);
    P.highArrow.position.copy(P.highPoint.position); P.highArrow.setDirection(f.n);
    P.lowArrow.position.copy(P.lowPoint.position); P.lowArrow.setDirection(_hiTmpA.copy(f.n).negate());
  }
  if (P.periPoint) {
    _hiTmpA.copy(f.S).addScaledVector(f.p, 100 * f.rPeriAU);
    P.periPoint.position.copy(_hiTmpA);
    P.periLabel.position.copy(_hiTmpA).addScaledVector(f.n, f.aScene * 0.06);
    _hiSetLine(P.periLine, 0, f.S); _hiSetLine(P.periLine, 1, _hiTmpA); _hiFlagLine(P.periLine);
  }
  if (P.sunPlanetLine) {
    _hiSetLine(P.sunPlanetLine, 0, f.S); _hiSetLine(P.sunPlanetLine, 1, f.P); _hiFlagLine(P.sunPlanetLine);
    const sweep = (line, radius, deg) => {
      const rad = deg * _hiD2R;
      for (let i = 0; i <= _HI_ARC_SEGS; i++) {
        const t = rad * i / _HI_ARC_SEGS;
        _hiTmpA.copy(f.S).addScaledVector(f.p, radius * Math.cos(t)).addScaledVector(f.q, radius * Math.sin(t));
        _hiSetLine(line, i, _hiTmpA);
      }
      _hiFlagLine(line);
    };
    sweep(P.trueArc, P.trueArcR, f.trueAnomalyDeg);
    sweep(P.meanArc, P.meanArcR, f.meanAnomalyDeg);
  }
  if (P.locator) {
    P.locator.position.copy(f.P);
    P.locator.lookAt(camera.position);
  }
}

// ─── camera ────────────────────────────────────────────────────────────────

/**
 * Orbit view: straight down onto the ecliptic of date at the Sun, the
 * equinox ĝ to the RIGHT (longitudes run counter-clockwise), tilted by
 * _HI_TILT_DEG toward ecliptic longitude 270° so the screen-up direction is
 * defined — a camera exactly on the pole axis leaves three.js's lookAt to
 * pick the roll from a fallback perturbation, which is where the former
 * inspector's "90° clockwise" start came from. Planet view: from behind the
 * planet toward the Sun.
 */
function focusInspectorCamera(mode) {
  const f = computeInspectorOrbitFrame(hierarchyInspector.currentPlanet);
  if (!f) return;
  const H = hierarchyInspector;
  H._cameraControlActive = true;
  if (mode === 'planet') {
    H._cameraTarget = f.obj.planetObj;
    const d = Math.max(20, (f.obj.size || 1) * 40);
    _hiTmpA.copy(f.r).normalize();                       // Sun→planet
    camera.position.copy(f.P).addScaledVector(_hiTmpA, d).addScaledVector(f.n, d * 0.35);
    controls.target.copy(f.P);
  } else {
    H._cameraTarget = sun.planetObj;
    const d = Math.max(200, f.aScene * 2.6);
    const up = _hiTmpB.crossVectors(f.n, f.g).normalize();  // screen-up = n̂ × ĝ ⇒ ĝ to the right
    const tilt = _HI_TILT_DEG * _hiD2R;
    _hiTmpA.copy(f.n).multiplyScalar(Math.cos(tilt)).addScaledVector(up, -Math.sin(tilt)).normalize();
    camera.position.copy(f.S).addScaledVector(_hiTmpA, d);
    controls.target.copy(f.S);
  }
  (H._lastTargetPos ??= new THREE.Vector3()).copy(controls.target);   // the follow starts from here
  controls.minDistance = 0;
  controls.maxDistance = Infinity;
  controls.update();
  camera.near = 0.1;
  camera.updateProjectionMatrix();
}

// ─── panel ─────────────────────────────────────────────────────────────────

const _HI_ROWS_ELEMENTS = [
  ['aAU', 'Semi-major axis (a)', 'AU', 'The chain’s a of date (engine-D element chain + the banked secular-series override).'],
  ['e', 'Eccentricity (e)', '', ''],
  ['inclJ2000', 'Inclination (i, J2000 ecliptic)', '°', 'The chain element: the orbit plane against the FIXED J2000 ecliptic (Mercury ≈ 7.005°, JPL 7.00498°). The of-date value against the rendered ecliptic is in the geometry section; the inclination to the INVARIABLE plane (Mercury ≈ 6.345°) is the separate row below.'],
  ['ascNodeJ2000', 'Ascending node (Ω, J2000 ecliptic)', '°', ''],
  ['inclInv', 'Inclination to the invariable plane (i_inv)', '°', 'The chain element against the model’s own invariable plane (the system’s total-angular-momentum plane) — the planet panel’s "Inclination to Inv. plane" row.'],
  ['ascNodeInv', 'Ascending node on the invariable plane (Ω_inv, S&S origin)', '°', 'The chain’s node of date on the invariable plane in the Souami & Souchay (2012) longitude origin — the planet panel’s row and the Orbital Plane Precession chart’s Ω.'],
  ['lonPeri', 'Longitude of perihelion (ϖ, J2000 ecliptic)', '°', 'The element every reference table publishes; the same channel as the planet panel’s ϖ row.'],
  ['argPeri', 'Argument of perihelion (ω = ϖ − Ω)', '°', ''],
  ['meanLon', 'Mean longitude (λ̄)', '°', ''],
  ['period', 'Period (Kepler III, a³⁄²)', 'yr', 'In the solar-mass unit — the ring and the fan span exactly one of these.'],
  ['rPeri', 'Perihelion distance a(1−e)', 'AU', ''],
  ['rApo', 'Aphelion distance a(1+e)', 'AU', ''],
];
const _HI_ROWS_LIVE = [
  ['rAU', 'Sun → planet distance (rendered)', 'AU', 'The rendered planet is light-time retarded (astrometric), as the eye sees it.'],
  ['trueAnomaly', 'True anomaly (ν) at the Sun', '°', 'Angle at the Sun from the perihelion direction to the rendered planet, in the orbit plane — the amber arc.'],
  ['meanAnomaly', 'Mean anomaly (M) of the chain', '°', 'The chain’s uniform angle since perihelion (λ̄ − ϖ) — the cyan dashed arc, drawn at the Sun for comparison.'],
  ['eoc', 'Equation of centre (ν − M)', '°', ''],
  ['inclDate', 'Inclination to the ecliptic OF DATE', '°', 'The angle between the orbit normal and the rendered ecliptic pole n̂ (R4: the engine’s ecliptic of date). The fan’s tilt.'],
  ['nodeLonDate', 'Ascending node longitude OF DATE', '°', 'From the rendered equinox ĝ along the ecliptic of date to the node direction n̂_ecl × n̂_orb — the magenta marker.'],
  ['argLat', 'Argument of latitude (u, node → planet)', '°', '0° at the ascending node, 90° at the highest point, 180° at the descending node.'],
  ['height', 'Height above the ecliptic of date', 'AU', ''],
  ['heightPct', 'Height / maximum height', '%', ''],
  ['hemisphere', 'Hemisphere', '', ''],
  ['planetRA', 'Planet RA (scene equator of date)', '', ''],
  ['planetDec', 'Planet Dec', '', ''],
  ['sunDec', 'Sun Dec', '', ''],
  ['decVsSun', 'Planet Dec vs Sun Dec', '', 'At a transit the two agree.'],
];

function _hiGridHtml(rows) {
  return '<div class="hi-props">' + rows.map(([id, label, unit, tip]) =>
    `<span class="hi-key"${tip ? ` title="${tip.replace(/"/g, '&quot;')}"` : ''}>${label}</span>` +
    `<span class="hi-val" data-id="${id}"></span>`).join('') + '</div>';
}

function _hiBuildReadouts(planetKey) {
  const panel = hierarchyInspector.panel;
  panel.querySelector('.hi-elements-content').innerHTML = _hiGridHtml(_HI_ROWS_ELEMENTS);
  panel.querySelector('.hi-live-content').innerHTML = _hiGridHtml(_HI_ROWS_LIVE);
  const els = { planet: planetKey };
  panel.querySelectorAll('.hi-val[data-id]').forEach((el) => { els[el.dataset.id] = el; });
  hierarchyInspector._els = els;
}

function _hiWriteReadouts(f) {
  const e = hierarchyInspector._els;
  if (!e) return;
  const el = f.el;
  const fx = (v, d, unit = '') => (Number.isFinite(v) ? v.toFixed(d) + unit : '—');
  e.aAU.textContent = fx(el.aAU, 6, ' AU');
  e.e.textContent = fx(el.e, 6);
  e.inclJ2000.textContent = fx(el.inclEclipticDeg, 4, '°');
  e.ascNodeJ2000.textContent = fx(_hiWrap360(el.ascNodeEclipticDeg), 4, '°');
  e.inclInv.textContent = fx(el.inclInvPlaneDeg, 4, '°');
  e.ascNodeInv.textContent = Number.isFinite(el.ascNodeInvPlaneDeg)
    ? fx(_hiWrap360(convertNodeSFrameToEquatorOriginDeg(el.ascNodeInvPlaneDeg, _chainNodeOriginSSDeg())), 4, '°') : '—';
  e.lonPeri.textContent = fx(_hiWrap360(el.lonPeriEclipticDeg), 4, '°');
  e.argPeri.textContent = fx(_hiWrap360(el.lonPeriEclipticDeg - el.ascNodeEclipticDeg), 4, '°');
  e.meanLon.textContent = fx(_hiWrap360(el.meanLonEclipticDeg), 4, '°');
  e.period.textContent = fx(f.pDays / DAYS_PER_JULIAN_YEAR, 4, ' yr');
  e.rPeri.textContent = fx(f.rPeriAU, 6, ' AU');
  e.rApo.textContent = fx(f.rApoAU, 6, ' AU');
  e.rAU.textContent = fx(f.rAU, 6, ' AU');
  e.trueAnomaly.textContent = fx(f.trueAnomalyDeg, 3, '°');
  e.meanAnomaly.textContent = fx(f.meanAnomalyDeg, 3, '°');
  e.eoc.textContent = (f.eocDeg >= 0 ? '+' : '') + fx(f.eocDeg, 3, '°');
  e.inclDate.textContent = fx(f.inclDateDeg, 4, '°');
  e.nodeLonDate.textContent = fx(f.nodeLonDateDeg, 4, '°');
  e.argLat.textContent = fx(f.argLatDeg, 3, '°');
  e.height.textContent = (f.heightAU >= 0 ? '+' : '') + fx(f.heightAU, 6, ' AU');
  e.heightPct.textContent = f.maxHeightAU > 1e-9 ? fx(100 * f.heightAU / f.maxHeightAU, 1, ' %') : '—';
  const north = f.heightAU > 1e-7, south = f.heightAU < -1e-7;
  e.hemisphere.textContent = north ? 'NORTH of the ecliptic' : south ? 'SOUTH of the ecliptic' : 'ON the ecliptic';
  e.hemisphere.style.color = north ? '#4caf50' : south ? '#ffc107' : '#64b5f6';
  e.height.style.color = e.heightPct.style.color = e.hemisphere.style.color;
  e.planetRA.textContent = f.obj.raDisplay || '—';
  e.planetDec.textContent = f.obj.decDisplay || '—';
  e.sunDec.textContent = sun.decDisplay || '—';
  const planetDecDeg = Number.isFinite(f.obj.dec) ? 90 - f.obj.dec * 180 / Math.PI : NaN;
  const sunDecDeg = Number.isFinite(sun.dec) ? 90 - sun.dec * 180 / Math.PI : NaN;
  const dDec = planetDecDeg - sunDecDeg;
  e.decVsSun.textContent = !Number.isFinite(dDec) ? '—' : Math.abs(dDec) < 0.01 ? 'SAME as the Sun'
    : `${Math.abs(dDec).toFixed(2)}° ${dDec > 0 ? 'NORTH' : 'SOUTH'} of the Sun`;
}

function createInspectorPanel() {
  const panel = document.createElement('div');
  panel.id = 'hierarchyInspector';
  const chainKeys = Object.keys(PLANET_HIERARCHIES).filter((k) => PLANET_HIERARCHIES[k].chain);
  panel.innerHTML = `
    <div class="hi-header">
      <div class="hi-title-block">
        <h2>Planet Orbit Analysis</h2>
        <div class="hi-subtitle">Inspect the orbit of date of one planet from the N-body chain — elements, geometry, the orbit picture and the position report vs NASA/JPL</div>
      </div>
      <button class="hi-export-btn" title="Export the orbit picture on screen — the orbit of date top-down with its nodes, apsides and the planet (PNG or SVG download)">Export</button>
      <div class="hi-close" title="Close"></div>
    </div>
    <div class="hi-selector">
      <label>Planet:</label>
      <select class="hi-planet-select">
        ${chainKeys.map((key) => `<option value="${key}">${PLANET_HIERARCHIES[key].label}</option>`).join('')}
      </select>
    </div>
    <div class="hi-body">
      <div class="hi-section">
        <div class="hi-section-title">Chain elements of date</div>
        <div class="hi-elements-content"></div>
      </div>
      <div class="hi-section hi-live-section">
        <div class="hi-section-title">Orbit geometry <span style="color:#4caf50; font-size:10px;">(live)</span></div>
        <div class="hi-live-content"></div>
      </div>
      <div class="hi-section hi-legend-section">
        <div class="hi-section-title">Visual Legend</div>
        <div class="hi-legend-content" style="font-size: 11px; line-height: 1.6;">
          <div><span style="color:#ffffff">White</span> outline: the chain orbit over one period, fanned from the Sun</div>
          <div><span style="color:#00ff00">GREEN</span> fan: above the ecliptic of date &middot; <span style="color:#ff0000">RED</span> fan: below</div>
          <div><span style="color:#4488ff">Blue</span> dashed ring: the ecliptic of date at the semi-major axis</div>
          <div><span style="color:#ff00ff">Magenta</span> sphere ↑: ascending node &middot; <span style="color:#00ffff">Cyan</span> sphere ↓: descending node (<span style="color:#ffff00">yellow</span> dashed: line of nodes)</div>
          <div><span style="color:#00ff00">Green</span> small ↑: highest point &middot; <span style="color:#ff0000">Red</span> small ↓: lowest point</div>
          <div><span style="color:#00ff00">P</span> + green line: perihelion of the chain elements, from the Sun</div>
          <div><span style="color:#ffbf00">Amber</span> line and arc: Sun → planet, true anomaly ν at the Sun</div>
          <div><span style="color:#00ffff">Cyan</span> dashed arc: the chain’s mean anomaly M (an angle, drawn at the Sun beside ν)</div>
          <div><span style="color:#00ffff">Cyan</span> ring: the rendered planet</div>
          <div style="margin-top:6px; color:#8a93a5;">Export — the orbit picture: its month ring puts each month at the Sun’s longitude on the 1st. The Gregorian calendar drifts against the seasons by about a day per 3,300 years, so away from J2000 the vernal equinox leaves March; the four cardinal ticks carry the model’s own dates for the scene year. The outer band carries the IAU constellation boundaries of J2000 with the precession of the equinox of date — a naming of the sidereal direction, not a sky view: over 10⁵ years the stars’ proper motions dissolve the figures.</div>
        </div>
      </div>
      <div class="hi-helpers">
        <div class="hi-helpers-title">Visual Helpers</div>
        <label class="hi-helper-row"><input type="checkbox" data-helper="showInclinationPlane" checked> Orbit plane, nodes and extremes</label>
        <label class="hi-helper-row"><input type="checkbox" data-helper="showPerihelion" checked> Perihelion point and Sun → perihelion line</label>
        <label class="hi-helper-row"><input type="checkbox" data-helper="showAnomalies" checked> Sun → planet line and anomaly arcs</label>
        <label class="hi-helper-row"><input type="checkbox" data-helper="showLocator" checked> Planet locator ring</label>
      </div>
      <div class="hi-section hi-report-section">
        <div class="hi-section-title">Position Report <span style="color:#64b5f6; font-size:10px;">(vs the NASA / JPL test dates)</span></div>
        <div class="hi-report-content">
          <button class="hi-report-btn generate">Generate report</button>
          <div class="hi-report-loading" style="display:none;">Generating report...</div>
          <pre class="hi-report" style="display:none;"></pre>
          <div class="hi-report-buttons" style="display:none;">
            <button class="hi-report-btn download">Download Excel</button>
            <button class="hi-report-btn copy">Copy Report</button>
            <label class="hi-report-checkbox-label">
              <input type="checkbox" class="hi-report-show-all">
              <span>Show all results</span>
            </label>
          </div>
        </div>
      </div>
    </div>
    <div class="hi-footer">
      <button class="hi-nav-btn hi-view-orbit-btn" title="Top-down on the Sun, equinox to the right">⬇ Orbit view</button>
      <button class="hi-nav-btn hi-highlight-btn active">Hide Helpers</button>
      <button class="hi-nav-btn hi-view-planet-btn" title="From behind the planet toward the Sun">◉ Planet view</button>
    </div>`;
  document.body.appendChild(panel);

  panel.querySelector('.hi-close').addEventListener('click', closeHierarchyInspector);
  // ONE "Export" prints the orbit picture of the selected planet at the scene date
  panel.querySelector('.hi-export-btn').addEventListener('click', () => {
    const key = hierarchyInspector.currentPlanet;
    openChartExportModal(inspectorRenderPaperSVG(key), `Planet Orbit Analysis — ${PLANET_HIERARCHIES[key].label}`);
  });
  panel.querySelector('.hi-planet-select').addEventListener('change', (e) => {
    hierarchyInspector.currentPlanet = e.target.value;
    updateInspectorDisplay();
  });
  panel.querySelector('.hi-view-orbit-btn').addEventListener('click', () => focusInspectorCamera('orbit'));
  panel.querySelector('.hi-view-planet-btn').addEventListener('click', () => focusInspectorCamera('planet'));
  panel.querySelector('.hi-highlight-btn').addEventListener('click', (e) => {
    hierarchyInspector.highlightActive = !hierarchyInspector.highlightActive;
    e.target.classList.toggle('active', hierarchyInspector.highlightActive);
    e.target.textContent = hierarchyInspector.highlightActive ? 'Hide Helpers' : 'Show Helpers';
    if (hierarchyInspector.highlightActive) createVisualHelpers(); else clearVisualHelpers();
  });
  panel.querySelectorAll('.hi-helper-row input').forEach((checkbox) => {
    checkbox.addEventListener('change', (e) => {
      hierarchyInspector.helpers[e.target.dataset.helper] = e.target.checked;
      if (hierarchyInspector.highlightActive) createVisualHelpers();
    });
  });
  // Position report — on demand (it walks the scene through the test dates)
  panel.querySelector('.hi-report-btn.generate').addEventListener('click', () => {
    generateAndDisplayReport(hierarchyInspector.currentPlanet);
  });
  panel.querySelector('.hi-report-btn.download').addEventListener('click', async () => {
    if (_currentReportData?.excelData) await exportPlanetReportToExcel(_currentReportData.planetKey, _currentReportData.excelData);
  });
  panel.querySelector('.hi-report-btn.copy').addEventListener('click', () => {
    if (_currentReportData?.screenReport) copyReportToClipboard(_currentReportData.screenReport);
  });
  panel.querySelector('.hi-report-show-all').addEventListener('change', async (e) => {
    hierarchyInspector.showAllResults = e.target.checked;
    if (_currentReportData?.planetKey) {
      const reportElement = panel.querySelector('.hi-report');
      const loadingElement = panel.querySelector('.hi-report-loading');
      loadingElement.style.display = 'block';
      reportElement.style.display = 'none';
      const result = await generatePlanetReport(_currentReportData.planetKey, e.target.checked);
      _currentReportData.screenReport = result.screenReport;
      reportElement.innerHTML = result.screenReport;
      loadingElement.style.display = 'none';
      reportElement.style.display = 'block';
    }
  });
  // Keyboard: ←/→ previous/next planet, Escape/q close
  document.addEventListener('keydown', (e) => {
    if (!panel.classList.contains('visible')) return;
    const activeEl = document.activeElement;
    if (activeEl && (activeEl.tagName === 'INPUT' || activeEl.tagName === 'TEXTAREA' || activeEl.isContentEditable)) return;
    const select = panel.querySelector('.hi-planet-select');
    if (e.key === 'ArrowLeft' || e.key === 'p') {
      select.selectedIndex = (select.selectedIndex + select.length - 1) % select.length;
      select.dispatchEvent(new Event('change'));
    } else if (e.key === 'ArrowRight' || e.key === 'n') {
      select.selectedIndex = (select.selectedIndex + 1) % select.length;
      select.dispatchEvent(new Event('change'));
    } else if (e.key === 'Escape' || e.key === 'q') {
      closeHierarchyInspector();
    }
  });
  return panel;
}

/** (Re)build the readouts and the helpers for the current planet and point the camera at its orbit. */
function updateInspectorDisplay() {
  const H = hierarchyInspector;
  if (!H.panel) return;
  const target = PLANET_HIERARCHIES[H.currentPlanet];
  if (!target) return;
  // (the header subtitle is static; the planet's name is the selector's)
  // the report belongs to the planet it was generated for
  const reportEl = H.panel.querySelector('.hi-report'), btns = H.panel.querySelector('.hi-report-buttons');
  if (_currentReportData && _currentReportData.planetKey !== H.currentPlanet) {
    reportEl.style.display = 'none'; btns.style.display = 'none'; _currentReportData = null;
  }
  _hiBuildReadouts(H.currentPlanet);
  H._lastReadoutJD = null;
  H.highlightActive = true;
  const highlightBtn = H.panel.querySelector('.hi-highlight-btn');
  highlightBtn.classList.add('active');
  highlightBtn.textContent = 'Hide Helpers';
  createVisualHelpers();
  focusInspectorCamera('orbit');
  updateHierarchyLiveData();
}

function openHierarchyInspector() {
  if (!hierarchyInspector.panel) hierarchyInspector.panel = createInspectorPanel();
  hierarchyInspector.panel.classList.add('visible');
  hierarchyInspector.panel.querySelector('.hi-planet-select').value = hierarchyInspector.currentPlanet;
  updateInspectorDisplay();
  // Hide the planet data panel while the inspector is open
  labelDismissed = true;
  const planetLabel = document.getElementById('planetLabel');
  if (planetLabel) planetLabel.style.display = 'none';
  if (o.lookAtObj?.orbitPlaneHelper) o.lookAtObj.orbitPlaneHelper.visible = false;
  if (focusRing) focusRing.visible = false;
}

function closeHierarchyInspector() {
  const H = hierarchyInspector;
  if (!H.panel) return;
  H.panel.classList.remove('visible');
  H.highlightActive = false;
  H._cameraControlActive = false;
  H._cameraTarget = null;
  H._lastTargetPos = null;
  clearVisualHelpers();
  const highlightBtn = H.panel.querySelector('.hi-highlight-btn');
  highlightBtn.classList.remove('active');
  highlightBtn.textContent = 'Show Helpers';
  // Reset view to Earth with the default bird's eye view (same as initial load)
  o.lookAtObj = earth;
  camera.position.set(0, 500, 0);
  controls.target.set(0, 0, 0);
  focusPlanet(earth);
  labelDismissed = false;
  const planetLabel = document.getElementById('planetLabel');
  if (planetLabel) planetLabel.style.display = 'block';
  o.Target = 'Earth';
  planetObjects.forEach((p) => { if (p.orbitPlaneHelper) p.orbitPlaneHelper.visible = false; });
  // Update the "Look at" dropdown to show Earth
  const guiContainer = document.getElementById('gui');
  if (guiContainer) {
    guiContainer.querySelectorAll('select').forEach((select) => {
      if (Array.from(select.options).some((opt) => opt.value === 'Earth')) select.value = 'Earth';
    });
  }
}

// ═══════════════════════════════════════════════════════════════════
// WEBGEOCALC EXPLORER PANEL (.wgc-)
// Shows observed perihelion precession rates 1900-2026 from JPL WebGeoCalc
// Data source: tools/explore/wgc-perihelion-rates.js → data/wgc-perihelion-data.json
// ═══════════════════════════════════════════════════════════════════

let wgcPanel = null;
let wgcData = null;
let wgcSelectedPlanet = 'MERCURY';

async function loadWGCData() {
  if (wgcData) return wgcData;
  wgcData = await fetchRepoJson('public/input/wgc-perihelion-data.json');
  return wgcData;
}

let _stephensonDtPoly = null;
async function loadStephensonDtPolynomial() {
  if (_stephensonDtPoly) return _stephensonDtPoly;
  _stephensonDtPoly = await fetchRepoJson('public/input/stephenson-2016-deltaT-polynomial.json');
  if (_stephensonDtPoly) console.log(`Loaded Stephenson 2016 ΔT polynomial: ${_stephensonDtPoly.segments.length} spline segments`);
  return _stephensonDtPoly;
}

/** Evaluate the Stephenson 2016 ΔT polynomial spline at a given year.
 *  Returns null if year is outside the [-720, 2016] window.
 *  8.6-1: the pure evaluator lives in @essrt/physics/reference/
 *  published-curves; the poly itself is app-loaded JSON data. */
function stephensonDeltaT(year, poly) {
  return _PC.stephensonDeltaT(year, poly);
}

let _stephensonSolar = null;
let _stephensonLunar = null;
let _documentedLunar = null;
let _nasaLunarCanon = null;
function wgcUnwrap(angles) {
  const out = [angles[0]];
  for (let i = 1; i < angles.length; i++) {
    let d = angles[i] - angles[i - 1];
    while (d > 180) d -= 360;
    while (d < -180) d += 360;
    out.push(out[i - 1] + d);
  }
  return out;
}

function wgcLinearFit(x, y) {
  const n = x.length;
  const xMean = x.reduce((s, v) => s + v, 0) / n;
  const yMean = y.reduce((s, v) => s + v, 0) / n;
  let num = 0, den = 0;
  for (let i = 0; i < n; i++) {
    num += (x[i] - xMean) * (y[i] - yMean);
    den += (x[i] - xMean) ** 2;
  }
  return { slope: num / den, intercept: yMean - (num / den) * xMean };
}

/** Render an SVG line chart with data + trend line. */
function wgcRenderChart(title, yrArr, values, color, label, modelValues, omitRate) {
  const W = 800, H = 180;
  const margin = { top: 18, right: 20, bottom: 24, left: 60 };
  const plotW = W - margin.left - margin.right;
  const plotH = H - margin.top - margin.bottom;

  const unwrapped = wgcUnwrap(values);
  const fit = wgcLinearFit(yrArr, unwrapped);

  // Optional modelValues: parallel array to yrArr with the model's ϖ(t) (the chain's
  // apsidal advance + equatorial projection, see wgcModelCurves). Plotted as red polyline.

  // Find min/max of UNWRAPPED values + trend line + model line for scaling
  const allY = [...unwrapped];
  if (modelValues) allY.push(...modelValues);
  const ymin = Math.min(...allY);
  const ymax = Math.max(...allY);
  const yPad = (ymax - ymin) * 0.05 || 1;
  const y0 = ymin - yPad;
  const y1 = ymax + yPad;

  const xmin = yrArr[0];
  const xmax = yrArr[yrArr.length - 1];

  const sx = (x) => margin.left + ((x - xmin) / (xmax - xmin)) * plotW;
  const sy = (y) => margin.top + plotH - ((y - y0) / (y1 - y0)) * plotH;

  // Data polyline (use unwrapped values — smoother)
  let pathPoints = '';
  for (let i = 0; i < yrArr.length; i++) {
    pathPoints += (i === 0 ? 'M' : 'L') + sx(yrArr[i]).toFixed(1) + ',' + sy(unwrapped[i]).toFixed(1) + ' ';
  }

  // Trend line
  const trendY0 = fit.slope * xmin + fit.intercept;
  const trendY1 = fit.slope * xmax + fit.intercept;
  const trendStart = { x: sx(xmin), y: sy(trendY0) };
  const trendEnd   = { x: sx(xmax), y: sy(trendY1) };

  const rateArcSecCy = fit.slope * 3600 * 100;  // "/century
  const startVal = values[0];
  const endVal = values[values.length - 1];

  // Y-axis ticks (4 ticks)
  const yticks = [];
  for (let i = 0; i <= 4; i++) {
    const yv = y0 + (y1 - y0) * (i / 4);
    yticks.push(`<line x1="${margin.left - 4}" y1="${sy(yv).toFixed(1)}" x2="${margin.left}" y2="${sy(yv).toFixed(1)}" stroke="#888" stroke-width="0.5"/>
                  <text x="${margin.left - 6}" y="${(sy(yv) + 3).toFixed(1)}" text-anchor="end" font-size="9" font-family="Inter,system-ui,sans-serif" fill="#aaa">${yv.toFixed(2)}</text>`);
  }

  // X-axis ticks (year)
  const xticks = [];
  const nXticks = Math.min(8, Math.floor((xmax - xmin) / 20) + 1);
  for (let i = 0; i <= nXticks; i++) {
    const xv = xmin + ((xmax - xmin) * i) / nXticks;
    xticks.push(`<line x1="${sx(xv).toFixed(1)}" y1="${margin.top + plotH}" x2="${sx(xv).toFixed(1)}" y2="${margin.top + plotH + 4}" stroke="#888" stroke-width="0.5"/>
                  <text x="${sx(xv).toFixed(1)}" y="${margin.top + plotH + 14}" text-anchor="middle" font-size="9" font-family="Inter,system-ui,sans-serif" fill="#aaa">${Math.round(xv)}</text>`);
  }

  return `
    <div class="wgc-chart">
      <div class="wgc-chart-title">${title}</div>
      <svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" class="wgc-svg">
        <rect x="${margin.left}" y="${margin.top}" width="${plotW}" height="${plotH}" fill="#111" stroke="#333" stroke-width="0.5"/>
        ${yticks.join('')}
        ${xticks.join('')}
        ${modelValues ? `<path d="${modelValues.map((v, i) => (i === 0 ? 'M' : 'L') + sx(yrArr[i]).toFixed(1) + ',' + sy(v).toFixed(1)).join(' ')}" fill="none" stroke="#ff5252" stroke-width="1.4" opacity="0.95"/>` : ''}
        <path d="${pathPoints}" fill="none" stroke="${color}" stroke-width="1.4" opacity="0.95"/>
        ${(() => {
          const xJ2000 = sx(2000);
          if (xJ2000 >= margin.left && xJ2000 <= margin.left + plotW) {
            return `<line x1="${xJ2000.toFixed(1)}" y1="${margin.top}" x2="${xJ2000.toFixed(1)}" y2="${(margin.top + plotH).toFixed(1)}" stroke="#555" stroke-width="0.6" stroke-dasharray="2,3"/><text x="${xJ2000.toFixed(1)}" y="${(margin.top + 8).toFixed(1)}" text-anchor="middle" font-size="8" font-family="Inter,system-ui,sans-serif" fill="#777">J2000</text>`;
          }
          return '';
        })()}
        <text x="${W - margin.right}" y="${margin.top - 4}" text-anchor="end" font-size="10" font-family="Inter,system-ui,sans-serif" fill="#ccc">start: ${startVal.toFixed(3)}\u00B0 &#8594; end: ${endVal.toFixed(3)}\u00B0</text>
        ${modelValues ? `
        <g font-family="Inter,system-ui,sans-serif" font-size="9">
          <rect x="${(margin.left + 6).toFixed(1)}" y="${(margin.top + 4).toFixed(1)}" width="196" height="26" fill="rgba(0,0,0,0.55)" stroke="rgba(255,255,255,0.12)" stroke-width="0.5" rx="3"/>
          <line x1="${(margin.left + 10).toFixed(1)}" y1="${(margin.top + 11).toFixed(1)}" x2="${(margin.left + 22).toFixed(1)}" y2="${(margin.top + 11).toFixed(1)}" stroke="${color}" stroke-width="1.6"/>
          <text x="${(margin.left + 26).toFixed(1)}" y="${(margin.top + 14).toFixed(1)}" fill="#ccc">Observed (WebGeoCalc, ecliptic)</text>
          <line x1="${(margin.left + 10).toFixed(1)}" y1="${(margin.top + 23).toFixed(1)}" x2="${(margin.left + 22).toFixed(1)}" y2="${(margin.top + 23).toFixed(1)}" stroke="#ff5252" stroke-width="1.6"/>
          <text x="${(margin.left + 26).toFixed(1)}" y="${(margin.top + 26).toFixed(1)}" fill="#ccc">Model (N-body)</text>
        </g>` : ''}
      </svg>
      <div class="wgc-chart-footer">
        ${omitRate ? '' : `<span>Observed trend: <b>${rateArcSecCy.toFixed(1)} \u2033/cy</b></span>`}
        ${label ? `<span style="${omitRate ? '' : 'margin-left:16px'}">${label}</span>` : ''}
      </div>
    </div>
  `;
}

function wgcRenderPlanet(planetKey) {
  if (!wgcData || !wgcData[planetKey]) return '<div style="padding:40px;text-align:center;color:#888">Loading data\u2026</div>';
  const d = wgcData[planetKey];

  // Use the exploration script's pre-computed rates. For all trend lines we
  // fall back to raw OLS linear regression (the rate shown in the chart footer).
  // The "sin-fit" rate below is the bias-corrected trend (linear + sinusoid
  // model removes the dominant periodic component). For inner planets (short
  // oscillation periods) both rates agree; for outer planets they differ.
  const piFit = wgcLinearFit(d.yrArr, wgcUnwrap(d.piArr));
  const rateRawCy = piFit.slope * 3600 * 100;                   // raw OLS trend
  const rateSinCy = (d.rates && d.rates.sinPi != null) ? d.rates.sinPi : rateRawCy;
  const ratePiCy = rateSinCy;                                   // prefer sin-fit for period estimate
  const periodYr = ratePiCy !== 0 ? Math.abs(360 * 3600 * 100 / ratePiCy) : Infinity;

  const baselineYr = d.yrArr[d.yrArr.length - 1] - d.yrArr[0];
  const oscPeriod = d.oscPeriod || 10;
  const nCycles = baselineYr / oscPeriod;
  const reliable = nCycles >= 4;  // heuristic: need ≥4 oscillation cycles for clean OLS

  // Planets whose perihelion trend cannot be reliably determined from the
  // 1900-2026 observational baseline: Venus, Jupiter, Saturn, Uranus, Neptune.
  // For Venus / Jupiter / Uranus / Neptune the trend literally flips sign
  // across sub-windows (1800-1900, 1900-2026, 2026-2100). For Saturn the
  // direction stays retrograde across most windows, but the magnitude
  // varies by ~2× depending on which 126-year stretch is used (sliding-
  // window analysis showed midpoint trends from -1,800 to -3,600 ″/cy with
  // 0.4° non-linear residuals). Saturn's "rate" is therefore reported as
  // un-determined and we let the user read the trend visually from the chart.
  // Only Mercury and Mars have reliably resolvable trends from this baseline.
  const undeterminedTrend = ['VENUS', 'JUPITER', 'SATURN', 'URANUS', 'NEPTUNE'].includes(planetKey.toUpperCase());

  // The two model curves (A: the chain's advance in ecliptic longitude; B: + the
  // equatorial projection, the projection hypothesis) — see wgcModelCurves.
  const model = wgcModelCurves(planetKey, d);
  const diffStr = (rate) => undeterminedTrend ? '—' : `${(rateSinCy - rate) >= 0 ? '+' : ''}${(rateSinCy - rate).toFixed(1)}`;

  return `
    <div class="wgc-planet-content">
      <div class="wgc-planet-title">${planetKey} PERIHELION PRECESSION</div>
      <div class="wgc-planet-summary">
        <div><span style="color:#268bd2">\u2501\u2501</span> <b>Observed:</b> ${undeterminedTrend ? '<span style="color:#cb4b16;">\u26a0 trend cannot be determined from 1900\u20132026 baseline</span>' : `[raw OLS] ${rateRawCy.toFixed(1)} \u2033/cy \u2022 [sin+lin] ${rateSinCy.toFixed(1)} \u2033/cy`}</div>
        ${(() => {
          // P8c/P5 \u2014 the split of record (E22 owner decision): the dynamics
          // line is engine D's own 1800\u20132100 window rate from the embedded
          // governed artifact (Newtonian + the derived 1PN supplement, the
          // P8b closure asserts their difference = 3n\u00b3a\u00b2/c\u00b2(1\u2212e\u00b2)); every
          // number bound, none retyped.
          const _wr = CHAIN_ARTIFACT.windowRatesArcsecCy;
          const _pk = planetKey.toLowerCase();
          if (!_wr || _wr.gr[_pk] === undefined) return '';
          const _gr = _wr.gr[_pk], _nw = _wr.newton[_pk], _rel = _gr - _nw;
          return `<div><span style="color:#859900">\u2501\u2501</span> <b>Model (N-body):</b> ${_gr.toFixed(1)} \u2033/cy <span style="color:#aaa">(1800\u20132100 window) = Newtonian ${_nw.toFixed(1)} + relativistic ${_rel.toFixed(2)} (1PN, derived from the model's constants)</span></div>`;
        })()}
      </div>
      <div class="wgc-planet-method">
        Baseline: ${Math.round(baselineYr)} yr, ${nCycles.toFixed(1)}\u00D7 dominant osc period (${oscPeriod} yr) \u2014 ${reliable ? 'raw OLS is reliable' : '\u26a0 too few cycles for raw OLS \u2014 use sin+lin'}${undeterminedTrend ? '<br><span style="color:#cb4b16;">\u26a0 Long-term trend <b>cannot be determined</b> from 1900\u20132026 observations \u2014 short-baseline trend flips sign across sub-windows (1800\u20131900, 1900\u20132026, 2026\u20132100). Only Mercury, Mars, and Saturn have reliably resolvable trends from observation.</span>' : ''}
      </div>
      ${wgcRenderChart('Longitude of perihelion vs. Time (\u03D6 = \u03A9 + \u03C9)', d.yrArr, d.piArr, '#268bd2', `Baseline: ${d.yrArr[0]}\u2013${Math.round(d.yrArr[d.yrArr.length-1])} \u2014 <span style="color:#ff5252">red line = model (own N-body)</span>`, model ? model.values : null, undeterminedTrend)}
      <div class="wgc-frame-note">
        <b>Frame note:</b> All angles (\u03A9, \u03C9, \u03D6) are measured in the <b>ECLIPJ2000</b> frame \u2014
        Earth\u2019s mean ecliptic at J2000, an inertial reference plane. Earth\u2019s current orbital plane
        precesses relative to the invariable plane in ecliptic with period ${Math.round(1296000 / _s3ArcsecPerYr()).toLocaleString('en-US')} yr (the dominant nodal mode s₃).
      </div>
      <details class="wgc-chart-collapsible" data-wgc-chart="node">
        <summary>Ascending node longitude vs. Time (\u03A9) \u2014 ecliptic frame, click to expand</summary>
        ${wgcRenderChart('Ascending node longitude vs. Time (\u03A9) \u2014 ecliptic frame', d.yrArr, d.omArr, '#2aa198', '')}
      </details>
      <details class="wgc-chart-collapsible" data-wgc-chart="arg">
        <summary>Argument of periapsis vs. Time (\u03C9) \u2014 ecliptic frame, click to expand</summary>
        ${wgcRenderChart('Argument of periapsis vs. Time (\u03C9) \u2014 ecliptic frame', d.yrArr, d.wArr, '#859900', '')}
      </details>
    </div>
  `;
}

// The model curve drawn against WebGeoCalc's ϖ(t) — shared by the on-screen
// explorer and the paper export so both carry the same overlay:
//   ϖ = λ₀ + (projectedRa/360000)·(y − 2000)
// i.e. the chain's inertial apsidal advance (360°/perihelionEclipticYears, 1,296,000/g) plus the
// equatorial projection excess (dα/dλ − 1 at the perihelion's longitude) —
// Mercury 531.44 + 42.71 = 574.14, the model's account of the relativistic
// advance (42.98 from the same constants). Owner decision; the derivation,
// the all-planet table and the caveats are doc 13 §1.8. Drawn for every
// planet by the same rule. The Earth-frame RA rate (the equatorial projection
// of the chain motion, perihelionFrameBreakdown) is a different coordinate
// and stays on the Cycles tab, not here.

// |s₃|, ″/yr — the dominant nodal mode of Earth's orbit on the invariable plane
// (the engine's deep secular modes; the obliquity beat's partner). The
// obliquity cycle is the BEAT 2π/(ψ̇ᵢₙ − |s₃|) of the spin axis's INERTIAL
// precession rate against this mode — falsification leg 1.
// ψ̇ᵢₙ is the composed rate × the hybrid's self-anchor factor (the general
// precession plus the planetary mean the N-body ecliptic's motion carries,
// +0.097 ″/yr at J2000 ≡ IAU's ψ_A − p_A), the rate the obliquity integration
// itself precesses ŝ on; the beat is 41,098 yr at J2000 (the general rate
// alone read 41,224). That is the INSTANTANEOUS limit — a dated record
// sees the beat of the pole rate's mean over its own window, with the pole's
// of-date factors (faster spin, lower mean obliquity, higher mean eccentricity
// in the past): 40,927 yr over the LR04 record, the climate formula's p+s₀
// line (createModel().lunisolar.obliquityPeriodRealizedYears, the one home;
// the pane row here shows the J2000 beat).
function _s3ArcsecPerYr() { return _dtc().s3ArcsecPerYr; }   // B2: the chain's (the dominant nodal mode of the deep-mode table)
/** The hybrid's self-anchor factor — the spin axis's inertial rate over the general precession at
 *  J2000 (1.0019 with the series; the factory's own diagnostics, ONE home). 1 until the series-driven
 *  hybrid exists (the deep-time pane and the Framework Verification charts build it first). */
function _spinAxisInertialFactor() {
  const h = _deepHistSeriesM;
  return h && h.alphaArcsecPerYr > 0 ? h.alphaLunisolarArcsecPerYr / h.alphaArcsecPerYr : 1;
}
/** The obliquity beat period at age t_Ma, years — on the spin axis's INERTIAL rate (null past the tidal chain's domain). */
function _obliqBeatYearsAtAge(t_Ma) {
  const Tp = _deepLod().lunisolarPrecessionPeriodYearsAtAge(t_Ma);
  return Tp === null ? null : 1296000 / ((1296000 / Tp) * _spinAxisInertialFactor() - _s3ArcsecPerYr());
}

function wgcModelCurves(planetKey, d) {
  const modelPlanetKey = planetKey.toLowerCase();
  const modelPlanet = planets[modelPlanetKey];
  if (!modelPlanet || !modelPlanet.perihelionEclipticYears || typeof perihelionFrameBreakdown !== 'function') return null;
  const fb = perihelionFrameBreakdown(modelPlanetKey, 2000);
  const latticeCy = 1296000 / modelPlanet.perihelionEclipticYears * 100;   // ″/cy, the chain's inertial advance in ecliptic longitude
  const projectedCy = fb.projectedRa;                                     // ″/cy, the advance + equatorial projection
  const values = new Array(d.yrArr.length);
  for (let i = 0; i < d.yrArr.length; i++) {
    // P5/K5b (owner-ruled): the red curve IS Engine D — the chain's real
    // ϖ(t) in ECLIPJ2000 (the plotted frame). The jd construction mirrors
    // the chain's own year coordinate exactly (round-trip identity, no
    // calendar slip).
    values[i] = _chainPerihelionEclLonDeg(modelPlanetKey, KC_ANCHOR_EPOCH_JD + (d.yrArr[i] - 2000) * DAYS_PER_JULIAN_YEAR);
  }
  // Unwrap the curve (owner-corrected: Neptune's near-zero e lets ϖ wobble
  // across 0° — the wrapped series jumped to ~360) and align its branch to
  // the observed series' start so both plot on one continuous scale.
  for (let i = 1; i < values.length; i++) {
    while (values[i] - values[i - 1] > 180) values[i] -= 360;
    while (values[i] - values[i - 1] < -180) values[i] += 360;
  }
  if (d.piArr && d.piArr.length) {
    const shift = Math.round((d.piArr[0] - values[0]) / 360) * 360;
    if (shift !== 0) for (let i = 0; i < values.length; i++) values[i] += shift;
  }
  const grCy = (typeof relativisticPerihelionAdvanceArcsecCy === 'function') ? relativisticPerihelionAdvanceArcsecCy(modelPlanetKey) : null;
  return { values, latticeCy, projectedCy, excessCy: fb.projection, grCy };
}

// Paper-styled single chart panel for the export SVG.
// W and H are the panel dimensions; everything (axes, ticks, labels, lines) is drawn
// in paper-friendly colors against a near-white plot area.
function wgcPaperChartPanel(xOff, yOff, W, H, opts) {
  const xmlEsc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const { title, yrArr, values, color, modelValues } = opts;
  const m = { top: 30, right: 24, bottom: 32, left: 70 };
  const plotW = W - m.left - m.right;
  const plotH = H - m.top - m.bottom;
  const unwrapped = wgcUnwrap(values);
  const fit = wgcLinearFit(yrArr, unwrapped);
  const allY = [...unwrapped]; if (modelValues) allY.push(...modelValues);
  const ymin = Math.min(...allY), ymax = Math.max(...allY);
  const yPad = (ymax - ymin) * 0.05 || 1;
  const y0 = ymin - yPad, y1 = ymax + yPad;
  const xmin = yrArr[0], xmax = yrArr[yrArr.length - 1];
  const sx = (x) => xOff + m.left + ((x - xmin) / (xmax - xmin)) * plotW;
  const sy = (y) => yOff + m.top + plotH - ((y - y0) / (y1 - y0)) * plotH;

  const COL_AXIS = '#666', COL_TICK = '#aaa', COL_GRID = '#e8e8e8';
  const COL_PLOT_BG = '#fafafa', COL_FRAME = '#bbb';
  const COL_TEXT = '#222';

  let s = '';
  // Chart title
  s += `<text x="${xOff + W/2}" y="${yOff + 14}" text-anchor="middle" font-size="12" font-weight="700" fill="${COL_TEXT}">${xmlEsc(title)}</text>`;
  // Plot background + frame
  s += `<rect x="${xOff + m.left}" y="${yOff + m.top}" width="${plotW}" height="${plotH}" fill="${COL_PLOT_BG}" stroke="${COL_FRAME}" stroke-width="0.7"/>`;

  // Y ticks + horizontal gridlines
  for (let i = 0; i <= 4; i++) {
    const yv = y0 + (y1 - y0) * (i / 4);
    const py = sy(yv);
    if (i > 0 && i < 4) s += `<line x1="${xOff + m.left}" y1="${py.toFixed(1)}" x2="${xOff + m.left + plotW}" y2="${py.toFixed(1)}" stroke="${COL_GRID}" stroke-width="0.5"/>`;
    s += `<line x1="${xOff + m.left - 4}" y1="${py.toFixed(1)}" x2="${xOff + m.left}" y2="${py.toFixed(1)}" stroke="${COL_AXIS}" stroke-width="0.6"/>`;
    s += `<text x="${xOff + m.left - 6}" y="${(py + 3).toFixed(1)}" text-anchor="end" font-size="10" fill="${COL_TICK}">${yv.toFixed(2)}°</text>`;
  }
  // X ticks
  const nXticks = Math.min(8, Math.floor((xmax - xmin) / 20) + 1);
  for (let i = 0; i <= nXticks; i++) {
    const xv = xmin + ((xmax - xmin) * i) / nXticks;
    const px = sx(xv);
    s += `<line x1="${px.toFixed(1)}" y1="${(yOff + m.top + plotH).toFixed(1)}" x2="${px.toFixed(1)}" y2="${(yOff + m.top + plotH + 4).toFixed(1)}" stroke="${COL_AXIS}" stroke-width="0.6"/>`;
    s += `<text x="${px.toFixed(1)}" y="${(yOff + m.top + plotH + 16).toFixed(1)}" text-anchor="middle" font-size="10" fill="${COL_TICK}">${Math.round(xv)}</text>`;
  }
  // J2000 marker
  const xJ2000 = sx(2000);
  if (xJ2000 >= xOff + m.left && xJ2000 <= xOff + m.left + plotW) {
    s += `<line x1="${xJ2000.toFixed(1)}" y1="${(yOff + m.top).toFixed(1)}" x2="${xJ2000.toFixed(1)}" y2="${(yOff + m.top + plotH).toFixed(1)}" stroke="#888" stroke-width="0.6" stroke-dasharray="2,3"/>`;
    s += `<text x="${xJ2000.toFixed(1)}" y="${(yOff + m.top + 10).toFixed(1)}" text-anchor="middle" font-size="9" fill="#888">J2000</text>`;
  }
  // Model line (red) drawn first, observed (blue) on top
  if (modelValues) {
    let p = '';
    for (let i = 0; i < modelValues.length; i++) p += (i === 0 ? 'M' : 'L') + sx(yrArr[i]).toFixed(1) + ',' + sy(modelValues[i]).toFixed(1) + ' ';
    s += `<path d="${p.trim()}" fill="none" stroke="#cc3333" stroke-width="1.4" opacity="0.95"/>`;
  }
  // Observed data line
  let p = '';
  for (let i = 0; i < yrArr.length; i++) p += (i === 0 ? 'M' : 'L') + sx(yrArr[i]).toFixed(1) + ',' + sy(unwrapped[i]).toFixed(1) + ' ';
  s += `<path d="${p.trim()}" fill="none" stroke="${color}" stroke-width="1.6" opacity="0.95"/>`;
  // OLS trend dashed
  const trendY0 = fit.slope * xmin + fit.intercept;
  const trendY1 = fit.slope * xmax + fit.intercept;
  s += `<line x1="${sx(xmin).toFixed(1)}" y1="${sy(trendY0).toFixed(1)}" x2="${sx(xmax).toFixed(1)}" y2="${sy(trendY1).toFixed(1)}" stroke="${color}" stroke-width="0.8" stroke-dasharray="4,3" opacity="0.6"/>`;

  // (the series legend is the page's standard legend row — wgcRenderPaperSVG;
  // the fitted rates and the baseline read in the panel, not on the picture)
  return s;
}

// Render the WGC export as a paper-styled self-contained SVG.
// opts.node / opts.arg: add the ascending-node / argument-of-periapsis charts
// under the perihelion chart (the ones expanded on screen).
function wgcRenderPaperSVG(planetKey, opts) {
  opts = opts || {};
  const showNode = !!opts.node, showArg = !!opts.arg;   // the charts expanded on screen
  if (!wgcData || !wgcData[planetKey]) return '<svg xmlns="http://www.w3.org/2000/svg" width="600" height="100"><text x="20" y="50" font-family="Inter,system-ui,sans-serif" font-size="14" fill="#222">WGC data not loaded for ' + planetKey + '</text></svg>';
  const d = wgcData[planetKey];
  const planetName = planetKey[0] + planetKey.slice(1).toLowerCase();

  const model = wgcModelCurves(planetKey, d);

  // The standard export page: title + legend rows, the chart(s), the credit.
  // The fitted rates, the baseline count and the frame note read in the
  // panel; the picture carries the series and their axes only.
  const W = 1100;
  const CHART_H = 320;
  const CHART_GAP = 16;
  const numCharts = 1 + (showNode ? 1 : 0) + (showArg ? 1 : 0);
  const COL_OBS = '#1976d2', COL_NODE = '#00796b', COL_ARG = '#558b2f', COL_MODEL = '#cc3333';
  const legend = [{ name: numCharts > 1 ? 'Observed ϖ = Ω + ω (WebGeoCalc, ecliptic)' : 'Observed (WebGeoCalc, ecliptic)', color: COL_OBS, bold: true }];
  if (showNode) legend.push({ name: 'Observed Ω', color: COL_NODE });
  if (showArg) legend.push({ name: 'Observed ω', color: COL_ARG });
  if (model) legend.push({ name: 'Model (ecliptic-frame rate + equatorial projection)', color: COL_MODEL });
  legend.push({ name: 'Linear trend (OLS)', color: '#888', dash: '4,3' });
  const head = chartExportHeader(`Perihelion of Planets Verification — ${planetName}, JPL WebGeoCalc 1900–2026`, legend, W);
  const HEADER_H = head.bottom + 8;
  const HGT = HEADER_H + numCharts * CHART_H + (numCharts - 1) * CHART_GAP + CHART_EXPORT_CREDIT_H;

  let s = '';
  s += `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${HGT}" width="${W}" height="${HGT}" font-family="Inter, system-ui, sans-serif">`;
  s += `<rect x="0" y="0" width="${W}" height="${HGT}" fill="#ffffff"/>`;
  s += head.svg;

  // Charts — the perihelion chart always, the others as expanded on screen
  let yOff = HEADER_H;
  s += wgcPaperChartPanel(0, yOff, W, CHART_H, {
    title: 'Longitude of perihelion vs. Time (ϖ = Ω + ω)',
    yrArr: d.yrArr, values: d.piArr, color: COL_OBS,
    modelValues: model ? model.values : null,
  });
  if (showNode) {
    yOff += CHART_H + CHART_GAP;
    s += wgcPaperChartPanel(0, yOff, W, CHART_H, {
      title: 'Ascending node longitude vs. Time (Ω) — ecliptic frame',
      yrArr: d.yrArr, values: d.omArr, color: COL_NODE, modelValues: null,
    });
  }
  if (showArg) {
    yOff += CHART_H + CHART_GAP;
    s += wgcPaperChartPanel(0, yOff, W, CHART_H, {
      title: 'Argument of periapsis vs. Time (ω) — ecliptic frame',
      yrArr: d.yrArr, values: d.wArr, color: COL_ARG, modelValues: null,
    });
  }

  s += chartExportCredit(W, HGT);
  s += '</svg>';
  return s;
}

// ── Chart export: paper SVG → PNG, shown in an in-app modal ─────────────────
// Every Tools-panel export (Framework Verification, Perihelion of Planets
// Verification, Earth–Moon Genesis Analysis, Earth Climate Analysis, dLOD/dt
// Analysis) renders a self-contained paper-style SVG
// string — text/line/path/rect/clipPath only, no foreignObject, no external
// images or stylesheets, width/height on the root. Those SVGs used to be
// opened as a blob: URL in a new tab: a vector document nobody could save as a
// picture, blocked by popup blockers, unusable on an iPad. They are now
// rasterized in the browser (Image → canvas → PNG) and shown in a modal with
// Download PNG / Download SVG / Share / Copy. The canvas stays untainted
// because the SVG references nothing external, and the text renders with the
// page's own fonts, so the PNG matches the panel.
const CHART_EXPORT_PNG_SCALE = 2;    // device pixels per SVG unit (print quality)
const CHART_EXPORT_MAX_PX = 4096;    // iOS Safari's canvas limit per side

function chartExportSlug(title) {
  const s = String(title).normalize('NFKD').replace(/[^\w\s-]+/g, '').trim().replace(/\s+/g, '-').replace(/-+/g, '-');
  return s.slice(0, 80) || 'chart';
}

/** Rasterize a self-contained SVG string to a PNG Blob. Resolves { blob, width, height }. */
function svgStringToPngBlob(svgString, scale) {
  return new Promise((resolve, reject) => {
    const root = (svgString.match(/<svg\b[^>]*>/) || [''])[0];
    const attr = (name) => { const m = root.match(new RegExp('\\s' + name + '="\\s*([\\d.]+)')); return m ? +m[1] : 0; };
    const vb = root.match(/\sviewBox="\s*[-\d.]+\s+[-\d.]+\s+([\d.]+)\s+([\d.]+)/);
    const w = attr('width') || (vb ? +vb[1] : 0), h = attr('height') || (vb ? +vb[2] : 0);
    if (!(w > 0 && h > 0)) { reject(new Error('chart export: the SVG root carries no width/height')); return; }
    const s = Math.min(scale, CHART_EXPORT_MAX_PX / Math.max(w, h));
    const url = URL.createObjectURL(new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' }));
    const img = new Image();
    img.onload = () => {
      URL.revokeObjectURL(url);
      const c = document.createElement('canvas');
      c.width = Math.round(w * s); c.height = Math.round(h * s);
      const ctx = c.getContext('2d');
      ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, c.width, c.height);   // paper background under any transparency
      ctx.drawImage(img, 0, 0, c.width, c.height);
      c.toBlob((blob) => (blob ? resolve({ blob, width: c.width, height: c.height }) : reject(new Error('chart export: toBlob returned null'))), 'image/png');
    };
    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('chart export: the SVG failed to decode')); };
    img.src = url;
  });
}

function chartExportDownload(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = Object.assign(document.createElement('a'), { href: url, download: filename });
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 60000);   // iOS Safari reads the blob after the click returns
}

// ── The paper-export standard (owner: "only the picture") ───────────────────
// Every Tools-panel export shares ONE layout: a 16-px title at y = 18, the
// wrapping legend rows under it (_vfpPaperLegend, first row at y = 34), the
// plot under the legend, axis and tick labels only, and a 9-px credit in the
// bottom-right corner. No subtitle, no caption paragraphs, no fitted numbers,
// no footer sentences — that reading lives in the panels, not in the picture.
const CHART_EXPORT_CREDIT = 'ESSRT · holisticuniverse.com';
const CHART_EXPORT_CREDIT_H = 16;    // the strip under the plot the credit sits in

/** Title + legend rows. Returns { svg, bottom } — `bottom` is where the plot may start. */
function chartExportHeader(title, legendEntries, W) {
  const entries = legendEntries || [];
  const legend = _vfpPaperLegend(entries, W);
  const svg = `<text x="${W / 2}" y="18" text-anchor="middle" fill="#222" font-size="16" font-weight="600" font-family="Inter,Helvetica,Arial,sans-serif">${escapeXml(title)}</text>` + legend.svg;
  return { svg, bottom: entries.length ? legend.bottom : 30 };
}

/** The credit line, bottom-right of a W × H page. */
function chartExportCredit(W, H) {
  return `<text x="${W - 12}" y="${H - 7}" text-anchor="end" font-size="9" fill="#888" font-family="Inter,Helvetica,Arial,sans-serif">${CHART_EXPORT_CREDIT}</text>`;
}

// ── One in-flight open per panel ─────────────────────────────────────────────
// The Tools panels build asynchronously (their data loads first). A second
// click while one was in flight built a SECOND panel: the first stayed in the
// DOM, orphaned and unclosable, on top of the second — "when I am quick the
// panels no longer open" (owner). Further clicks now join the open in flight.
const _panelOpening = new Map();
/** GoatCounter custom event (index.html loads the counter; a no-op when it is
 *  absent, blocked, or on localhost where the counter does not count). */
function _gcEvent(path, title) {
  const gc = window.goatcounter;
  if (gc && typeof gc.count === 'function') gc.count({ path, title, event: true });
}
const _GC_PANEL_TITLES = { wgc: 'Perihelion of Planets Verification', essrt: 'Framework Verification', cfm: 'Earth Climate Analysis', lcr: 'Earth dLOD/dt Analysis' };
function _openPanelOnce(key, build) {
  if (_panelOpening.has(key)) return _panelOpening.get(key);
  _gcEvent('tools/' + key, _GC_PANEL_TITLES[key] || key);
  const p = (async () => { try { return await build(); } finally { _panelOpening.delete(key); } })();
  _panelOpening.set(key, p);
  return p;
}

/** Show a paper-style chart SVG as a downloadable picture (PNG first, SVG kept). */
function openChartExportModal(svgString, title) {
  const slug = chartExportSlug(title);
  _gcEvent('export/' + slug, 'Export: ' + title);
  const isTouch = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
  const modal = document.createElement('div');
  modal.className = 'chart-export-modal';
  modal.innerHTML = `
    <div class="chart-export-card" role="dialog" aria-modal="true" aria-label="Export chart">
      <div class="chart-export-head">
        <div class="chart-export-title"></div>
        <button type="button" class="chart-export-close" aria-label="Close">&#x2715;</button>
      </div>
      <div class="chart-export-body"><div class="chart-export-status">Rendering picture…</div></div>
      <div class="chart-export-actions">
        <button type="button" class="cfm-export-btn" data-act="png" disabled>Download PNG</button>
        <button type="button" class="cfm-export-btn" data-act="svg">Download SVG</button>
        <button type="button" class="cfm-export-btn" data-act="share" hidden>Share…</button>
        <button type="button" class="cfm-export-btn" data-act="copy" hidden>Copy image</button>
      </div>
      <div class="chart-export-hint">${isTouch ? 'Long-press the picture to save it to Photos, or use Share.' : 'Right-click the picture to copy it, or use the buttons.'}</div>
    </div>`;
  modal.querySelector('.chart-export-title').textContent = title;
  const body = modal.querySelector('.chart-export-body');
  const btn = (act) => modal.querySelector(`[data-act="${act}"]`);
  let pngUrl = null;
  const close = () => {
    if (pngUrl) URL.revokeObjectURL(pngUrl);
    document.removeEventListener('keydown', onKey);
    modal.remove();
  };
  const onKey = (e) => { if (e.key === 'Escape') close(); };
  document.addEventListener('keydown', onKey);
  modal.addEventListener('click', (e) => { if (e.target === modal) close(); });
  modal.querySelector('.chart-export-close').addEventListener('click', close);
  btn('svg').addEventListener('click', () => chartExportDownload(new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' }), slug + '.svg'));
  document.body.appendChild(modal);

  svgStringToPngBlob(svgString, CHART_EXPORT_PNG_SCALE).then(({ blob, width, height }) => {
    pngUrl = URL.createObjectURL(blob);
    const img = document.createElement('img');
    img.src = pngUrl; img.alt = title;
    img.width = width / CHART_EXPORT_PNG_SCALE; img.height = height / CHART_EXPORT_PNG_SCALE;
    body.replaceChildren(img);
    btn('png').disabled = false;
    btn('png').addEventListener('click', () => chartExportDownload(blob, slug + '.png'));
    const file = new File([blob], slug + '.png', { type: 'image/png' });
    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      btn('share').hidden = false;
      btn('share').addEventListener('click', () => navigator.share({ files: [file], title }).catch(() => {}));
    }
    if (navigator.clipboard && navigator.clipboard.write && window.ClipboardItem) {
      btn('copy').hidden = false;
      btn('copy').addEventListener('click', () => {
        navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })])
          .then(() => { btn('copy').textContent = 'Copied'; setTimeout(() => { btn('copy').textContent = 'Copy image'; }, 1500); })
          .catch(() => { btn('copy').textContent = 'Copy failed'; });
      });
    }
  }).catch((err) => {
    body.replaceChildren(Object.assign(document.createElement('div'), { className: 'chart-export-status', textContent: String(err.message || err) + ' — the SVG download still works.' }));
  });
}

/** Export the current planet: the perihelion chart plus whichever of the
 *  node / argument charts are expanded on screen ({ node, arg }). */
function exportWGCPaper(planetKey, opts) {
  opts = opts || {};
  if (!wgcData) { alert('WGC data not loaded yet'); return; }
  const svg = wgcRenderPaperSVG(planetKey, opts);
  const planetName = planetKey[0] + planetKey.slice(1).toLowerCase();
  openChartExportModal(svg, `Perihelion of Planets Verification — ${planetName}`);
}

async function createWGCPanel() {
  await loadWGCData();

  const panel = document.createElement('div');
  panel.id = 'wgcPanel';
  panel.className = 'wgc-modal';

  // Earth excluded: Earth's ecliptic inclination is ~0 by definition (ecliptic IS
  // Earth's orbital plane), so its ascending node Ω is numerically undefined
  // and produces spurious trends. The reference WebGeoCalc charts also omit Earth.
  const planets = ['MERCURY','VENUS','MARS','JUPITER','SATURN','URANUS','NEPTUNE'];
  if (!planets.includes(wgcSelectedPlanet)) wgcSelectedPlanet = 'MERCURY';

  panel.innerHTML = `
    <div class="wgc-overlay"></div>
    <div class="wgc-container">
      <div class="wgc-header">
        <div class="wgc-title-block">
          <div class="wgc-title">Perihelion of Planets Verification</div>
          <div class="wgc-subtitle">The model vs the observed perihelion precession from JPL NAIF WebGeoCalc (1900\u20132026)</div>
        </div>
        <div class="wgc-controls">
          <button class="wgc-export-btn" data-wgc-export title="Export the current planet's charts as on screen \u2014 the perihelion chart plus any expanded chart (PNG or SVG download)">Export</button>
        </div>
        <div class="wgc-close" title="Close"></div>
      </div>
      <div class="wgc-body">
        <div class="wgc-tabs">
          ${planets.map(p => `<button class="wgc-tab${p === wgcSelectedPlanet ? ' wgc-tab-active' : ''}" data-planet="${p}">${p[0] + p.slice(1).toLowerCase()}</button>`).join('')}
        </div>
        <div class="wgc-content">
          ${wgcData ? wgcRenderPlanet(wgcSelectedPlanet) : '<div style="padding:40px;text-align:center;color:#888">Loading data\u2026</div>'}
        </div>
      </div>
    </div>
  `;

  // Event: close
  panel.querySelector('.wgc-close').addEventListener('click', closeWGCPanel);
  panel.querySelector('.wgc-overlay').addEventListener('click', closeWGCPanel);

  // Event: tab switch
  panel.querySelectorAll('.wgc-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      wgcSelectedPlanet = tab.dataset.planet;
      panel.querySelectorAll('.wgc-tab').forEach(t => t.classList.toggle('wgc-tab-active', t.dataset.planet === wgcSelectedPlanet));
      panel.querySelector('.wgc-content').innerHTML = wgcRenderPlanet(wgcSelectedPlanet);
    });
  });

  // ONE "Export": the selected planet as on screen — the perihelion chart
  // plus whichever of the two collapsible charts are expanded
  const exportBtn = panel.querySelector('[data-wgc-export]');
  if (exportBtn) exportBtn.addEventListener('click', () => {
    const open = (key) => { const d = panel.querySelector(`details[data-wgc-chart="${key}"]`); return !!(d && d.open); };
    exportWGCPaper(wgcSelectedPlanet, { node: open('node'), arg: open('arg') });
  });

  document.body.appendChild(panel);
  return panel;
}

function openWGCPanel() {
  return _openPanelOnce('wgc', async () => {
    if (wgcPanel) { wgcPanel.remove(); wgcPanel = null; }
    wgcPanel = await createWGCPanel();
    wgcPanel.classList.add('visible');
  });
}

function closeWGCPanel() {
  if (wgcPanel) wgcPanel.classList.remove('visible');
}

// ═══════════════════════════════════════════════════════════════════
// CLIMATE FORMULA EXPLORER (.cfm-)
// The climate formula — L1 (the engine's 28 orbital lines, the 405-kyr
// family among them) + L3 (regime steps: a baseline shift at each dated
// climate-regime transition) — overlaid on LR04
// δ¹⁸O and CENOGRID δ¹⁸O/δ¹³C proxies. The coefficient file still carries
// an L2 array (empty since the 405-kyr family moved into L1); the evaluator
// reads it under 'all', no UI offers it. See docs/92-climate-formula.md.
//
// Coefficients are embedded as CLIMATE_FORMULA_COEFFS below (same pattern
// as PREDICT_COEFFS / BALANCE_PRESETS). Proxy data arrays stay as runtime
// fetches because of size:
//   public/input/lr04-data.json                LR04 (Lisiecki & Raymo 2005)
//   public/input/cenogrid-data.json            CENOGRID (Westerhold 2020, 25-kyr binned)
//   public/input/epica-co2-data.json           EPICA CO₂ (Bereiter 2015, 2-kyr binned)
// ═══════════════════════════════════════════════════════════════════

// CLIMATE_FORMULA_COEFFS_BEGIN
// Source of truth: public/input/climate-formula-coefficients.json
// Regenerated by: python3 scripts/export_climate_formula_browser.py
// Reaches script.js by IMPORT, not by patching: npm run constants:generate
const CLIMATE_FORMULA_COEFFS = FIT.CLIMATE_FORMULA_COEFFS;
// CLIMATE_FORMULA_COEFFS_END

let climateFormulaPanel = null;
let cfmLR04Data = null;                 // public/input/lr04-data.json
let cfmCenogridData = null;             // public/input/cenogrid-data.json
let cfmEpicaData = null;                 // public/input/epica-co2-data.json
let cfmCenco2pipData = null;             // public/input/cenco2pip-data.json
let cfmSelectedTab = 'full';
let cfmSelectedProxy = 'd18o';          // only relevant for CENOGRID tab; 'd18o' or 'd13c'
// Layer toggles. The "L1 alone" line shows the formula with only its orbital
// lines enabled (see cfmEvalRaw). There is no L3 toggle — its contribution
// is visible as the gap between Total and the L1 alone line.
let cfmLayerVisibility = {
  data:  true,   // the proxy record under the formula (off = the formula alone)
  total: true,
  l1:    true,
};

// Per-tab → regime + proxy mapping
function cfmTabToRegime(tabKey) {
  switch (tabKey) {
    case 'past200':
    case 'postMPT':
    case 'postMPText':
    case 'future':
      return 'lr04-post-mpt';
    case 'full':
      // Full LR04 uses a stitched curve — see cfmRegimeForAge() and
      // cfmEvalStitched(). This single regime key is only used for the
      // R² breakdown panel; the chart curve routes per-t through the
      // three LR04 regime fits.
      return 'lr04-full';
    case 'cenogrid':
      return cfmSelectedProxy === 'd13c' ? 'cenogrid-d13c' : 'cenogrid-d18o';
    case 'epica':
      return 'epica-co2';
    case 'cenco2pip':
      return 'cenco2pip';
    default:
      return 'lr04-full';
  }
}

/** Pick the LR04 regime block for a given age (kyr BP), valid for 0–5320 kyr.
 * 0 ≤ t < 1000 → post-MPT; 1000 ≤ t < 2700 → inhg-MPT; 2700 ≤ t ≤ 5320 → pre-iNHG. */
function cfmRegimeForAge(t_kyr_BP) {
  if (t_kyr_BP < 1000) return 'lr04-post-mpt';
  if (t_kyr_BP < 2700) return 'lr04-inhg-mpt';
  return 'lr04-pre-inhg';
}

/** Stitched evaluation for the LR04 window (≤ 5320 kyr). */
function cfmEvalStitched(t_kyr_BP, layer) {
  return cfmEvalRaw(t_kyr_BP, cfmRegimeForAge(t_kyr_BP), layer);
}

/** Mean offset between the CENOGRID (Westerhold 2020) and LR04 (Lisiecki &
 * Raymo 2005) δ¹⁸O stacks over their 0–5.3 Ma overlap. Empirically computed
 * as mean(CENOGRID − LR04) = +0.273 ‰ (n=2115 LR04 samples interpolated
 * against CENOGRID). The two stacks use different reference standards and
 * splice points; this offset is the known systematic difference. Applied
 * as a display-only correction when LR04-fitted segments are shown on the
 * CENOGRID chart so the formula stays continuous across the 5.3 Ma boundary
 * with the cenogrid-d18o fit on the older side. */
const CENOGRID_LR04_D18O_OFFSET = 0.273;

/** Stitched evaluation for the CENOGRID δ¹⁸O view (0–67 Ma):
 *   0 ≤ t ≤ 5320 kyr → LR04 regime fits + CENOGRID_LR04_D18O_OFFSET
 *                       (recovers Quaternary amplitudes; offset puts the
 *                       result on the CENOGRID absolute scale)
 *   t > 5320 kyr     → cenogrid-d18o fit (deep-time trend + L3 step terms)
 * For δ¹³C there's no LR04-equivalent stack, so the caller uses cenogrid-d13c
 * directly via cfmEvalRaw — this helper is δ¹⁸O-only. */
function cfmEvalStitchedCenogrid(t_kyr_BP, layer) {
  if (t_kyr_BP <= 5320) {
    return cfmEvalRaw(t_kyr_BP, cfmRegimeForAge(t_kyr_BP), layer) + CENOGRID_LR04_D18O_OFFSET;
  }
  return cfmEvalRaw(t_kyr_BP, 'cenogrid-d18o', layer);
}

async function loadCfmLR04Data() {
  if (cfmLR04Data) return cfmLR04Data;
  cfmLR04Data = await fetchRepoJson('public/input/lr04-data.json');
  return cfmLR04Data;
}

async function loadCenogridData() {
  if (cfmCenogridData) return cfmCenogridData;
  cfmCenogridData = await fetchRepoJson('public/input/cenogrid-data.json');
  return cfmCenogridData;
}

async function loadEpicaData() {
  if (cfmEpicaData) return cfmEpicaData;
  cfmEpicaData = await fetchRepoJson('public/input/epica-co2-data.json');
  return cfmEpicaData;
}

async function loadCenco2pipData() {
  if (cfmCenco2pipData) return cfmCenco2pipData;
  cfmCenco2pipData = await fetchRepoJson('public/input/cenco2pip-data.json');
  return cfmCenco2pipData;
}

/** Evaluate climate formula in original-proxy units at age t (kyr BP).
 * Each layer line shows the formula with that layer ON TOP OF the
 * regime-adjusted baseline (baseline + L3 step terms), so the line
 * follows the L3 step structure and the user can see the layer's
 * unique wiggles overlaid on the regime story:
 *   layer='l1'  → baseline + L1 + L3   (orbital wiggles on regime baseline)
 *   layer='all' → baseline + L1 + L2 + L3   (= Total; L2 is empty in the shipped file)
 * L3 is included in every line because it defines the per-period climate
 * regime — without it, layer lines float on the smooth linear trend and
 * fail to track the visible step structure in the data. */
function cfmEvalRaw(t_kyr_BP, regimeKey, layer) {
  const r = CLIMATE_FORMULA_COEFFS.regimes[regimeKey];
  if (!r) return NaN;
  let C = r.intercept;
  if (layer === 'l1' || layer === 'all') {
    for (const c of r.L1) {
      const omega = 2 * Math.PI / c.period_kyr;
      C += c.a * Math.cos(omega * t_kyr_BP) + c.b * Math.sin(omega * t_kyr_BP);
    }
  }
  if (layer === 'all') {
    for (const c of r.L2) {
      const omega = 2 * Math.PI / c.p_kyr;
      C += c.a * Math.cos(omega * t_kyr_BP) + c.b * Math.sin(omega * t_kyr_BP);
    }
  }
  // L3 step terms are included on EVERY layer line (defines regime baseline)
  for (const s of r.L3) {
    if (t_kyr_BP >= s.t_kyr) C += s.beta;
  }
  const d = r.denormalization;
  return C * d.y_std + d.y_mean + d.trend_slope * t_kyr_BP + d.trend_intercept;
}

/** Find local maxima or minima in [t, vals] arrays.
 *  type: 'max' (glacial) or 'min' (interglacial); prominence in proxy units.
 *  halfWidth = sample radius for peak detection AND baseline computation;
 *    pick large enough that half-cycle peaks (~10 kyr each side) are flat
 *    enough to register as extrema. Default 8 works for short-window views
 *    where dtGrid is sub-kyr; tune up (e.g. 32) for cycle-scale searches. */
function cfmFindExtrema(t, vals, type, prominence, halfWidth = 8) {
  const out = [];
  for (let i = halfWidth; i < vals.length - halfWidth; i++) {
    const v = vals[i];
    let isExtremum = true;
    for (let j = 1; j <= halfWidth; j++) {
      if (type === 'max' && (vals[i - j] >= v || vals[i + j] >= v)) { isExtremum = false; break; }
      if (type === 'min' && (vals[i - j] <= v || vals[i + j] <= v)) { isExtremum = false; break; }
    }
    if (!isExtremum) continue;
    const localOpposite = (vals[i - halfWidth] + vals[i + halfWidth]) / 2;
    if (Math.abs(v - localOpposite) < prominence) continue;
    out.push({ t: t[i], v });
  }
  return out;
}

/** Render the multi-layer climate-formula overlay chart for a chosen tab.
 *  tabKey: 'past200' | 'postMPT' | 'postMPText' | 'full' | 'cenogrid' | 'epica' | 'future'
 *  Respects cfmLayerVisibility (data/total/l1) and cfmSelectedProxy (for CENOGRID). */
function cfmRenderChart(tabKey) {
  const needsLR04 = tabKey !== 'cenogrid' && tabKey !== 'epica' && tabKey !== 'cenco2pip';
  if (needsLR04 && !cfmLR04Data) {
    return '<div style="padding:40px;text-align:center;color:#888">Loading LR04 data…</div>';
  }
  if (!cfmCenogridData && tabKey === 'cenogrid') {
    return '<div style="padding:40px;text-align:center;color:#888">Loading CENOGRID data…</div>';
  }
  if (!cfmEpicaData && tabKey === 'epica') {
    return '<div style="padding:40px;text-align:center;color:#888">Loading EPICA CO₂ data…</div>';
  }
  if (!cfmCenco2pipData && tabKey === 'cenco2pip') {
    return '<div style="padding:40px;text-align:center;color:#888">Loading CenCO2PIP data…</div>';
  }

  // Tab → window + title + regime + data source
  let t_lo, t_hi, title, subtitle, showFuture, isCenogrid = false, isEpica = false, isCenco2pip = false;
  let dataAges, dataVals, proxyLabel;
  switch (tabKey) {
    case 'past200':
      t_lo = 0;    t_hi = 200;  title = 'Last 200 kyr';
      subtitle = 'High-resolution recent record; LGM + MIS 6 visible';
      showFuture = false; break;
    case 'postMPT':
      t_lo = 0;    t_hi = 700;  title = 'Post-MPT (0–700 kyr BP)';
      subtitle = '~7 glacial-interglacial cycles since MPT';
      showFuture = false; break;
    case 'postMPText':
      t_lo = 0;    t_hi = 1200; title = 'Post-MPT extended (0–1,200 kyr BP)';
      subtitle = 'Stitched across MPT (~1 Ma): post-MPT 100-kyr-band ↔ iNHG–MPT 41-kyr-band';
      showFuture = false; break;
    case 'full':
      t_lo = 0;    t_hi = 5320; title = 'Full LR04 (0–5,320 kyr BP)';
      subtitle = 'Stitched per-regime fit (Post-MPT · iNHG–MPT · Pre-iNHG) · Pre-MPT 41-kyr-band, Post-MPT 100-kyr-band';
      showFuture = false; break;
    case 'cenogrid':
      t_lo = 0;    t_hi = 67000;
      title = `CENOGRID (0–67 Myr BP) — ${cfmSelectedProxy === 'd13c' ? 'δ¹³C' : 'δ¹⁸O'}`;
      subtitle = (cfmSelectedProxy === 'd13c'
                  ? 'Carbon-cycle proxy. L3 step components dominate variance (B5).'
                  : 'Deep-time benthic stack. L3 step components at PETM/EOT/Mi-1/MMCT/iNHG/MPT.');
      showFuture = false; isCenogrid = true; break;
    case 'epica':
      t_lo = 0;    t_hi = 800;
      title = 'EPICA CO₂ (0–800 kyr BP)';
      subtitle = 'Cross-proxy test: same L1 line set fitted to atmospheric CO₂ from Antarctic ice cores';
      showFuture = false; isEpica = true; break;
    case 'cenco2pip':
      t_lo = 0;    t_hi = 66000;
      title = 'CenCO2PIP CO₂ (0–66 Myr BP)';
      subtitle = 'Deep-time atmospheric CO₂ — Bayesian synthesis of multi-proxy data (CenCO2PIP Consortium 2023)';
      showFuture = false; isCenco2pip = true; break;
    case 'future':
      t_lo = -250; t_hi = 250;  title = 'Forward projection: −250 to +250 kyr';
      subtitle = 'Past = LR04 + formula match; future = post-MPT formula extrapolation';
      showFuture = true; break;
    default:
      t_lo = 0;    t_hi = 200;  title = ''; subtitle = ''; showFuture = false;
  }

  // Data source + proxy label
  if (isCenogrid) {
    dataAges = cfmCenogridData.age_kyr_BP;
    dataVals = cfmSelectedProxy === 'd13c'
                ? cfmCenogridData.d13c_per_mille
                : cfmCenogridData.d18o_per_mille;
    proxyLabel = cfmSelectedProxy === 'd13c'
                  ? 'CENOGRID δ¹³C (Westerhold 2020)'
                  : 'CENOGRID δ¹⁸O (Westerhold 2020)';
  } else if (isEpica) {
    dataAges = cfmEpicaData.age_kyr_BP;
    dataVals = cfmEpicaData.co2_ppm;
    proxyLabel = 'EPICA CO₂ (Bereiter 2015)';
  } else if (isCenco2pip) {
    dataAges = cfmCenco2pipData.age_kyr_BP;
    dataVals = cfmCenco2pipData.co2_ppm;
    proxyLabel = 'CenCO2PIP CO₂ (Consortium 2023, median)';
  } else {
    dataAges = cfmLR04Data.age_kyr_BP;
    dataVals = cfmLR04Data.d18o_per_mille;
    proxyLabel = 'LR04 δ¹⁸O (Lisiecki & Raymo 2005)';
  }

  // Regime + R² for current tab
  const regimeKey = cfmTabToRegime(tabKey);
  const regime = CLIMATE_FORMULA_COEFFS.regimes[regimeKey];

  // Extract proxy data in the window (only for past, t ≥ 0)
  const dT = [], dV = [];
  for (let i = 0; i < dataAges.length; i++) {
    if (dataAges[i] >= Math.max(0, t_lo) && dataAges[i] <= t_hi) {
      dT.push(dataAges[i]); dV.push(dataVals[i]);
    }
  }

  // Build formula grids for each layer (resolution scales with window).
  // Full LR04 uses per-regime stitching so amplitudes match each regime
  // instead of being diluted by a single 5.3-Myr joint fit.
  // Deep-time tabs (cenogrid, cenco2pip) use 3000 samples (dtGrid ~22 kyr)
  // — needed so the 100-kyr post-MPT glacial cycles are sampled above
  // Nyquist; otherwise peaks at t=0 appear as single-pixel spikes because
  // neighbouring troughs fall between samples.
  const nSamples = (tabKey === 'cenogrid' || tabKey === 'cenco2pip') ? 3000 : 1000;
  const dtGrid = (t_hi - t_lo) / nSamples;
  const fT = [];
  const totalV = [], l1V = [], l3V = [];
  // Tabs that span a regime boundary use stitched fits so each segment
  // matches its data amplitude:
  //   full + postMPText → LR04 regime stitching only
  //   cenogrid δ¹⁸O      → LR04 regimes for ≤5.3 Ma + cenogrid-d18o for older
  //   cenogrid δ¹³C      → single cenogrid-d13c regime (no LR04 δ¹³C exists)
  const useCenogridStitch = tabKey === 'cenogrid' && cfmSelectedProxy !== 'd13c';
  const useLR04Stitch     = tabKey === 'full' || tabKey === 'postMPText';
  const evalAt = useCenogridStitch
    ? (t, layer) => cfmEvalStitchedCenogrid(t, layer)
    : useLR04Stitch
    ? (t, layer) => cfmEvalStitched(t, layer)
    : (t, layer) => cfmEvalRaw(t, regimeKey, layer);
  for (let t = t_lo; t <= t_hi + 1e-9; t += dtGrid) {
    fT.push(t);
    totalV.push(evalAt(t, 'all'));
    l1V.push(evalAt(t, 'l1'));
    l3V.push(evalAt(t, 'l3'));
  }

  // Chart dimensions
  const W = 980, H = 380;
  const margin = { top: 30, right: 30, bottom: 60, left: 60 };
  const plotW = W - margin.left - margin.right;
  const plotH = H - margin.top - margin.bottom;

  // CO₂ tabs (EPICA, CenCO2PIP) use a standard (non-inverted) y-axis.
  const isCo2 = isEpica || isCenco2pip;

  // y-range: locked to data + Total so the scale doesn't jump when the L1
  // toggle is flipped. The L1 line stays inside this range because it only
  // differs from Total by the L3 steps — small relative to the data + Total spread.
  const allV = [...dV, ...totalV];
  const finiteV = allV.filter(v => Number.isFinite(v));
  const ymin = finiteV.length ? Math.min(...finiteV) : -1;
  const ymax = finiteV.length ? Math.max(...finiteV) : 1;
  const yPad = (ymax - ymin) * 0.08 || 0.2;
  let y0 = ymin - yPad;
  let y1 = ymax + yPad;
  // CO₂ is physically non-negative; clamp the axis floor at 0 so we never
  // show negative ppm even when padding pushes it below zero.
  if (isCo2) y0 = Math.max(0, y0);

  const xmin = t_lo;
  const xmax = t_hi;

  // x-axis runs left-to-right with TIME (past on left, future on right)
  const sx = x => margin.left + ((xmax - x) / (xmax - xmin)) * plotW;
  // y-axis: δ¹⁸O is inverted by paleoclimate convention (high value = cold → bottom);
  //         CO₂ uses standard orientation (high value = warm → top).
  const sy = isCo2
    ? y => margin.top + ((y1 - y) / (y1 - y0)) * plotH
    : y => margin.top + ((y - y0) / (y1 - y0)) * plotH;

  // Build polylines
  function buildPath(ts, vs) {
    let p = '';
    for (let i = 0; i < ts.length; i++) {
      if (!Number.isFinite(vs[i])) continue;
      p += (p === '' ? 'M' : 'L') + sx(ts[i]).toFixed(1) + ',' + sy(vs[i]).toFixed(1) + ' ';
    }
    return p;
  }
  const dataPath  = buildPath(dT, dV);
  const totalPath = buildPath(fT, totalV);
  const l1Path    = buildPath(fT, l1V);
  const l3Path    = buildPath(fT, l3V);

  // Y-axis ticks
  const yticks = [];
  for (let i = 0; i <= 4; i++) {
    const yv = y0 + (y1 - y0) * (i / 4);
    yticks.push(`<line x1="${margin.left - 4}" y1="${sy(yv).toFixed(1)}" x2="${margin.left}" y2="${sy(yv).toFixed(1)}" stroke="#888" stroke-width="0.5"/>` +
                `<text x="${margin.left - 6}" y="${(sy(yv) + 3).toFixed(1)}" text-anchor="end" font-size="9" font-family="Inter,system-ui,sans-serif" fill="#aaa">${yv.toFixed(2)}</text>`);
  }
  const yLabel = isCo2
                  ? 'CO₂ (ppm)'
                  : (cfmSelectedProxy === 'd13c' && isCenogrid
                      ? 'δ¹³C (‰)'
                      : 'δ¹⁸O (‰)');
  yticks.push(`<text x="14" y="${(margin.top + plotH/2).toFixed(1)}" font-size="10" font-family="Inter,system-ui,sans-serif" fill="#888" transform="rotate(-90 14 ${(margin.top + plotH/2).toFixed(1)})">${yLabel}</text>`);
  // Axis compass anchors — label top and bottom of the y-axis so the
  // physical meaning is obvious without mental conversion.
  //   δ¹⁸O: low value (top) = warm, high value (bottom) = cold (inverted)
  //   δ¹³C: low value (top) = ¹²C-enriched → carbon released to ocean
  //          high value (bottom) = ¹³C-enriched → carbon stored in biosphere
  //   CO₂  (standard axis): high value (top) = warm, low value (bottom) = cold
  if (isCo2) {
    yticks.push(`<text x="${margin.left + 10}" y="${(margin.top + 16).toFixed(1)}" font-size="10" font-family="Inter,system-ui,sans-serif" fill="rgba(255,184,122,0.85)" text-anchor="start" font-weight="600">↑ high CO₂ (warm)</text>`);
    yticks.push(`<text x="${margin.left + 10}" y="${(margin.top + plotH - 6).toFixed(1)}" font-size="10" font-family="Inter,system-ui,sans-serif" fill="rgba(140,180,255,0.85)" text-anchor="start" font-weight="600">↓ low CO₂ (glacial)</text>`);
  } else if (cfmSelectedProxy === 'd13c' && isCenogrid) {
    yticks.push(`<text x="${margin.left + 10}" y="${(margin.top + 16).toFixed(1)}" font-size="10" font-family="Inter,system-ui,sans-serif" fill="rgba(255,155,102,0.85)" text-anchor="start" font-weight="600">↑ carbon released</text>`);
    yticks.push(`<text x="${margin.left + 10}" y="${(margin.top + plotH - 6).toFixed(1)}" font-size="10" font-family="Inter,system-ui,sans-serif" fill="rgba(102,224,160,0.85)" text-anchor="start" font-weight="600">↓ carbon stored</text>`);
  } else {
    yticks.push(`<text x="${margin.left + 10}" y="${(margin.top + 16).toFixed(1)}" font-size="10" font-family="Inter,system-ui,sans-serif" fill="rgba(255,184,122,0.85)" text-anchor="start" font-weight="600">↑ warmer</text>`);
    yticks.push(`<text x="${margin.left + 10}" y="${(margin.top + plotH - 6).toFixed(1)}" font-size="10" font-family="Inter,system-ui,sans-serif" fill="rgba(140,180,255,0.85)" text-anchor="start" font-weight="600">↓ colder</text>`);
  }

  // X-axis ticks. For CENOGRID, use Ma labels; otherwise use BC/AD calendar years
  function cfmFmtYear(yr) {
    if (yr === 0) return '0';
    return yr < 0 ? Math.abs(yr).toLocaleString() + ' BC'
                  : yr.toLocaleString() + ' AD';
  }
  const xticks = [];
  if (isCenogrid || isCenco2pip) {
    // 5 Ma ticks
    for (let xv = 0; xv <= xmax; xv += 5000) {
      const label = (xv / 1000).toFixed(0) + ' Ma';
      xticks.push(`<line x1="${sx(xv).toFixed(1)}" y1="${margin.top + plotH}" x2="${sx(xv).toFixed(1)}" y2="${margin.top + plotH + 4}" stroke="#888" stroke-width="0.5"/>` +
                  `<text x="${sx(xv).toFixed(1)}" y="${margin.top + plotH + 16}" text-anchor="middle" font-size="9" font-family="Inter,system-ui,sans-serif" fill="#aaa">${label}</text>`);
    }
    xticks.push(`<text x="${(margin.left + plotW/2).toFixed(1)}" y="${(H - 18).toFixed(1)}" text-anchor="middle" font-size="10" font-family="Inter,system-ui,sans-serif" fill="#888">Million years before present (Ma BP) — past ← → present</text>`);
  } else {
    const tickStep = (xmax - xmin) <= 250 ? 25
                  : (xmax - xmin) <= 700 ? 100
                  : (xmax - xmin) <= 1500 ? 200
                  : 500;
    for (let xv = Math.ceil(xmin / tickStep) * tickStep; xv <= xmax; xv += tickStep) {
      const yearCE = 2000 - xv * 1000;
      const label = cfmFmtYear(yearCE);
      xticks.push(`<line x1="${sx(xv).toFixed(1)}" y1="${margin.top + plotH}" x2="${sx(xv).toFixed(1)}" y2="${margin.top + plotH + 4}" stroke="#888" stroke-width="0.5"/>` +
                  `<text x="${sx(xv).toFixed(1)}" y="${margin.top + plotH + 16}" text-anchor="middle" font-size="9" font-family="Inter,system-ui,sans-serif" fill="#aaa">${label}</text>`);
    }
    xticks.push(`<text x="${(margin.left + plotW/2).toFixed(1)}" y="${(H - 18).toFixed(1)}" text-anchor="middle" font-size="10" font-family="Inter,system-ui,sans-serif" fill="#888">Calendar year (today ≈ 2000 AD; past ← → future)</text>`);
  }

  // "now" line at t=0 if 0 is in window (every tab includes t=0)
  let nowMarker = '';
  if (xmin <= 0 && xmax >= 0) {
    const x0 = sx(0);
    nowMarker = `<line x1="${x0.toFixed(1)}" y1="${margin.top}" x2="${x0.toFixed(1)}" y2="${margin.top + plotH}" stroke="#ff6b6b" stroke-width="1.0" stroke-dasharray="3,4" opacity="0.7"/>` +
                `<text x="${x0.toFixed(1)}" y="${(margin.top - 6).toFixed(1)}" text-anchor="middle" font-size="9" font-family="Inter,system-ui,sans-serif" fill="#ff6b6b">today</text>`;
  }

  // Marine isotope stage markers (past windows only)
  let eventMarkers = '';
  if (tabKey === 'past200' || tabKey === 'postMPT' || tabKey === 'postMPText' || tabKey === 'future' || tabKey === 'epica') {
    const events = [
      { t: 20,   label: 'LGM' },
      { t: 140,  label: 'MIS 6' },
      { t: 240,  label: 'MIS 8' },
      { t: 340,  label: 'MIS 10' },
      { t: 425,  label: 'MIS 11' },
    ];
    for (const ev of events) {
      if (ev.t >= xmin && ev.t <= xmax) {
        const xe = sx(ev.t);
        eventMarkers += `<line x1="${xe.toFixed(1)}" y1="${margin.top + plotH - 8}" x2="${xe.toFixed(1)}" y2="${margin.top + plotH}" stroke="#ccc" stroke-width="0.6" opacity="0.6"/>` +
                        `<text x="${xe.toFixed(1)}" y="${margin.top + plotH - 12}" text-anchor="middle" font-size="8" font-family="Inter,system-ui,sans-serif" fill="#999">${ev.label}</text>`;
      }
    }
  }

  // L3 transition markers for windows that include transitions
  let transitionMarkers = '';
  const transitionsAll = [
    { t: 56000, label: 'PETM', desc: 'Paleocene-Eocene Thermal Maximum (carbon excursion)' },
    { t: 34000, label: 'EOT',  desc: 'Eocene-Oligocene transition (Antarctic glaciation onset)' },
    { t: 23000, label: 'Mi-1', desc: 'Antarctic deglaciation pulse' },
    { t: 14000, label: 'MMCT', desc: 'Mid-Miocene cooling' },
    { t: 2700,  label: 'iNHG', desc: 'Northern Hemisphere glaciation onset' },
    { t: 1000,  label: 'MPT',  desc: '41-kyr → 100-kyr world' },
  ];
  if (tabKey === 'full' || tabKey === 'cenogrid' || tabKey === 'cenco2pip' || tabKey === 'postMPText') {
    for (const tr of transitionsAll) {
      if (tr.t >= xmin && tr.t <= xmax) {
        const xe = sx(tr.t);
        const showDesc = !isCenogrid && !isCenco2pip;  // 6 transitions would overcrowd
        transitionMarkers += `<line x1="${xe.toFixed(1)}" y1="${margin.top}" x2="${xe.toFixed(1)}" y2="${margin.top + plotH}" stroke="#ff9b66" stroke-width="0.8" stroke-dasharray="4,3" opacity="0.55"/>` +
                              `<text x="${xe.toFixed(1)}" y="${(margin.top + 10).toFixed(1)}" text-anchor="middle" font-size="9" font-family="Inter,system-ui,sans-serif" fill="#ff9b66" font-weight="600">${tr.label}</text>`;
        if (showDesc) {
          transitionMarkers += `<text x="${xe.toFixed(1)}" y="${(margin.top + 22).toFixed(1)}" text-anchor="middle" font-size="8" font-family="Inter,system-ui,sans-serif" fill="rgba(255,155,102,0.7)">${tr.desc}</text>`;
        }
      }
    }
  }

  // Forward-projection markers (future tab only) — derived from the
  // currently-fit formula at render time. Glacial = δ¹⁸O peak (cold,
  // labeled near the bottom of the plot — matches inverted y-axis);
  // interglacial = δ¹⁸O trough (warm, labeled near the top).
  // Two filters: (1) local-prominence ≥ 0.3 ‰ to drop tiny ripples;
  // (2) absolute δ¹⁸O thresholds to keep only physically meaningful
  // events — glacial ≥ 4.5 ‰ (mid-glacial to full-glacial range),
  // interglacial ≤ 3.7 ‰ (true interglacial; Holocene ≈ 3.2).
  // Calibrated against LR04 ranges: glacial 4.8-5.3, mid-cycle 4.0-4.5,
  // interglacial 3.0-3.5.
  let futureMarkers = '';
  if (tabKey === 'future') {
    const GLACIAL_D18O      = 4.5;
    const INTERGLACIAL_D18O = 3.7;
    const fT_future = [], fV_future = [];
    for (let i = 0; i < fT.length; i++) {
      if (fT[i] < 0) { fT_future.push(fT[i]); fV_future.push(totalV[i]); }
    }
    // halfWidth=32 ≈ 20 kyr at this grid (dtGrid 0.625): wide enough to
    // resolve 100-kyr glacial-cycle peaks (which are locally flat).
    const glacials      = cfmFindExtrema(fT_future, fV_future, 'max', 0.3, 32)
                           .filter(p => p.v >= GLACIAL_D18O);
    const interglacials = cfmFindExtrema(fT_future, fV_future, 'min', 0.3, 32)
                           .filter(p => p.v <= INTERGLACIAL_D18O);
    const plotBot = margin.top + plotH;
    for (const ev of [...glacials, ...interglacials]) {
      if (ev.t < xmin || ev.t > xmax) continue;
      const isGlacial = glacials.includes(ev);
      const xe = sx(ev.t);
      const adYear = Math.round((2000 + (-ev.t) * 1000) / 500) * 500;
      const color = isGlacial ? '#8cb4ff' : '#ffb87a';
      const lbl1 = `${isGlacial ? 'Glacial' : 'Interglacial'} ~${adYear.toLocaleString('en-US')} AD`;
      const lbl2 = `δ¹⁸O ${ev.v.toFixed(2)}‰`;
      if (isGlacial) {
        // Bottom of plot (where high δ¹⁸O sits on the inverted axis)
        futureMarkers += `<line x1="${xe.toFixed(1)}" y1="${(plotBot - 8).toFixed(1)}" x2="${xe.toFixed(1)}" y2="${plotBot.toFixed(1)}" stroke="${color}" stroke-width="0.7" opacity="0.8"/>` +
                          `<text x="${xe.toFixed(1)}" y="${(plotBot - 14).toFixed(1)}" text-anchor="middle" font-size="8" font-family="Inter,system-ui,sans-serif" fill="${color}">${lbl1}</text>` +
                          `<text x="${xe.toFixed(1)}" y="${(plotBot - 4).toFixed(1)}" text-anchor="middle" font-size="7" font-family="Inter,system-ui,sans-serif" fill="${color}" opacity="0.75">${lbl2}</text>`;
      } else {
        // Top of plot (where low δ¹⁸O = warm sits)
        futureMarkers += `<line x1="${xe.toFixed(1)}" y1="${margin.top.toFixed(1)}" x2="${xe.toFixed(1)}" y2="${(margin.top + 8).toFixed(1)}" stroke="${color}" stroke-width="0.7" opacity="0.8"/>` +
                          `<text x="${xe.toFixed(1)}" y="${(margin.top + 18).toFixed(1)}" text-anchor="middle" font-size="8" font-family="Inter,system-ui,sans-serif" fill="${color}">${lbl1}</text>` +
                          `<text x="${xe.toFixed(1)}" y="${(margin.top + 28).toFixed(1)}" text-anchor="middle" font-size="7" font-family="Inter,system-ui,sans-serif" fill="${color}" opacity="0.75">${lbl2}</text>`;
      }
    }
  }

  // Future-projection note (future tab only)
  const futureNote = showFuture
    ? `<div class="cfm-future-note"><b>Orbital-only projection.</b> Natural orbital + carbon-cycle + boundary terms only; no anthropogenic CO₂ forcing. Glacial / interglacial markers auto-detected from the curve.<br/>Under natural forcing the curve shows glacial inception by ~30,000 AD (next strong glacial peak at ~60,500 AD). Whether anthropogenic CO₂ alters this depends on CO₂'s causal role in glacial cycles — itself contested. If CO₂ drives temperature (<a href="https://www.nature.com/articles/nature16494" target="_blank" rel="noopener">Ganopolski et al. 2016</a>), present cumulative emissions delay inception by ~50,000 yr (high-emission scenarios ~100,000 yr). If CO₂ lags as a feedback (ice-core record, <a href="https://www.science.org/doi/10.1126/science.1078758" target="_blank" rel="noopener">Caillon et al. 2003</a>), the orbital projection largely holds. Honest scope: post-MPT regime continues.</div>`
    : '';

  // R² breakdown table. Tabs that use a stitched fit (full / postMPText /
  // cenogrid δ¹⁸O) report the true R² of the stitched curve against the
  // proxy data shown in the chart, plus the per-regime breakdown for the
  // regimes that the chart actually crosses.
  let r2Table;
  const usingStitched = useLR04Stitch || useCenogridStitch;
  if (usingStitched) {
    // True stitched R² against the data samples actually plotted.
    let ssRes = 0, ssTot = 0;
    const dMean = dV.reduce((a, b) => a + b, 0) / Math.max(dV.length, 1);
    for (let i = 0; i < dT.length; i++) {
      const yPred = evalAt(dT[i], 'all');
      if (!Number.isFinite(yPred)) continue;
      ssRes += (dV[i] - yPred) ** 2;
      ssTot += (dV[i] - dMean) ** 2;
    }
    const stitchedR2 = ssTot > 0 ? 1 - ssRes / ssTot : NaN;

    const allRegimes = [
      { key: 'lr04-post-mpt', label: 'Post-MPT (0–1 Ma)',          lo: 0,    hi: 1000  },
      { key: 'lr04-inhg-mpt', label: 'iNHG–MPT (1.0–2.7 Ma)',      lo: 1000, hi: 2700  },
      { key: 'lr04-pre-inhg', label: 'Pre-iNHG (2.7–5.3 Ma)',      lo: 2700, hi: 5320  },
      { key: 'cenogrid-d18o', label: 'Cenozoic (5.3–67 Ma)',       lo: 5320, hi: 67000 },
    ];
    // Only list regimes the visible window actually covers AND that the
    // current stitched eval would use.
    const stitched = allRegimes.filter(r => {
      if (r.lo >= t_hi || r.hi <= t_lo) return false;
      // LR04-only stitch doesn't reach the cenogrid block
      if (useLR04Stitch && r.key === 'cenogrid-d18o') return false;
      return true;
    });
    const rows = stitched.map(s => {
      const r = CLIMATE_FORMULA_COEFFS.regimes[s.key].r2;
      return `<tr><td>${s.label} <span class="cfm-r2-regime">${s.key}</span></td>` +
             `<td>${r.l1_only.toFixed(4)}</td>` +
             `<td>${(r.delta_l3 >= 0 ? '+' : '')}${r.delta_l3.toFixed(4)}</td>` +
             `<td><b>${r.l1_l2_l3.toFixed(4)}</b></td></tr>`;
    }).join('');
    const windowDesc = tabKey === 'full'       ? 'full LR04 record'
                      : tabKey === 'postMPText' ? 'Post-MPT extended window'
                      : 'CENOGRID δ¹⁸O record (0–67 Ma)';
    r2Table = `
      <details class="cfm-r2-panel">
        <summary class="cfm-r2-summary">Stitched fit R² = ${stitchedR2.toFixed(4)} (curve shown vs data)</summary>
        <table class="cfm-r2-table">
          <thead><tr><th>Regime</th><th>R² L1</th><th>ΔR² L3</th><th>Total</th></tr></thead>
          <tbody>${rows}
            <tr><td colspan="3"><b>Stitched curve vs ${windowDesc}</b></td><td><b>${stitchedR2.toFixed(4)}</b></td></tr>
          </tbody>
        </table>
      </details>
    `;
  } else {
    const r2 = regime.r2;
    const nL3 = regime.L3.length;
    r2Table = `
      <details class="cfm-r2-panel">
        <summary class="cfm-r2-summary">Per-layer R² breakdown — regime: <span class="cfm-r2-regime">${regimeKey}</span> · total R² = ${r2.l1_l2_l3.toFixed(4)}</summary>
        <table class="cfm-r2-table">
          <thead><tr><th>Layer</th><th>R² (cumulative)</th><th>ΔR² (unique)</th><th>Notes</th></tr></thead>
          <tbody>
            <tr><td>L1 orbital (${regime.L1.length} engine beat lines, the 405-kyr family among them)</td><td>${r2.l1_only.toFixed(4)}</td><td>${r2.l1_only.toFixed(4)}</td><td>Σ aᵢ cos(2πt/Tᵢ) + bᵢ sin(2πt/Tᵢ)</td></tr>
            <tr><td>+ L3 boundary steps (${nL3} transition${nL3 === 1 ? '' : 's'} in window)</td><td>${r2.l1_l2_l3.toFixed(4)}</td><td>${(r2.delta_l3 >= 0 ? '+' : '')}${r2.delta_l3.toFixed(4)}</td><td>Heaviside steps at named events</td></tr>
          </tbody>
        </table>
      </details>
    `;
  }

  // CENOGRID cross-proxy L3 step amplitudes — the "ice vs carbon" story.
  // Always shown on the cenogrid tab regardless of which proxy is selected,
  // because the comparison itself is what's pedagogically valuable.
  // Values are in raw ‰ (β × y_std) so they match the chart's y-axis units.
  let cenogridCompare = '';
  if (tabKey === 'cenogrid') {
    const dO = CLIMATE_FORMULA_COEFFS.regimes['cenogrid-d18o'];
    const dC = CLIMATE_FORMULA_COEFFS.regimes['cenogrid-d13c'];
    const oStd = dO.denormalization.y_std;
    const cStd = dC.denormalization.y_std;
    const interps = {
      PETM:  'Carbon-cycle event (CO₂ / methane release) — both proxies record it',
      EOT:   'Ice-volume event (Antarctic glaciation) — mostly δ¹⁸O',
      'Mi-1':'Deglaciation pulse + carbon reorganization',
      MMCT:  'Mid-Miocene cooling with carbon-burial shift',
      iNHG:  'NH glaciation + carbon-cycle reorganization',
      MPT:   'δ¹⁸O regime shift (climate-sensitivity change)',
    };
    const byLabel = (arr) => Object.fromEntries(arr.map(s => [s.label, s.beta]));
    const oMap = byLabel(dO.L3), cMap = byLabel(dC.L3);
    const order = ['PETM', 'EOT', 'Mi-1', 'MMCT', 'iNHG', 'MPT'];
    const compareRows = order.map(lbl => {
      const oRaw = oMap[lbl] != null ? oMap[lbl] * oStd : null;
      const cRaw = cMap[lbl] != null ? cMap[lbl] * cStd : null;
      const fmt = v => v == null ? '—' : (v >= 0 ? '+' : '') + v.toFixed(2);
      return `<tr><td><b>${lbl}</b></td><td>${fmt(oRaw)}</td><td>${fmt(cRaw)}</td><td>${interps[lbl] || ''}</td></tr>`;
    }).join('');
    cenogridCompare = `
      <details class="cfm-r2-panel">
        <summary class="cfm-r2-summary">L3 step amplitudes: ice (δ¹⁸O) vs carbon (δ¹³C) — what each Cenozoic transition was</summary>
        <table class="cfm-r2-table">
          <thead><tr><th>Transition</th><th>δ¹⁸O jump (‰)</th><th>δ¹³C jump (‰)</th><th>Interpretation</th></tr></thead>
          <tbody>${compareRows}</tbody>
        </table>
      </details>
    `;
  }

  // EPICA carbon-amplification ratios — for each L1 line, the ratio of
  // EPICA-fitted amplitude to LR04 post-MPT-fitted amplitude. Identifies
  // which L1 lines manifest primarily through carbon-cycle dynamics
  // (high ratio) vs ice volume (low ratio).
  let epicaAmpTable = '';
  if (tabKey === 'epica') {
    const ratios = CLIMATE_FORMULA_COEFFS.regimes['epica-co2'].carbon_amplification_ratios || {};
    const entries = Object.values(ratios)
      .map(e => ({ ...e, period_kyr: Number(e.period_kyr) }))
      .sort((a, b) => b.ratio - a.ratio);
    const ampRows = entries.map(e => {
      return `<tr><td>${e.period_kyr.toFixed(1)}</td>` +
             `<td>${e.lr04_post_mpt_amp.toFixed(4)}</td>` +
             `<td>${e.epica_amp.toFixed(4)}</td>` +
             `<td><b>${e.ratio.toFixed(2)}×</b></td>` +
             `<td style="opacity:0.7">${e.label}</td></tr>`;
    }).join('');
    epicaAmpTable = `
      <details class="cfm-r2-panel">
        <summary class="cfm-r2-summary">L1 carbon-amplification ratio (EPICA CO₂ amp / LR04 post-MPT amp) — sorted high → low</summary>
        <table class="cfm-r2-table">
          <thead><tr><th>Period (kyr)</th><th>LR04 amp</th><th>EPICA amp</th><th>Ratio</th><th>Identity</th></tr></thead>
          <tbody>${ampRows}</tbody>
        </table>
      </details>
    `;
  }

  // Layer legend entries — rendered as an HTML strip above the chart so
  // markers (MPT, iNHG, today, etc.) never collide with the legend box.
  const legendItems = [];
  if (cfmLayerVisibility.data)  legendItems.push({ color: '#8cb4ff', label: proxyLabel, kind: 'data' });
  if (cfmLayerVisibility.total) legendItems.push({ color: '#ffffff', label: 'Total (L1+L3)', kind: 'total' });
  if (cfmLayerVisibility.l1)    legendItems.push({ color: '#ffe066', label: 'L1 alone (orbital)', kind: 'l1' });
  const legendHtml = `
    <div class="cfm-legend">
      ${legendItems.map(item => {
        const totalClass = item.kind === 'total' ? ' cfm-legend-total' : '';
        const swatchStyle = item.kind === 'l3'
          ? `background:linear-gradient(90deg, ${item.color} 0 4px, transparent 4px 7px, ${item.color} 7px 11px, transparent 11px 14px, ${item.color} 14px 18px)`
          : `background:${item.color}`;
        return `<span class="cfm-legend-item"><span class="cfm-legend-swatch${totalClass}" style="${swatchStyle}"></span>${item.label}</span>`;
      }).join('')}
    </div>
  `;

  // Render layer polylines based on visibility flags
  // Order matters for layering: L1 below, Total on top, data on top of all
  let layerPaths = '';
  if (cfmLayerVisibility.l1) layerPaths += `<path d="${l1Path}" fill="none" stroke="#ff5252" stroke-width="1.2" opacity="0.85"/>`;
  if (cfmLayerVisibility.total) layerPaths += `<path d="${totalPath}" fill="none" stroke="#ffffff" stroke-width="1.6" opacity="0.95"/>`;

  // Per-tab info note (neutral styling). Short, says what you're looking at.
  const tabNotes = {
    full:       `<b>Three regimes, stitched.</b> The formula curve is routed per-t through the three regime fits (Post-MPT 0–1 Ma · iNHG–MPT 1.0–2.7 Ma · Pre-iNHG 2.7–5.3 Ma), so each section's amplitude matches its regime instead of being diluted by a single 5.3-Myr joint fit. Discontinuities at iNHG (2.7 Ma) and MPT (1.0 Ma) visualize the climate-sensitivity shifts that L3 step terms encode.`,
    postMPText: `<b>Across the MPT transition.</b> A per-regime stitched fit: post-MPT (0–1 Ma) uses the 100-kyr-band amplitudes; iNHG–MPT (1.0–1.2 Ma here) uses the 41-kyr-band amplitudes. The visible discontinuity at MPT is the climate-sensitivity step — the same change that the L3 step term encodes globally.`,
    postMPT:    `<b>The formula's best-fit regime (R² = ${CLIMATE_FORMULA_COEFFS.regimes['lr04-post-mpt'].r2.l1_l2_l3.toFixed(2)}).</b> Seven glacial-interglacial cycles. L1 is dominated by the 100-kyr eccentricity-modulated band; the 405-kyr family contributes little inside a 1-Myr window; no L3 transitions inside the window.`,
    past200:    `<b>Current glacial cycle in detail.</b> Termination I ended the LGM (~20 kyr BP); MIS 6 was the previous deep glacial; we are at the Holocene warm peak (~3.1 ‰ δ¹⁸O).`,
    cenogrid:   `<b>Stitched Cenozoic view.</b> The δ¹⁸O curve routes through the LR04 regime fits for the last 5.3 Myr (so Quaternary amplitudes aren't diluted by the 67-Myr joint fit) and the cenogrid-d18o fit for older times. L3 step terms carry the deep-time variance — PETM, EOT, Mi-1, MMCT, iNHG, MPT. δ¹³C uses the cenogrid-d13c fit only (no LR04 δ¹³C stack exists).`,
    epica:      `<b>Cross-proxy validation.</b> The same ${CLIMATE_FORMULA_COEFFS.config.L1_lines.length} physical L1 lines fitted to <i>atmospheric CO₂</i> from Antarctic ice cores (an independent recording mechanism, independent age model, different physics from benthic δ¹⁸O). R² L1 alone = <b>${CLIMATE_FORMULA_COEFFS.regimes['epica-co2'].r2.l1_only.toFixed(2)}</b>: the same orbital structure that drives ice volume also drives carbon-cycle dynamics. The amplification-ratio table below identifies which L1 lines manifest <i>primarily</i> through carbon-cycle response (high ratio) vs ice-volume response (low ratio).`,
    cenco2pip:  `<b>Deep-time atmospheric CO₂.</b> The CenCO2PIP Consortium (2023, <i>Science</i>) Bayesian synthesis of multi-proxy paleo-CO₂ data — boron isotopes, phytoplankton, paleosols, stomata, liverworts — over the full Cenozoic. CO₂ ranges from ~280 ppm today to peaks of ~1500 ppm in the Eocene (~50 Ma). The L3 step components capture the major Cenozoic CO₂ shifts (PETM spike, EOT decline, Mi-1 / MMCT, NHG cooling). Total R² ≈ ${CLIMATE_FORMULA_COEFFS.regimes['cenco2pip'].r2.l1_l2_l3.toFixed(2)} across 66 Myr.`,
  };
  const tabNote = tabNotes[tabKey]
    ? `<div class="cfm-info">${tabNotes[tabKey]}</div>`
    : '';

  return `
    <div class="cfm-chart-title">${title}</div>
    <div class="cfm-chart-subtitle">${subtitle}</div>
    ${legendHtml}
    <svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" class="cfm-svg">
      <rect x="${margin.left}" y="${margin.top}" width="${plotW}" height="${plotH}" fill="#0a0d11" stroke="#333" stroke-width="0.5"/>
      ${yticks.join('')}
      ${xticks.join('')}
      ${nowMarker}
      ${eventMarkers}
      ${transitionMarkers}
      ${futureMarkers}
      ${cfmLayerVisibility.data ? `<path d="${dataPath}" fill="none" stroke="#8cb4ff" stroke-width="1.3" opacity="0.95"/>` : ''}
      ${layerPaths}
    </svg>
    ${r2Table}
    ${cenogridCompare}
    ${epicaAmpTable}
    ${tabNote}
    ${futureNote}
  `;
}

// ───────────────────────────────────────────────────────────────────
// Paper export — white-background SVG of the current tab.
// Mirrors renderVFPPaperChart's style (Framework Verification modal).
//
// opts.includeData   default true   — overlay the proxy data line
// opts.layers        default ['total'] — which formula layers to draw
//                                     subset of ['l1','total']
// ───────────────────────────────────────────────────────────────────
function cfmRenderPaperChart(tabKey, opts) {
  opts = opts || {};
  const includeData = opts.includeData !== false;
  const layers = opts.layers || ['total'];
  // SVG/XML entity escaping — proxy labels contain '&' (e.g. "Lisiecki & Raymo")
  // which would break the SVG parser if inserted raw into text elements.
  const xmlEsc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

  // Tab → window + title (mirrors cfmRenderChart switch)
  let t_lo, t_hi, title, isCenogrid = false, isEpica = false, isCenco2pip = false;
  switch (tabKey) {
    case 'past200':    t_lo = 0;    t_hi = 200;   title = 'Earth Climate Analysis — Last 200 kyr'; break;
    case 'postMPT':    t_lo = 0;    t_hi = 700;   title = 'Earth Climate Analysis — Post-MPT (0–700 kyr BP)'; break;
    case 'postMPText': t_lo = 0;    t_hi = 1200;  title = 'Earth Climate Analysis — Post-MPT extended (0–1,200 kyr BP)'; break;
    case 'full':       t_lo = 0;    t_hi = 5320;  title = 'Earth Climate Analysis — Full LR04 (0–5,320 kyr BP)'; break;
    case 'cenogrid':
      t_lo = 0; t_hi = 67000; isCenogrid = true;
      title = `Earth Climate Analysis — CENOGRID (0–67 Myr BP, ${cfmSelectedProxy === 'd13c' ? 'δ¹³C' : 'δ¹⁸O'})`;
      break;
    case 'epica':      t_lo = 0;    t_hi = 800;   isEpica = true;
      title = 'Earth Climate Analysis — EPICA CO₂ (0–800 kyr BP)'; break;
    case 'cenco2pip':  t_lo = 0;    t_hi = 66000; isCenco2pip = true;
      title = 'Earth Climate Analysis — CenCO2PIP CO₂ (0–66 Myr BP)'; break;
    case 'future':     t_lo = -250; t_hi = 250;
      title = 'Earth Climate Analysis — Forward projection (−250 to +250 kyr)'; break;
    default:           t_lo = 0;    t_hi = 200;   title = 'Earth Climate Analysis'; break;
  }

  // Data source selection (mirrors cfmRenderChart)
  let dataAges, dataVals, proxyLabel;
  if (isCenogrid) {
    dataAges = cfmCenogridData.age_kyr_BP;
    dataVals = cfmSelectedProxy === 'd13c' ? cfmCenogridData.d13c_per_mille : cfmCenogridData.d18o_per_mille;
    proxyLabel = cfmSelectedProxy === 'd13c' ? 'CENOGRID δ¹³C (Westerhold 2020)' : 'CENOGRID δ¹⁸O (Westerhold 2020)';
  } else if (isEpica) {
    dataAges = cfmEpicaData.age_kyr_BP; dataVals = cfmEpicaData.co2_ppm;
    proxyLabel = 'EPICA CO₂ (Bereiter 2015)';
  } else if (isCenco2pip) {
    dataAges = cfmCenco2pipData.age_kyr_BP; dataVals = cfmCenco2pipData.co2_ppm;
    proxyLabel = 'CenCO2PIP CO₂ (Consortium 2023)';
  } else {
    dataAges = cfmLR04Data.age_kyr_BP; dataVals = cfmLR04Data.d18o_per_mille;
    proxyLabel = 'LR04 δ¹⁸O (Lisiecki & Raymo 2005)';
  }
  const isCo2 = isEpica || isCenco2pip;

  // Extract proxy data in window
  const dT = [], dV = [];
  for (let i = 0; i < dataAges.length; i++) {
    if (dataAges[i] >= Math.max(0, t_lo) && dataAges[i] <= t_hi) {
      dT.push(dataAges[i]); dV.push(dataVals[i]);
    }
  }

  // Formula evaluation
  const regimeKey = cfmTabToRegime(tabKey);
  const nSamples = (tabKey === 'cenogrid' || tabKey === 'cenco2pip') ? 3000 : 1000;
  const dtGrid = (t_hi - t_lo) / nSamples;
  const useCenogridStitch = tabKey === 'cenogrid' && cfmSelectedProxy !== 'd13c';
  const useLR04Stitch     = tabKey === 'full' || tabKey === 'postMPText';
  const evalAt = useCenogridStitch
    ? (t, layer) => cfmEvalStitchedCenogrid(t, layer)
    : useLR04Stitch
    ? (t, layer) => cfmEvalStitched(t, layer)
    : (t, layer) => cfmEvalRaw(t, regimeKey, layer);
  const fT = [], totalV = [], l1V = [];
  for (let t = t_lo; t <= t_hi + 1e-9; t += dtGrid) {
    fT.push(t);
    totalV.push(evalAt(t, 'all'));
    l1V.push(evalAt(t, 'l1'));
  }

  // The standard export page: title + legend rows above a 370-px plot,
  // the credit strip under the axis label (the R² caption reads in the panel)
  const legendItems = [];
  if (includeData)              legendItems.push({ name: proxyLabel,                    color: '#1f2937' });
  if (layers.includes('total')) legendItems.push({ name: 'Total formula (L1+L3)',       color: '#dc2626', bold: true });
  if (layers.includes('l1'))    legendItems.push({ name: 'L1 only (orbital lines)',     color: '#b45309' });
  const W = 1000;
  const head = chartExportHeader(title, legendItems, W);
  const PAD = { l: 80, r: 30, t: head.bottom + 14, b: 70 };
  const plotW = W - PAD.l - PAD.r;
  const plotH = 370;
  const H = PAD.t + plotH + PAD.b + CHART_EXPORT_CREDIT_H;

  // Y-range — locked to data + Total like the modal chart
  const allV = [];
  if (includeData) allV.push(...dV);
  if (layers.includes('total')) allV.push(...totalV);
  if (layers.includes('l1'))    allV.push(...l1V);
  const finiteV = allV.filter(v => Number.isFinite(v));
  const ymin = finiteV.length ? Math.min(...finiteV) : -1;
  const ymax = finiteV.length ? Math.max(...finiteV) : 1;
  const yPad = (ymax - ymin) * 0.08 || 0.2;
  let y0 = ymin - yPad, y1 = ymax + yPad;
  if (isCo2) y0 = Math.max(0, y0);

  const xmin = t_lo, xmax = t_hi;
  // x runs left → right = past → future (today on left edge for forward tab,
  // past on left for backward tabs because xmin = 0; same convention as modal).
  const sx = x => PAD.l + ((xmax - x) / (xmax - xmin)) * plotW;
  // y inverted for δ¹⁸O/δ¹³C, standard for CO₂
  const sy = isCo2
    ? y => PAD.t + ((y1 - y) / (y1 - y0)) * plotH
    : y => PAD.t + ((y - y0) / (y1 - y0)) * plotH;

  function buildPath(ts, vs) {
    let p = '';
    let started = false;
    for (let i = 0; i < ts.length; i++) {
      if (!Number.isFinite(vs[i])) { started = false; continue; }
      const x = sx(ts[i]).toFixed(1), y = sy(vs[i]).toFixed(1);
      p += started ? ` L${x},${y}` : ` M${x},${y}`;
      started = true;
    }
    return p;
  }

  // Paper palette — data as near-black "ground truth", formula in bold red
  // for maximum contrast on white background.
  const colors = {
    bg:       '#ffffff',
    plotBg:   '#ffffff',
    border:   '#ccc',
    grid:     '#e8e8e8',
    gridMaj:  '#ddd',
    tickText: '#555',
    axisLabel:'#444',
    title:    '#222',
    subtitle: '#666',
    data:     '#1f2937',  // slate-800 (near-black, conventional ground truth)
    total:    '#dc2626',  // red-600 (bold model curve)
    l1:       '#b45309',  // amber-700
    today:    '#7c3aed',  // violet-600 (distinct from formula red)
    event:    '#9ca3af',  // gray-400
    trans:    '#b45309',  // amber-700
    glacial:  '#1d4ed8',  // blue-700
    inter:    '#c2410c',  // orange-700
  };

  // Y-axis ticks + label
  let yticks = '';
  for (let i = 0; i <= 4; i++) {
    const yv = y0 + (y1 - y0) * (i / 4);
    const yp = sy(yv).toFixed(1);
    yticks += `<line x1="${PAD.l}" y1="${yp}" x2="${W - PAD.r}" y2="${yp}" stroke="${colors.grid}" stroke-width="0.5"/>`;
    yticks += `<text x="${PAD.l - 8}" y="${yp}" text-anchor="end" dominant-baseline="middle" fill="${colors.tickText}" font-size="11" font-family="Inter,Helvetica,Arial,sans-serif">${yv.toFixed(2)}</text>`;
  }
  const yLabelText = isCo2
    ? 'CO₂ (ppm)'
    : (cfmSelectedProxy === 'd13c' && isCenogrid ? 'δ¹³C (‰)' : 'δ¹⁸O (‰)');
  const yLabel = `<text x="16" y="${PAD.t + plotH / 2}" text-anchor="middle" dominant-baseline="middle" transform="rotate(-90,16,${PAD.t + plotH / 2})" fill="${colors.axisLabel}" font-size="12" font-weight="500" font-family="Inter,Helvetica,Arial,sans-serif">${yLabelText}</text>`;

  // X-axis ticks + label
  let xticks = '';
  let xAxisLabel;
  if (isCenogrid || isCenco2pip) {
    for (let xv = 0; xv <= xmax; xv += 5000) {
      const xp = sx(xv).toFixed(1);
      const label = (xv / 1000).toFixed(0) + ' Ma';
      xticks += `<line x1="${xp}" y1="${PAD.t}" x2="${xp}" y2="${H - PAD.b}" stroke="${colors.grid}" stroke-width="0.5"/>`;
      xticks += `<line x1="${xp}" y1="${H - PAD.b}" x2="${xp}" y2="${H - PAD.b + 4}" stroke="${colors.tickText}" stroke-width="0.5"/>`;
      xticks += `<text x="${xp}" y="${H - PAD.b + 16}" text-anchor="middle" fill="${colors.tickText}" font-size="10" font-family="Inter,Helvetica,Arial,sans-serif">${label}</text>`;
    }
    xAxisLabel = 'Million years before present (Ma BP) — past ← → present';
  } else {
    const span = xmax - xmin;
    const tickStep = span <= 250 ? 25 : span <= 700 ? 100 : span <= 1500 ? 200 : 500;
    for (let xv = Math.ceil(xmin / tickStep) * tickStep; xv <= xmax; xv += tickStep) {
      const xp = sx(xv).toFixed(1);
      const yearCE = 2000 - xv * 1000;
      const label = xv === 0 ? '2000 AD' : (yearCE < 0 ? Math.abs(yearCE).toLocaleString() + ' BC' : yearCE.toLocaleString() + ' AD');
      xticks += `<line x1="${xp}" y1="${PAD.t}" x2="${xp}" y2="${H - PAD.b}" stroke="${colors.grid}" stroke-width="0.5"/>`;
      xticks += `<line x1="${xp}" y1="${H - PAD.b}" x2="${xp}" y2="${H - PAD.b + 4}" stroke="${colors.tickText}" stroke-width="0.5"/>`;
      xticks += `<text x="${xp}" y="${H - PAD.b + 16}" text-anchor="middle" fill="${colors.tickText}" font-size="10" font-family="Inter,Helvetica,Arial,sans-serif">${label}</text>`;
    }
    xAxisLabel = 'Calendar year (today ≈ 2000 AD; past ← → future)';
  }
  const xLabel = `<text x="${PAD.l + plotW / 2}" y="${H - CHART_EXPORT_CREDIT_H - 18}" text-anchor="middle" fill="${colors.axisLabel}" font-size="12" font-weight="500" font-family="Inter,Helvetica,Arial,sans-serif">${xAxisLabel}</text>`;

  // Plot border + clip path
  const plotBorder = `<rect x="${PAD.l}" y="${PAD.t}" width="${plotW}" height="${plotH}" fill="${colors.plotBg}" stroke="${colors.border}" stroke-width="0.5"/>`;
  const clipDef = `<defs><clipPath id="cfm-paper-clip"><rect x="${PAD.l}" y="${PAD.t}" width="${plotW}" height="${plotH}"/></clipPath></defs>`;

  // "today" line if t=0 is in window
  let todayMarker = '';
  if (xmin <= 0 && xmax >= 0) {
    const x0 = sx(0).toFixed(1);
    todayMarker = `<line x1="${x0}" y1="${PAD.t}" x2="${x0}" y2="${H - PAD.b}" stroke="${colors.today}" stroke-width="1" stroke-dasharray="3,4"/>` +
                  `<text x="${x0}" y="${PAD.t - 6}" text-anchor="middle" font-size="10" font-family="Inter,Helvetica,Arial,sans-serif" fill="${colors.today}" font-weight="600">today</text>`;
  }

  // MIS event markers (past-only windows)
  let eventMarkers = '';
  if (tabKey === 'past200' || tabKey === 'postMPT' || tabKey === 'postMPText' || tabKey === 'future' || tabKey === 'epica') {
    const events = [{ t: 20, label: 'LGM' }, { t: 140, label: 'MIS 6' }, { t: 240, label: 'MIS 8' }, { t: 340, label: 'MIS 10' }, { t: 425, label: 'MIS 11' }];
    for (const ev of events) {
      if (ev.t >= xmin && ev.t <= xmax) {
        const xe = sx(ev.t).toFixed(1);
        eventMarkers += `<line x1="${xe}" y1="${H - PAD.b - 10}" x2="${xe}" y2="${H - PAD.b}" stroke="${colors.event}" stroke-width="0.7"/>` +
                        `<text x="${xe}" y="${H - PAD.b - 14}" text-anchor="middle" font-size="9" font-family="Inter,Helvetica,Arial,sans-serif" fill="${colors.event}">${ev.label}</text>`;
      }
    }
  }

  // L3 transition markers
  let transMarkers = '';
  if (tabKey === 'full' || tabKey === 'cenogrid' || tabKey === 'cenco2pip' || tabKey === 'postMPText') {
    const trans = [
      { t: 56000, label: 'PETM' }, { t: 34000, label: 'EOT' }, { t: 23000, label: 'Mi-1' },
      { t: 14000, label: 'MMCT' }, { t: 2700,  label: 'iNHG' }, { t: 1000,  label: 'MPT' },
    ];
    for (const tr of trans) {
      if (tr.t >= xmin && tr.t <= xmax) {
        const xe = sx(tr.t).toFixed(1);
        transMarkers += `<line x1="${xe}" y1="${PAD.t}" x2="${xe}" y2="${H - PAD.b}" stroke="${colors.trans}" stroke-width="0.8" stroke-dasharray="4,3" opacity="0.7"/>` +
                        `<text x="${xe}" y="${PAD.t + 12}" text-anchor="middle" font-size="10" font-family="Inter,Helvetica,Arial,sans-serif" fill="${colors.trans}" font-weight="600">${tr.label}</text>`;
      }
    }
  }

  // Forward projection markers (future tab only)
  let futureMarkers = '';
  if (tabKey === 'future') {
    const GLACIAL_D18O = 4.5, INTERGLACIAL_D18O = 3.7;
    const fT_future = [], fV_future = [];
    for (let i = 0; i < fT.length; i++) {
      if (fT[i] < 0) { fT_future.push(fT[i]); fV_future.push(totalV[i]); }
    }
    const glacials      = cfmFindExtrema(fT_future, fV_future, 'max', 0.3, 32).filter(p => p.v >= GLACIAL_D18O);
    const interglacials = cfmFindExtrema(fT_future, fV_future, 'min', 0.3, 32).filter(p => p.v <= INTERGLACIAL_D18O);
    const plotBot = H - PAD.b;
    for (const ev of [...glacials, ...interglacials]) {
      if (ev.t < xmin || ev.t > xmax) continue;
      const isG = glacials.includes(ev);
      const xe = sx(ev.t).toFixed(1);
      const kyr = (-ev.t).toFixed(0);
      const color = isG ? colors.glacial : colors.inter;
      const lbl1 = `${isG ? 'Glacial' : 'Interglacial'} ${kyr} kyr`;
      if (isG) {
        futureMarkers += `<line x1="${xe}" y1="${plotBot - 10}" x2="${xe}" y2="${plotBot}" stroke="${color}" stroke-width="0.8"/>` +
                         `<text x="${xe}" y="${plotBot - 14}" text-anchor="middle" font-size="9" font-family="Inter,Helvetica,Arial,sans-serif" fill="${color}" font-weight="600">${lbl1}</text>`;
      } else {
        futureMarkers += `<line x1="${xe}" y1="${PAD.t}" x2="${xe}" y2="${PAD.t + 10}" stroke="${color}" stroke-width="0.8"/>` +
                         `<text x="${xe}" y="${PAD.t + 22}" text-anchor="middle" font-size="9" font-family="Inter,Helvetica,Arial,sans-serif" fill="${color}" font-weight="600">${lbl1}</text>`;
      }
    }
  }

  // Curves
  let curvePaths = '';
  if (includeData) {
    const dataPath = buildPath(dT, dV);
    curvePaths += `<path d="${dataPath}" fill="none" stroke="${colors.data}" stroke-width="1.4" opacity="0.9" clip-path="url(#cfm-paper-clip)"/>`;
  }
  if (layers.includes('l1')) {
    curvePaths += `<path d="${buildPath(fT, l1V)}" fill="none" stroke="${colors.l1}" stroke-width="1.6" clip-path="url(#cfm-paper-clip)"/>`;
  }
  if (layers.includes('total')) {
    curvePaths += `<path d="${buildPath(fT, totalV)}" fill="none" stroke="${colors.total}" stroke-width="2.2" clip-path="url(#cfm-paper-clip)"/>`;
  }

  return `<?xml version="1.0" encoding="UTF-8"?>
<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" xmlns="http://www.w3.org/2000/svg">
  <rect width="${W}" height="${H}" fill="${colors.bg}"/>
  ${clipDef}
  ${head.svg}
  ${chartExportCredit(W, H)}
  ${plotBorder}
  ${yticks}
  ${xticks}
  ${yLabel}
  ${xLabel}
  ${todayMarker}
  ${eventMarkers}
  ${transMarkers}
  ${futureMarkers}
  ${curvePaths}
</svg>`;
}

function exportCfmPaper(opts) {
  opts = opts || {};
  const tabKey = cfmSelectedTab;
  // Ensure needed data is loaded before exporting
  const needsLR04   = tabKey !== 'cenogrid' && tabKey !== 'epica' && tabKey !== 'cenco2pip';
  if (needsLR04   && !cfmLR04Data)      { alert('LR04 data not loaded yet'); return; }
  if (tabKey === 'cenogrid'  && !cfmCenogridData)  { alert('CENOGRID data not loaded yet'); return; }
  if (tabKey === 'epica'     && !cfmEpicaData)     { alert('EPICA data not loaded yet'); return; }
  if (tabKey === 'cenco2pip' && !cfmCenco2pipData) { alert('CenCO2PIP data not loaded yet'); return; }
  const svg = cfmRenderPaperChart(tabKey, opts);
  const titleMap = {
    past200: 'Earth Climate Analysis — Last 200 kyr',
    postMPT: 'Earth Climate Analysis — Post-MPT (0–700 kyr BP)',
    postMPText: 'Earth Climate Analysis — Post-MPT extended',
    full: 'Earth Climate Analysis — Full LR04',
    cenogrid: 'Earth Climate Analysis — CENOGRID',
    epica: 'Earth Climate Analysis — EPICA CO₂',
    cenco2pip: 'Earth Climate Analysis — CenCO2PIP CO₂',
    future: 'Earth Climate Analysis — Forward projection',
  };
  openChartExportModal(svg, titleMap[tabKey] || 'Earth Climate Analysis');
}

async function createClimateFormulaPanel() {
  // Coefficients are embedded in the bundle as CLIMATE_FORMULA_COEFFS.
  // Proxy data arrays are fetched on demand; CENOGRID / EPICA / CenCO2PIP
  // are loaded lazily when their tab is first activated.
  await loadCfmLR04Data();
  if (cfmSelectedTab === 'cenogrid')  await loadCenogridData();
  if (cfmSelectedTab === 'epica')     await loadEpicaData();
  if (cfmSelectedTab === 'cenco2pip') await loadCenco2pipData();

  const panel = document.createElement('div');
  panel.id = 'climateFormulaPanel';
  panel.className = 'cfm-modal';

  const tabs = [
    { key: 'cenco2pip',  label: 'CenCO2PIP · 66M' },
    { key: 'cenogrid',   label: 'CENOGRID · 67M' },
    { key: 'full',       label: 'LR04 · 5.3M' },
    { key: 'postMPText', label: 'LR04 · 1.2M' },
    { key: 'epica',      label: 'EPICA · 800k' },
    { key: 'postMPT',    label: 'LR04 · 700k' },
    { key: 'past200',    label: 'LR04 · 200k' },
    { key: 'future',     label: 'LR04 · forward' },
  ];

  const proxySubtoggle = `
    <div class="cfm-proxy-toggle${cfmSelectedTab === 'cenogrid' ? ' cfm-proxy-toggle-visible' : ''}" data-cfm-proxy-toggle>
      <span class="cfm-proxy-toggle-label">CENOGRID proxy:</span>
      <button class="cfm-proxy-btn${cfmSelectedProxy === 'd18o' ? ' cfm-proxy-btn-active' : ''}" data-proxy="d18o">δ¹⁸O</button>
      <button class="cfm-proxy-btn${cfmSelectedProxy === 'd13c' ? ' cfm-proxy-btn-active' : ''}" data-proxy="d13c">δ¹³C</button>
    </div>
  `;

  const layerToggles = `
    <div class="cfm-layer-toggles">
      <span class="cfm-layer-toggles-label">Layers:</span>
      <label class="cfm-layer-check" title="The proxy record under the formula (LR04, CENOGRID, EPICA or CenCO2PIP per tab). Off = the formula alone — the Export prints what is on screen."><input type="checkbox" data-layer="data" ${cfmLayerVisibility.data ? 'checked' : ''}> Proxy data</label>
      <label class="cfm-layer-check" title="Total formula = baseline + L1 + L3 (the complete prediction at each timestamp). The L1 toggle shows the formula with only its orbital lines; the gap to Total is the L3 boundary-condition steps."><input type="checkbox" data-layer="total" ${cfmLayerVisibility.total ? 'checked' : ''}/><span class="cfm-swatch cfm-swatch-total"></span>Total</label>
      <label class="cfm-layer-check" title="L1 only — Orbital forcing applied to the baseline.
Displayed curve = baseline + L1 contributions (the formula's prediction with ONLY L1 enabled).

Structural claim: every L1 line is one of the engine's OWN secular beats — the periods are computed from the model's N-body secular modes (gᵢ apsidal, sᵢ nodal) and its composed precession rate p, never fitted. Only the amplitudes (a, b) are fitted. If the data demanded peaks the engine's beats cannot supply, the formula would be falsified.

Three classic Berger peaks fall out of the beats (Laskar's mode numbering; the engine's own labels appear in the line list):
 • 94.9 kyr  g₄−g₅ Mars-Jupiter eccentricity
 • 41.2 kyr  p+s₃ Earth obliquity
 • 23.8 kyr  p+g₅ Jupiter climatic precession

Composition (28 lines, doc 92 §2 — the engine-written list):
 • 5 climatic-precession lines p+gᵢ (19.0–23.8 kyr) — ride the composed precession rate at deep time
 • 10 obliquity lines p+sᵢ (27.4–54.1 kyr) — ride the composed precession rate at deep time
 • 10 eccentricity lines gᵢ−gⱼ (94.9–134.5 kyr) — planetary beats, fixed at every epoch
 • the 405.6-kyr g₂−g₅ long-eccentricity metronome and its 202.8 / 135.2-kyr carbon-thermostat harmonics (doc 92 §3)

Fitted via sequential ridge regression — see doc 92 §9.

Description, not prediction (T7, doc 92 §2): the per-line amplitudes AND phases are fitted inside each regime window, so the per-regime R² shown here describes the record; fitted on one half of a window the same lines have no skill on the other half. The model's own e(t), ε(t), e·sin ϖ(t) with one coefficient each and a ~6-kyr climate lag keep about half the in-window R² out of sample (post-MPT, iNHG–MPT) — the transferable part; the 100-kyr band is what the fitted lines describe and the linear response cannot generate.

Note: L1 and Total each carry the baseline once — they do NOT visually sum. Read per-layer variance contributions from the R² panel below."><input type="checkbox" data-layer="l1" ${cfmLayerVisibility.l1 ? 'checked' : ''}/><span class="cfm-swatch cfm-swatch-l1"></span>L1 alone</label>
    </div>
  `;

  panel.innerHTML = `
    <div class="cfm-overlay"></div>
    <div class="cfm-container">
      <div class="cfm-header">
        <div class="cfm-title">Earth Climate Analysis</div>
        <div class="cfm-subtitle">The climate formula vs the proxy records — the engine's 28 orbital lines (L1, the 405-kyr family among them) plus regime steps (L3, a baseline shift at each dated climate-regime transition), fitted per regime</div>
        <button class="cfm-export-btn" data-cfm-export title="Export the current tab with the layers toggled on screen as a picture (PNG or SVG download)">Export</button>
        <div class="cfm-close" title="Close"></div>
      </div>
      <div class="cfm-body">
        <div class="cfm-tabs">
          ${tabs.map(t => `<button class="cfm-tab${t.key === cfmSelectedTab ? ' cfm-tab-active' : ''}" data-tab="${t.key}">${t.label}</button>`).join('')}
        </div>
        <div class="cfm-controls">
          ${layerToggles}
          ${proxySubtoggle}
        </div>
        <div class="cfm-content">
          ${cfmRenderChart(cfmSelectedTab)}
        </div>
      </div>
    </div>
  `;

  const contentEl   = panel.querySelector('.cfm-content');
  const proxyToggle = panel.querySelector('[data-cfm-proxy-toggle]');

  function rerender() {
    contentEl.innerHTML = cfmRenderChart(cfmSelectedTab);
  }

  panel.querySelector('.cfm-close').addEventListener('click', closeClimateFormulaPanel);
  panel.querySelector('.cfm-overlay').addEventListener('click', closeClimateFormulaPanel);

  panel.querySelectorAll('.cfm-tab').forEach(tab => {
    tab.addEventListener('click', async () => {
      cfmSelectedTab = tab.dataset.tab;
      panel.querySelectorAll('.cfm-tab').forEach(t => t.classList.toggle('cfm-tab-active', t.dataset.tab === cfmSelectedTab));
      proxyToggle.classList.toggle('cfm-proxy-toggle-visible', cfmSelectedTab === 'cenogrid');
      if (cfmSelectedTab === 'cenogrid' && !cfmCenogridData) {
        contentEl.innerHTML = '<div style="padding:40px;text-align:center;color:#888">Loading CENOGRID data…</div>';
        await loadCenogridData();
      }
      if (cfmSelectedTab === 'epica' && !cfmEpicaData) {
        contentEl.innerHTML = '<div style="padding:40px;text-align:center;color:#888">Loading EPICA CO₂ data…</div>';
        await loadEpicaData();
      }
      if (cfmSelectedTab === 'cenco2pip' && !cfmCenco2pipData) {
        contentEl.innerHTML = '<div style="padding:40px;text-align:center;color:#888">Loading CenCO2PIP data…</div>';
        await loadCenco2pipData();
      }
      rerender();
    });
  });

  panel.querySelectorAll('.cfm-layer-check input').forEach(cb => {
    cb.addEventListener('change', () => {
      cfmLayerVisibility[cb.dataset.layer] = cb.checked;
      rerender();
    });
  });

  panel.querySelectorAll('.cfm-proxy-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      cfmSelectedProxy = btn.dataset.proxy;
      panel.querySelectorAll('.cfm-proxy-btn').forEach(b => b.classList.toggle('cfm-proxy-btn-active', b.dataset.proxy === cfmSelectedProxy));
      rerender();
    });
  });

  // ONE "Export" prints the current view: the tab on screen with the
  // layers toggled on screen (the former "formula only" picture is the
  // Proxy-data toggle off).
  const exportBtn = panel.querySelector('[data-cfm-export]');
  if (exportBtn) exportBtn.addEventListener('click', () => exportCfmPaper({
    includeData: cfmLayerVisibility.data,
    layers: ['total', 'l1'].filter((k) => cfmLayerVisibility[k]),
  }));

  document.body.appendChild(panel);
  return panel;
}

function openClimateFormulaPanel() {
  return _openPanelOnce('cfm', async () => {
    if (climateFormulaPanel) { climateFormulaPanel.remove(); climateFormulaPanel = null; }
    climateFormulaPanel = await createClimateFormulaPanel();
    climateFormulaPanel.classList.add('visible');
  });
}

function closeClimateFormulaPanel() {
  if (climateFormulaPanel) climateFormulaPanel.classList.remove('visible');
}

// ═══════════════════════════════════════════════════════════════════
// ESSRT EXPLORER (.essrt-) — Expanding Solar System Resonance Theory
// Deep-time visualisation of 8 quantities over solar-system history.
// Reuses .cfm-* CSS classes (generic modal patterns).
// ═══════════════════════════════════════════════════════════════════

let essrtPanel = null;
let essrtSelectedQty   = 'lod';   // the day length opens first
let essrtSelectedRange = 'full';

const ESSRT_QTY_TABS = [
  { key: 'axial',      label: 'Axial Precession' },
  { key: 'obliqCycle', label: 'Obliquity period' },
  { key: 'lod',        label: 'Length of Day' },
  { key: 'year',       label: 'Length of Year' },
  { key: 'au',         label: 'AU Distance' },
  { key: 'moon',       label: 'Moon Distance' },
];

// Time ranges (x in calendar Ma; negative = past). Convention: t_Ma_geo = -x.
const ESSRT_RANGE_TABS = [
  { key: 'full',    t_lo: -4429, t_hi: 1000, label: 'Full (−4.43 to +1 Gyr)' },
  { key: 'phanero', t_lo:  -650, t_hi:    0, label: 'Phanerozoic (650 Ma)' },
];

// Wu et al. 2024 (sciadv.ado2412) cyclostratigraphy anchor points.
// All values are paper midpoint estimates; rough ranges from Table 1 / Figures.
const WU_ANCHORS = [
  { t_Ma: 0,   lod_hr: 24.00,  moon_er: 60.27, axial_arcsec_yr: 51.25, lod_sigma: 0,    moon_sigma: 0,    axial_sigma: 0 },
  { t_Ma: 100, lod_hr: 23.65,  moon_er: 59.50, axial_arcsec_yr: 53.0,  lod_sigma: 0.15, moon_sigma: 0.5,  axial_sigma: 1.0 },
  { t_Ma: 200, lod_hr: 23.70,  moon_er: 58.50, axial_arcsec_yr: 54.36, lod_sigma: 0.10, moon_sigma: 0.5,  axial_sigma: 1.0 },
  { t_Ma: 300, lod_hr: 22.75,  moon_er: 54.00, axial_arcsec_yr: 59.5,  lod_sigma: 0.25, moon_sigma: 1.0,  axial_sigma: 0.5 },
  { t_Ma: 400, lod_hr: 21.75,  moon_er: 52.50, axial_arcsec_yr: 61.5,  lod_sigma: 0.25, moon_sigma: 0.5,  axial_sigma: 0.5 },
  { t_Ma: 500, lod_hr: 21.20,  moon_er: 53.50, axial_arcsec_yr: 64.5,  lod_sigma: 0.30, moon_sigma: 0.5,  axial_sigma: 0.5 },
  { t_Ma: 650, lod_hr: 20.94,  moon_er: 56.73, axial_arcsec_yr: 67.64, lod_sigma: 0.10, moon_sigma: 0.30, axial_sigma: 0.30 },
];

// Per-quantity specs. compute(t_Ma) returns a number or null.
const ESSRT_QTY_SPECS = {
  lod: {
    title:    'Length of Day (LOD)',
    subtitle: 'Earth\'s mean solar day length under Driver 1 — angular-momentum conservation on the cited Earth-Moon distance history (Farhat et al. 2022). Tidal slowing increases the day; LOD grew from ~5.5 hr at Earth-Moon genesis (the history\'s end, 4.43 Ga) to ~24 hr at J2000.',
    yLabel:   'LOD (hours)',
    compute:  (t_Ma) => { const s = meanLodSecondsAtAge(t_Ma); return s === null ? null : s / 3600; },
    yFmt:     (v) => v.toFixed(2) + ' hr',
    // From the Hadean ~5.5 hr through J2000 24 hr to ~32 hr at +1 Gyr
    yMin: 0, yMax: 36,
    hasWu:    true,
    wuKey:    'lod_hr',
    wuConvert:(v) => v,
    footnote: 'Note: the small mid-Phanerozoic offset below the Wu et al. 2024 anchors (largest ~0.8 hr at 200 Ma) is the documented Pangea high-tidal-dissipation interval — Wu\'s key finding is that lunar recession ran non-uniformly (~7.0 cm/yr in the supercontinent era vs ~2.2 before it), which the calibrated smooth 0–1000 Ma branch deliberately averages over. The deviation is recorded and gated as documented bands (docs/99 §Pangea interval).',
  },
  year: {
    title:    'Length of Year (sidereal, days at epoch)',
    subtitle: 'Sidereal year length in mean-solar days AT EACH EPOCH. Combines both drivers — Driver 2 sets year-in-seconds (the solar-mass law), Driver 1 sets day-in-seconds (conservation on the cited Earth-Moon distance history). At the Devonian (380 Ma) Earth had ~403 days/year against Wells 1963\'s ~400 coral growth bands. The sidereal year is shown because the tropical year\'s definition fails near genesis, where the precession period collapses to years.',
    yLabel:   'Year (days at epoch)',
    // Sidereal-year seconds (Driver 2) divided by mean solar day length (Driver 1).
    // plan 12 option A: the sidereal year, not the tropical — near the history's end
    // T_p falls to years and the tropical year (one equinox turn fewer) loses its meaning.
    compute:  (t_Ma) => {
      const yearSec = meanSiderealYearSecondsAtAge(t_Ma);
      const lodSec  = meanLodSecondsAtAge(t_Ma);
      if (yearSec === null || lodSec === null || lodSec === 0) return null;
      return yearSec / lodSec;
    },
    yFmt:     (v) => Math.round(v).toLocaleString('en-US') + ' days',
    // Full range needs to cover the Hadean ~1,590 days/yr → +1 Gyr ~274 days/yr.
    // Phanerozoic (650 Ma → J2000) only spans 416 → 365 days/yr — clamp tighter
    // so the curve fills the chart instead of looking flat.
    yMin: 0, yMax: 2000,
    yRangeOverrides: { phanero: { yMin: 0, yMax: 500 } },
    // Wu et al. 2024 doesn't directly tabulate days/year, but it's a trivial
    // derivation from their LOD: days/year = year_seconds / LOD_seconds.
    // (Year-seconds is essentially constant across the Phanerozoic — Driver 2
    // shifts it by only ~0.05% over 650 Myr.)
    // At 400 Ma: 31,556,925 / (21.75 × 3600) ≈ 403 days/year — matches Wells
    // 1963's Devonian coral growth-band count.
    hasWu:    true,
    wuKey:    'lod_hr',
    wuConvert:(lod_hr) => MEAN_TROPICAL_YEAR_J2000_S / (lod_hr * 3600),
    footnote: 'Note: the Wu et al. 2024 points here are derived from their LOD anchors, so the same documented Pangea-interval offset applies as on the Length-of-Day tab (docs/99 §Pangea interval).',
  },
  axial: {
    title:    'Mean Lunisolar Precession Period T_p(t)',
    subtitle: 'The period of the composed torque rate [ω/ω₀]·p₀·[f_S + (1 − f_S)(a₀/a_M)³] — Earth’s spin carrying both torques, the lunar torque growing on the Moon’s distance; 25,771 yr at J2000.',
    yLabel:   'Period (years)',
    // ONE curve, ONE home — the composed lunisolar period from the deep-time
    // factory (earth/precession-composed), on the derived J2000 anchor.
    compute:  (t_Ma) => _deepLod().lunisolarPrecessionPeriodYearsAtAge(t_Ma),
    yFmt:     (v) => Math.round(v).toLocaleString('en-US') + ' yr',
    yMin: 0, yMax: 40000,
    hasWu:    true,
    wuKey:    'axial_arcsec_yr',
    wuConvert:(rate) => 1296000 / rate,
    footnote: 'Note: the curve is the composed lunisolar precession period — Earth’s spin carrying the solar and lunar torques, the lunar term scaling with 1/a³ so the closer Moon drove precession faster than spin-scaling alone — anchored on the IAU 2006 general precession at J2000 (25,771.6 yr). This is the quantity cyclostratigraphic inversions (Wu et al. 2024) measure. The real axial precession also oscillates by ~50–500 years around the mean on the ~21,000- and ~41,000-year cycles (the perihelion-of-date and obliquity beats), invisible at this scale.',
  },
  obliqCycle: {
    title:    'Obliquity Cycle Period (the beat)',
    subtitle: 'The beat 2π/(ψ̇ᵢₙ − |s₃|) of the spin axis’s inertial precession rate (the composed lunisolar rate plus the planetary mean) against the orbit’s dominant nodal mode — 41.1 kyr today; the pre-registered deep-time prediction of falsification leg 1. The obliquity itself oscillates ±1° around ~23.4° on this period — what evolves at deep time is the period, not the mean.',
    yLabel:   'Period (years)',
    compute:  (t_Ma) => _obliqBeatYearsAtAge(t_Ma),
    yFmt:     (v) => Math.round(v).toLocaleString('en-US') + ' yr',
    yMin: 0, yMax: 65000,
    hasWu:    false,
    footnote: 'Note: Earth\'s axial tilt oscillates between approximately 22.4° and 24.5° around a mean of ~23.4° today. The cycle period (shown here — the beat of the spin axis\'s inertial rate against the dominant nodal mode) evolves with deep time, and so does the mean obliquity of date: it follows the cited Earth–Moon history (Farhat et al. 2022), lower in the deep past — 22.2° at the Devonian, 19.7° at 2.46 Ga — and the precession rate carries it.',
  },
  au: {
    title:    'Earth-Sun Distance',
    subtitle: 'Earth\'s semi-major axis under Driver 2 (solar mass loss: a × M = const)',
    yLabel:   'Earth-Sun (km)',
    // Returns km directly. Range across the visible window:
    // −4.54 Gyr: 149,535,217 km → J2000: 149,597,871 km → +1 Gyr: 149,611,786 km
    compute:  (t_Ma) => meanAuAtAge(t_Ma),
    yFmt:     (v) => Math.round(v).toLocaleString('en-US') + ' km',
    yMin: 149500000, yMax: 149700000,
    hasWu:    false,
  },
  moon: {
    title:    'Earth-Moon Distance',
    subtitle: 'Tidal recession under Driver 1 — the cited Earth-Moon distance history (Farhat et al. 2022, AstroGeo22) on the observed J2000 distance with the LLR rate as its J2000 slope; it ends at the Moon-formation age its authors adopt, 4.43 Ga (Moon at ~6 Earth radii). Forward of J2000 the LLR rate is held.',
    yLabel:   'Moon distance (km)',
    // Returns kilometres directly so tick labels render as natural numbers.
    compute:  (t_Ma) => { const m = meanMoonDistanceMetresAtAge(t_Ma); return m === null ? null : m / 1000; },
    yFmt:     (v) => Math.round(v).toLocaleString('en-US') + ' km',
    // From ~39,500 km (the history's end) through J2000 384,399 km to ~421,000 km at +1 Gyr
    yMin: 0, yMax: 500000,
    hasWu:    true,
    wuKey:    'moon_er',
    // ER → km: R_EARTH_M is metres; ER × R_EARTH_M = metres; ÷1000 = km
    wuConvert:(er) => (er * R_EARTH_M) / 1000,
    footnote: 'Note: the 300–500 Ma Wu et al. 2024 distance anchors sit ~4–5 Earth radii below the curve — the documented Pangea high-tidal-dissipation interval. Wu\'s key finding is that recession ran non-uniformly (~7.0 cm/yr during supercontinent assembly, 325–200 Ma, vs ~2.2 cm/yr before it); the calibrated smooth 0–1000 Ma branch deliberately averages over this regime, and the deviation is recorded and gated as documented bands (docs/99 §Pangea interval). The endpoints agree: 650 Ma within 2%, J2000 exact.',
  },
};

// Geological-era markers (calendar Ma, negative = past)
const ESSRT_ERA_MARKERS = [
  { t_cal: -4429, label: 'Earth-Moon genesis', color: '#a66' },
  { t_cal: -541,  label: 'Cambrian',           color: '#699' },
  { t_cal: -380,  label: 'Devonian',           color: '#6a9' },
  { t_cal: -250,  label: 'Pangea (mid)',       color: '#c95' },
  { t_cal: 0,     label: 'J2000 (now)',        color: '#fb3' },
];

// Compute "nice" axis tick values for a [min, max] range targeting ~targetTicks
// ticks. Step is rounded to {1,2,5}×10^k closest to range/targetTicks, and
// returned ticks are [ceil(min/step)*step, ..., floor(max/step)*step].
// Used by both renderers so y-axis labels read as round numbers
// (e.g., 100,000 / 200,000 / 300,000 instead of 83,333 / 166,667 / 250,000).
function essrtNiceTicks(min, max, targetTicks) {
  const range = max - min;
  if (range <= 0 || !Number.isFinite(range)) return [min, max];
  const rawStep = range / Math.max(1, targetTicks);
  const exp10  = Math.pow(10, Math.floor(Math.log10(rawStep)));
  const norm   = rawStep / exp10; // 1..10
  let niceStep;
  if      (norm < 1.5) niceStep = 1  * exp10;
  else if (norm < 3.5) niceStep = 2  * exp10;
  else if (norm < 7.5) niceStep = 5  * exp10;
  else                 niceStep = 10 * exp10;
  const first = Math.ceil(min / niceStep) * niceStep;
  const last  = Math.floor(max / niceStep) * niceStep;
  const ticks = [];
  // Float-safe count to avoid drift on long runs
  const count = Math.round((last - first) / niceStep);
  for (let i = 0; i <= count; i++) ticks.push(first + i * niceStep);
  return ticks;
}

function essrtComputeSeries(spec, t_lo_cal, t_hi_cal, N, planetKey) {
  const samples = [];
  for (let i = 0; i < N; i++) {
    const t_cal = t_lo_cal + (t_hi_cal - t_lo_cal) * (i / (N - 1));
    const t_Ma_geo = -t_cal;
    const v = spec.compute(t_Ma_geo, planetKey);
    samples.push({ t_cal, value: (v == null || !Number.isFinite(v)) ? null : v });
  }
  return samples;
}

function essrtRenderChart(qtyKey, rangeKey) {
  const spec = ESSRT_QTY_SPECS[qtyKey];
  const range = ESSRT_RANGE_TABS.find(r => r.key === rangeKey) || ESSRT_RANGE_TABS[0];
  const t_lo = range.t_lo, t_hi = range.t_hi;
  const N = 480;

  // Title/subtitle now live OUTSIDE the SVG (HTML in modal body) so the
  // chart itself gets more vertical room and renders cleaner.
  const W = 1100, H = 470;
  const margin = { top: 30, right: 50, bottom: 95, left: 140 };
  const plotW = W - margin.left - margin.right;
  const plotH = H - margin.top - margin.bottom;

  // Compute series
  const allSeries = [{ samples: essrtComputeSeries(spec, t_lo, t_hi, N) }];
  // Optional secondary curve (e.g. the composed physical axial precession next to
  // the published period — doc 99). Rendered only on the Phanerozoic view, where
  // the published anchors it reconciles are shown.
  if (spec.compute2 && rangeKey === 'phanero') {
    allSeries.push({
      samples: essrtComputeSeries({ ...spec, compute: spec.compute2 }, t_lo, t_hi, N),
      color: '#7dd87d',
      dash: '6,4',
    });
  }

  // Y range. Each spec declares yMin/yMax so we never get pathological
  // auto-ranging when a quantity approaches its asymptote (e.g., LOD past
  // tidal lock). Per-range overrides via spec.yRangeOverrides[rangeKey]
  // tighten the cap when a range covers a much smaller value-span than the
  // default (e.g., Length of Year on Phanerozoic only spans 365–416 days vs
  // the full-range 274–1750 days). Auto-mode kicks in only if neither layer
  // declares both yMin/yMax.
  let yMin, yMax;
  const wuShow = spec.hasWu && rangeKey === 'phanero';
  const yOverride = spec.yRangeOverrides && spec.yRangeOverrides[rangeKey];
  if (yOverride && Number.isFinite(yOverride.yMin) && Number.isFinite(yOverride.yMax)) {
    yMin = yOverride.yMin;
    yMax = yOverride.yMax;
  } else if (Number.isFinite(spec.yMin) && Number.isFinite(spec.yMax)) {
    yMin = spec.yMin;
    yMax = spec.yMax;
  } else {
    yMin = Infinity; yMax = -Infinity;
    for (const s of allSeries) {
      for (const p of s.samples) {
        if (p.value === null) continue;
        if (p.value < yMin) yMin = p.value;
        if (p.value > yMax) yMax = p.value;
      }
    }
    if (wuShow) {
      for (const a of WU_ANCHORS) {
        const v = spec.wuConvert(a[spec.wuKey]);
        if (v < yMin) yMin = v; if (v > yMax) yMax = v;
      }
    }
    if (!Number.isFinite(yMin) || !Number.isFinite(yMax)) { yMin = 0; yMax = 1; }
    const pad = (yMax - yMin) * 0.08 || 1;
    yMin -= pad; yMax += pad;
  }

  // Log Y for planet panels
  const useLog = !!spec.logY;
  const yPos = (v) => {
    if (useLog) {
      const lmin = Math.log10(Math.max(yMin, 1e-6));
      const lmax = Math.log10(Math.max(yMax, lmin + 1));
      const lv   = Math.log10(Math.max(v, 1e-6));
      return margin.top + (1 - (lv - lmin) / (lmax - lmin)) * plotH;
    }
    return margin.top + (1 - (v - yMin) / (yMax - yMin)) * plotH;
  };
  // Clip to plot area so out-of-range (e.g., asymptote) values draw at the edge
  const yPosClipped = (v) => {
    const y = yPos(v);
    if (y < margin.top) return margin.top;
    if (y > margin.top + plotH) return margin.top + plotH;
    return y;
  };
  const xPos = (t_cal) => margin.left + ((t_cal - t_lo) / (t_hi - t_lo)) * plotW;

  // X-axis tick spacing — nice-number selector
  const span = t_hi - t_lo;
  let xStep = 1000;
  if (span <= 100)     xStep = 20;
  else if (span <= 1000) xStep = 100;
  else if (span <= 2000) xStep = 200;
  else if (span <= 5000) xStep = 500;
  else                 xStep = 1000;

  // X ticks — brighter strokes (#888 vs #666), bigger labels (11pt vs 10pt)
  const xticks = [];
  const xStart = Math.ceil(t_lo / xStep) * xStep;
  for (let t = xStart; t <= t_hi + 1e-6; t += xStep) {
    const x = xPos(t);
    const labelMa = Math.round(t);
    const label = Math.abs(labelMa) >= 1000
      ? (labelMa / 1000).toFixed(1) + ' Gyr'
      : labelMa + ' Ma';
    xticks.push(`<line x1="${x}" y1="${margin.top + plotH}" x2="${x}" y2="${margin.top + plotH + 5}" stroke="#888" stroke-width="0.7"/>
      <text x="${x}" y="${margin.top + plotH + 20}" text-anchor="middle" font-size="11" fill="#d4d4d4">${label}</text>`);
  }

  // Y ticks — 7 nice values, brighter strokes, subtler gridlines
  const yticks = [];
  if (useLog) {
    const lmin = Math.log10(Math.max(yMin, 1e-6));
    const lmax = Math.log10(Math.max(yMax, lmin + 1));
    for (let l = Math.ceil(lmin); l <= Math.floor(lmax); l++) {
      const v = Math.pow(10, l);
      const y = yPos(v);
      yticks.push(`<line x1="${margin.left - 5}" y1="${y}" x2="${margin.left}" y2="${y}" stroke="#888" stroke-width="0.7"/>
        <text x="${margin.left - 9}" y="${y + 4}" text-anchor="end" font-size="11" fill="#d4d4d4">${v.toFixed(0)}</text>
        <line x1="${margin.left}" y1="${y}" x2="${margin.left + plotW}" y2="${y}" stroke="#2a2f37" stroke-width="0.5"/>`);
    }
  } else {
    // Nice-number ticks (e.g., 100k/200k/300k instead of 83,333/166,667/250,000)
    const tickVals = essrtNiceTicks(yMin, yMax, 6);
    for (const v of tickVals) {
      if (v < yMin - 1e-9 || v > yMax + 1e-9) continue;
      const y = yPos(v);
      yticks.push(`<line x1="${margin.left - 5}" y1="${y}" x2="${margin.left}" y2="${y}" stroke="#888" stroke-width="0.7"/>
        <text x="${margin.left - 9}" y="${y + 4}" text-anchor="end" font-size="11" fill="#d4d4d4">${spec.yFmt(v)}</text>
        <line x1="${margin.left}" y1="${y}" x2="${margin.left + plotW}" y2="${y}" stroke="#2a2f37" stroke-width="0.5"/>`);
    }
  }

  // Brighter curve color — was muted #8cb4ff. Cyan with subtle glow filter.
  const CURVE_COLOR = '#6ee5ff';

  // Data path(s) — clip y to plot area so asymptote values draw at edge
  const paths = allSeries.map(s => {
    let d = '';
    let prevNull = true;
    s.samples.forEach((p) => {
      if (p.value === null) { prevNull = true; return; }
      const cmd = (d === '' || prevNull) ? 'M' : 'L';
      d += `${cmd}${xPos(p.t_cal).toFixed(1)} ${yPosClipped(p.value).toFixed(1)} `;
      prevNull = false;
    });
    const strokeCol = s.color || CURVE_COLOR;
    const dashAttr = s.dash ? ` stroke-dasharray="${s.dash}"` : '';
    return `<path d="${d}" fill="none" stroke="${strokeCol}" stroke-width="2"${dashAttr} opacity="1" filter="url(#essrt-glow)"/>`;
  }).join('');

  // Subtle glow filter for the data line — gives it the premium look
  const defs = `
    <defs>
      <filter id="essrt-glow" x="-20%" y="-20%" width="140%" height="140%">
        <feGaussianBlur stdDeviation="1.4" result="blur"/>
        <feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge>
      </filter>
    </defs>`;

  // Hover overlay — invisible interaction layer for tooltip.
  const hoverData = allSeries[0].samples
    .filter(p => p.value !== null)
    .map(p => ({ x: xPos(p.t_cal), y: yPosClipped(p.value), t: p.t_cal, v: p.value }));

  // Era markers — vertical line + horizontal label at TOP of plot area, with
  // anti-collision PLUS a minimum 50-px gap so labels never sit shoulder-to-
  // shoulder. J2000 is the priority marker — if a less-important marker would
  // be too close, J2000 wins. Earth-Moon genesis gets a red tint (Earth's
  // beginning, the most important non-J2000 marker).
  const ERA_MIN_GAP_PX = 50;
  const isGenesis = m => m.label === 'Earth-Moon genesis';
  // Step 1: sort by importance (J2000 highest), then by x. Walk and decide
  // which labels to keep — closer-to-already-placed wins by importance.
  const visibleEras = ESSRT_ERA_MARKERS.filter(m => m.t_cal >= t_lo && m.t_cal <= t_hi)
    .map(m => ({ m, x: xPos(m.t_cal), labelWidth: m.label.length * 5.5 + 8 }));
  // Importance order: J2000 > genesis > others
  const importanceRank = (m) => (m.t_cal === 0 ? 100 : isGenesis(m) ? 50 : 10);
  const sortedByImportance = [...visibleEras].sort((a, b) => importanceRank(b.m) - importanceRank(a.m));
  const labelKept = new Set();
  const labelXs = [];
  for (const e of sortedByImportance) {
    if (labelXs.some(x => Math.abs(x - e.x) < ERA_MIN_GAP_PX)) continue;
    labelKept.add(e.m);
    labelXs.push(e.x);
  }
  // Step 2: render in left-to-right order so the SVG paint sequence is natural
  const sortedByX = [...visibleEras].sort((a, b) => a.x - b.x);
  const eraMarkers = sortedByX.map(({ m, x, labelWidth }) => {
    const isJ2000 = m.t_cal === 0;
    const isGen   = isGenesis(m);
    const dash = isJ2000 ? '' : ' stroke-dasharray="3,4"';
    const sw = isJ2000 ? 1.4 : isGen ? 1.1 : 0.7;
    const opacity = isJ2000 ? 0.95 : isGen ? 0.75 : 0.5;
    const lineCol = isJ2000 ? '#ffce4b' : isGen ? '#e07070' : '#888';
    let labelHtml = '';
    if (labelKept.has(m)) {
      const labelY = margin.top - 6;
      const labelText = isJ2000 ? 'J2000 (now)' : m.label;
      const labelColor = isJ2000 ? '#ffce4b' : isGen ? '#e07070' : '#b6b6b6';
      const labelWeight = isJ2000 ? '600' : isGen ? '500' : '400';
      labelHtml = `<text x="${x}" y="${labelY}" font-size="9" fill="${labelColor}" font-weight="${labelWeight}" text-anchor="middle">${m.label}</text>`;
    }
    return `<line x1="${x}" y1="${margin.top}" x2="${x}" y2="${margin.top + plotH}" stroke="${lineCol}" stroke-width="${sw}"${dash} opacity="${opacity}"/>${labelHtml}`;
  }).join('');

  // Wu et al. overlay (Phanerozoic only).
  let wuOverlay = '';
  if (wuShow) {
    wuOverlay = WU_ANCHORS.map(a => {
      const xt = xPos(-a.t_Ma);
      const v = spec.wuConvert(a[spec.wuKey]);
      const yt = yPosClipped(v);
      const sigmaKey = spec.wuKey === 'lod_hr' ? 'lod_sigma' :
                       spec.wuKey === 'moon_er' ? 'moon_sigma' : 'axial_sigma';
      const sig = a[sigmaKey] || 0;
      const sigConverted = spec.wuConvert === ((x)=>x) ? sig
        : Math.abs(spec.wuConvert(a[spec.wuKey] + sig) - v);
      const yErrTop    = yPosClipped(v + sigConverted);
      const yErrBottom = yPosClipped(v - sigConverted);
      return `<line x1="${xt}" y1="${yErrTop}" x2="${xt}" y2="${yErrBottom}" stroke="#ff9a3c" stroke-width="1.2"/>
        <circle cx="${xt}" cy="${yt}" r="4.5" fill="#ff9a3c" stroke="#fff" stroke-width="0.8"/>`;
    }).join('');
  }

  let wuLegend = '';
  if (wuShow) {
    wuLegend = `<a href="https://www.science.org/doi/10.1126/sciadv.ado2412" target="_blank" rel="noopener" style="cursor:pointer">
      <circle cx="${margin.left + plotW - 210}" cy="${margin.top + 14}" r="5" fill="#ff9a3c" stroke="#fff" stroke-width="0.8"/>
      <text x="${margin.left + plotW - 198}" y="${margin.top + 18}" font-size="11" fill="#e0e0e0" font-weight="500" text-decoration="underline">Wu et al. 2024 (±2σ)</text>
    </a>`;
    if (spec.compute2 && spec.label2) {
      wuLegend += `
        <line x1="${margin.left + plotW - 216}" y1="${margin.top + 32}" x2="${margin.left + plotW - 204}" y2="${margin.top + 32}" stroke="#7dd87d" stroke-width="2" stroke-dasharray="6,4"/>
        <text x="${margin.left + plotW - 198}" y="${margin.top + 36}" font-size="11" fill="#e0e0e0" font-weight="500">${spec.label2}</text>
        <line x1="${margin.left + plotW - 216}" y1="${margin.top + 50}" x2="${margin.left + plotW - 204}" y2="${margin.top + 50}" stroke="${CURVE_COLOR}" stroke-width="2"/>
        <text x="${margin.left + plotW - 198}" y="${margin.top + 54}" font-size="11" fill="#e0e0e0" font-weight="500">frozen-clock counter</text>`;
    }
  }

  const frame = `<rect x="${margin.left}" y="${margin.top}" width="${plotW}" height="${plotH}" fill="#0a0d11" stroke="#5a5f68" stroke-width="0.8"/>`;

  // Extrapolation zone — anything FUTURE of J2000 (t_cal > 0). The entire
  // future is a projection of the polynomial past-fit; values remain physically
  // reasonable but become increasingly uncertain at multi-100-Myr scales.
  // Subtle grey wash so it reads as "this region is projected" without competing
  // with the data curve. Hidden on ranges that end at J2000 (Phanerozoic).
  let extrapolationZone = '';
  const EXTRAP_START_MA = 0;
  if (t_hi > EXTRAP_START_MA) {
    const xStart = xPos(Math.max(EXTRAP_START_MA, t_lo));
    const xEnd   = xPos(t_hi);
    const zoneW  = xEnd - xStart;
    extrapolationZone = `
      <defs>
        <pattern id="essrt-extrap-hatch" patternUnits="userSpaceOnUse" width="16" height="16" patternTransform="rotate(45)">
          <line x1="0" y1="0" x2="0" y2="16" stroke="#a0a0a0" stroke-width="0.4" opacity="0.08"/>
        </pattern>
      </defs>
      <rect x="${xStart}" y="${margin.top}" width="${zoneW}" height="${plotH}" fill="#888" opacity="0.05"/>
      <rect x="${xStart}" y="${margin.top}" width="${zoneW}" height="${plotH}" fill="url(#essrt-extrap-hatch)"/>
    `;
  }

  // Axis labels — larger (13pt), brighter, with subtle background for legibility
  const yAxisLabel = `<text x="${30}" y="${margin.top + plotH / 2}" text-anchor="middle" font-size="13" fill="#e0e0e0" font-weight="500" transform="rotate(-90 30 ${margin.top + plotH / 2})">${spec.yLabel}</text>`;
  const xAxisLabel = `<text x="${margin.left + plotW / 2}" y="${H - 6}" text-anchor="middle" font-size="13" fill="#e0e0e0" font-weight="500">Time (Ma; negative = past, 0 = J2000)</text>`;

  // Hover line + tooltip — invisible mouse-tracker rect, JS finds nearest sample.
  // Tooltip group hidden by default, shown on mouseover via JS.
  const hoverDataAttr = `data-essrt-hover='${JSON.stringify({
    samples: hoverData.map(p => [Number(p.x.toFixed(1)), Number(p.y.toFixed(1)), p.t, p.v]),
    yFmtKey: qtyKey,
    margin, plotW, plotH,
  })}'`;

  const hoverLayer = `
    <g class="essrt-hover-layer" style="pointer-events:none">
      <line class="essrt-hover-line" x1="0" y1="${margin.top}" x2="0" y2="${margin.top + plotH}" stroke="#fff" stroke-width="0.8" opacity="0" stroke-dasharray="3,3"/>
      <circle class="essrt-hover-dot" cx="0" cy="0" r="5" fill="${CURVE_COLOR}" stroke="#fff" stroke-width="1.2" opacity="0"/>
      <g class="essrt-hover-tooltip" opacity="0">
        <rect class="essrt-hover-bg" x="0" y="0" width="180" height="38" fill="rgba(10,13,17,0.95)" stroke="${CURVE_COLOR}" stroke-width="0.8" rx="3"/>
        <text class="essrt-hover-year"  x="8" y="16" font-size="11" fill="#ffce4b" font-weight="600">year</text>
        <text class="essrt-hover-value" x="8" y="31" font-size="11" fill="#e0e0e0" font-weight="500">value</text>
      </g>
    </g>
    <rect class="essrt-hover-capture" x="${margin.left}" y="${margin.top}" width="${plotW}" height="${plotH}" fill="transparent" style="cursor:crosshair" ${hoverDataAttr}/>
  `;

  let footnoteHtml = '';
  if (spec.footnote) {
    footnoteHtml = `<div class="cfm-info" style="margin-top:8px">${spec.footnote}</div>`;
  }

  // Context line under chart title — key reference values like WebGeoCalc's
  // "Observed / Model / Baseline" line. Shows the quantity at the deep past,
  // J2000, and end of range so the user sees the evolution span at a glance.
  const j2000Val = spec.compute(0);
  const primarySamples = allSeries[0].samples;
  const startVal = primarySamples.length ? primarySamples[0].value : null;
  const endVal   = primarySamples.length ? primarySamples[primarySamples.length - 1].value : null;
  const fmt = (v) => (v !== null && Number.isFinite(v)) ? spec.yFmt(v) : '—';
  const startLabel = t_lo <= -1000 ? (-t_lo / 1000).toFixed(2) + ' Gyr ago'
                   : t_lo < 0      ? Math.round(-t_lo) + ' Ma ago'
                                   : 'start';
  const endLabel   = t_hi >= 1000  ? '+' + (t_hi / 1000).toFixed(2) + ' Gyr'
                   : t_hi > 0      ? '+' + Math.round(t_hi) + ' Ma'
                                   : 'today';
  // Skip the J2000 column when the range ends AT J2000 (Phanerozoic) — the
  // end value would just duplicate it.
  const j2000IsEnd = t_hi === 0;
  const contextLine = `
    <div class="cfm-chart-subtitle" style="display:flex; gap:18px; justify-content:center; align-items:center; flex-wrap:wrap; font-family:'JetBrains Mono','SF Mono',Menlo,monospace; font-size:11px">
      <span><span style="color:#888">${startLabel}:</span> <span style="color:#d4d4d4; font-weight:600">${fmt(startVal)}</span></span>
      ${j2000IsEnd ? '' : `
        <span style="color:#555">·</span>
        <span><span style="color:#ffce4b">J2000 (now):</span> <span style="color:#ffce4b; font-weight:600">${fmt(j2000Val)}</span></span>`}
      <span style="color:#555">·</span>
      <span><span style="color:#888">${endLabel}:</span> <span style="color:#d4d4d4; font-weight:600">${fmt(endVal)}</span></span>
    </div>`;

  // Driver note at bottom — only what applies to THIS panel, like WebGeoCalc's
  // "Frame note:" block. Concise per-quantity description.
  const driverText = {
    lod:        '<strong>Driver 1</strong> — Earth-Moon tidal recession (Layer-2 angular-momentum conservation, Farhat 2022 polynomial fit).',
    year:       '<strong>Drivers 1+2</strong> — days/year = (sidereal year_s) / LOD. Driver 2 sets year-in-seconds (Kepler dT/T = −2 dM/M); Driver 1 sets day-in-seconds (conservation on the cited Farhat 2022 distance history). Wu et al. days/year are derived from their LOD: at 400 Ma → ~403 days/yr (Wells 1963 coral bands ~400).',
    axial:      '<strong>Driver 1</strong> — the composed lunisolar precession period: Earth’s spin (Layer-2 angular momentum, Farhat 2022 recession) carrying the solar and lunar torques, the lunar torque growing on the Moon’s distance; anchored on the IAU 2006 general precession at J2000 (25,771.6 yr).',
    obliqCycle: '<strong>Driver 1</strong> — the obliquity beat 2π/(ψ̇ᵢₙ − |s₃|): the spin axis’s inertial precession rate (the composed rate × the hybrid’s self-anchor factor) against the orbit’s dominant nodal mode (s₃ at its dynamical value under the solar-mass history).',
    au:         '<strong>Driver 2</strong> — solar mass loss: a × M = const (Kepler dT/T = −2 dM/M, ~9.3×10⁻¹⁴ /yr).',
    moon:       '<strong>Driver 1</strong> — tidal recession via the Farhat 2022 LSQ polynomial fit a(t)/a_now = 1 + α₁t + α₃t³ + α₄t⁴.',
  }[qtyKey] || 'Drivers 1+2';
  const wuLine = (spec.hasWu && rangeKey === 'phanero')
    ? ' <strong style="color:#ff9a3c">Orange markers</strong>: <a href="https://www.science.org/doi/10.1126/sciadv.ado2412" target="_blank" rel="noopener" style="color:#ff9a3c">Wu et al. 2024</a> cyclostratigraphy anchors ±2σ.'
    : '';
  const driverNote = `
    <div class="cfm-info" style="margin-top:10px; font-size:11px; line-height:1.55">
      <div><strong style="color:#6ee5ff">Driver note:</strong> <span style="color:#bbb">${driverText}</span></div>
      ${wuLine ? `<div style="margin-top:4px; color:#bbb">${wuLine.trim()}</div>` : ''}
    </div>`;

  // Title + subtitle live OUTSIDE the SVG (HTML in modal body) — gives the
  // chart more vertical room and renders crisper.
  return `
    <div class="cfm-chart-title">${spec.title}</div>
    <div class="cfm-chart-subtitle">${spec.subtitle}</div>
    ${contextLine}
    <svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" class="cfm-svg essrt-svg" font-family="Inter, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif">
      ${defs}
      ${frame}
      ${extrapolationZone}
      ${yticks.join('')}
      ${xticks.join('')}
      ${eraMarkers}
      ${paths}
      ${wuOverlay}
      ${wuLegend}
      ${yAxisLabel}
      ${xAxisLabel}
      ${hoverLayer}
    </svg>
    ${driverNote}
    ${footnoteHtml}
  `;
}

// ─────────────────────────────────────────────────────────────────
// Paper-export render — white background, no hover layer, larger fonts.
// Mirrors essrtRenderChart's geometry so the exported SVG looks like
// what you see on screen but is paper-ready.
// ─────────────────────────────────────────────────────────────────
function essrtRenderPaperChart(qtyKey, rangeKey) {
  const spec  = ESSRT_QTY_SPECS[qtyKey];
  const range = ESSRT_RANGE_TABS.find(r => r.key === rangeKey) || ESSRT_RANGE_TABS[0];
  const t_lo = range.t_lo, t_hi = range.t_hi;
  const N = 600;
  const xmlEsc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

  const W = 1200, H = 720;
  // The standard export page: title + legend rows (the model line; the Wu
  // anchors when shown), a plot of fixed height, the axis labels, the credit.
  // The panel's subtitle paragraph reads on screen, not on the picture.
  const wuShow = spec.hasWu && rangeKey === 'phanero';
  const legend = [{ name: spec.title + ' — model', color: '#1a5fb4', bold: true }];
  if (wuShow) legend.push({ name: 'Wu et al. 2024 (±2σ)', color: '#e07b00', marker: 'dot' });
  const head = chartExportHeader(spec.title + ' — ' + range.label, legend, W);
  const margin = { top: head.bottom + 14, right: 50, bottom: 110, left: 130 };
  const plotW = W - margin.left - margin.right;
  const plotH = H - margin.top - margin.bottom;

  const samples = essrtComputeSeries(spec, t_lo, t_hi, N);

  // Y range — per-range override first, then spec's declared cap, then auto.
  let yMin, yMax;
  const yOverride = spec.yRangeOverrides && spec.yRangeOverrides[rangeKey];
  if (yOverride && Number.isFinite(yOverride.yMin) && Number.isFinite(yOverride.yMax)) {
    yMin = yOverride.yMin; yMax = yOverride.yMax;
  } else if (Number.isFinite(spec.yMin) && Number.isFinite(spec.yMax)) {
    yMin = spec.yMin; yMax = spec.yMax;
  } else {
    yMin = Infinity; yMax = -Infinity;
    for (const p of samples) {
      if (p.value === null) continue;
      if (p.value < yMin) yMin = p.value;
      if (p.value > yMax) yMax = p.value;
    }
    if (wuShow) {
      for (const a of WU_ANCHORS) {
        const v = spec.wuConvert(a[spec.wuKey]);
        if (v < yMin) yMin = v; if (v > yMax) yMax = v;
      }
    }
    if (!Number.isFinite(yMin)) { yMin = 0; yMax = 1; }
    const pad = (yMax - yMin) * 0.08 || 1;
    yMin -= pad; yMax += pad;
  }

  const useLog = !!spec.logY;
  const yPos = (v) => {
    if (useLog) {
      const lmin = Math.log10(Math.max(yMin, 1e-6));
      const lmax = Math.log10(Math.max(yMax, lmin + 1));
      const lv   = Math.log10(Math.max(v, 1e-6));
      return margin.top + (1 - (lv - lmin) / (lmax - lmin)) * plotH;
    }
    return margin.top + (1 - (v - yMin) / (yMax - yMin)) * plotH;
  };
  const yPosClipped = (v) => {
    const y = yPos(v);
    if (y < margin.top) return margin.top;
    if (y > margin.top + plotH) return margin.top + plotH;
    return y;
  };
  const xPos = (t_cal) => margin.left + ((t_cal - t_lo) / (t_hi - t_lo)) * plotW;

  // X ticks
  const span = t_hi - t_lo;
  let xStep = 1000;
  if (span <= 100) xStep = 20;
  else if (span <= 1000) xStep = 100;
  else if (span <= 2000) xStep = 200;
  else if (span <= 5000) xStep = 500;
  else xStep = 1000;
  const xticks = [];
  const xStart = Math.ceil(t_lo / xStep) * xStep;
  for (let t = xStart; t <= t_hi + 1e-6; t += xStep) {
    const x = xPos(t);
    const labelMa = Math.round(t);
    const label = Math.abs(labelMa) >= 1000
      ? (labelMa / 1000).toFixed(1) + ' Gyr'
      : labelMa + ' Ma';
    xticks.push(`<line x1="${x}" y1="${margin.top + plotH}" x2="${x}" y2="${margin.top + plotH + 6}" stroke="#444" stroke-width="0.7"/>
      <text x="${x}" y="${margin.top + plotH + 22}" text-anchor="middle" font-size="12" fill="#222">${label}</text>`);
  }

  // Y ticks — round numbers via essrtNiceTicks helper
  const yticks = [];
  const tickVals = essrtNiceTicks(yMin, yMax, 6);
  for (const v of tickVals) {
    if (v < yMin - 1e-9 || v > yMax + 1e-9) continue;
    const y = yPos(v);
    yticks.push(`<line x1="${margin.left - 6}" y1="${y}" x2="${margin.left}" y2="${y}" stroke="#444" stroke-width="0.7"/>
      <text x="${margin.left - 10}" y="${y + 4}" text-anchor="end" font-size="11" fill="#222">${xmlEsc(spec.yFmt(v))}</text>
      <line x1="${margin.left}" y1="${y}" x2="${margin.left + plotW}" y2="${y}" stroke="#ddd" stroke-width="0.4"/>`);
  }

  // Data path
  let d = '', prevNull = true;
  samples.forEach(p => {
    if (p.value === null) { prevNull = true; return; }
    const cmd = (d === '' || prevNull) ? 'M' : 'L';
    d += `${cmd}${xPos(p.t_cal).toFixed(1)} ${yPosClipped(p.value).toFixed(1)} `;
    prevNull = false;
  });
  const dataPath = `<path d="${d}" fill="none" stroke="#1a5fb4" stroke-width="2" opacity="1"/>`;

  // Era markers — same anti-collision + min-gap as the modal renderer, with
  // J2000 and Earth-Moon genesis as priority markers.
  const ERA_MIN_GAP_PX_PAPER = 60;
  const isGenesisP = m => m.label === 'Earth-Moon genesis';
  const visibleErasP = ESSRT_ERA_MARKERS.filter(m => m.t_cal >= t_lo && m.t_cal <= t_hi)
    .map(m => ({ m, x: xPos(m.t_cal) }));
  const importanceRankP = (m) => (m.t_cal === 0 ? 100 : isGenesisP(m) ? 50 : 10);
  const sortedByImportanceP = [...visibleErasP].sort((a, b) => importanceRankP(b.m) - importanceRankP(a.m));
  const labelKeptP = new Set();
  const labelXsP = [];
  for (const e of sortedByImportanceP) {
    if (labelXsP.some(x => Math.abs(x - e.x) < ERA_MIN_GAP_PX_PAPER)) continue;
    labelKeptP.add(e.m);
    labelXsP.push(e.x);
  }
  const sortedByXP = [...visibleErasP].sort((a, b) => a.x - b.x);
  const eraMarkers = sortedByXP.map(({ m, x }) => {
    const isJ2000 = m.t_cal === 0;
    const isGen   = isGenesisP(m);
    const dash = isJ2000 ? '' : ' stroke-dasharray="4,3"';
    const sw = isJ2000 ? 1.4 : isGen ? 1.1 : 0.8;
    const opacity = isJ2000 ? 0.9 : isGen ? 0.75 : 0.55;
    const lineCol = isJ2000 ? '#888' : isGen ? '#b04545' : '#888';
    const labelY = margin.top + plotH + 40;
    const labelHtml = labelKeptP.has(m)
      ? `<text x="${x}" y="${labelY}" font-size="11" fill="${isGen ? '#a03535' : '#555'}" opacity="0.9" text-anchor="end" transform="rotate(-32 ${x} ${labelY})">${xmlEsc(m.label)}</text>`
      : '';
    return `<line x1="${x}" y1="${margin.top}" x2="${x}" y2="${margin.top + plotH}" stroke="${lineCol}"${dash} stroke-width="${sw}" opacity="${opacity}"/>${labelHtml}`;
  }).join('');

  // Wu overlay
  let wuOverlay = '';
  if (wuShow) {
    wuOverlay = WU_ANCHORS.map(a => {
      const xt = xPos(-a.t_Ma);
      const v = spec.wuConvert(a[spec.wuKey]);
      const yt = yPosClipped(v);
      const sigmaKey = spec.wuKey === 'lod_hr' ? 'lod_sigma' :
                       spec.wuKey === 'moon_er' ? 'moon_sigma' : 'axial_sigma';
      const sig = a[sigmaKey] || 0;
      const sigConverted = spec.wuConvert === ((x) => x) ? sig
        : Math.abs(spec.wuConvert(a[spec.wuKey] + sig) - v);
      const yErrTop = yPosClipped(v + sigConverted);
      const yErrBottom = yPosClipped(v - sigConverted);
      return `<line x1="${xt}" y1="${yErrTop}" x2="${xt}" y2="${yErrBottom}" stroke="#e07b00" stroke-width="1.4"/>
        <circle cx="${xt}" cy="${yt}" r="5" fill="#e07b00" stroke="#fff" stroke-width="1"/>`;
    }).join('');
  }
  const frame = `<rect x="${margin.left}" y="${margin.top}" width="${plotW}" height="${plotH}" fill="white" stroke="#222" stroke-width="0.8"/>`;

  // Extrapolation zone — anything future of J2000. Subtle grey wash so the
  // marked region is identifiable on the white background without competing
  // with the data line. No boundary label needed (J2000 is already marked
  // separately).
  let extrapolationZone = '';
  const EXTRAP_START_MA = 0;
  if (t_hi > EXTRAP_START_MA) {
    const xStart = xPos(Math.max(EXTRAP_START_MA, t_lo));
    const xEnd   = xPos(t_hi);
    const zoneW  = xEnd - xStart;
    extrapolationZone = `
      <defs>
        <pattern id="essrt-paper-extrap-hatch" patternUnits="userSpaceOnUse" width="14" height="14" patternTransform="rotate(45)">
          <line x1="0" y1="0" x2="0" y2="14" stroke="#888" stroke-width="0.5" opacity="0.18"/>
        </pattern>
      </defs>
      <rect x="${xStart}" y="${margin.top}" width="${zoneW}" height="${plotH}" fill="#cccccc" opacity="0.35"/>
      <rect x="${xStart}" y="${margin.top}" width="${zoneW}" height="${plotH}" fill="url(#essrt-paper-extrap-hatch)"/>
      <text x="${xStart + zoneW / 2}" y="${margin.top + 18}" font-size="11" fill="#666" opacity="0.9" text-anchor="middle" font-style="italic" font-weight="500">Extrapolation</text>
    `;
  }
  const yAxisLabel = `<text x="${36}" y="${margin.top + plotH / 2}" text-anchor="middle" font-size="13" fill="#222" transform="rotate(-90 36 ${margin.top + plotH / 2})">${xmlEsc(spec.yLabel)}</text>`;
  const xAxisLabel = `<text x="${margin.left + plotW / 2}" y="${H - 18}" text-anchor="middle" font-size="13" fill="#222">Time (Ma; negative = past, 0 = J2000)</text>`;

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" font-family="Inter, system-ui, sans-serif">
    <rect width="${W}" height="${H}" fill="white"/>
    ${head.svg}
    ${frame}
    ${extrapolationZone}
    ${yticks.join('')}
    ${xticks.join('')}
    ${eraMarkers}
    ${dataPath}
    ${wuOverlay}
    ${yAxisLabel}
    ${xAxisLabel}
    ${chartExportCredit(W, H)}
  </svg>`;
}

function essrtExport(rangeKey) {
  const svg = essrtRenderPaperChart(essrtSelectedQty, rangeKey);
  const range = ESSRT_RANGE_TABS.find(r => r.key === rangeKey);
  const spec = ESSRT_QTY_SPECS[essrtSelectedQty];
  openChartExportModal(svg, `Earth–Moon Genesis Analysis — ${spec.title} — ${range.label}`);
}

async function createEssrtPanel() {
  const panel = document.createElement('div');
  panel.id = 'essrtPanel';
  panel.className = 'cfm-modal';

  // Range-tab teal accent: distinct from quantity-tab gold. Inline styles
  // override the inherited cfm-tab-active gold rules to give the two rows
  // visually different active states (matches Climate Formula's layered look).
  const RANGE_TAB_ACCENT = '#3ec9b9';   // teal-cyan
  const RANGE_TAB_BG     = 'rgba(62,201,185,0.10)';

  panel.innerHTML = `
    <div class="cfm-overlay"></div>
    <div class="cfm-container">
      <div class="cfm-header">
        <div style="display:flex; flex-direction:column; align-items:flex-start; flex:1; min-width:0">
          <div class="cfm-title">Earth–Moon Genesis Analysis</div>
          <div class="cfm-subtitle">The model's own evolution from Earth–Moon genesis (−4.43 Gyr, the cited distance history's end) to +1 Gyr — the clock lengthens as tidal friction slows the spin and the receding Moon weakens its torque</div>
        </div>
        <button class="cfm-export-btn" data-essrt-export title="Export the quantity and time range on screen as a picture (PNG or SVG download)">Export</button>
        <div class="cfm-close" title="Close"></div>
      </div>
      <div class="cfm-body">
        <div class="cfm-tabs" data-essrt-qty-tabs>
          ${ESSRT_QTY_TABS.map(t => `<button class="cfm-tab${t.key === essrtSelectedQty ? ' cfm-tab-active' : ''}" data-qty="${t.key}">${t.label}</button>`).join('')}
        </div>
        <div class="cfm-tabs" data-essrt-range-tabs style="margin-top:6px">
          ${ESSRT_RANGE_TABS.map(t => `<button class="cfm-tab" data-range="${t.key}" style="${t.key === essrtSelectedRange
              ? `color:${RANGE_TAB_ACCENT}; border-color:${RANGE_TAB_ACCENT}; background:${RANGE_TAB_BG}`
              : ''}">${t.label}</button>`).join('')}
        </div>
        <div class="cfm-content" data-essrt-content>
          ${essrtRenderChart(essrtSelectedQty, essrtSelectedRange)}
        </div>
      </div>
    </div>
  `;

  const contentEl = panel.querySelector('[data-essrt-content]');

  // Hover tooltip wire-up. Delegates to .essrt-hover-capture (drawn last in SVG).
  function bindHoverTooltip() {
    const svg = contentEl.querySelector('svg.essrt-svg');
    if (!svg) return;
    const capture = svg.querySelector('.essrt-hover-capture');
    if (!capture) return;
    const data = JSON.parse(capture.getAttribute('data-essrt-hover'));
    const samples = data.samples;
    const spec = ESSRT_QTY_SPECS[essrtSelectedQty];
    const m = data.margin;
    const plotW = data.plotW, plotH = data.plotH;
    const hoverLine = svg.querySelector('.essrt-hover-line');
    const hoverDot  = svg.querySelector('.essrt-hover-dot');
    const tooltip   = svg.querySelector('.essrt-hover-tooltip');
    const bg        = svg.querySelector('.essrt-hover-bg');
    const yearTxt   = svg.querySelector('.essrt-hover-year');
    const valueTxt  = svg.querySelector('.essrt-hover-value');

    capture.addEventListener('mousemove', (ev) => {
      // Convert client mouse coords → SVG viewBox coords
      const pt = svg.createSVGPoint();
      pt.x = ev.clientX; pt.y = ev.clientY;
      const ctm = svg.getScreenCTM();
      if (!ctm) return;
      const svgPt = pt.matrixTransform(ctm.inverse());
      const mx = svgPt.x;
      // Find nearest sample by x distance
      let best = 0, bestDx = Infinity;
      for (let i = 0; i < samples.length; i++) {
        const dx = Math.abs(samples[i][0] - mx);
        if (dx < bestDx) { bestDx = dx; best = i; }
      }
      const [x, y, t_cal, v] = samples[best];
      hoverLine.setAttribute('x1', x); hoverLine.setAttribute('x2', x);
      hoverLine.setAttribute('opacity', 0.6);
      hoverDot.setAttribute('cx', x); hoverDot.setAttribute('cy', y);
      hoverDot.setAttribute('opacity', 1);
      // Position tooltip — keep within plot bounds
      let tx = x + 10;
      const tw = 160;
      if (tx + tw > m.left + plotW) tx = x - tw - 10;
      const ty = Math.max(m.top + 4, Math.min(m.top + plotH - 38, y - 18));
      tooltip.setAttribute('opacity', 1);
      tooltip.setAttribute('transform', `translate(${tx}, ${ty})`);
      // Format year label as Gyr or Ma
      const labelMa = Math.round(t_cal);
      const yearLabel = Math.abs(labelMa) >= 1000
        ? (labelMa / 1000).toFixed(2) + ' Gyr (' + (t_cal < 0 ? 'past' : 'future') + ')'
        : labelMa + ' Ma (' + (t_cal <= 0 ? 'past/now' : 'future') + ')';
      yearTxt.textContent  = yearLabel;
      valueTxt.textContent = spec.yFmt(v);
    });
    capture.addEventListener('mouseleave', () => {
      hoverLine.setAttribute('opacity', 0);
      hoverDot.setAttribute('opacity', 0);
      tooltip.setAttribute('opacity', 0);
    });
  }

  function rerender() {
    contentEl.innerHTML = essrtRenderChart(essrtSelectedQty, essrtSelectedRange);
    bindHoverTooltip();
  }

  panel.querySelector('.cfm-close').addEventListener('click', closeEssrtPanel);
  panel.querySelector('.cfm-overlay').addEventListener('click', closeEssrtPanel);

  panel.querySelectorAll('[data-essrt-qty-tabs] .cfm-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      essrtSelectedQty = tab.getAttribute('data-qty');
      panel.querySelectorAll('[data-essrt-qty-tabs] .cfm-tab').forEach(t =>
        t.classList.toggle('cfm-tab-active', t.getAttribute('data-qty') === essrtSelectedQty));
      rerender();
    });
  });
  panel.querySelectorAll('[data-essrt-range-tabs] .cfm-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      essrtSelectedRange = tab.getAttribute('data-range');
      panel.querySelectorAll('[data-essrt-range-tabs] .cfm-tab').forEach(t => {
        const isActive = t.getAttribute('data-range') === essrtSelectedRange;
        // Apply teal accent inline so we don't share the gold cfm-tab-active rules.
        t.style.color        = isActive ? RANGE_TAB_ACCENT : '';
        t.style.borderColor  = isActive ? RANGE_TAB_ACCENT : '';
        t.style.background   = isActive ? RANGE_TAB_BG      : '';
      });
      rerender();
    });
  });

  // ONE "Export" (top-right in header) prints the quantity + range on screen
  const exportBtn = panel.querySelector('[data-essrt-export]');
  if (exportBtn) exportBtn.addEventListener('click', () => essrtExport(essrtSelectedRange));

  document.body.appendChild(panel);
  requestAnimationFrame(() => panel.classList.add('visible'));
  // Bind hover for the initial render
  bindHoverTooltip();
  return panel;
}

function openEssrtPanel() {
  return _openPanelOnce('essrt', async () => {
    if (essrtPanel) { essrtPanel.remove(); essrtPanel = null; }
    essrtPanel = await createEssrtPanel();
  });
}

function closeEssrtPanel() {
  if (essrtPanel) essrtPanel.classList.remove('visible');
}

// ═══════════════════════════════════════════════════════════════════
// LOD-CLIMATE RHYTHM (.lcr-)
// All-cycles stack vs named historical climate transitions.
// Reuses .cfm-* CSS classes for modal chrome. Findings live in docs/102
// § "Defensible scientific position" item 7 and docs/105.
// ═══════════════════════════════════════════════════════════════════

let lcrPanel = null;
let lcrProxyData = null;   // { sources: [{name, unit, range, data:[[year,°C],…]}] }

// Which layers to show in the chart. Kept minimal: Net L2 secular baseline,
// Net L3 observable (which contains the stack signal as its offset from L2),
// climate bands, framework zero-crossings, and the GISP2 temperature proxy.
// Stack rate and GIA rate are decomposition-only diagnostics — reachable via
// the tweakpane dLOD/dt decomposition sub-folder, not needed in this modal.
const lcrLayerVisibility = {
  tidal: true,        // Tidal-only reference (+2.12 ms/cy, ~flat) — pure Moon-recession
  netL2: true,        // Tidal + GIA (secular baseline)
  netL3: true,        // Tidal + GIA + 4-flag cycles (flags only since the joint world); gates the ▲/▼ transition markers
  netL4: true,        // + Core-mantle swing (Resonator) = the shipped observable (Layer 4, joint world)
  bondCurve: false,   // Bond harmonic isolated (thin dashed) — expected 1466-yr sinusoid — opt-in
  resonator: false,   // Core-mantle swing episode isolated (rendered on the Net L2 baseline like Bond) — opt-in
  bands: true,        // named climate period bands (background shading)
  proxy: false,       // temperature anomaly overlay GISP2 (secondary Y-axis) — opt-in
  proxyLR04: false,   // LR04 inverted-δ¹⁸O overlay (secondary Y-axis) — opt-in, covers the 200-kyr tab
};

// Bond events — North Atlantic ice-rafted-debris cold events on ~1470 yr
// cycle (Bond et al. 1997 Science; Bond et al. 2001 Science). Dates converted
// from age-kyr-BP (1950 CE base) to calendar year CE.
//   Bond 0: 500  yr BP → 1450 CE (Little Ice Age)
//   Bond 1: 1400 yr BP →  550 CE (Migration Period / Late Antique LIA)
//   Bond 2: 2800 yr BP → -850 CE (Iron Age cold epoch)
//   Bond 3: 4200 yr BP → -2250 CE (4.2 ka event / Late Bronze Age)
//   Bond 4: 5900 yr BP → -3950 CE
//   Bond 5: 8200 yr BP → -6250 CE (8.2 ka event)
//   Bond 6: 9400 yr BP → -7450 CE
//   Bond 7: 10300 yr BP → -8350 CE
//   Bond 8: 11100 yr BP → -9150 CE
const LCR_BOND_EVENTS = [
  { year: 1450,  n: 0, name: 'Bond 0', desc: 'Little Ice Age' },
  { year:  550,  n: 1, name: 'Bond 1', desc: 'Migration Period / Late Antique' },
  { year: -850,  n: 2, name: 'Bond 2', desc: 'Iron Age cold epoch' },
  { year: -2250, n: 3, name: 'Bond 3', desc: '4.2 ka event' },
  { year: -3950, n: 4, name: 'Bond 4' },
  { year: -6250, n: 5, name: 'Bond 5', desc: '8.2 ka event' },
  { year: -7450, n: 6, name: 'Bond 6' },
  { year: -8350, n: 7, name: 'Bond 7' },
  { year: -9150, n: 8, name: 'Bond 8', desc: 'Younger Dryas onset era' },
];

// Proxy sources — fixed roles, no user selector:
//   - CHART overlay = GISP2 Alley 2000 (Greenland temperature) — smoothest
//     signal across the Holocene window, best for visual overlay.
//   - CHART overlay (deep) = LR04 benthic stack (Lisiecki & Raymo 2005),
//     derived at load from the Earth Climate Analysis's lr04-data.json as
//     inverted δ¹⁸O anomaly — covers the full 200-kyr glacial tab where
//     GISP2 runs out (~27,950 BC).
//   - CORRELATION target = Bond 2001 IRD stack — Bond's OWN dataset, the
//     most direct out-of-sample COMPARISON for the framework's Bond harmonic
//     (joint world, stack incl. Core-mantle swing: r = +0.36 in the
//     validated window, r = +0.27 full overlap; pre-joint 4-flag stack
//     gave +0.49 / +0.38). NOT a validation: the correspondence fails its
//     null tests and is not carried by the 1466-yr band — at that period the
//     stack and IRD are ~175° apart. See docs/102 § "Defensible scientific
//     position" item 7; regenerate via tools/explore/climate-band-phase.js.
// All proxies live in lcrProxyData.sources; correlation ignores non-targets.
const LCR_CHART_PROXY       = 'GISP2 (Alley 2000)';
const LCR_CHART_PROXY_LR04  = 'LR04 (Lisiecki & Raymo 2005)';
const LCR_CORRELATION_PROXY = 'Bond 2001 IRD';

/** Compute framework-vs-temperature Pearson correlations over the Holocene
 *  overlap window. Two series are compared to the detrended GISP2 proxy:
 *    (1) Σ_stack — cumulative 4-flag ΔT stack contribution (Bond + Hallstatt +
 *        Jose5 + Jose4). Same physical dimension as an LOD anomaly.
 *    (2) Bond harmonic isolated — just the 1466-yr term.
 *  Sign convention: Σ > 0 = higher LOD than Layer 2 baseline = Earth slower
 *  = mass equatorward = WARM anomaly. Same sign as positive T anomaly.
 *  Positive r → framework tracks temperature (co-varies). Negative r → anti-
 *  phase / driven by other signals. Near zero → no linear relationship.
 *
 *  Also computes the best-lag cross-correlation for the Bond harmonic
 *  (search ±500 yr) — if the framework's Bond phase is offset from the true
 *  Bond phase, the best lag reveals it. */
function lcrComputeCorrelations(windowLo, windowHi) {
  if (!lcrProxyData || !lcrProxyData.sources) return null;
  const proxy = lcrProxyData.sources.find(s => s.name === LCR_CORRELATION_PROXY);
  if (!proxy || !proxy.dataDetrended || proxy.dataDetrended.length < 3) return null;

  const proxyMin = proxy.dataDetrended[0][0];
  const proxyMax = proxy.dataDetrended[proxy.dataDetrended.length - 1][0];
  // Sample framework at proxy's native step (~100 yr for GISP2). Optional
  // caller-supplied [windowLo, windowHi] clamps the scan (e.g., to restrict
  // to the framework's Espenak-fit-validated window).
  const STEP = 100;
  const yrLo = Math.max(windowLo != null ? windowLo : -Infinity,
                        Math.ceil(proxyMin / STEP) * STEP);
  const yrHi = Math.min(windowHi != null ? windowHi :  Infinity,
                        Math.floor(proxyMax / STEP) * STEP);

  // Linear interpolation of proxy detrended values.
  const dd = proxy.dataDetrended;
  const interpT = (year) => {
    if (year < dd[0][0] || year > dd[dd.length - 1][0]) return null;
    let lo = 0, hi = dd.length - 1;
    while (hi - lo > 1) {
      const mid = (lo + hi) >> 1;
      if (dd[mid][0] < year) lo = mid; else hi = mid;
    }
    const [y1, v1] = dd[lo], [y2, v2] = dd[hi];
    if (y1 === y2) return v1;
    return v1 + ((year - y1) / (y2 - y1)) * (v2 - v1);
  };

  const stackVals = [];
  const bondVals  = [];
  const tempVals  = [];
  const years     = [];
  for (let year = yrLo; year <= yrHi; year += STEP) {
    const t = interpT(year);
    if (t == null) continue;
    stackVals.push(dtCycleLodCorrectionSum(year));
    bondVals.push(bondCycleLodCorrection(year));
    tempVals.push(t);
    years.push(year);
  }
  if (tempVals.length < 30) return null;

  function pearson(x, y) {
    const n = x.length;
    if (n !== y.length || n < 3) return null;
    let sx = 0, sy = 0;
    for (let i = 0; i < n; i++) { sx += x[i]; sy += y[i]; }
    const mx = sx / n, my = sy / n;
    let sxy = 0, sxx = 0, syy = 0;
    for (let i = 0; i < n; i++) {
      const dx = x[i] - mx, dy = y[i] - my;
      sxy += dx * dy; sxx += dx * dx; syy += dy * dy;
    }
    const den = Math.sqrt(sxx * syy);
    return den > 0 ? sxy / den : null;
  }

  // Best-lag cross-correlation for Bond harmonic (±500 yr in 25-yr steps).
  // Positive lag = framework LEADS temperature by that many years.
  let bestLag = 0, bestR = pearson(bondVals, tempVals) ?? 0;
  const lagStep = 25;
  const lagMax  = 500;
  for (let lag = -lagMax; lag <= lagMax; lag += lagStep) {
    if (lag === 0) continue;
    // Recompute bond at (year + lag) so we test "if the framework Bond were
    // shifted by `lag` years, would it correlate better?".
    const bondLagged = [];
    const tempSame   = [];
    for (let i = 0; i < years.length; i++) {
      const b = bondCycleLodCorrection(years[i] + lag);
      const t = tempVals[i];
      if (b == null || t == null) continue;
      bondLagged.push(b);
      tempSame.push(t);
    }
    const r = pearson(bondLagged, tempSame);
    if (r != null && Math.abs(r) > Math.abs(bestR)) { bestR = r; bestLag = lag; }
  }

  return {
    n: tempVals.length,
    windowLo: yrLo,
    windowHi: yrHi,
    proxyName: proxy.name,
    r_stack: pearson(stackVals, tempVals),
    r_bond:  pearson(bondVals,  tempVals),
    bestLag: bestLag,
    r_bond_bestlag: bestR,
  };
}

/** Sign-convention diagnostic — at each named cold or warm event, print
 *  the framework's Σ_stack value. Under the derived convention (Σ > 0 =
 *  higher LOD than baseline = mass equatorward = WARM anomaly), we
 *  expect Σ < 0 at cold events and Σ > 0 at warm events.
 *
 *  If most events match expectation: sign convention is right; framework
 *  really does anti-correlate weakly with GISP2 temperature (some other
 *  signal dominates, e.g., mantle-core coupling).
 *
 *  If most events reversed: sign flipped somewhere in physics chain →
 *  fix it, re-run correlations, and everything may look better.
 *
 *  If mixed: framework doesn't cleanly track climate at these named events. */
const LCR_SIGN_CHECK_EVENTS = [
  { year: -10500, type: 'cold', name: 'Younger Dryas cold' },
  { year:  -6250, type: 'cold', name: '8.2 ka event' },
  { year:  -5000, type: 'warm', name: 'Holocene Optimum peak' },
  { year:  -3950, type: 'cold', name: 'Bond 4 event' },
  { year:  -2250, type: 'cold', name: '4.2 ka event' },
  { year:    100, type: 'warm', name: 'Roman Warm Period peak' },
  { year:   1050, type: 'warm', name: 'MWP peak' },
  { year:   1670, type: 'cold', name: 'Maunder Minimum' },
  { year:   1810, type: 'cold', name: 'Dalton Minimum' },
  { year:   2000, type: 'warm', name: 'Modern warm (nominal)' },
];

/** Band-level counterpart to the event check below. The event check samples ONE
 *  hand-picked year per named period, which flatters the result; this scores
 *  EVERY year inside each named period against its warm/cold label. Restricted
 *  to the validated window and to sub-Milankovitch periods (≤1000 yr span),
 *  i.e. the named events the stack is claimed to time — not the multi-millennial
 *  glacial envelopes. Returns pooled % correct plus the Little Ice Age alone. */
function lcrBandSignScore() {
  const LO = -4000, HI = 1800, STEP = 5;
  let tot = 0, ok = 0, liaTot = 0, liaOk = 0;
  for (const p of LCR_CLIMATE_PERIODS) {
    if (p.end - p.start > 1000) continue;
    const a = Math.max(p.start, LO), b = Math.min(p.end, HI);
    if (b <= a) continue;
    const want = p.type === 'warm' ? 1 : -1;
    for (let y = a; y <= b; y += STEP) {
      const sgn = Math.sign(dtCycleLodCorrectionSum(y));
      tot++; if (sgn === want) ok++;
      if (p.name === 'Little Ice Age') { liaTot++; if (sgn === want) liaOk++; }
    }
  }
  return { pct: tot ? Math.round(100 * ok / tot) : null,
           liaPct: liaTot ? Math.round(100 * liaOk / liaTot) : null,
           nPeriods: tot };
}

function lcrRenderSignCheckPanel(hideTitle) {
  // Validated window bounds (same as correlation panel) — where framework's
  // harmonic extrapolation from its Espenak 1650-2017 fit remains trustworthy.
  const validLo = -4000, validHi = 1800;
  const rows = LCR_SIGN_CHECK_EVENTS.map(evt => {
    const sigma = dtCycleLodCorrectionSum(evt.year);   // seconds
    const sigma_ms = sigma * 1000;                     // for display
    const expectedSign = evt.type === 'cold' ? -1 : +1;
    const actualSign   = sigma > 0 ? +1 : sigma < 0 ? -1 : 0;
    const match = actualSign === expectedSign;
    const inWindow = evt.year >= validLo && evt.year <= validHi;
    return { evt, sigma_ms, match, inWindow };
  });
  const inWinRows = rows.filter(r => r.inWindow);
  const outRows   = rows.filter(r => !r.inWindow);
  const inWinMatch  = inWinRows.filter(r => r.match).length;
  const outMatch    = outRows.filter(r => r.match).length;

  const fmtYr    = (y) => (y > 0 ? y + ' AD' : y < 0 ? (-y) + ' BC' : '1 BC');
  const fmtSigma = (v) => (v >= 0 ? '+' : '') + v.toFixed(3) + ' ms';
  const trRow = ({ evt, sigma_ms, match, inWindow }) => `
    <tr class="${inWindow ? '' : 'lcr-sign-outside'}">
      <td class="lcr-match-td-name">${evt.name}</td>
      <td class="lcr-match-td-year">${fmtYr(evt.year)}</td>
      <td>${evt.type === 'cold' ? '🩵 cold' : '🟥 warm'}</td>
      <td class="lcr-match-td-off">${fmtSigma(sigma_ms)}</td>
      <td class="${match ? 'lcr-r-strong' : 'lcr-r-mod'}">${match ? '✓' : '✗'}</td>
    </tr>`;

  return `
    ${hideTitle ? '' : '<div class="lcr-match-title">Sign convention check — Σ_stack at named events</div>'}
    <table class="lcr-match-table">
      <thead>
        <tr><th>Event</th><th>Year</th><th>Expected</th><th>Σ_stack</th><th>Match</th></tr>
      </thead>
      <tbody>${rows.map(trRow).join('')}</tbody>
    </table>
    <div class="lcr-match-summary">
      <b class="lcr-r-strong">${inWinMatch}/${inWinRows.length} within validated window match</b> (4000 BC – 1800 AD).
      <b class="lcr-r-mod">${outMatch}/${outRows.length} outside window match</b> (deep-past extrapolation drift + modern anthropogenic warming — not framework's cyclic prediction).
      <span class="lcr-match-note">
        Grey rows fall outside the framework's extrapolation-valid range; those mismatches are expected
        given the fit-window and modern-warming caveats.
        <br/><b>Read the ${inWinMatch}/${inWinRows.length} with care — each row samples one hand-picked year.</b>
        Scored instead across the <i>full</i> named periods, every year against its warm/cold label,
        the rule holds for <b>${(() => { const b = lcrBandSignScore(); return b.pct == null ? '—' : b.pct + '%'; })()}</b>
        of years against a 50% coin-flip baseline — and for
        <b>${(() => { const b = lcrBandSignScore(); return b.liaPct == null ? '—' : b.liaPct + '%'; })()}</b>
        of the Little Ice Age, where Σ_stack stays positive ("warm") across all five centuries.
        The event test books that as a single narrow miss at Maunder; it is a five-century systematic one.
        This comparison is an open correspondence, not a validation of the stack's periods.
      </span>
    </div>
  `;
}

/** Render the framework-vs-temperature correlation panel. Reports Pearson r
 *  for two comparisons + best-lag Bond harmonic; color-codes strength. */
function lcrRenderCorrelationPanel(hideTitle) {
  // Two windows: full overlap (framework range ∩ proxy range) + the
  // "framework-validated" window (-4000 BC to 1800 AD) — the span the
  // sign-check panel scores its named events against. Everything outside
  // is too many millennia before Espenak's 1650-2017 fit window; harmonic
  // extrapolation drifts.
  const cFull = lcrComputeCorrelations();
  const cRec  = lcrComputeCorrelations(-4000, 1800);
  if (!cFull) {
    return '<div class="lcr-match-note">(temperature proxy not loaded — correlation cannot be computed)</div>';
  }
  const strengthClass = (r) => {
    if (r == null) return '';
    const a = Math.abs(r);
    if (a >= 0.5)  return 'lcr-r-strong';
    if (a >= 0.25) return 'lcr-r-mod';
    if (a >= 0.10) return 'lcr-r-weak';
    return 'lcr-r-none';
  };
  const strengthLabel = (r) => {
    if (r == null) return '—';
    const a = Math.abs(r);
    if (a >= 0.5)  return 'strong';
    if (a >= 0.25) return 'moderate';
    if (a >= 0.10) return 'weak';
    return 'negligible';
  };
  const fmtR  = (r) => (r == null ? '—' : (r >= 0 ? '+' : '') + r.toFixed(3));
  const fmtYr = (y) => (y > 0 ? y + ' AD' : y < 0 ? (-y) + ' BC' : '1 BC');
  const row = (c, label) => c ? `
        <tr>
          <td>${label} <span class="lcr-match-td-empty">(${fmtYr(c.windowLo)}–${fmtYr(c.windowHi)}, n=${c.n})</span></td>
          <td class="lcr-match-td-off ${strengthClass(c.r_stack)}">${fmtR(c.r_stack)}</td>
          <td>${strengthLabel(c.r_stack)}</td>
        </tr>` : '';

  return `
    ${hideTitle ? '' : `<div class="lcr-match-title">Framework ↔ ${cFull.proxyName} correlation (detrended)</div>`}
    <table class="lcr-match-table">
      <thead>
        <tr><th>Window</th><th>Pearson r</th><th>Strength</th></tr>
      </thead>
      <tbody>
        ${row(cRec,  '<b>Validated window</b>')}
        ${row(cFull, 'Full overlap')}
      </tbody>
    </table>
    <div class="lcr-match-summary">
      Positive <b>r</b> ⇒ framework Σ_stack and Bond IRD co-vary (warm-with-warm).
      Validated window (−4000 BC → 1800 AD) is where the framework's harmonic
      extrapolation from its Espenak 1650-2017 fit target remains trustworthy;
      deep-past accumulates phase drift, modern era excludes anthropogenic warming.
      Strength: |r| ≥ 0.5 strong, ≥ 0.25 moderate, ≥ 0.10 weak.
    </div>
  `;
}

/** Bond-event ↔ framework-TROUGH match table. Uses a wide scan window
 *  (-12000 to +2050 CE) via lcrComputeSeries('full') so B8 is reachable;
 *  filters framework crossings to TROUGH only and picks the nearest one
 *  for each Bond event. Returns an HTML string for the panel. */
function lcrRenderBondMatchTable(hideTitle) {
  // Ensure we have the widest scan available (Full range) — it includes all Bond events.
  const S = lcrComputeSeries('full');
  const troughs = S.crossings.filter(c => c.type === 'TROUGH');
  if (troughs.length === 0) {
    return '<div class="lcr-match-note">(no framework TROUGH crossings in scan window)</div>';
  }
  const rows = [];
  const offsets = [];
  // Track which framework troughs have already been consumed by an earlier
  // Bond event — prevents the same crossing being reported twice as if it
  // matched two different Bond events (Bond 6 vs Bond 5 problem).
  const usedTroughYears = new Set();
  for (const b of LCR_BOND_EVENTS) {
    let best = null;
    for (const t of troughs) {
      const dt = t.year - b.year;
      if (best === null || Math.abs(dt) < Math.abs(best.dt)) best = { year: t.year, dt };
    }
    // Guard: if the nearest is absurdly far (>1500 yr) OR was already
    // consumed by an earlier Bond event, mark this event as no unique
    // match — the framework may be missing a trough near that event.
    if (best && Math.abs(best.dt) <= 1500 && !usedTroughYears.has(best.year)) {
      offsets.push(Math.abs(best.dt));
      usedTroughYears.add(best.year);
      rows.push({ bond: b, matched: best, alsoNear: null });
    } else {
      // Record what the nearest would be — helps the reader see the miss.
      rows.push({ bond: b, matched: null, alsoNear: best });
    }
  }
  const median = offsets.length > 0
    ? offsets.slice().sort((a, b) => a - b)[Math.floor(offsets.length / 2)]
    : null;
  const mean = offsets.length > 0
    ? Math.round(offsets.reduce((a, b) => a + b, 0) / offsets.length)
    : null;

  const fmtYear = y => (y > 0 ? y + ' AD' : y < 0 ? (-y) + ' BC' : '1 BC');
  const fmtOff  = d => (d > 0 ? '+' + d : String(d)) + ' yr';
  const nMissed = rows.filter(r => !r.matched).length;
  const trRows = rows.map(({ bond, matched, alsoNear }) => {
    const bondCell    = `<td class="lcr-match-td-name">${bond.name}</td><td class="lcr-match-td-year">${fmtYear(bond.year)}</td>`;
    const arrowCell   = `<td class="lcr-match-td-arrow">↔</td>`;
    if (matched) {
      const fwCell = `<td class="lcr-match-td-year">${fmtYear(matched.year)}</td>`;
      const offCell = `<td class="lcr-match-td-off ${Math.abs(matched.dt) <= 200 ? 'lcr-match-td-off-good' : Math.abs(matched.dt) <= 500 ? 'lcr-match-td-off-fair' : 'lcr-match-td-off-poor'}">${fmtOff(matched.dt)}</td>`;
      return `<tr>${bondCell}${arrowCell}${fwCell}${offCell}</tr>`;
    }
    // No unique match — framework missed this Bond event (or the nearest
    // trough was already consumed by a neighbor). Show the "would-be nearest"
    // in muted style so reader sees the miss clearly.
    const missCell = alsoNear
      ? `<td class="lcr-match-td-year lcr-match-td-empty">(no match — nearest ${fmtYear(alsoNear.year)} used by neighbor)</td>`
      : `<td class="lcr-match-td-year lcr-match-td-empty">(no match in ±1500 yr)</td>`;
    return `<tr class="lcr-sign-outside">${bondCell}${arrowCell}${missCell}<td class="lcr-match-td-off"></td></tr>`;
  }).join('');
  return `
    ${hideTitle ? '' : '<div class="lcr-match-title">Bond event ↔ nearest framework ▼ TROUGH crossing</div>'}
    <table class="lcr-match-table">
      <thead>
        <tr>
          <th>#</th><th>Literature</th><th></th><th>Framework</th><th>Offset</th>
        </tr>
      </thead>
      <tbody>${trRows}</tbody>
    </table>
    <div class="lcr-match-summary">
      <b>${offsets.length}/${LCR_BOND_EVENTS.length}</b> matched uniquely (framework has no framework-trough duplicate matches),
      median |offset| <b>${median != null ? median + ' yr' : '—'}</b>, mean <b>${mean != null ? mean + ' yr' : '—'}</b>.
      <span class="lcr-match-note">
        Bond dating uncertainty in the literature is ~100-300 yr per event.
        ${nMissed > 0 ? `${nMissed} event(s) had no unique nearest trough — the framework's Bond harmonic misses those events (or its interference with Hallstatt/Jose5/Jose4 hides them).` : ''}
      </span>
    </div>
  `;
}

/** Detrend a proxy series by subtracting a symmetric rolling-mean baseline.
 *  Purpose: highlight sub-Milankovitch (Bond-scale) oscillations by removing
 *  the slow Milankovitch-scale trend (e.g. Younger Dryas → Holocene warming
 *  or Holocene → present cooling). Uses a full-window mean at each point,
 *  clamped at edges (partial windows shorter than requested near boundaries).
 *  Input:  data = [[year, value], …] sorted ascending
 *          windowYr = detrend baseline window (default 5000 yr)
 *  Output: [[year, detrended_value], …] same length. */
function lcrDetrendSeries(data, windowYr = 5000) {
  const halfWin = windowYr / 2;
  const out = [];
  for (let i = 0; i < data.length; i++) {
    const [yi, vi] = data[i];
    let sum = 0, count = 0;
    for (let j = 0; j < data.length; j++) {
      const [yj, vj] = data[j];
      if (yj < yi - halfWin) continue;
      if (yj > yi + halfWin) break;
      sum += vj;
      count += 1;
    }
    out.push([yi, vi - (sum / count)]);
  }
  return out;
}

/** Async loader for climate proxy data. Caches on first call (fetchRepoJson:
 *  the local copy, then the repository). */
async function lcrLoadProxyData() {
  if (lcrProxyData) return lcrProxyData;
  lcrProxyData = await fetchRepoJson('public/input/climate-proxy.json');
  if (!lcrProxyData) {
    console.error('[LCR] Failed to load climate-proxy.json (both local and GitHub fallback). Proxy overlay disabled.');
    lcrProxyData = { sources: [] };
  } else {
    console.log(`[LCR] Loaded climate proxy: ${lcrProxyData.sources.length} sources (${lcrProxyData.sources.map(s => s.name).join(', ')})`);
    // Precompute a detrended version (5-kyr rolling mean baseline) for each
    // source, cached under `dataDetrended`. Used by the "Detrended" toggle to
    // reveal sub-Milankovitch (Bond-scale) oscillations by removing the
    // slow Milankovitch-scale trend.
    for (const src of lcrProxyData.sources) {
      src.dataDetrended = lcrDetrendSeries(src.data, 5000);
    }
  }
  // Derive the LR04 overlay source from the Earth Climate Analysis's data
  // file: inverted benthic δ¹⁸O anomaly vs core-top (positive = warm), same
  // sign convention as the Bond IRD source. 1-kyr native resolution; clipped
  // to the widest LCR tab (200,000 BC) to keep the series small.
  const lr04 = await loadCfmLR04Data();
  if (lr04 && lr04.age_kyr_BP && lr04.d18o_per_mille) {
    const ref = lr04.d18o_per_mille[0]; // core-top (0 ka BP)
    const data = [];
    for (let i = lr04.age_kyr_BP.length - 1; i >= 0; i--) {
      const year = 1950 - lr04.age_kyr_BP[i] * 1000;
      if (year < -202000) continue;
      data.push([year, ref - lr04.d18o_per_mille[i]]);
    }
    lcrProxyData.sources.push({
      name: LCR_CHART_PROXY_LR04,
      reference: lr04.source || 'Lisiecki & Raymo (2005)',
      region: 'global benthic stack (57 sites)',
      unit: 'inverted δ¹⁸O anomaly (‰, positive = warm) vs core-top',
      data,
    });
  } else {
    console.error('[LCR] Failed to load lr04-data.json — LR04 overlay disabled.');
  }
  return lcrProxyData;
}

// Epoch tabs — seven windows spanning deep past to deep future. Default is
// 'historical' (750-2050 AD) — the culturally-recognizable window (MWP,
// LIA, Modern). yMin/yMax auto-computed per tab from visible data.
const LCR_RANGE_TABS = [
  { key: 'glacial',    xLo:-200000, xHi: 2050, label: '200,000 BC–2050',     xStep: 25000, samples: 3000 },
  { key: 'deep',       xLo:-27500, xHi:  2050, label: '27,500 BC–2050',      xStep: 4000 },
  { key: 'lgm',        xLo:-13000, xHi:  2050, label: '13,000 BC–2050',      xStep: 2000 },
  { key: 'holocene',   xLo: -4000, xHi:  2050, label: '4,000 BC–2050',       xStep: 1000 },
  { key: 'historical', xLo:   750, xHi:  2050, label: '750–2050 AD',         xStep: 100  },
  { key: 'nearFuture', xLo:  1200, xHi:  2500, label: '1,200–2,500 AD',      xStep: 100  },
  { key: 'full',       xLo:-13000, xHi: 15000, label: '13,000 BC–15,000',    xStep: 2000 },
];
let lcrSelectedRange = 'historical';

// Named climate periods with mainstream literature dates + sources.
// Bands are drawn as light background rectangles behind the rate curves.
// Sign convention: type 'cold' = blue band; 'warm' = red band.
const LCR_CLIMATE_PERIODS = [
  { start: -200000, end: -189000, type: 'warm', name: 'MIS 7 interglacial',            src: 'MIS 7a–7c interglacial complex, ends ~191 ka BP' },
  { start: -189000, end: -128000, type: 'cold', name: 'Penultimate Glaciation (MIS 6)', src: 'Saalian / Illinoian glacial, ~191–130 ka BP' },
  { start: -128000, end: -113000, type: 'warm', name: 'Eemian (MIS 5e)',               src: 'Last Interglacial, ~130–115 ka BP' },
  { start: -113000, end:   -9700, type: 'cold', name: 'Last Glacial Period',           src: 'MIS 5d–2, ~115–11.7 ka BP' },
  { start: -22000, end: -18000, type: 'cold', name: 'Last Glacial Maximum',       src: 'LGM sea-level minimum window ~24,000–20,000 BP' },
  { start: -12050, end: -11750, type: 'cold', name: 'Older Dryas',                src: '14,000–13,700 BP cold reversal within Bølling-Allerød' },
  { start: -10950, end:  -9750, type: 'cold', name: 'Younger Dryas',              src: 'Alley 2000 (12,900–11,700 BP → calendar 10,950–9,750 BC)' },
  { start:  -7000, end:  -3000, type: 'warm', name: 'Holocene Climatic Optimum',  src: 'various' },
  { start:  -6250, end:  -6100, type: 'cold', name: '8.2 ka event',               src: 'Alley 1997' },
  { start:  -3850, end:  -3750, type: 'cold', name: 'Bond 4 event',               src: 'Bond 2001' },
  { start:  -2250, end:  -2150, type: 'cold', name: '4.2 ka event / Bond 3',      src: 'Weiss 1993' },
  { start:  -1200, end:  -1100, type: 'cold', name: 'Late Bronze Age Collapse',   src: 'Kaniewski 2013' },
  { start:   -800, end:   -400, type: 'cold', name: 'Iron Age cold epoch',        src: 'van Geel 1996' },
  { start:   -250, end:    400, type: 'warm', name: 'Roman Warm Period',          src: 'Lamb 1965' },
  { start:    536, end:    660, type: 'cold', name: 'Late Antique Little Ice Age',src: 'Büntgen 2016' },
  { start:    950, end:   1250, type: 'warm', name: 'Medieval Warm Period',       src: 'Lamb 1965; Mann 2009' },
  { start:   1300, end:   1850, type: 'cold', name: 'Little Ice Age',             src: 'Matthes 1939; Grove 2004 (includes Maunder ~1645-1715 and Dalton ~1790-1830 solar minima)' },
  { start:   1850, end:   2050, type: 'warm', name: 'Modern warm period',         src: 'Instrumental (part-anthropogenic)' },
];

/** Compute the four rate curves + framework crossings across the requested LCR window.
 *  Cached per range so repeated renders on the same tab don't rebuild.
 *  Returns { xs, netL2, netL3, stack, gia, crossings, xLo, xHi, step }. */
const _lcrSeriesCache = {};
function lcrComputeSeries(rangeKey) {
  if (_lcrSeriesCache[rangeKey]) return _lcrSeriesCache[rangeKey];
  const range = LCR_RANGE_TABS.find(r => r.key === rangeKey) || LCR_RANGE_TABS[0];
  const xLo = range.xLo;
  const xHi = range.xHi;
  // Adaptive step: coarser on wide views, finer on narrow (target ~600 samples).
  // Very wide tabs can override via range.samples — the 200-kyr view needs a
  // finer grid to keep the ~716-yr Jose4 harmonic above Nyquist (no moiré).
  const step = Math.max(2, Math.round((xHi - xLo) / (range.samples || 600)));

  const xs = [];
  const tidal = [];
  const netL2 = [];
  const netL3 = [];
  const netL4 = [];
  const stack = [];
  const gia   = [];
  const bond  = [];   // Bond harmonic isolated rate — d/dt of bondCycleLodCorrection
  const resonator = [];   // Core-mantle swing isolated rate (Resonator driver channel)

  const DYR_BOND = 50;
  for (let year = xLo; year <= xHi; year += step) {
    const t_Ma = (2000 - year) / 1e6;
    const d = dLodDtDecompositionAtAge(t_Ma);
    xs.push(year);
    tidal.push(d.tidal);
    netL2.push(d.net_L2);
    netL3.push(d.net_L3);
    netL4.push(d.net_L4);
    resonator.push(d.resonator);
    stack.push(d.stack);
    gia.push(d.gia);
    // Bond harmonic rate (ms/century): numerical derivative of
    // bondCycleLodCorrection at ±50 yr, converted from s/yr to ms/century.
    const bondPlus  = bondCycleLodCorrection(year + DYR_BOND);
    const bondMinus = bondCycleLodCorrection(year - DYR_BOND);
    bond.push(((bondPlus - bondMinus) / (2 * DYR_BOND)) * 100 * 1000);
  }

  const crossings = [];
  for (let i = 1; i < xs.length; i++) {
    const r1 = stack[i - 1];
    const r2 = stack[i];
    if (r1 == null || r2 == null) continue;
    if (r1 * r2 < 0) {
      const y1 = xs[i - 1];
      const y2 = xs[i];
      const yc = y1 + (y2 - y1) * (-r1) / (r2 - r1);
      const type = r1 > 0 ? 'PEAK' : 'TROUGH';
      crossings.push({ year: Math.round(yc), type });
    }
  }

  _lcrSeriesCache[rangeKey] = { xs, tidal, netL2, netL3, netL4, resonator, stack, gia, bond, crossings, xLo, xHi, step };
  return _lcrSeriesCache[rangeKey];
}

function lcrRenderChart(rangeKey) {
  const range = LCR_RANGE_TABS.find(r => r.key === rangeKey) || LCR_RANGE_TABS[0];
  const S = lcrComputeSeries(rangeKey);
  const W = 1100, H = 420;
  // right margin widened from 30 → 78 to accommodate the secondary temperature-anomaly axis.
  // top margin 50 leaves room for J2000 label + 2-3 rows of 45° leader labels
  // pointing to narrow climate-period bands (Older Dryas, 8.2 ka event, etc.).
  const margin = { top: 50, right: 78, bottom: 70, left: 78 };
  const plotW = W - margin.left - margin.right;
  const plotH = H - margin.top - margin.bottom;

  // Auto-compute Y range from visible data. Consider only currently-toggled
  // curves so hiding a curve rescales the axis to fit what's visible.
  let dataMin = +Infinity, dataMax = -Infinity;
  const scan = (arr) => {
    for (let i = 0; i < arr.length; i++) {
      const v = arr[i];
      if (v == null) continue;
      if (v < dataMin) dataMin = v;
      if (v > dataMax) dataMax = v;
    }
  };
  if (lcrLayerVisibility.tidal) scan(S.tidal);
  if (lcrLayerVisibility.netL2) scan(S.netL2);
  if (lcrLayerVisibility.netL3) scan(S.netL3);
  if (lcrLayerVisibility.netL4) scan(S.netL4);
  // Resonator isolated curve is rendered OFFSET by Net L2 (like Bond below).
  if (lcrLayerVisibility.resonator) {
    for (let i = 0; i < S.resonator.length; i++) {
      const v = (S.resonator[i] != null && S.netL2[i] != null) ? S.resonator[i] + S.netL2[i] : null;
      if (v == null) continue;
      if (v < dataMin) dataMin = v;
      if (v > dataMax) dataMax = v;
    }
  }
  // Bond isolated curve is rendered OFFSET by Net L2 so it visually
  // oscillates on the Framework baseline (the reference height of the
  // TROUGH triangles). Scan its shifted values for auto-Y-range so the
  // axis fits the visible curve.
  if (lcrLayerVisibility.bondCurve) {
    for (let i = 0; i < S.bond.length; i++) {
      const v = (S.bond[i] != null && S.netL2[i] != null) ? S.bond[i] + S.netL2[i] : null;
      if (v == null) continue;
      if (v < dataMin) dataMin = v;
      if (v > dataMax) dataMax = v;
    }
  }
  // Always include IERS reference and zero line in the axis so they're never clipped.
  if (dataMin > 0)    dataMin = 0;
  if (dataMax < 1.75) dataMax = 1.75;
  // Fallback if no curves toggled.
  if (!Number.isFinite(dataMin) || !Number.isFinite(dataMax)) { dataMin = -0.5; dataMax = 3.5; }
  const pad = Math.max(0.2, (dataMax - dataMin) * 0.08);
  // Snap to nice 0.5-multiples so gridlines land on clean values.
  const yMin = Math.floor((dataMin - pad) * 2) / 2;
  const yMax = Math.ceil((dataMax + pad) * 2) / 2;

  const xPos = (year) => margin.left + ((year - S.xLo) / (S.xHi - S.xLo)) * plotW;
  const yPos = (v)    => margin.top + (1 - (v - yMin) / (yMax - yMin)) * plotH;
  const yPosClipped = (v) => {
    const y = yPos(v);
    if (y < margin.top) return margin.top;
    if (y > margin.top + plotH) return margin.top + plotH;
    return y;
  };

  // X ticks — nice-round spacing per range.
  const xticks = [];
  const xStart = Math.ceil(S.xLo / range.xStep) * range.xStep;
  for (let year = xStart; year <= S.xHi + 1e-9; year += range.xStep) {
    const x = xPos(year);
    // Year 0 in the astronomical calendar = 1 BC (there's no "year 0 AD").
    // J2000 is calendar year 2000 AD, handled by the vertical J2000 line +
    // label elsewhere — not by an x-axis tick.
    const label = year === 0 ? '1 BC' : (year < 0 ? `${-year} BC` : `${year} AD`);
    xticks.push(`<line x1="${x}" y1="${margin.top + plotH}" x2="${x}" y2="${margin.top + plotH + 5}" stroke="#888" stroke-width="0.7"/>
      <text x="${x}" y="${margin.top + plotH + 20}" text-anchor="middle" font-size="10" fill="#d4d4d4">${label}</text>`);
  }

  // Y ticks — 0.5 ms/cy spacing.
  const yticks = [];
  for (let v = Math.ceil(yMin * 2) / 2; v <= yMax + 1e-9; v += 0.5) {
    const y = yPos(v);
    yticks.push(`<line x1="${margin.left - 5}" y1="${y}" x2="${margin.left}" y2="${y}" stroke="#888" stroke-width="0.7"/>
      <text x="${margin.left - 9}" y="${y + 4}" text-anchor="end" font-size="10" fill="#d4d4d4">${v.toFixed(1)}</text>
      <line x1="${margin.left}" y1="${y}" x2="${margin.left + plotW}" y2="${y}" stroke="#2a2f37" stroke-width="0.5"/>`);
  }

  // Zero line (bold)
  const zeroY = yPos(0);
  const zeroLine = `<line x1="${margin.left}" y1="${zeroY}" x2="${margin.left + plotW}" y2="${zeroY}" stroke="#666" stroke-width="1" stroke-dasharray="4,3"/>`;

  // (IERS +1.75 reference line removed — Framework baseline (teal) already
  // sits at ≈ 1.77 ms/cy on the historical view, so an extra dashed reference
  // would be visually redundant. IERS anchor remains documented in the "How
  // to read" panel + Framework baseline tooltip.)
  const iersLine = '';

  // J2000 vertical (only if year 2000 is inside the range). No text label —
  // the tab range already communicates the epoch; the vertical line is only
  // kept as a subtle visual anchor.
  let j2000Line = '';
  if (S.xLo <= 2000 && 2000 <= S.xHi) {
    const j2000X = xPos(2000);
    j2000Line = `<line x1="${j2000X}" y1="${margin.top}" x2="${j2000X}" y2="${margin.top + plotH}" stroke="#e8e8e8" stroke-width="1.1" opacity="0.55"/>`;
  }

  // (Bond event markers removed from the chart — the Bond-match table below
  // provides the numeric mainstream-vs-framework comparison instead.)

  // Climate period bands (background shading). Cold = blue, warm = red.
  // Wide bands (≥60 px) get an inline horizontal label; narrower bands get
  // their name in the top margin above the plot, connected by a thin
  // 45°-angled leader line pointing down to the band top. Multiple narrow
  // labels are staggered across 3 vertical rows to avoid overlapping each
  // other.
  const bands = (() => {
    if (!lcrLayerVisibility.bands) return '';
    const visible = LCR_CLIMATE_PERIODS
      .filter(p => p.end >= S.xLo && p.start <= S.xHi)
      .map(p => {
        const x1 = xPos(Math.max(p.start, S.xLo));
        const x2 = xPos(Math.min(p.end, S.xHi));
        return { p, x1, x2, w: Math.max(1, x2 - x1), midX: (x1 + x2) / 2 };
      });
    const rects = [];
    const inlineLabels = [];
    const leaderLabels = [];

    // Inline-label anti-collision (wide bands): 2 rows inside plot area.
    const inlineRowLastX = [-Infinity, -Infinity];
    // Leader-label anti-collision (narrow bands): 3 rows staggered at
    // different leader lengths so labels don't overlap in the top margin.
    // Larger L pushes the label higher and further to the right of the band.
    const LEADER_LENGTHS  = [12, 24, 36];
    const leaderRowLastX  = [-Infinity, -Infinity, -Infinity];

    visible.forEach(({ p, x1, x2, w, midX }) => {
      const color = p.type === 'warm' ? '#e07070' : '#6db4ff';
      rects.push(`<rect x="${x1}" y="${margin.top}" width="${w}" height="${plotH}" fill="${color}" opacity="0.10" data-lcr-band="${p.name}" data-lcr-band-src="${p.src}"><title>${p.name} (${p.start}–${p.end}) — ${p.src}</title></rect>`);

      if (w >= 60) {
        // Wide band — horizontal inline label at the top of the band.
        let row = 0;
        for (row = 0; row < inlineRowLastX.length; row++) {
          if (midX - inlineRowLastX[row] >= 50) break;
        }
        if (row >= inlineRowLastX.length) return;
        inlineRowLastX[row] = midX;
        const y = margin.top + 12 + row * 14;
        const maxChars = Math.max(6, Math.floor(w / 6));
        const displayName = p.name.length > maxChars ? p.name.slice(0, maxChars - 1) + '…' : p.name;
        inlineLabels.push(`<text x="${midX}" y="${y}" text-anchor="middle" font-size="11" fill="${color}" opacity="0.95" font-weight="600">${displayName}</text>`);
      } else {
        // Narrow band — leader label in the top margin, connected by a
        // thin 45° line pointing down to the band top. Try each row until
        // the label fits without colliding with the previous label in that
        // row (~6 px per character estimate).
        const labelWEst = p.name.length * 6 + 6;
        let row = 0;
        for (row = 0; row < LEADER_LENGTHS.length; row++) {
          const L = LEADER_LENGTHS[row];
          const labelStartX = midX + L;
          if (labelStartX - leaderRowLastX[row] >= labelWEst + 10) break;
        }
        if (row >= LEADER_LENGTHS.length) return; // no free row
        const L = LEADER_LENGTHS[row];
        const labelStartX = midX + L;
        leaderRowLastX[row] = labelStartX + labelWEst;
        const labelX = labelStartX + 3;
        const labelY = margin.top - L + 3; // slight baseline padding
        leaderLabels.push(
          `<line x1="${midX.toFixed(1)}" y1="${margin.top}" x2="${(midX + L).toFixed(1)}" y2="${(margin.top - L).toFixed(1)}" stroke="${color}" stroke-width="0.6" opacity="0.7"/>` +
          `<text x="${labelX.toFixed(1)}" y="${labelY.toFixed(1)}" text-anchor="start" font-size="10" fill="${color}" opacity="0.95" font-weight="600">${p.name}</text>`
        );
      }
    });
    return rects.join('') + inlineLabels.join('') + leaderLabels.join('');
  })();

  // Curve helpers.
  function pathFor(data) {
    let d = '';
    let prevNull = true;
    for (let i = 0; i < S.xs.length; i++) {
      const v = data[i];
      if (v == null) { prevNull = true; continue; }
      const cmd = (d === '' || prevNull) ? 'M' : 'L';
      d += `${cmd}${xPos(S.xs[i]).toFixed(1)} ${yPosClipped(v).toFixed(1)} `;
      prevNull = false;
    }
    return d;
  }

  const paths = [];
  // Tidal-only reference (~flat at +2.12 ms/cy). Drawn first so the other
  // physical layers stack visibly above it. Dashed rust color reads as a
  // bedrock reference rather than a derived prediction.
  if (lcrLayerVisibility.tidal) {
    paths.push(`<path d="${pathFor(S.tidal)}" fill="none" stroke="#c46a4d" stroke-width="1.5" stroke-dasharray="4,3" opacity="0.9" data-lcr-curve="tidal"/>`);
  }
  if (lcrLayerVisibility.netL2) {
    paths.push(`<path d="${pathFor(S.netL2)}" fill="none" stroke="#4dd0c8" stroke-width="2" opacity="0.95" data-lcr-curve="netL2"/>`);
  }
  if (lcrLayerVisibility.bondCurve) {
    // Bond isolated (1466-yr harmonic only). Thin lavender dashed —
    // expected to be a clean 1466-yr sinusoid. Rendered SHIFTED by Net L2
    // so the sinusoid oscillates ON THE FRAMEWORK BASELINE (the reference
    // height for TROUGH triangles + Bond mainstream dots). Sub-baseline
    // portions = COLD anomalies, above-baseline = WARM anomalies.
    const bondShifted = S.bond.map((b, i) =>
      (b == null || S.netL2[i] == null) ? null : b + S.netL2[i]
    );
    paths.push(`<path d="${pathFor(bondShifted)}" fill="none" stroke="#c084fc" stroke-width="1.2" stroke-dasharray="5,3" opacity="0.85" data-lcr-curve="bond"/>`);
  }
  if (lcrLayerVisibility.resonator) {
    // Core-mantle swing isolated (Resonator driver), SHIFTED by Net L2 so the
    // episode rides the framework baseline: zero before −1600, the swing
    // through antiquity, terminated by +1600, zero today — the 4th driver
    // made visible. Solid thin green.
    const resShifted = S.resonator.map((r, i) =>
      (r == null || S.netL2[i] == null) ? null : r + S.netL2[i]
    );
    paths.push(`<path d="${pathFor(resShifted)}" fill="none" stroke="#7bd88f" stroke-width="1.4" opacity="0.9" data-lcr-curve="resonator"/>`);
  }
  if (lcrLayerVisibility.netL3) {
    paths.push(`<path d="${pathFor(S.netL3)}" fill="none" stroke="#ffce4b" stroke-width="1.4" stroke-dasharray="6,3" opacity="0.85" data-lcr-curve="netL3"/>`);
  }
  if (lcrLayerVisibility.netL4) {
    // The shipped observable (joint world): Layer 4 = Tidal + GIA + cycles +
    // Core-mantle swing. Drawn last/boldest — this is THE prediction curve.
    paths.push(`<path d="${pathFor(S.netL4)}" fill="none" stroke="#ff8c42" stroke-width="2.2" opacity="1" data-lcr-curve="netL4"/>`);
  }

  // Framework crossings as small triangle markers ON the Framework baseline
  // (Net L2 line) — that's where the stack contribution is zero, i.e., where
  // Net L3 crosses Net L2. Placing them there makes the visual meaning
  // immediate: "at this year, prediction touches baseline; before/after it
  // swings warm or cold". Falls back to zero line if netL2 is null.
  // Transition markers piggy-back on Framework prediction (netL3) visibility —
  // they mark zero-crossings of the all-cycles stack, which is the very
  // signal Net L3 adds. Separate toggle previously; now one control.
  // Suppress crossing triangles when the view is so wide they'd overlap into
  // a solid stripe (the 200-kyr tab has ~450 crossings across ~950 px).
  const crossingMarks = (lcrLayerVisibility.netL3 && S.crossings.length <= 120) ? S.crossings.map(c => {
    if (c.year < S.xLo || c.year > S.xHi) return '';
    const x = xPos(c.year);
    // Interpolate Net L2 at c.year for the marker's Y position.
    const idx = Math.max(0, Math.min(S.xs.length - 1, Math.round((c.year - S.xLo) / S.step)));
    const l2 = S.netL2[idx];
    const y = (l2 != null) ? yPosClipped(l2) : zeroY;
    const isPeak = c.type === 'PEAK';
    const color = isPeak ? '#ff4757' : '#4dabff';
    const tri = isPeak
      ? `<polygon points="${x-5},${y+2} ${x+5},${y+2} ${x},${y-8}" fill="${color}" opacity="0.95" data-lcr-crossing="${c.year}" data-lcr-crossing-type="${c.type}"/>`
      : `<polygon points="${x-5},${y-2} ${x+5},${y-2} ${x},${y+8}" fill="${color}" opacity="0.95" data-lcr-crossing="${c.year}" data-lcr-crossing-type="${c.type}"/>`;
    return tri;
  }).join('') : '';

  // ── Secondary Y-axis: climate proxy overlay (temperature anomaly, °C) ──
  // Renders LCR_CHART_PROXY (GISP2 Alley 2000, 27,950 BC – 1850 AD at 100-yr
  // resolution, extended by two chart-only anchor points to 2000 AD) on the
  // right-hand °C-anomaly axis.
  let proxyGroup = '';
  const enabledProxyNames = [];
  if (lcrLayerVisibility.proxy)     enabledProxyNames.push(LCR_CHART_PROXY);
  if (lcrLayerVisibility.proxyLR04) enabledProxyNames.push(LCR_CHART_PROXY_LR04);
  if (enabledProxyNames.length > 0 && lcrProxyData && lcrProxyData.sources) {
    const activeSources = lcrProxyData.sources
      .filter(src => enabledProxyNames.includes(src.name))
      .map(src => {
        // Include chart-only extension points (e.g., modern-era anchor points
        // appended for visual continuity) but not consumed by correlation.
        const combined = src.dataChartExtension
          ? [...src.data, ...src.dataChartExtension]
          : src.data;
        const filtered = combined.filter(([y, _]) => y >= S.xLo && y <= S.xHi);
        return { src, filtered };
      })
      .filter(({ filtered }) => filtered.length >= 2);

    if (activeSources.length > 0) {
      // Compute proxy Y range from all active sources (with 10% padding).
      let pMin = +Infinity, pMax = -Infinity;
      for (const { filtered } of activeSources) {
        for (const [_, t] of filtered) {
          if (t < pMin) pMin = t;
          if (t > pMax) pMax = t;
        }
      }
      const pPad = Math.max(0.15, (pMax - pMin) * 0.10);
      const proxyMin = pMin - pPad;
      const proxyMax = pMax + pPad;
      const yPosProxy = (t) => margin.top + (1 - (t - proxyMin) / (proxyMax - proxyMin)) * plotH;

      const proxyColors = {
        'GISP2 (Alley 2000)':          '#ff5978',
        'LR04 (Lisiecki & Raymo 2005)': '#4ade80',
      };
      const proxyPaths = activeSources.map(({ src, filtered }) => {
        // Smooth path via Catmull-Rom → cubic Bezier conversion. Sparse
        // series (GISP2 at 100-yr binning gives only ~10 points on the
        // historical view) look unrealistically jagged with straight L
        // segments; cubic Bezier through the same anchors preserves data
        // fidelity while producing a fluent curve.
        //   c1 = P[i]   + (P[i+1] - P[i-1]) / 6
        //   c2 = P[i+1] - (P[i+2] - P[i])   / 6
        // Endpoints degenerate to the anchor itself.
        const pts = filtered.map(([y, t]) => [xPos(y), yPosProxy(t)]);
        let d = '';
        if (pts.length === 1) {
          d = `M${pts[0][0].toFixed(1)} ${pts[0][1].toFixed(1)}`;
        } else if (pts.length === 2) {
          d = `M${pts[0][0].toFixed(1)} ${pts[0][1].toFixed(1)} L${pts[1][0].toFixed(1)} ${pts[1][1].toFixed(1)}`;
        } else {
          d = `M${pts[0][0].toFixed(1)} ${pts[0][1].toFixed(1)}`;
          for (let i = 0; i < pts.length - 1; i++) {
            const p0 = pts[Math.max(i - 1, 0)];
            const p1 = pts[i];
            const p2 = pts[i + 1];
            const p3 = pts[Math.min(i + 2, pts.length - 1)];
            const c1x = p1[0] + (p2[0] - p0[0]) / 6;
            const c1y = p1[1] + (p2[1] - p0[1]) / 6;
            const c2x = p2[0] - (p3[0] - p1[0]) / 6;
            const c2y = p2[1] - (p3[1] - p1[1]) / 6;
            d += ` C${c1x.toFixed(1)} ${c1y.toFixed(1)} ${c2x.toFixed(1)} ${c2y.toFixed(1)} ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`;
          }
        }
        const col = proxyColors[src.name] || '#ffb0d0';
        // xmlEsc: source names/references may contain '&' (e.g. "Lisiecki &
        // Raymo") which breaks strict-XML parsing of the exported SVG.
        const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        return `<path d="${d}" fill="none" stroke="${col}" stroke-width="1.6" opacity="0.75" data-lcr-proxy="${esc(src.name)}"><title>${esc(src.name)} — ${esc(src.reference)}
${esc(src.region)} • ${esc(src.unit)}</title></path>`;
      }).join('');

      // Right-hand axis ticks + label. Ticks take the color of the sole
      // active proxy; pink when both are shown (mixed-unit axis).
      const onlyLR04 = enabledProxyNames.length === 1 && enabledProxyNames[0] === LCR_CHART_PROXY_LR04;
      const axisCol = (activeSources.length === 1)
        ? (proxyColors[activeSources[0].src.name] || '#ff5978')
        : '#ff5978';
      const proxyTicks = [];
      // Choose a nice tick step.
      const proxySpan = proxyMax - proxyMin;
      let pStep = 0.5;
      if (proxySpan > 30) pStep = 5;
      else if (proxySpan > 15) pStep = 2;
      else if (proxySpan > 6)  pStep = 1;
      else if (proxySpan > 2)  pStep = 0.5;
      else                     pStep = 0.25;
      const pStart = Math.ceil(proxyMin / pStep) * pStep;
      for (let t = pStart; t <= proxyMax + 1e-9; t += pStep) {
        const y = yPosProxy(t);
        proxyTicks.push(`<line x1="${margin.left + plotW}" y1="${y}" x2="${margin.left + plotW + 5}" y2="${y}" stroke="${axisCol}" stroke-width="0.7"/>
          <text x="${margin.left + plotW + 8}" y="${y + 4}" text-anchor="start" font-size="10" fill="${axisCol}" opacity="0.85">${t > 0 ? '+' : ''}${t.toFixed(pStep < 1 ? 1 : 0)}</text>`);
      }
      const axisLabelText = activeSources.length > 1
        ? 'Temperature anomaly (GISP2 °C / LR04 −δ¹⁸O ‰)'
        : onlyLR04 ? 'Temperature proxy (−δ¹⁸O ‰, LR04)'
                   : 'Temperature anomaly (°C, GISP2)';
      const proxyAxisLabel = `<text x="${margin.left + plotW + 42}" y="${margin.top + plotH / 2}" text-anchor="middle" transform="rotate(90 ${margin.left + plotW + 42} ${margin.top + plotH / 2})" font-size="11" fill="${axisCol}" font-weight="600">${axisLabelText}</text>`;

      proxyGroup = proxyTicks.join('') + proxyPaths + proxyAxisLabel;
    }
  }

  // Axis labels
  const yLabel = `<text x="${margin.left - 55}" y="${margin.top + plotH / 2}" text-anchor="middle" transform="rotate(-90 ${margin.left - 55} ${margin.top + plotH / 2})" font-size="11" fill="#d4d4d4" font-weight="600">dLOD/dt (ms/century)</text>`;
  const xLabel = `<text x="${margin.left + plotW / 2}" y="${margin.top + plotH + 46}" text-anchor="middle" font-size="11" fill="#d4d4d4" font-weight="600">Calendar year</text>`;

  // Hover overlay — invisible rect that catches mouse; JS reads x → year.
  const hoverRect = `<rect class="lcr-hover-capture" x="${margin.left}" y="${margin.top}" width="${plotW}" height="${plotH}" fill="transparent" pointer-events="all"/>`;

  // Hover tooltip elements (positioned by JS)
  const hoverLine = `<line class="lcr-hover-line" x1="0" y1="${margin.top}" x2="0" y2="${margin.top + plotH}" stroke="#fff" stroke-width="0.8" opacity="0" pointer-events="none"/>`;
  const hoverDot  = `<circle class="lcr-hover-dot" cx="0" cy="0" r="4" fill="#ffce4b" opacity="0" pointer-events="none"/>`;
  const hoverBg   = `<rect class="lcr-hover-bg" x="0" y="0" width="180" height="70" rx="4" fill="rgba(20,22,28,.94)" stroke="rgba(255,255,255,.15)" opacity="0" pointer-events="none"/>`;
  const hoverTxt  = `<text class="lcr-hover-year" x="0" y="0" font-size="11" fill="#fff" font-weight="700" opacity="0" pointer-events="none"></text>
    <text class="lcr-hover-l2" x="0" y="0" font-size="10" fill="#4dd0c8" opacity="0" pointer-events="none"></text>
    <text class="lcr-hover-l3" x="0" y="0" font-size="10" fill="#ffce4b" opacity="0" pointer-events="none"></text>
    <text class="lcr-hover-l4" x="0" y="0" font-size="10" fill="#ff8c42" opacity="0" pointer-events="none"></text>`;

  return `<svg class="lcr-svg" viewBox="0 0 ${W} ${H}" width="100%" preserveAspectRatio="xMidYMid meet" font-family="Inter, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif">
    <rect x="${margin.left}" y="${margin.top}" width="${plotW}" height="${plotH}" fill="#0e1116" stroke="rgba(255,255,255,.08)"/>
    ${bands}
    ${yticks.join('')}
    ${xticks.join('')}
    ${zeroLine}
    ${iersLine}
    ${j2000Line}
    ${paths.join('')}
    ${crossingMarks}
    ${proxyGroup}
    ${yLabel}
    ${xLabel}
    ${hoverBg}
    ${hoverLine}
    ${hoverDot}
    ${hoverTxt}
    ${hoverRect}
  </svg>`;
}

/** Export the currently-visible Earth dLOD/dt Analysis chart as a paper-style
 *  SVG (white background, dark text) in a new tab. Reuses lcrRenderChart's
 *  output — strips hover overlays, remaps dark-theme colors to light-theme
 *  equivalents, and wraps in an outer SVG with title, subtitle, and footer.
 *  Curve/band colors are kept as-is — they read fine on white too. */
function lcrExport() {
  const range = LCR_RANGE_TABS.find(r => r.key === lcrSelectedRange) || LCR_RANGE_TABS[0];
  openChartExportModal(lcrRenderPaperSVG(range.key), `Earth dLOD/dt Analysis — ${range.label}`);
}

/** The Earth dLOD/dt Analysis paper form for one range tab (the export's picture). */
function lcrRenderPaperSVG(rangeKey) {
  const range = LCR_RANGE_TABS.find(r => r.key === rangeKey) || LCR_RANGE_TABS[0];

  // 1. Get the interactive chart SVG, then strip the outer <svg> wrapper so
  //    the inner elements can be placed inside our paper outer SVG at an
  //    offset via <g transform="translate(...)">.
  let inner = lcrRenderChart(rangeKey);
  inner = inner.replace(/^\s*<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '');

  // 2. Strip the hover overlays (invisible in-app, pollute the export).
  inner = inner.replace(/<[^>]*class="lcr-hover-[a-z]+"[^>]*(?:\/>|>[^<]*<\/[a-z]+>)/g, '');

  // 3. Recolor dark-theme surfaces + text + curves for a white background.
  //    Dark-theme pastels (bright teal, pale gold, light lavender) wash out
  //    on white — remap each to a darker/deeper equivalent that keeps its
  //    hue identity but reads with enough contrast on paper.
  const PRINT = {
    teal:     '#0f8e83',   // Tidal + GIA         (was #4dd0c8)
    gold:     '#c68a13',   // Tidal + GIA + all cycles (was #ffce4b)
    lavender: '#6d3ee0',   // Bond cycle          (was #c084fc)
    orange:   '#c75b12',   // + Core-mantle swing (L4) (was #ff8c42)
    resGreen: '#2e8b57',   // Core-mantle swing isolated (was #7bd88f)
    rust:     '#a4553d',   // Tidal baseline      (was #c46a4d — nudge darker)
    pink:     '#e63959',   // Temperature (GISP2) (was #ff5978)
    green:    '#15803d',   // Temperature (LR04)  (was #4ade80)
    peak:     '#c62838',   // PEAK triangles      (was #ff4757)
    trough:   '#1a72c9',   // TROUGH triangles    (was #4dabff)
    warmBand: '#c94040',   // warm period band + leader labels (was #e07070)
    coldBand: '#3d84e0',   // cold period band + leader labels (was #6db4ff)
  };
  const colorMap = [
    // Backgrounds / grid / text
    [/fill="#0e1116"/g,                     'fill="#ffffff"'],
    // Plot-area frame: match ESSRT — dark, thin border.
    [/stroke="rgba\(255,255,255,\.08\)"/g,  'stroke="#222"'],
    [/fill="#d4d4d4"/g,                     'fill="#222222"'],
    [/stroke="#2a2f37"/g,                   'stroke="#ececec"'],
    [/stroke="#e8e8e8"/g,                   'stroke="#999999"'],
    [/stroke="#888"/g,                      'stroke="#666666"'],
    // Curves
    [/stroke="#4dd0c8"/g,                   `stroke="${PRINT.teal}"`],
    [/stroke="#ffce4b"/g,                   `stroke="${PRINT.gold}"`],
    [/stroke="#c084fc"/g,                   `stroke="${PRINT.lavender}"`],
    [/stroke="#ff8c42"/g,                   `stroke="${PRINT.orange}"`],
    [/stroke="#7bd88f"/g,                   `stroke="${PRINT.resGreen}"`],
    [/stroke="#c46a4d"/g,                   `stroke="${PRINT.rust}"`],
    [/stroke="#ff5978"/g,                   `stroke="${PRINT.pink}"`],
    [/fill="#ff5978"/g,                     `fill="${PRINT.pink}"`],
    [/stroke="#4ade80"/g,                   `stroke="${PRINT.green}"`],
    [/fill="#4ade80"/g,                     `fill="${PRINT.green}"`],
    // Peak / trough triangles
    [/fill="#ff4757"/g,                     `fill="${PRINT.peak}"`],
    [/fill="#4dabff"/g,                     `fill="${PRINT.trough}"`],
    // Band shading + narrow-band leader labels
    [/fill="#e07070"/g,                     `fill="${PRINT.warmBand}"`],
    [/fill="#6db4ff"/g,                     `fill="${PRINT.coldBand}"`],
    [/stroke="#e07070"/g,                   `stroke="${PRINT.warmBand}"`],
    [/stroke="#6db4ff"/g,                   `stroke="${PRINT.coldBand}"`],
    // Boost band-rect opacity from 0.10 → 0.16 so shading reads on white.
    [/(<rect[^>]*data-lcr-band[^>]*)opacity="0\.10"/g, '$1opacity="0.16"'],
  ];
  for (const [pat, repl] of colorMap) inner = inner.replace(pat, repl);

  // Bump the three axis labels (Y "dLOD/dt", X "Calendar year", right-hand
  // "Temperature anomaly") from screen-scale 11 pt to paper-scale 13 pt so
  // they read at print size (matches ESSRT). Targeted by their text content
  // so the many other 11 pt labels (bands, ticks) stay put.
  inner = inner.replace(/(<text[^>]+)font-size="11"([^>]*>dLOD\/dt)/,        '$1font-size="13"$2');
  inner = inner.replace(/(<text[^>]+)font-size="11"([^>]*>Calendar year)/,   '$1font-size="13"$2');
  inner = inner.replace(/(<text[^>]+)font-size="11"([^>]*>Temperature anom)/,'$1font-size="13"$2');

  // 4. Compose the standard export page: title + legend rows (one entry per
  //    visible layer, swatches in the PRINT palette so they match the
  //    recolored curves), the 1100×420 chart, the credit. The Bond
  //    correlation sentence and the fit provenance read in the panel.
  const chartW = 1100, chartH = 420;
  const chartX = 50;
  const outerW  = chartW + 100;
  const legendEntries = [];
  if (lcrLayerVisibility.tidal)     legendEntries.push({ name: 'Tidal (L1)', color: PRINT.rust, dash: '4,3' });
  if (lcrLayerVisibility.netL2)     legendEntries.push({ name: '+ GIA (L2)', color: PRINT.teal, bold: true });
  if (lcrLayerVisibility.netL3)     legendEntries.push({ name: '+ Cycles (L3)', color: PRINT.gold, dash: '6,3' });
  if (lcrLayerVisibility.netL4)     legendEntries.push({ name: '+ Core-mantle (L4)', color: PRINT.orange, bold: true });
  if (lcrLayerVisibility.bands)     legendEntries.push({ name: 'Warm periods', color: PRINT.warmBand, marker: 'rect' }, { name: 'Cold periods', color: PRINT.coldBand, marker: 'rect' });
  if (lcrLayerVisibility.bondCurve) legendEntries.push({ name: 'Bond cycle', color: PRINT.lavender, dash: '5,3' });
  if (lcrLayerVisibility.resonator) legendEntries.push({ name: 'Core-mantle swing (isolated)', color: PRINT.resGreen });
  if (lcrLayerVisibility.proxy)     legendEntries.push({ name: 'Temp. (GISP2)', color: PRINT.pink });
  if (lcrLayerVisibility.proxyLR04) legendEntries.push({ name: 'Temp. (LR04, −δ¹⁸O)', color: PRINT.green });
  const head = chartExportHeader(`Earth dLOD/dt Analysis — ${range.label}`, legendEntries, outerW);
  const chartY  = head.bottom + 8;
  const outerH  = chartY + chartH + CHART_EXPORT_CREDIT_H;

  const paperSvg = `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${outerW} ${outerH}" width="${outerW}" height="${outerH}" font-family="Inter, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif">
  <rect width="${outerW}" height="${outerH}" fill="#ffffff"/>
  ${head.svg}
  <g transform="translate(${chartX}, ${chartY})">
    ${inner}
  </g>
  ${chartExportCredit(outerW, outerH)}
</svg>`;
  return paperSvg;
}

async function createLcrPanel() {
  const panel = document.createElement('div');
  panel.id = 'lodClimateRhythmPanel';
  panel.className = 'cfm-modal';   // reuse cfm chrome styles
  // J2000 net rates for the layer tooltips — read live from the engine, never hard-coded.
  const _lcrD0 = dLodDtDecompositionAtAge(0);
  const _lcrRate = (v) => (Number.isFinite(v) ? `${v >= 0 ? '+' : '−'}${Math.abs(v).toFixed(2)}` : '—');

  const tabs = LCR_RANGE_TABS.map(t =>
    `<button class="cfm-tab${t.key === lcrSelectedRange ? ' cfm-tab-active' : ''}" data-lcr-tab="${t.key}">${t.label}</button>`
  ).join('');

  const layerToggles = `
    <div class="cfm-layer-toggles">
      <label class="cfm-layer-check" title="Pure tidal channel = Moon-recession torque only, no GIA compensation, no cycles. At J2000: +2.12 ms/cy. Essentially flat across the Holocene. Provides a physical reference height above which GIA subtracts and the ΔT cycles oscillate."><input type="checkbox" data-lcr-layer="tidal" ${lcrLayerVisibility.tidal ? 'checked' : ''}/><span class="lcr-swatch lcr-swatch-tidal"></span>Tidal (L1)</label>
      <label class="cfm-layer-check" title="Tidal + GIA secular rate = Layer 2 net rate = Moon recession plus the Milankovitch mass response. The GIA term is TWO-SIGNED, not a one-way drag: negative (spin-up) while the mantle rebounds poleward after a deglaciation, positive while ice sheets grow and mantle is displaced equatorward. So this curve dips below the tidal line through a deglaciation and rides above it during ice growth (visible on the 200,000 BC and 27,500 BC tabs; GIA = +0.08 ms/cy at 25,000 BC). At J2000: GIA −0.35, net +1.77 ms/cy, matches IERS +1.75."><input type="checkbox" data-lcr-layer="netL2" ${lcrLayerVisibility.netL2 ? 'checked' : ''}/><span class="lcr-swatch lcr-swatch-netL2"></span>+ GIA (L2)</label>
      <label class="cfm-layer-check" title="Layer 3 net rate = Tidal + GIA + the 4 harmonic cycles (Bond + Hallstatt + Jose5 + Jose4), flags only — cyclic modulation WITHOUT the Core-mantle swing. At J2000: ${_lcrRate(_lcrD0.net_L3)} ms/cy."><input type="checkbox" data-lcr-layer="netL3" ${lcrLayerVisibility.netL3 ? 'checked' : ''}/><span class="lcr-swatch lcr-swatch-netL3"></span>+ Cycles (L3)</label>
      <label class="cfm-layer-check" title="The SHIPPED observable (joint world) = Layer 4 = Tidal + GIA + 4-flag cycles + Core-mantle swing (Resonator driver, fitted jointly). At J2000: ${_lcrRate(_lcrD0.net_L4)} ms/cy; the Layer-4 solar day closes the USNO anchor 86400.0021 by construction."><input type="checkbox" data-lcr-layer="netL4" ${lcrLayerVisibility.netL4 ? 'checked' : ''}/><span class="lcr-swatch lcr-swatch-netL4"></span>+ Core-mantle (L4)</label>
      <label class="cfm-layer-check" title="Named climate period bands from mainstream literature. Cold = blue; Warm = red."><input type="checkbox" data-lcr-layer="bands" ${lcrLayerVisibility.bands ? 'checked' : ''}/><span class="lcr-swatch lcr-swatch-bands"></span>Periods</label>
      <label class="cfm-layer-check" title="Bond harmonic (1466 yr; the stack’s n = 1830 line) ISOLATED from the 4-cycle stack. A clean 1466-yr sinusoid. TESTED: its phase does NOT align with Bond's own IRD record — band-limited projection puts the two ~175° apart, essentially anti-phase, and allowing a drifting phase does not recover alignment (PLV p = 0.49). The harmonic earns its place as a ΔT correction, not as a reproduction of the Bond climate cycle. Full-stack prediction has additional Hallstatt / Jose5 / Jose4 crossings on top of this."><input type="checkbox" data-lcr-layer="bondCurve" ${lcrLayerVisibility.bondCurve ? 'checked' : ''}/><span class="lcr-swatch lcr-swatch-bondcurve"></span>Bond</label>
      <label class="cfm-layer-check" title="Core-mantle swing episode ISOLATED (Resonator driver — the 4th dLOD/dt channel): impulse-consistent damped oscillation of the core eigenmode (T₀ ≈ 3,916 yr, Q = 1.8), excitation −1600, termination +1600, zero before and after. Rendered on the Net L2 baseline like the Bond curve. See docs/104."><input type="checkbox" data-lcr-layer="resonator" ${lcrLayerVisibility.resonator ? 'checked' : ''}/><span class="lcr-swatch lcr-swatch-resonator"></span>Core</label>
      <label class="cfm-layer-check" title="GISP2 Alley 2000 Greenland ice-core temperature reconstruction on the secondary right-hand °C-anomaly axis. Independent paleoclimate reconstruction — not part of the framework fit. Covers 27,950 BC to 1850 AD at 100-yr resolution, with two anchor points appended at 1950 and 2000 AD for visual continuity to the modern era."><input type="checkbox" data-lcr-layer="proxy" ${lcrLayerVisibility.proxy ? 'checked' : ''}/><span class="lcr-swatch lcr-swatch-proxy"></span>GISP2</label>
      <label class="cfm-layer-check" title="LR04 global benthic δ¹⁸O stack (Lisiecki & Raymo 2005, 57 sites) shown as inverted anomaly vs core-top on the secondary axis — positive = warm, same sign convention as the Bond IRD panel. Independent paleoclimate reconstruction — not part of the framework fit; the same dataset the Earth Climate Analysis fits against. 1-kyr resolution; covers the full 200,000 BC tab where GISP2 ends (~27,950 BC)."><input type="checkbox" data-lcr-layer="proxyLR04" ${lcrLayerVisibility.proxyLR04 ? 'checked' : ''}/><span class="lcr-swatch lcr-swatch-proxylr04"></span>LR04</label>
    </div>
  `;

  // Legend quotes the same validated-window correlation the panel below computes,
  // read live rather than hardcoded so the two can never silently diverge.
  const _lcrLegendC = lcrComputeCorrelations(-4000, 1800);
  const lcrLegendR = (_lcrLegendC && _lcrLegendC.r_stack != null)
    ? (_lcrLegendC.r_stack >= 0 ? '+' : '') + _lcrLegendC.r_stack.toFixed(2)
    : '—';

  panel.innerHTML = `
    <div class="cfm-overlay"></div>
    <div class="cfm-container">
      <div class="cfm-header">
        <div class="cfm-title">Earth dLOD/dt Analysis</div>
        <div class="cfm-subtitle">The day-length rate decomposed into its drivers, vs named climate periods and the GISP2 / LR04 temperature proxies</div>
        <button class="cfm-export-btn" data-lcr-export title="Export the current chart with the layers toggled on screen as a picture (PNG or SVG download)">Export</button>
        <div class="cfm-close" title="Close"></div>
      </div>
      <div class="cfm-body">
        <div class="cfm-tabs">${tabs}</div>
        <div class="cfm-controls">${layerToggles}</div>
        <div class="cfm-content lcr-content">
          ${lcrRenderChart(lcrSelectedRange)}
        </div>
        <div class="lcr-legend-panel">
          <div class="lcr-legend-note">
            <b>How to read</b> — each line adds one mechanism; hover a toggle for detail.
            <b>Tidal (L1)</b> +2.12 ms/cy, flat · <b>+ GIA (L2)</b> two-signed, −0.35 at J2000 ·
            <b>+ Cycles (L3)</b> the 4 flags · <b>+ Core-mantle (L4)</b> the shipped observable.
            <b>Bond</b>/<b>Core</b> isolate single components; full stack ↔ Bond IRD <b>r = ${lcrLegendR}</b>.
            <br/><b>Don't swap these two readings.</b> <b>GIA</b> — teal below rust = mantle still
            rebounding from past ice loss, which outlasts the melting, so only its <i>deepest</i> excursion
            marks peak melt. <b>Cycles</b> — the orange-minus-teal gap accumulates into Σ_stack
            (&gt; 0 = longer day); surface mass and solid Earth move rotation <i>opposite</i> ways, and
            Σ_stack's sign is <b>not</b> a validated warm/cold rule.
          </div>
        </div>
        <details class="lcr-match-panel lcr-details">
          <summary class="lcr-details-summary">Framework ↔ Bond 2001 IRD correlation (detrended)</summary>
          <div class="lcr-details-body">${lcrRenderCorrelationPanel(true)}</div>
        </details>
        <details class="lcr-match-panel lcr-details">
          <summary class="lcr-details-summary">Sign convention check — Σ_stack at named events</summary>
          <div class="lcr-details-body">${lcrRenderSignCheckPanel(true)}</div>
        </details>
        <details class="lcr-match-panel lcr-details">
          <summary class="lcr-details-summary">Bond event ↔ nearest framework ▼ TROUGH crossing</summary>
          <div class="lcr-details-body">${lcrRenderBondMatchTable(true)}</div>
        </details>
      </div>
    </div>
  `;

  const contentEl = panel.querySelector('.cfm-content');

  function rerender() {
    contentEl.innerHTML = lcrRenderChart(lcrSelectedRange);
    bindLcrHover();
  }

  panel.querySelector('.cfm-close').addEventListener('click', closeLcrPanel);
  panel.querySelector('.cfm-overlay').addEventListener('click', closeLcrPanel);

  panel.querySelectorAll('[data-lcr-tab]').forEach(tab => {
    tab.addEventListener('click', () => {
      lcrSelectedRange = tab.dataset.lcrTab;
      panel.querySelectorAll('[data-lcr-tab]').forEach(t =>
        t.classList.toggle('cfm-tab-active', t.dataset.lcrTab === lcrSelectedRange));
      rerender();
    });
  });

  panel.querySelectorAll('[data-lcr-layer]').forEach(cb => {
    cb.addEventListener('change', () => {
      lcrLayerVisibility[cb.dataset.lcrLayer] = cb.checked;
      rerender();
    });
  });

  const exportBtn = panel.querySelector('[data-lcr-export]');
  if (exportBtn) exportBtn.addEventListener('click', lcrExport);

  // Hover tooltip binding — delegates to the .lcr-hover-capture rect.
  function bindLcrHover() {
    const svg = contentEl.querySelector('svg.lcr-svg');
    if (!svg) return;
    const capture = svg.querySelector('.lcr-hover-capture');
    if (!capture) return;
    const S = lcrComputeSeries(lcrSelectedRange);
    const W = 1100;
    // Must match margins used in lcrRenderChart above — otherwise plotW is
    // wrong and the hover-year lookup drifts (~60 yr shift observed when
    // right went 30 → 78 for the secondary axis but this constant lagged).
    const margin = { top: 50, right: 78, bottom: 70, left: 78 };
    const plotW = W - margin.left - margin.right;
    const plotH = 420 - margin.top - 70;
    const xLo = S.xLo, xHi = S.xHi;
    // Re-derive the auto Y range the same way lcrRenderChart does so the
    // hover dot's Y coordinate matches the visible curve pixel-for-pixel.
    let dataMin = +Infinity, dataMax = -Infinity;
    const scanH = (arr) => { for (const v of arr) if (v != null) { if (v < dataMin) dataMin = v; if (v > dataMax) dataMax = v; } };
    if (lcrLayerVisibility.tidal) scanH(S.tidal);
    if (lcrLayerVisibility.netL2) scanH(S.netL2);
    if (lcrLayerVisibility.netL3) scanH(S.netL3);
    if (lcrLayerVisibility.netL4) scanH(S.netL4);
    if (dataMin > 0)    dataMin = 0;
    if (dataMax < 1.75) dataMax = 1.75;
    if (!Number.isFinite(dataMin) || !Number.isFinite(dataMax)) { dataMin = -0.5; dataMax = 3.5; }
    const padH = Math.max(0.2, (dataMax - dataMin) * 0.08);
    const yMin = Math.floor((dataMin - padH) * 2) / 2;
    const yMax = Math.ceil((dataMax + padH) * 2) / 2;

    const hoverLine  = svg.querySelector('.lcr-hover-line');
    const hoverDot   = svg.querySelector('.lcr-hover-dot');
    const hoverBg    = svg.querySelector('.lcr-hover-bg');
    const yearTxt    = svg.querySelector('.lcr-hover-year');
    const l2Txt      = svg.querySelector('.lcr-hover-l2');
    const l3Txt      = svg.querySelector('.lcr-hover-l3');
    const l4Txt      = svg.querySelector('.lcr-hover-l4');

    function showTooltip(event) {
      const rect = svg.getBoundingClientRect();
      const svgWidth  = rect.width;
      const scaleX = W / svgWidth;
      const mouseX = (event.clientX - rect.left) * scaleX;

      // Convert mouseX → year → nearest sample index.
      const year = xLo + ((mouseX - margin.left) / plotW) * (xHi - xLo);
      const idx = Math.round((year - xLo) / S.step);
      if (idx < 0 || idx >= S.xs.length) return;

      const l2 = S.netL2[idx];
      const l3 = S.netL3[idx];
      const l4 = S.netL4[idx];
      const y  = S.xs[idx];

      const xPos = margin.left + ((y - xLo) / (xHi - xLo)) * plotW;
      const yPos = margin.top + (1 - ((l4 != null ? l4 : l3) - yMin) / (yMax - yMin)) * plotH;

      hoverLine.setAttribute('x1', xPos);
      hoverLine.setAttribute('x2', xPos);
      hoverLine.setAttribute('opacity', '0.6');
      hoverDot.setAttribute('cx', xPos);
      hoverDot.setAttribute('cy', yPos);
      hoverDot.setAttribute('opacity', '1');

      const label = y === 2000 ? 'J2000' : y === 0 ? '1 BC' : y < 0 ? `${-y} BC` : `${y} AD`;
      yearTxt.textContent = label;
      l2Txt.textContent    = `Baseline:    ${l2.toFixed(3)} ms/cy`;
      l3Txt.textContent    = `+ cycles:    ${l3.toFixed(3)} ms/cy`;
      l4Txt.textContent    = `Full (L4):   ${l4 != null ? l4.toFixed(3) : '—'} ms/cy`;

      const tipW = 178, tipH = 70;
      let tipX = xPos + 12;
      if (tipX + tipW > margin.left + plotW) tipX = xPos - 12 - tipW;
      const tipY = Math.max(margin.top + 6, Math.min(yPos - tipH/2, margin.top + plotW - tipH));
      hoverBg.setAttribute('x', tipX);
      hoverBg.setAttribute('y', tipY);
      hoverBg.setAttribute('width', tipW);
      hoverBg.setAttribute('height', tipH);
      hoverBg.setAttribute('opacity', '1');
      yearTxt.setAttribute('x', tipX + 10); yearTxt.setAttribute('y', tipY + 16); yearTxt.setAttribute('opacity', '1');
      l2Txt.setAttribute('x', tipX + 10);   l2Txt.setAttribute('y', tipY + 32);   l2Txt.setAttribute('opacity', '1');
      l3Txt.setAttribute('x', tipX + 10);   l3Txt.setAttribute('y', tipY + 46);   l3Txt.setAttribute('opacity', '1');
      l4Txt.setAttribute('x', tipX + 10);   l4Txt.setAttribute('y', tipY + 60);   l4Txt.setAttribute('opacity', '1');
    }
    function hideTooltip() {
      hoverLine.setAttribute('opacity', '0');
      hoverDot.setAttribute('opacity', '0');
      hoverBg.setAttribute('opacity', '0');
      yearTxt.setAttribute('opacity', '0');
      l2Txt.setAttribute('opacity', '0');
      l3Txt.setAttribute('opacity', '0');
      l4Txt.setAttribute('opacity', '0');
    }
    capture.addEventListener('mousemove', showTooltip);
    capture.addEventListener('mouseleave', hideTooltip);
  }
  bindLcrHover();

  document.body.appendChild(panel);
  requestAnimationFrame(() => panel.classList.add('visible'));
  return panel;
}

function openLcrPanel() {
  return _openPanelOnce('lcr', async () => {
    if (lcrPanel) { lcrPanel.remove(); lcrPanel = null; }
    // Wipe series cache — range specs (LCR_RANGE_TABS) can change between
    // sessions during development, and cached samples over stale windows
    // would render at the wrong X-scale.
    for (const k of Object.keys(_lcrSeriesCache)) delete _lcrSeriesCache[k];
    await lcrLoadProxyData();
    lcrPanel = await createLcrPanel();
  });
}

function closeLcrPanel() {
  if (lcrPanel) lcrPanel.classList.remove('visible');
}

// ═══════════════════════════════════════════════════════════════════
// FORMULA VERIFICATION PANEL (.vfp-)
// Compare model predictions vs published scientific formulas
// ═══════════════════════════════════════════════════════════════════

/** Convert calendar year to approximate JD (standard polynomial convention) */
function yearToJDApprox(year) { return j2000JD + (year - 2000) * DAYS_PER_JULIAN_YEAR; }

// ── Reference formula implementations ────────────────────────────

// The three Earth polynomials the Framework Verification plots (Meeus eq.
// 25.4 eccentricity, the IAU 2006 obliquity polynomial, Meeus Table 31.A's
// perihelion) live in @essrt/reference published-curves with their
// provenance — bound here to this browser's calendar→JD conversion, like the
// Laskar/Peters/Chapront/Capitaine polynomials below.
function eccMeeus(year) { return _pubCurves().eccMeeus(year); }
function obliquityChapront2002(year) { return _pubCurves().obliquityChapront2002(year); }
function perihelionMeeusEarth(year) { return _pubCurves().perihelionMeeusEarth(year); }
/** The anomalistic year of date (SI days), derived as the Tropical panel
 *  derives Vondrák: Chapront's sidereal year with the Table 31.B sidereal
 *  perihelion rate — T_anom = 360 / (360/T_sid − ϖ̇), ϖ̇ per day. */
function anomalisticYearMeeusDerived(year) {
  const tSid = siderealYearChapront(year);
  const wPerDay = perihelionRateMeeusJ2000FrameDegPerCy(year) / julianCenturyDays;
  return 360 / (360 / tSid - wPerDay);
}

// 8.6-1: the published reference curves live in @essrt/physics/reference/
// published-curves — exactly as published, per-curve provenance in the
// module header. This browser injects its approximate calendar→JD
// conversion for the T-based analytic polynomials (the four year/day/precession
// polynomials below and the six Earth polynomials above).
var _pubCurvesM = null;
function _pubCurves() {
  if (!_pubCurvesM) {
    _pubCurvesM = _PC.createPublishedCurves({
      yearToJDApprox: (y) => yearToJDApprox(y),
      j2000JD: j2000JD,
      julianCenturyDays: julianCenturyDays,
    });
  }
  return _pubCurvesM;
}

function tropicalYearLaskar(year) { return _pubCurves().tropicalYearLaskar(year); }

function solarDayPeters(year) { return _pubCurves().solarDayPeters(year); }

/** Espenak & Meeus (NASA Five Millennium Canon) piecewise ΔT polynomial.
 *  Standard form covers ~[-1999, 3000]; returns the raw TT − UT1 offset in
 *  seconds. Anchored at the RAW convention: ΔT(2000) ≈ 62.92 s. To compare
 *  with our model's ΔT-relative-to-J2000 convention (ΔT(2000) = 0), use
 *  deltaTEspenakMeeusRelJ2000 instead. */
function deltaTEspenakMeeusRaw(year) {
  // EXACTLY the published NASA canon, from
  // @essrt/physics/deltat/historical. The previously shipped simplification
  // (1986–2005 merged into the 62.92-branch, NaN outside −1999..3000)
  // differed by ≤4.6 s in 1986–2005 and 52 s at 2100, and its chart was
  // labeled "NASA Canon" while not plotting it. The display anchor
  // (deltaTEspenakJ2000Seconds) moved 62.92 → 63.86 with it — matched pair.
  return deltaTEspenakMeeusCanonSeconds(year);
}

/** Meeus (1998) eq. 22.2 first-order mean obliquity, in RADIANS.
 *  T is Julian centuries TT from J2000. DELIBERATELY the IAU 1976/1980
 *  convention (23.4392911° = 84381.448″/3600 truncated, rate −46.8150″/cy)
 *  because the Meeus-comparison reports that call it are checked against
 *  Meeus's own worked values — NOT the same quantity as
 *  ASTRO_REFERENCE.obliquityJ2000 (IAU 2006, 84381.406″). Five verbatim
 *  copies of this line existed before 8.1b; this is the one. */
function meeusMeanObliquityRad(T) {
  return _PC.meeusMeanObliquityRad(T);
}

// ΔT(J2000) in the Espenak/Meeus convention — the value we subtract to
// re-anchor the reference curve to our model's ΔT(J2000) = 0 convention.
// Computed from the polynomial at t=0, kept as a literal so a stale poly
// coefficient bump doesn't silently drift the anchor. 8.4-4c: 63.86 — the
// CANON 1986–2005 segment's value at 2000 (was 62.92, the shipped
// simplification's value); curve and anchor moved together.
const DELTA_T_ESPENAK_J2000_S = R.externalCurveAnchors.deltaTEspenakJ2000Seconds;

/** Espenak/Meeus ΔT re-anchored to ΔT(J2000) = 0 so it plots on the same
 *  axis as our model. */
function deltaTEspenakMeeus(year) {
  const dT = deltaTEspenakMeeusRaw(year);
  return Number.isFinite(dT) ? dT - DELTA_T_ESPENAK_J2000_S : NaN;
}

function siderealYearChapront(year) { return _pubCurves().siderealYearChapront(year); }

function axialPrecessionCapitaine2009(year) { return _pubCurves().axialPrecessionCapitaine2009(year); }

// ── Berger (1978) trigonometric series ────────────────────────────
// 8.6-1: series + evaluators live in @essrt/reference/published-curves.

function eccBerger1978(year) { return _PC.eccBerger1978(year); }

function obliquityBerger1978(year) { return _PC.obliquityBerger1978(year); }

// ── Vondrák et al. (2011) long-term precession ──────────────────
// 8.6-1: table + evaluator live in @essrt/reference/published-curves.

function axialPrecessionVondrak2011(year) { return _PC.axialPrecessionVondrak2011(year); }

// ── Laskar La2004 N-body solution (IMCCE) ────────────────────────
// 8.6-1: the 351-row published table + interpolants live in
// @essrt/reference/published-curves.

function eccLa2004(year) { return _PC.eccLa2004(year); }
function obliquityLa2004(year) { return _PC.obliquityLa2004(year); }
function perihelionLa2004(year) { return _PC.perihelionLa2004(year); }

// ── Laskar La2010a orbital elements (invariable plane) ───────────
// Source: Laskar et al. (2011), A&A 532, A89
// ONE home: public/input/la2010-orbital-elements.json (501 rows, 1-kyr,
// −500,000 → 0 years from J2000, invariable plane), fetched once at start
// into _la2010ElementsData — the same table the planet-inclination chart
// reads. A hand-thinned 2-kyr copy (251 rows) sat here as an inline literal
// until plan 18; the 2-kyr linear interpolation differed from the 1-kyr
// table by up to 0.32 % of a chart's range (1.15° in ϖ near −375 kyr).

const _LA2010_COLUMNS = [null, 'eccentricity', 'inclination', 'perihelionLong', 'ascendingNode'];
/** Interpolate the La2010 table. col: 1=ecc, 2=inclination, 3=periLong, 4=ascNode.
 *  NaN until the JSON has landed (the Framework Verification panel redraws on arrival). */
function _la2010Interp(yearFromJ2000, col) {
  const rows = _la2010ElementsData && _la2010ElementsData.data;
  if (!rows) return NaN;
  const n = rows.length, y0 = rows[0].year, step = rows[1].year - y0, key = _LA2010_COLUMNS[col];
  if (yearFromJ2000 < y0 || yearFromJ2000 > rows[n - 1].year) return NaN;
  const idx = (yearFromJ2000 - y0) / step;
  const i = Math.floor(idx);
  if (i >= n - 1) return rows[n - 1][key];
  const frac = idx - i;
  let a = rows[i][key], b = rows[i + 1][key];
  // Handle 360° wrapping for angular columns (ascending node, perihelion longitude)
  if (col >= 3 && Math.abs(b - a) > 180) {
    if (b > a) a += 360; else b += 360;
    return ((a * (1 - frac) + b * frac) % 360 + 360) % 360;
  }
  return a * (1 - frac) + b * frac;
}

function inclinationLa2010(year) { return _la2010Interp(year - 2000, 2); }
function ascNodeLa2010(year) { return _la2010Interp(year - 2000, 4); }

