  const tip = bodyEl.querySelector('div[data-vfpma-tip]');
  const cursor = svg ? svg.querySelector('line[data-vfpma-cursor]') : null;
  const G = _vfpMAState._screenGeom;
  if (!svg || !tip || !cursor || !G) return;
