    const r = svg.getBoundingClientRect();
    if (!r.width) return;
    const px = ((e.clientX - r.left) / r.width) * G.W;
    if (px < G.PAD.l || px > G.W - G.PAD.r) { hide(); return; }
    const pw = G.W - G.PAD.l - G.PAD.r;
    const i = Math.round(((px - G.PAD.l) / pw) * (S.yrs.length - 1));
    const y = S.yrs[i];
