    tip.style.display = 'block';
    const wr = svg.parentElement.getBoundingClientRect();
    let tx = e.clientX - wr.left + 14;
    if (tx + tip.offsetWidth > wr.width - 4) tx = e.clientX - wr.left - tip.offsetWidth - 14;
    let ty = e.clientY - wr.top + 12;
