/**
 * Copy report text to clipboard
 * Strips HTML tags (like color spans) from the text before copying
 */
function copyReportToClipboard(reportText) {
  // Remove HTML tags (e.g., <span style="color:...">...</span>) for plain text copy
  const plainText = reportText.replace(/<[^>]*>/g, '');
  navigator.clipboard.writeText(plainText)
    .then(() => {
      // Show brief feedback
      const copyBtn = document.querySelector('.hi-report-btn.copy');
      if (copyBtn) {
        const originalText = copyBtn.textContent;
        copyBtn.textContent = 'Copied!';
        setTimeout(() => { copyBtn.textContent = originalText; }, 1500);
      }
    })
    .catch(err => {
      console.error('Failed to copy report:', err);
    });
}

// Store current report data for button handlers
let _currentReportData = null;

/**
 * Generate and display the planet position report in the inspector panel
 */
async function generateAndDisplayReport(planetKey) {
  const panel = hierarchyInspector.panel;
  if (!panel) return;

  const reportElement = panel.querySelector('.hi-report');
  const loadingElement = panel.querySelector('.hi-report-loading');
  const buttonsElement = panel.querySelector('.hi-report-buttons');

  if (!reportElement || !loadingElement) return;

  // Show loading state
  loadingElement.style.display = 'block';
  reportElement.style.display = 'none';
  buttonsElement.style.display = 'none';

  try {
    // Get current showAll state from checkbox
    const showAllCheckbox = panel.querySelector('.hi-report-show-all');
    const showAll = showAllCheckbox ? showAllCheckbox.checked : false;

    // Generate the report
    const result = await generatePlanetReport(planetKey, showAll);

    // Store for button handlers
    _currentReportData = {
      planetKey,
      screenReport: result.screenReport,
      excelData: result.excelData
    };

    // Display the report (use innerHTML to render color-coded spans)
    reportElement.innerHTML = result.screenReport;
    loadingElement.style.display = 'none';
    reportElement.style.display = 'block';
    buttonsElement.style.display = 'flex';
  } catch (err) {
    console.error('Error generating report:', err);
    reportElement.textContent = `Error generating report: ${err.message}`;
    loadingElement.style.display = 'none';
    reportElement.style.display = 'block';
    buttonsElement.style.display = 'none';
  }
}

// ---------------------------------------------------------------------------
//  HELPER — "excess seconds per (mean) day" at the *current* JD
//  Positive  => Earth day is longer than 86 400 s  ➜ ΔT increases
//  Negative  => Earth day is shorter            ➜ ΔT decreases
// ---------------------------------------------------------------------------
function secondsExcessPerDay () {
  // Matches the tweakpane's Layer 4 Solar Day = REAL by construction — both
  // delegate to computeLodRealSecondsAtEpoch (kinematic + the ecliptic term + ΔT cycle sum
  // incl. Core-mantle swing, which is what makes this Layer 4, not 3;
  // USNO-tuned at J2000 by the DT-corrections fit). The cycle sum MUST stay
  // in the composite: omitting it desyncs the Rate cell from the display.
  return computeLodRealSecondsAtEpoch(o.currentYear) - SECONDS_PER_DAY;
}

// ---------------------------------------------------------------------------
//  CALL THIS ONCE *EACH* SIMULATION STEP *AFTER* YOU ADVANCE YOUR CLOCK
//  (`currentJD` must be the new Julian Day number for the model)
// ---------------------------------------------------------------------------
function updateDeltaT() {
  const currentJD = o.julianDay;                       // use your existing value
  const daysElapsed = currentJD - state.prevJD;
  // Layer 4 LOD — same value as tweakpane Solar Day = REAL, via the shared
  // computeLodRealSecondsAtEpoch composite.
  const excess = computeLodRealSecondsAtEpoch(o.currentYear) - SECONDS_PER_DAY;

  if (isNaN(excess) || isNaN(daysElapsed)) {
    console.warn("Bad input to updateDeltaT", { excess, daysElapsed });
    return;
  }

  state.deltaT += excess * daysElapsed;
  state.prevJD = currentJD;
}

function resetDeltaTForJump() {
  /* ------------------------------------------------------------------ */
  const BASE_YEAR          = startmodelYear;
  const SUBSTEPS_PER_YEAR  = 10; 
  /* ------------------------------------------------------------------ */

  const targetYear = o.currentYear;
  const startYear  = Math.min(BASE_YEAR, targetYear);
  const endYear    = Math.max(BASE_YEAR, targetYear);

  let deltaTsum = 0;           // total change to apply to deltaTStart

  /* ── integrate whole years, sampling “one-year-before” each slice ── */
  for (let y = startYear; y < endYear; y++) {
    for (let i = 0; i < SUBSTEPS_PER_YEAR; i++) {

      /* sample ***one year earlier*** than the slice we are adding   */
      const subYear    = y + i / SUBSTEPS_PER_YEAR;
      const sourceYear = subYear - 1;

      const lod = _lodKinematicSecondsOfDate(sourceYear);   // the Layer-0 tidal mean

      const solarYear = computeSolarYearDaysFromCardinals(sourceYear);

      // Raw kinematic LOD + the ecliptic-precession "missing motion" term
      // (~3.4 ms at J2000; ONE home — h5Correction rides the nodal period
      // 1,296,000/|s₃|). This is the raw-physics integrand for the ΔT accumulator;
      // it is NOT the Layer 4 physical LOD_real (which further adds the calibrated
      // 4-flag stack + Core-mantle swing to close the USNO anchor — 86400.0021 s in the fit's measured-day basis, joint world).
      const lodH5Raw = lod + h5Correction(sourceYear);
      const dTchangePerYr = (lodH5Raw - 86_400) * solarYear;   // seconds/yr
      deltaTsum += dTchangePerYr / SUBSTEPS_PER_YEAR;         // fraction
    }
  }

  /* ── fractional part of the final calendar year (if any) ─────────── */
  const frac = targetYear - Math.floor(targetYear);           // 0 … <1
  if (frac !== 0) {
    const y = Math.floor(targetYear);
    const slices = Math.round(SUBSTEPS_PER_YEAR * frac);

    for (let i = 0; i < slices; i++) {
      const subYear    = y + i / SUBSTEPS_PER_YEAR;
      const sourceYear = subYear - 1;

      const lod = _lodKinematicSecondsOfDate(sourceYear);   // plan 09: the Layer-0 tidal mean

      const solarYear = computeSolarYearDaysFromCardinals(sourceYear);

      // Raw kinematic LOD + the ecliptic-precession "missing motion" term
      // (~3.4 ms at J2000; ONE home — h5Correction rides the nodal period
      // 1,296,000/|s₃|). This is the raw-physics integrand for the ΔT accumulator;
      // it is NOT the Layer 4 physical LOD_real (which further adds the calibrated
      // 4-flag stack + Core-mantle swing to close the USNO anchor — 86400.0021 s in the fit's measured-day basis, joint world).
      const lodH5Raw = lod + h5Correction(sourceYear);
      const dTchangePerYr = (lodH5Raw - 86_400) * solarYear;
      deltaTsum += dTchangePerYr / SUBSTEPS_PER_YEAR;
    }
  }

  /* ── final ΔT: add for future, subtract for past ─────────────────── */
  const deltaT = (targetYear >= BASE_YEAR)
    ? deltaTStart + deltaTsum   // stepping FORWARD  → grows
    : deltaTStart - deltaTsum;  // stepping BACKWARD → shrinks

  state.deltaT = deltaT;
  state.prevJD = o.julianDay;     // avoid monster step on next frame
}

// ---------------------------------------------------------------------------
//  CONVENIENCE GETTERS — call whenever you need to *display* the values
// ---------------------------------------------------------------------------

// predicted change *per* tropical year at "right now"
function getDeltaTChangePerYear () {
  return secondsExcessPerDay() * o.solarYearDays;  // seconds / yr
}

// total accumulated ΔT (seconds) since 2000-06-21
function getDeltaT () {
  return state.deltaT;
}

function detectAndUpdateDeltaT() {
  const currentJD = o.julianDay;
  const jumpThreshold = 5; // days – tune this as needed

  if (Math.abs(currentJD - state.prevJD) > jumpThreshold) {
    resetDeltaTForJump();
  } else {
    updateDeltaT();
  }
}

function focusPlanet(pd, pad = 1.01) {
  if (!pd?.planetObj) {
    // user picked "Please select" → remove limits
    controls.minDistance = 0;
    controls.maxDistance = Infinity;
    return;
  }

  /* — planet world-space centre — */
  // Update from root of hierarchy to ensure all parent transforms are current
  // (needed when called while simulation is paused/idle)
  startingPoint.pivotObj.updateMatrixWorld(true);
  pd.planetObj.getWorldPosition(_ctrWS);

  /* — scaled radius (uniform scaling assumed) — */
  pd.planetObj.getWorldScale(_scale);
  const R = pd.size * _scale.x;          // pd.size = "pretty" radius
  const minD = R * pad;

  controls.target.copy(_ctrWS);
  controls.minDistance = minD;
  controls.maxDistance = Infinity;        // generous zoom-out

  /* — if camera is *inside* new shell → pop it to the skin — */
  _offset.subVectors(camera.position, _ctrWS);
  if (_offset.length() < minD) {
    camera.position.copy(_ctrWS).add(_offset.setLength(minD));
    controls.update();                   // rebuild spherical coords
  }

  /* — near plane: 20 % of min distance for good z-precision — */
  camera.near = Math.max(0.01, minD * 0.2);
  camera.updateProjectionMatrix();
}

/**
 * switchToPlanet(name) — programmatically switch focus to a planet by name.
 * Syncs o.Target, o.lookAtObj, Tweakpane Focus dropdown, camera, and helpers.
 */
function switchToPlanet(name) {
  o.Target    = name;
  o.lookAtObj = planetObjects.find(p => p.name === name) || undefined;
  hierarchyInspector._cameraControlActive = false;
  hierarchyInspector._cameraTarget = null;
  positionChanged = true;
  focusPlanet(o.lookAtObj);
  planetObjects.forEach(p => { if (p.orbitPlaneHelper) p.orbitPlaneHelper.visible = false; });
  if (o.lookAtObj?.orbitPlaneHelper) o.lookAtObj.orbitPlaneHelper.visible = _helperVisualsVisible;   // the Planet Info eye's state
  if (o._focusCtrl) o._focusCtrl.refresh();
}

/**
 * Jump to an indexed entry in ECLIPSE_PRESETS and update the displayed
 * Moon planetStats. Reuses the existing jumpToJulianDay (which sets
 * julianDay/Day/pos/perihelionDate + positionChanged), then refreshes
 * the Date/Time/JD root controls so the displayed values update too.
 */
function jumpToEclipsePreset(idx) {
  const n = ECLIPSE_PRESETS.length;
  _eclipseState.idx = ((idx % n) + n) % n;
  const jd = ECLIPSE_PRESETS[_eclipseState.idx].jd;
  jumpToJulianDay(jd);
  // Update Date/Time strings from the new JD so root controls show the right values
  const converted = dayToDate(jd);
  o.Date = converted.date;
  o.Time = converted.time;
  if (o._rootCtrls) {
    o._rootCtrls.dateCtrl?.refresh();
    o._rootCtrls.timeCtrl?.refresh();
    o._rootCtrls.jdCtrl?.refresh();
    o._rootCtrls.periCtrl?.refresh();
  }
}

/** Parallel to jumpToEclipsePreset but for LUNAR_ECLIPSE_PRESETS. Updates
 *  _lunarEclipseState.idx (wraps via modulo) and warps the simulation to the
 *  selected lunar eclipse's JD. Camera/planet selection unchanged — user keeps
 *  their current view (same convention as the solar Prev/Next buttons). */
function jumpToLunarEclipsePreset(idx) {
  const n = LUNAR_ECLIPSE_PRESETS.length;
  _lunarEclipseState.idx = ((idx % n) + n) % n;
  const jd = LUNAR_ECLIPSE_PRESETS[_lunarEclipseState.idx].jd;
  jumpToJulianDay(jd);
  const converted = dayToDate(jd);
  o.Date = converted.date;
  o.Time = converted.time;
  if (o._rootCtrls) {
    o._rootCtrls.dateCtrl?.refresh();
    o._rootCtrls.timeCtrl?.refresh();
    o._rootCtrls.jdCtrl?.refresh();
    o._rootCtrls.periCtrl?.refresh();
  }
}

/**
 * Blow-up slider for the physical planets only.
 * Pass a slider value `t` ∈ [0, 1].
 */
function updatePlanetSizes(t) {

  t = THREE.MathUtils.clamp(t, 0, 1);   // safety against out-of-range
  const BOOST = 250.0;                    // max multiple at t = 1

  planetObjects.forEach(pd => {

    /* ignore helpers / ghost objects */
    if (pd.isNotPhysicalObject === true || pd.visible === false) return;
    if (!pd.rotationAxis) return;

    /* linear scale from 1 → BOOST */
    const scale = 1 + t * (BOOST - 1);  // 0 ↦ 1, 1 ↦ BOOST
    pd.rotationAxis.scale.setScalar(scale);
  });
}

function addWidthToggle(gui, sizes = [350, 550]) {
  let idx = 0;

  /* create the floating badge */
  const badge = document.createElement('div');
  badge.id = 'guiWidthToggle';
  badge.textContent = '\u21C6';
  document.body.appendChild(badge);

  /* Tweakpane uses .element instead of .domElement */
  const panelEl = gui.element;

  /* positioning — centred beside the panel */
  function align() {
    const r  = panelEl.getBoundingClientRect();
    const bh = badge.getBoundingClientRect().height;
    badge.style.left = `${r.left - badge.offsetWidth}px`;
    badge.style.top  = `${r.top + (r.height - bh) / 2}px`;
  }
  align();

  window.addEventListener('resize', align);

  if ('ResizeObserver' in window) {
    new ResizeObserver(align).observe(panelEl);
  } else {
    setInterval(align, 1000);
  }

  /* click / tap toggles the panel width */
  badge.onclick = () => {
    idx = 1 - idx;
    panelEl.style.width = `${sizes[idx]}px`;
    align();
  };
}

function initConstellations() {
  console.log(`⏳ initConstellations() [${o.constellationLayout}] fetching…`);

  fetchRepoJson(constellationsUrl)
    .then(data => {
      if (!data) throw new Error('Constellations load failed from every source');
      // build raw strokes
      const strokes = [];
      let stroke = [];
      data.asterismIndices.forEach(idx => {
        if (idx !== -1) {
          const ra  = data.rightAscension[idx];
          const dec = data.declination   [idx];
          if (!Number.isFinite(ra) || !Number.isFinite(dec)) return;
          const R = o.starDistance;
          stroke.push(new THREE.Vector3(
            R * Math.cos(dec) * Math.sin(ra),
            R * Math.sin(dec),
            R * Math.cos(dec) * Math.cos(ra)
          ));
        } else {
          if (stroke.length > 1) strokes.push(stroke);
          stroke = [];
        }
      });
      if (stroke.length > 1) strokes.push(stroke);
      console.log(`  → parsed ${strokes.length} strokes`);

      // clear old
      sceneObjects.constellations.clear();
      drawMaterials.length = 0;

      if (o.constellationLayout === 'asterism') {
        console.log('  → drawing ASTERISM segments');
        const pts = [];
        strokes.forEach(s => {
          for (let i = 0; i < s.length - 1; i++) pts.push(s[i], s[i+1]);
        });
        if (pts.length === 0) return;

        const geo = new THREE.BufferGeometry().setFromPoints(pts);
        const distArr = new Float32Array(pts.length);
        let acc = 0;
        distArr[0] = 0;
        for (let i = 1; i < pts.length; i++) {
          acc += pts[i].distanceTo(pts[i - 1]);
          distArr[i] = acc;
        }
        geo.setAttribute('lineDistance', new THREE.BufferAttribute(distArr, 1));
        geo.computeBoundingSphere();

        const mesh = new THREE.LineSegments(geo, constellationMaterial);
        mesh.frustumCulled = false;
        sceneObjects.constellations.add(mesh);

        // single render if you’re not in a loop
        renderer.render(scene, camera);
        labelRenderer.render(scene, camera);
        console.log('  → ASTERISM render complete');

      } else {
        console.log('  → drawing STELLARIUM curves');

        // build curves & collect materials
        strokes.forEach(pts => {
          if (pts.length < 2) return;
          const curve     = new THREE.CatmullRomCurve3(pts, false, 'catmullrom', 0.5);
          const divisions = pts.length * 5;
          const splinePts = curve.getPoints(divisions);

          const geo = new THREE.BufferGeometry().setFromPoints(splinePts);
          const count = splinePts.length;
          const dArr  = new Float32Array(count);
          dArr[0] = 0;
          let totalLen = 0;
          for (let i = 1; i < count; i++) {
            totalLen += splinePts[i].distanceTo(splinePts[i - 1]);
            dArr[i] = totalLen;
          }
          geo.setAttribute('lineDistance', new THREE.BufferAttribute(dArr, 1));
          geo.computeBoundingSphere();

          const mat = drawOnShaderProto.clone();
          mat.uniforms.uTotalLength.value = totalLen;
          mat.uniforms.uColor.value       = constellationMaterial.color.clone();
          drawMaterials.push(mat);

          const line = new THREE.Line(geo, mat);
          line.frustumCulled = false;
          sceneObjects.constellations.add(line);
        });

        console.log(`  → created ${drawMaterials.length} curved lines`);

        if (drawMaterials.length) {
          console.log('  → starting draw-on animation');
          const start    = performance.now();
          const duration = 2000;
          (function animateDraw() {
            const t = Math.min((performance.now() - start) / duration, 1);
            drawMaterials.forEach(m => m.uniforms.uDrawProgress.value = t);
            renderer.render(scene, camera);
            labelRenderer.render(scene, camera);
            if (t < 1) requestAnimationFrame(animateDraw);
            else console.log('  → draw-on animation complete');
          })();
        }
      }
    })
    .catch(err => console.error('❌ initConstellations error:', err));
}

// — Make sure you have these at the top of your script —
// const bsc5url = 'https://raw.githubusercontent.com/dvansonsbeek/3d/main/public/input/stars.json';
// let starSizeMaterial = null;
// sceneObjects.stars = new THREE.Object3D();  scene.add(sceneObjects.stars);

function initStars() {
  console.log('⏳ initStars(): fetching', bsc5url);
  fetchRepoJson(bsc5url)
    .then(data => {
      if (!data) throw new Error('Stars load failed from every source');
      if (!Array.isArray(data) || data.length === 0) {
        throw new Error('Stars JSON is not an array or is empty');
      }

      // 1) Prepare flat arrays and label holders
      const positions    = [];
      const colors       = [];
      const sizes        = [];
      const labelObjects = [];
      const tmpColor     = new THREE.Color();
      const R            = o.starDistance    || 10000;
      const baseSize     = o.starsizeBase    ||   50;

      data.forEach((star, i) => {
        // 2) Parse & validate fields
        const ra   = raToRadians(star.RA);
        const dec  = decToRadians(star.Dec);
        const mag  = parseFloat(star.V);
        const kel  = parseFloat(star.K);
        const name = star.N;
        if (![ra, dec, mag, kel].every(Number.isFinite) || !name) return;

        // 3) Spherical → Cartesian via THREE.Spherical
        const sph = new THREE.Spherical(
          R,
          Math.PI/2 - dec,  // polar angle
          ra                 // azimuthal angle
        );
        const pos = new THREE.Vector3().setFromSpherical(sph);
        // tiny jitter to avoid z-fighting
        pos.x += (Math.random() - 0.5) * 0.001;
        pos.y += (Math.random() - 0.5) * 0.001;
        pos.z += (Math.random() - 0.5) * 0.001;

        // 4) Collect for BufferGeometry
        positions.push(pos.x, pos.y, pos.z);
        tmpColor.set(colorTemperature2rgb(kel));
        colors.push(tmpColor.r, tmpColor.g, tmpColor.b);
        const s = mag < 1 ? 1.5 : mag < 3 ? 1.0 : mag < 5 ? 0.6 : 0.3;
        sizes.push(s * baseSize);

        // 5) Create CSS2D label inline
        const labelDiv = document.createElement('div');
        labelDiv.className   = 'star-label';
        labelDiv.textContent = name;
        // (All styling comes from your CSS .star-label rules)
        labelDiv.style.pointerEvents = 'none';

        const labelObj = new CSS2DObject(labelDiv);
        labelObj.position.copy(pos);
        labelObj.visible = o.starNamesVisible;
        labelObjects.push(labelObj);
      });

      console.log(`  → kept ${positions.length/3} stars`);

      // 6) Build one BufferGeometry
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position',  new THREE.Float32BufferAttribute(positions, 3));
      geo.setAttribute('starColor', new THREE.Float32BufferAttribute(colors,    3));
      geo.setAttribute('starSize',  new THREE.Float32BufferAttribute(sizes,     1));
      geo.computeBoundingSphere();
      console.log('  → boundingSphere radius =', geo.boundingSphere.radius);

      // 7) Create ShaderMaterial with additive blending & alpha‐only sprite
      const mat = new THREE.ShaderMaterial({
        uniforms: {
          pointTexture: { value: starTexture },
          uScaleFactor: { value: 2500.0 },
          fadeStart:    { value: 7500.0 },
          fadeEnd:      { value: 30000.0 }
        },
        vertexShader: `
          uniform float uScaleFactor;
          attribute float starSize;
          attribute vec3 starColor;
          varying vec3 vColor;
          varying float vDist;
          void main() {
            vColor = starColor;
            vec4 mv = modelViewMatrix * vec4(position, 1.0);
            vDist = -mv.z;
            gl_PointSize = starSize * (uScaleFactor / max(vDist, 0.0001));
            gl_Position  = projectionMatrix * mv;
          }
        `,
        fragmentShader: `
          uniform sampler2D pointTexture;
          uniform float fadeStart, fadeEnd;
          varying vec3 vColor;
          varying float vDist;
          void main() {
            float a = texture2D(pointTexture, gl_PointCoord).a;
            float f = 1.0 - smoothstep(fadeStart, fadeEnd, vDist);
            gl_FragColor = vec4(vColor * f, a * f);
          }
        `,
        blending:     THREE.AdditiveBlending,
        depthWrite:   false,
        transparent:  true,
        vertexColors: true
      });
      // optional: expose for GUI tweaks
      starSizeMaterial = mat;

      // 8) Create & insert the Points mesh
      const points = new THREE.Points(geo, mat);
      points.frustumCulled = false;

      // clear any old stars & labels
      while (sceneObjects.stars.children.length) {
        sceneObjects.stars.remove(sceneObjects.stars.children[0]);
      }
      sceneObjects.stars.add(points);

      // 9) Add all CSS2D labels into the same group
      labelObjects.forEach(lo => sceneObjects.stars.add(lo));

      console.log('✅ initStars: complete');
    })
    .catch(err => console.error('❌ initStars error:', err));
}

function loadTexture( url, onLoad ) {
  if ( textureCache.has( url ) ) {
    // reuse
    const tex = textureCache.get( url );
    onLoad && onLoad( tex );
    return tex;
  }
  // first time: load + store — the local copy (the build ships public/); on a
  // miss the same repo-relative path from the repository, decoded into the
  // texture object already handed out (materials hold that object)
  const tex = textureLoader.load( url, t => {
    onLoad && onLoad( t );
  }, undefined, () => {
    if ( !url.startsWith( 'public/' ) ) return;
    textureLoader.load( REPO_RAW_URL + url, t => {
      tex.image = t.image;
      tex.needsUpdate = true;
      onLoad && onLoad( tex );
    });
  });
  textureCache.set( url, tex );
  return tex;
}

// ECLIPSE_PRESETS + _eclipseState moved earlier in the file (~line 24830)
// so they're available when setupGUI() runs at line ~24839 and constructs
// the Solar & Lunar Eclipses tweakpane folder. Keeping them here would put
// them in temporal-dead-zone at GUI construction time.

// Historical model predictions frozen at first access (J2000 state). The formula
// reads deep-time-mutable globals (planets.X.perihelionEclipticYears,
// etc.), so re-evaluating at runtime after setEpoch would
// give the epoch-shifted value instead of "what the model predicts at year 1900."
//
// Lazy memoization (rather than module-load `const`): the function chain needs
// the predict factory (`_predict`, declared much later) and other late-declared
// helpers — computing at module load throws TDZ. First render happens at J2000
// state (before any setEpoch), so lazy computation captures the J2000 value.
// ── Perihelion rate in its two coordinates (doc 13 §1.8; gate tools/verify/perihelion-projection-closure.js) ──
// (a) ecliptic longitude — what observers publish: the chain's inertial rate 360°/perihelionEclipticYears (1,296,000/g).
// (b) right ascension in the scene's equator (which co-moves with its stars) — what the
//     Earth-frame export and the predict basis produce; no observer publishes it:
//        rate_RA = rate_ecl · dα/dλ(λ, ε) + ∂α/∂ε(λ, ε) · ε̇
//     dα/dλ = cos ε / (cos²λ + sin²λ cos²ε),  ∂α/∂ε = −sin λ cos λ sin ε / (cos²λ + sin²λ cos²ε),
//     λ the chain's perihelion longitude of date, ε the published obliquity,
//     ε̇ its ±50-yr central difference.
// The Earth-frame RA rate itself (`earthFrame`) IS that projection — the inertial rate ×
// dα/dλ + ∂α/∂ε·ε̇, a kinematic identity (one formula, zero fitted constants; twin:
// tools/docs/model-values.mjs predictiveMachinery, identical ops). The chain's DYNAMICAL rate
// of date is a different quantity (a window rate; the outer planets' are
// great-inequality-dominated and Neptune's ϖ swings ~16°/cy on its near-zero e) and lives on
// the planet panel's chain rows.
function perihelionFrameBreakdown(planetKey, year) {
  const D2R = DEG2RAD;
  // The motion projected is THE CHAIN'S — the sidereal rate is the
  // chain's 1800–2100 window rate with 1PN OFF (the NEWTONIAN window) and the
  // perihelion longitude of date the chain's ϖ (J2000 ecliptic frame, series
  // handover beyond the boundary). Twin of tools/docs/model-values.mjs
  // predictiveMachinery (identical ops — the base must match there, or the
  // two surfaces quote different windows of one rate); the relativistic
  // supplement stays an explicit addition, never folded into the projection.
  // The property name `lattice` is kept for the callers.
  const lattice = CHAIN_ARTIFACT.windowRatesArcsecCy.newton[planetKey];                         // (a) ″/cy, sidereal, Newtonian
  const eps = _sceneEpsTargetDeg(year) * D2R;   // Phase 3 S3b: the published ε (the hybrid)
  const epsRate = (_sceneEpsTargetDeg(year + 50) - _sceneEpsTargetDeg(year - 50)) * 3600;  // ″/cy
  // projection excess and obliquity-rate term for the chain motion at ecliptic longitude lamDeg
  const lam = _chainPerihelionEclLonDeg(planetKey, yearToJDApprox(year)) * D2R;
  const den = Math.cos(lam) ** 2 + Math.sin(lam) ** 2 * Math.cos(eps) ** 2;
  const projection = lattice * (Math.cos(eps) / den - 1);
  const obliquityTerm = (-Math.sin(lam) * Math.cos(lam) * Math.sin(eps) / den) * epsRate;
  const projectedRa = lattice + projection;                                                       // the advance × dα/dλ
  const earthFrame = projectedRa + obliquityTerm;                                                  // (b) ″/cy
  return { lattice, projection, obliquityTerm, projectedRa, earthFrame };
}
// Right ascension of an ecliptic-of-date direction (β = 0) in the equatorial frame of the same date.
function eclipticLongitudeToRaDeg(lamDeg, year) {
  const D2R = DEG2RAD;
  const l = lamDeg * D2R, e = _sceneEpsTargetDeg(year) * D2R;
  return ((Math.atan2(Math.sin(l) * Math.cos(e), Math.cos(l)) / D2R) % 360 + 360) % 360;
}
// The general-relativistic perihelion advance from the model's own constants:
// 6π GM☉ / (c² a (1 − e²)) per orbit, a from the period (Kepler III), × orbits per century.
function relativisticPerihelionAdvanceArcsecCy(planetKey) {
  const p = planets[planetKey];
  const aKm = Math.pow(p.orbitalPeriodInputDays / (meansiderealyearlengthinSeconds / SECONDS_PER_DAY), 2 / 3) * AU_J2000_KM;
  const perOrbit = 6 * Math.PI * GM_SUN / (speedOfLight * speedOfLight * aKm * (1 - p.orbitalEccentricityJ2000 ** 2));
  return perOrbit * (36525 / p.orbitalPeriodInputDays) * 206264.806;
}

